window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["GEN"]={"book":"GEN","editions":{"fin-biblia1776":[[1,1,"Alussa loi Jumala taivaan ja maan.","Alussa loi Jumala taivaan ja maan."],[1,2,"Ja maa oli autio ja tyhjä, ja pimeys oli syvyyden päällä, ja Jumalan Henki liikkui vetten päällä.","Ja maa oli autio ja tyhjä, ja pimeys oli syvyyden päällä, ja Jumalan Henki liikkui vetten päällä."],[1,3,"Ja Jumala sanoi: tulkoon valkeus, ja valkeus tuli.","Ja Jumala sanoi: tulkoon valkeus, ja valkeus tuli."],[1,4,"Ja Jumala näki valkeuden hyväksi. Niin Jumala eroitti valkeuden pimeydestä:","Ja Jumala näki valkeuden hyväksi. Niin Jumala eroitti valkeuden pimeydestä:"],[1,5,"Ja Jumala kutsui valkeuden päiväksi, ja pimeyden kutsui hän yöksi. Ja tuli ehtoosta ja aamusta ensimäinen päivä.","Ja Jumala kutsui valkeuden päiväksi, ja pimeyden kutsui hän yöksi. Ja tuli ehtoosta ja aamusta ensimäinen päivä."],[1,6,"Ja Jumala sanoi: tulkoon vahvuus vetten vaiheelle, eroittamaan vesiä vesistä.","Ja Jumala sanoi: tulkoon vahvuus vetten vaiheelle, eroittamaan vesiä vesistä."],[1,7,"Ja Jumala teki vahvuuden, ja eroitti vedet, jotka ovat vahvuuden alla, niistä vesistä, jotka ovat vahvuuden päällä: ja tapahtui niin.","Ja Jumala teki vahvuuden, ja eroitti vedet, jotka ovat vahvuuden alla, niistä vesistä, jotka ovat vahvuuden päällä: ja tapahtui niin."],[1,8,"Ja Jumala kutsui vahvuuden taivaaksi. Ja tuli ehtoosta ja aamusta toinen päivä.","Ja Jumala kutsui vahvuuden taivaaksi. Ja tuli ehtoosta ja aamusta toinen päivä."],[1,9,"Ja Jumala sanoi: kokoontukoon vedet taivaan alla erinomaiseen paikkaan, niin että kuiva näkyy. Ja tapahtui niin.","Ja Jumala sanoi: kokoontukoon vedet taivaan alla erinomaiseen paikkaan, niin että kuiva näkyy. Ja tapahtui niin."],[1,10,"Ja Jumala kutsui kuivan maaksi, ja vetten kokoukset hän kutsui mereksi. Ja Jumala näki sen hyväksi.","Ja Jumala kutsui kuivan maaksi, ja vetten kokoukset hän kutsui mereksi. Ja Jumala näki sen hyväksi."],[1,11,"Ja Jumala sanoi: vihoittakoon maa, ja kasvakoon ruohon, jossa siemen on, ja hedelmälliset puut, jotka hedelmän kantavat lajinsa jälkeen, jossa sen siemen on maan päällä. Ja tapahtui niin.","Ja Jumala sanoi: vihoittakoon maa, ja kasvakoon ruohon, jossa siemen on, ja hedelmälliset puut, jotka hedelmän kantavat lajinsa jälkeen, jossa sen siemen on maan päällä. Ja tapahtui niin."],[1,12,"Ja maa vihoitti ja kasvoi ruohon, jossa siemen oli lajinsa jälkeen, ja hedelmälliset puut, joiden siemen oli itsessänsä lajinsa jälkeen. Ja Jumala näki sen hyväksi.","Ja maa vihoitti ja kasvoi ruohon, jossa siemen oli lajinsa jälkeen, ja hedelmälliset puut, joiden siemen oli itsessänsä lajinsa jälkeen. Ja Jumala näki sen hyväksi."],[1,13,"Ja tuli ehtoosta ja aamusta kolmas päivä.","Ja tuli ehtoosta ja aamusta kolmas päivä."],[1,14,"Ja Jumala sanoi: tulkoon valkeudet taivaan vahvuuteen, eroittamaan päivää ja yötä: ja olkoon merkeiksi, ja ajoiksi, ja päiviksi ja vuosiksi.","Ja Jumala sanoi: tulkoon valkeudet taivaan vahvuuteen, eroittamaan päivää ja yötä: ja olkoon merkeiksi, ja ajoiksi, ja päiviksi ja vuosiksi."],[1,15,"Ja olkoon valkeudeksi taivaan vahvuudessa, paistamaan maan päälle. Ja tapahtui niin.","Ja olkoon valkeudeksi taivaan vahvuudessa, paistamaan maan päälle. Ja tapahtui niin."],[1,16,"Ja Jumala teki kaksi suurta valkeutta: suuremman valkeuden päivää hallitsemaan, ja vähemmän valkeuden yötä hallitsemaan, ja tähdet.","Ja Jumala teki kaksi suurta valkeutta: suuremman valkeuden päivää hallitsemaan, ja vähemmän valkeuden yötä hallitsemaan, ja tähdet."],[1,17,"Ja Jumala pani ne taivaan vahvuuteen, paistamaan maan päälle.","Ja Jumala pani ne taivaan vahvuuteen, paistamaan maan päälle."],[1,18,"Ja hallitsemaan päivää ja yötä, ja eroittamaan valkeutta ja pimeyttä. Ja Jumala näki sen hyväksi.","Ja hallitsemaan päivää ja yötä, ja eroittamaan valkeutta ja pimeyttä. Ja Jumala näki sen hyväksi."],[1,19,"Ja tuli ehtoosta ja aamusta neljäs päivä.","Ja tuli ehtoosta ja aamusta neljäs päivä."],[1,20,"Ja Jumala sanoi: kuohuttakoon vedet yltäkyllä liikkuvaisia eläimiä, ja linnut lentäköön maan päällä taivaan avaruudessa.","Ja Jumala sanoi: kuohuttakoon vedet yltäkyllä liikkuvaisia eläimiä, ja linnut lentäköön maan päällä taivaan avaruudessa."],[1,21,"Ja Jumala loi suuret valaskalat, ja kaikkinaiset liikkuvaiset eläimet, jotka vedet kuohuttivat yltäkyllä kunkin lajinsa jälkeen, ja kaikkinaiset siivilliset linnut, lajinsa jälkeen. Ja Jumala näki sen hyväksi.","Ja Jumala loi suuret valaskalat, ja kaikkinaiset liikkuvaiset eläimet, jotka vedet kuohuttivat yltäkyllä kunkin lajinsa jälkeen, ja kaikkinaiset siivilliset linnut, lajinsa jälkeen. Ja Jumala näki sen hyväksi."],[1,22,"Ja Jumala siunasi heitä, ja sanoi: olkaat hedelmälliset ja lisääntykäät, ja täyttäkäät meren vedet, ja linnut lisääntyköön veden päällä.","Ja Jumala siunasi heitä, ja sanoi: olkaat hedelmälliset ja lisääntykäät, ja täyttäkäät meren vedet, ja linnut lisääntyköön veden päällä."],[1,23,"Ja tuli ehtoosta ja aamusta viides päivä.","Ja tuli ehtoosta ja aamusta viides päivä."],[1,24,"Ja Jumala sanoi: tuottakoon maa eläimet lajinsa jälkeen, karjan, madot ja pedot maalle lajinsa jälkeen. Ja tapahtui niin.","Ja Jumala sanoi: tuottakoon maa eläimet lajinsa jälkeen, karjan, madot ja pedot maalle lajinsa jälkeen. Ja tapahtui niin."],[1,25,"Ja jumala teki pedot maalle lajinsa jälkeen, ja karjan lajinsa jälkeen, ja kaikkinaiset matelevaiset maalla lajinsa jälkeen. Ja Jumala näki sen hyväksi.","Ja jumala teki pedot maalle lajinsa jälkeen, ja karjan lajinsa jälkeen, ja kaikkinaiset matelevaiset maalla lajinsa jälkeen. Ja Jumala näki sen hyväksi."],[1,26,"Ja Jumala sanoi: tehkäämme ihminen meidän kuvaksemme, meidän muotomme jälkeen: ja he vallitkaan kalat meressä, ja taivaan linnut, ja karjan ja koko maan, ja kaikki, jotka maalla matelevat.","Ja Jumala sanoi: tehkäämme ihminen meidän kuvaksemme, meidän muotomme jälkeen: ja he vallitkaan kalat meressä, ja taivaan linnut, ja karjan ja koko maan, ja kaikki, jotka maalla matelevat."],[1,27,"Ja Jumala loi ihmisen omaksi kuvaksensa, Jumalan kuvaksi hän sen loi: mieheksi ja vaimoksi loi hän heitä.","Ja Jumala loi ihmisen omaksi kuvaksensa, Jumalan kuvaksi hän sen loi: mieheksi ja vaimoksi loi hän heitä."],[1,28,"Ja Jumala siunasi heitä, ja Jumala sanoi heille: kasvakaat ja lisääntykäät ja täyttäkäät maata, ja tehkäät se teillenne alamaiseksi; ja vallitkaat kalat meressä, ja taivaan linnut, ja kaikki eläimet, jotka maalla liikkuvat.","Ja Jumala siunasi heitä, ja Jumala sanoi heille: kasvakaat ja lisääntykäät ja täyttäkäät maata, ja tehkäät se teillenne alamaiseksi; ja vallitkaat kalat meressä, ja taivaan linnut, ja kaikki eläimet, jotka maalla liikkuvat."],[1,29,"Ja Jumala sanoi: katso, minä annoin teille kaikkinaiset ruohot, joissa siemen on koko maan päällä, ja kaikkinaiset hedelmälliset puut, ja puut, joissa siemen on, teille ruaksi","Ja Jumala sanoi: katso, minä annoin teille kaikkinaiset ruohot, joissa siemen on koko maan päällä, ja kaikkinaiset hedelmälliset puut, ja puut, joissa siemen on, teille ruaksi"],[1,30,"Ja kaikille eläimille maan päällä, ja kaikille taivaan linnuille, ja kaikille, jotka matelevat maan päällä, joissa elävä henki on, kaikkinaiset viheriäiset ruohot syötäväksi. Ja tapahtui niin.","Ja kaikille eläimille maan päällä, ja kaikille taivaan linnuille, ja kaikille, jotka matelevat maan päällä, joissa elävä henki on, kaikkinaiset viheriäiset ruohot syötäväksi. Ja tapahtui niin."],[1,31,"Ja Jumala katsoi kaikkia, kuin hän tehnyt oli, ja katso, ne olivat sangen hyvät. Ja tuli ehtoosta ja aamusta se kuudes päivä.","Ja Jumala katsoi kaikkia, kuin hän tehnyt oli, ja katso, ne olivat sangen hyvät. Ja tuli ehtoosta ja aamusta se kuudes päivä."],[2,1,"Ja niin taivas ja maa päätettiin, ja kaikki heidän joukkonsa.","Ja niin taivas ja maa päätettiin, ja kaikki heidän joukkonsa."],[2,2,"Ja Jumala oli päättänyt seitsemänteen päivään (asti) työnsä, kuin hän tehnyt oli, ja lepäsi seitsemäntenä päivänä kaikista teoistansa, kuin hän tehnyt oli.","Ja Jumala oli päättänyt seitsemänteen päivään (asti) työnsä, kuin hän tehnyt oli, ja lepäsi seitsemäntenä päivänä kaikista teoistansa, kuin hän tehnyt oli."],[2,3,"Ja Jumala siunasi seitsemännen päivän ja pyhitti sen; että hän lepäsi hänessä kaikista teoistansa, jotka Jumala loi ja (täydellisesti) teki.","Ja Jumala siunasi seitsemännen päivän ja pyhitti sen; että hän lepäsi hänessä kaikista teoistansa, jotka Jumala loi ja (täydellisesti) teki."],[2,4,"Ja näin on taivas ja maa tullut, koska he luotiin, sillä ajalla jolla Herra Jumala teki maan ja taivaan.","Ja näin on taivas ja maa tullut, koska he luotiin, sillä ajalla jolla Herra Jumala teki maan ja taivaan."],[2,5,"Ja kaikkinaiset pensaat kedolla, jotka ei ennen olleet maan päällä, ja kaikkinaiset ruohot kedolla, jotka ei ennen kasvaneet. Sillä ei Herra Jumala antanut vielä sataa maan päälle, eikä ollut ihmistä, joka maata viljeli;","Ja kaikkinaiset pensaat kedolla, jotka ei ennen olleet maan päällä, ja kaikkinaiset ruohot kedolla, jotka ei ennen kasvaneet. Sillä ei Herra Jumala antanut vielä sataa maan päälle, eikä ollut ihmistä, joka maata viljeli;"],[2,6,"Vaan sumu nousi maasta, ja kasti kaiken maan.","Vaan sumu nousi maasta, ja kasti kaiken maan."],[2,7,"Ja Herra Jumala teki ihmisen, tomun maasta, ja puhalsi hänen sieraimiinsa elävän hengen: ja tuli ihminen niin eläväksi sieluksi.","Ja Herra Jumala teki ihmisen, tomun maasta, ja puhalsi hänen sieraimiinsa elävän hengen: ja tuli ihminen niin eläväksi sieluksi."],[2,8,"Ja Herra Jumala istutti Paradisin Edenissä itään päin, ja pani siihen ihmisen, jonka hän tehnyt oli.","Ja Herra Jumala istutti Paradisin Edenissä itään päin, ja pani siihen ihmisen, jonka hän tehnyt oli."],[2,9,"Ja Herra Jumala kasvatti maasta kaikkinaiset puut, ihanaiset nähdä ja hyvät syödä, ja elämän puun keskelle Paradisia, niin myös hyvän ja pahan tiedon puun.","Ja Herra Jumala kasvatti maasta kaikkinaiset puut, ihanaiset nähdä ja hyvät syödä, ja elämän puun keskelle Paradisia, niin myös hyvän ja pahan tiedon puun."],[2,10,"Ja Edenistä kävi virta kastamaan Paradisia, ja jakoi sieltä itsensä neljäksi päävirraksi.","Ja Edenistä kävi virta kastamaan Paradisia, ja jakoi sieltä itsensä neljäksi päävirraksi."],[2,11,"Ensimäinen kutsutaan Pison: se juoksee koko Hevilan maan ympärinsä, ja siellä on kultaa.","Ensimäinen kutsutaan Pison: se juoksee koko Hevilan maan ympärinsä, ja siellä on kultaa."],[2,12,"Ja sen maan kulta on kallis, ja siellä myös löytään Bedellion, ja kallis kivi Oniks.","Ja sen maan kulta on kallis, ja siellä myös löytään Bedellion, ja kallis kivi Oniks."],[2,13,"Toinen virta kutsutaan Gihon: se juoksee koko Etiopian ympärinsä.","Toinen virta kutsutaan Gihon: se juoksee koko Etiopian ympärinsä."],[2,14,"Kolmas virta kutsutaan Hiddekel, ja juoksee Assyrian editse. Ja neljäs virta on Phrat.","Kolmas virta kutsutaan Hiddekel, ja juoksee Assyrian editse. Ja neljäs virta on Phrat."],[2,15,"Ja Herra Jumala otti ihmisen, ja pani Edenissä Paradisiin, viljelemään ja varjelemaan sitä.","Ja Herra Jumala otti ihmisen, ja pani Edenissä Paradisiin, viljelemään ja varjelemaan sitä."],[2,16,"Ja Herra Jumala käski ihmistä, ja sanoi: syö vapaasti kaikkinaisista puista Paradisissa;","Ja Herra Jumala käski ihmistä, ja sanoi: syö vapaasti kaikkinaisista puista Paradisissa;"],[2,17,"Mutta hyvän ja pahan tiedon puusta älä syö: sillä jona päivänä sinä siitä syöt, pitää sinun kuolemalla kuoleman.","Mutta hyvän ja pahan tiedon puusta älä syö: sillä jona päivänä sinä siitä syöt, pitää sinun kuolemalla kuoleman."],[2,18,"Ja Herra Jumala sanoi: ei ole hyvä ihmisen yksinänsä olla, minä teen hänelle avun, joka hänen tykönänsä oleman pitää.","Ja Herra Jumala sanoi: ei ole hyvä ihmisen yksinänsä olla, minä teen hänelle avun, joka hänen tykönänsä oleman pitää."],[2,19,"Koska Herra Jumala oli tehnyt maasta kaikkinaiset eläimet kedolle, ja kaikkinaiset taivaan linnut, toi hän ne Adamin eteen, että hän näkis, kuinka hän ne nimittäis: sillä niinkuin Adam kaikkinaiset eläimet nimitti, niin ne kutsutaan.","Koska Herra Jumala oli tehnyt maasta kaikkinaiset eläimet kedolle, ja kaikkinaiset taivaan linnut, toi hän ne Adamin eteen, että hän näkis, kuinka hän ne nimittäis: sillä niinkuin Adam kaikkinaiset eläimet nimitti, niin ne kutsutaan."],[2,20,"Ja Adam antoi kullekin karjalle, ja taivaan linnuille, ja eläimille maan päällä heidän nimensä. Mutta Adamille ei löytty apua, joka hänen tykönänsä olisi.","Ja Adam antoi kullekin karjalle, ja taivaan linnuille, ja eläimille maan päällä heidän nimensä. Mutta Adamille ei löytty apua, joka hänen tykönänsä olisi."],[2,21,"Ja Herra jumala pani raskaan unen Adamiin, ja kuin hän nukkui, otti hän yhden hänen kylkiluistansa, ja täytti sen paikan lihalla.","Ja Herra jumala pani raskaan unen Adamiin, ja kuin hän nukkui, otti hän yhden hänen kylkiluistansa, ja täytti sen paikan lihalla."],[2,22,"Ja Herra Jumala rakensi vaimon siitä kylkiluusta, jonka hän Adamista otti, ja toi sen hänen eteensä.","Ja Herra Jumala rakensi vaimon siitä kylkiluusta, jonka hän Adamista otti, ja toi sen hänen eteensä."],[2,23,"Niin sanoi Adam: tämä on nyt luu minun luistani, ja liha minun lihastani: se pitää kutsuttaman miehiseksi, sillä hän on otettu miehestä.","Niin sanoi Adam: tämä on nyt luu minun luistani, ja liha minun lihastani: se pitää kutsuttaman miehiseksi, sillä hän on otettu miehestä."],[2,24,"Sentähden pitää miehen luopuman isästänsä ja äidistänsä, ja vaimoonsa sidottu oleman, ja tulevat yhdeksi lihaksi.","Sentähden pitää miehen luopuman isästänsä ja äidistänsä, ja vaimoonsa sidottu oleman, ja tulevat yhdeksi lihaksi."],[2,25,"Ja he olivat molemmat alasti, Adam ja hänen emäntänsä, ja ei hävenneet.","Ja he olivat molemmat alasti, Adam ja hänen emäntänsä, ja ei hävenneet."],[3,1,"Ja kärme oli kavalin kaikkia eläimiä maan päällä, jotka Herra Jumala tehnyt oli, ja se sanoi vaimolle: sanoiko Jumala, älkäät syökö kaikkinaisista puista Paradisissa?","Ja kärme oli kavalin kaikkia eläimiä maan päällä, jotka Herra Jumala tehnyt oli, ja se sanoi vaimolle: sanoiko Jumala, älkäät syökö kaikkinaisista puista Paradisissa?"],[3,2,"Niin vaimo sanoi kärmeelle: me syömme niiden puiden hedelmistä, jotka ovat Paradisissa;","Niin vaimo sanoi kärmeelle: me syömme niiden puiden hedelmistä, jotka ovat Paradisissa;"],[3,3,"Mutta sen puun hedelmästä, joka on keskellä Paradisia, on Jumala sanonut: älkäät syökö siitä, ja älkäät ruvetko siihen, ettette kuolis.","Mutta sen puun hedelmästä, joka on keskellä Paradisia, on Jumala sanonut: älkäät syökö siitä, ja älkäät ruvetko siihen, ettette kuolis."],[3,4,"Niin kärme sanoi vaimolle: ei suinkaan pidä teidän kuolemalla kuoleman.","Niin kärme sanoi vaimolle: ei suinkaan pidä teidän kuolemalla kuoleman."],[3,5,"Vaan Jumala tietää, että jona päivänä te syötte siitä, aukenevat teidän silmänne, ja te tulette niinkuin Jumala, tietämään hyvän ja pahan.","Vaan Jumala tietää, että jona päivänä te syötte siitä, aukenevat teidän silmänne, ja te tulette niinkuin Jumala, tietämään hyvän ja pahan."],[3,6,"Ja vaimo näki siitä puusta olevan hyvän syödä, ja että se oli ihana nähdä ja suloinen puu antamaan ymmärryksen: ja otti sen hedelmästä ja söi, ja antoi miehellensä siitä, ja hän söi.","Ja vaimo näki siitä puusta olevan hyvän syödä, ja että se oli ihana nähdä ja suloinen puu antamaan ymmärryksen: ja otti sen hedelmästä ja söi, ja antoi miehellensä siitä, ja hän söi."],[3,7,"Silloin aukenivat molempain heidän silmänsä, ja äkkäsivät, että he olivat alasti; ja sitoivat yhteen fikunalehtiä, ja tekivät heillensä peitteitä.","Silloin aukenivat molempain heidän silmänsä, ja äkkäsivät, että he olivat alasti; ja sitoivat yhteen fikunalehtiä, ja tekivät heillensä peitteitä."],[3,8,"Ja he kuulivat Herran Jumalan äänen, joka käyskenteli Paradisissa, kuin päivä viileäksi tuli. Ja Adam lymyi emäntinensä Herran Jumalan kasvoin edestä puiden sekaan Paradisissa.","Ja he kuulivat Herran Jumalan äänen, joka käyskenteli Paradisissa, kuin päivä viileäksi tuli. Ja Adam lymyi emäntinensä Herran Jumalan kasvoin edestä puiden sekaan Paradisissa."],[3,9,"Ja Herra Jumala kutsui Adamin, ja sanoi hänelle: Kussas olet?","Ja Herra Jumala kutsui Adamin, ja sanoi hänelle: Kussas olet?"],[3,10,"Ja hän sanoi: minä kuulin sinun äänes Paradisissa, ja pelkäsin: sillä minä olen alasti, ja sen tähden minä lymyin.","Ja hän sanoi: minä kuulin sinun äänes Paradisissa, ja pelkäsin: sillä minä olen alasti, ja sen tähden minä lymyin."],[3,11,"Ja hän sanoi: kuka sinulle ilmoitti, ettäs alasti olet? Etkös syönyt siitä puusta, josta minä sinua haastoin syömästä?","Ja hän sanoi: kuka sinulle ilmoitti, ettäs alasti olet? Etkös syönyt siitä puusta, josta minä sinua haastoin syömästä?"],[3,12,"Niin sanoi Adam: vaimo, jonkas annoit minulle, antoi minulle siitä puusta, ja minä söin.","Niin sanoi Adam: vaimo, jonkas annoit minulle, antoi minulle siitä puusta, ja minä söin."],[3,13,"Silloin sanoi Herra Jumala vaimolle: miksis sen teit? Ja vaimo sanoi: kärme petti minut, ja minä söin.","Silloin sanoi Herra Jumala vaimolle: miksis sen teit? Ja vaimo sanoi: kärme petti minut, ja minä söin."],[3,14,"Ja Herra Jumala sanoi kärmeelle: ettäs tämän teit, kirottu ole sinä kaikesta karjasta, ja kaikista eläimistä maalla: sinun pitää käymän vatsallas, ja syömän maata kaiken elinaikas.","Ja Herra Jumala sanoi kärmeelle: ettäs tämän teit, kirottu ole sinä kaikesta karjasta, ja kaikista eläimistä maalla: sinun pitää käymän vatsallas, ja syömän maata kaiken elinaikas."],[3,15,"Ja minä panen vainon sinun ja vaimon välille, ja sinun siemenes ja hänen siemenensä välille; sen pitää rikki polkemaan sinun pääs, ja sinä olet pistävä häntä kantapäähän.","Ja minä panen vainon sinun ja vaimon välille, ja sinun siemenes ja hänen siemenensä välille; sen pitää rikki polkemaan sinun pääs, ja sinä olet pistävä häntä kantapäähän."],[3,16,"Ja vaimolle sanoi hän: Minä saatan sinulle paljon tuskaa, koskas raskaaksi tulet: sinun pitää synnyttämän lapsia kivulla, ja sinun tahtos pitää miehes alle annettu oleman, ja hänen pitää vallitseman sinua.","Ja vaimolle sanoi hän: Minä saatan sinulle paljon tuskaa, koskas raskaaksi tulet: sinun pitää synnyttämän lapsia kivulla, ja sinun tahtos pitää miehes alle annettu oleman, ja hänen pitää vallitseman sinua."],[3,17,"Ja Adamille sanoi hän: ettäs kuulit emäntäs ääntä, ja söit puusta, josta minä kielsin sinua sanoen: ei sinun pidä siitä syömän: kirottu olkoon maa sinun tähtes; surulla pitää sinun elättämän itses hänestä kaiken elinaikas.","Ja Adamille sanoi hän: ettäs kuulit emäntäs ääntä, ja söit puusta, josta minä kielsin sinua sanoen: ei sinun pidä siitä syömän: kirottu olkoon maa sinun tähtes; surulla pitää sinun elättämän itses hänestä kaiken elinaikas."],[3,18,"Orjantappuroita ja ohdakkeita pitää hänen kasvaman, ja sinun pitää maan ruohoja syömän.","Orjantappuroita ja ohdakkeita pitää hänen kasvaman, ja sinun pitää maan ruohoja syömän."],[3,19,"Sinun otsas hiessä pitää sinun syömän leipää, siihen asti kuin sinä maaksi jällensä tulet, ettäs siitä otettu olet: sillä sinä olet maa, ja maaksi pitää sinun jällensä tuleman.","Sinun otsas hiessä pitää sinun syömän leipää, siihen asti kuin sinä maaksi jällensä tulet, ettäs siitä otettu olet: sillä sinä olet maa, ja maaksi pitää sinun jällensä tuleman."],[3,20,"Ja Adam kutsui emäntänsä nimen Heva, että hän on kaikkein elävitten äiti.","Ja Adam kutsui emäntänsä nimen Heva, että hän on kaikkein elävitten äiti."],[3,21,"Ja Herra Jumala teki Adamille ja hänen emännällensä nahoista hameet, ja puetti heidän yllensä.","Ja Herra Jumala teki Adamille ja hänen emännällensä nahoista hameet, ja puetti heidän yllensä."],[3,22,"Ja Herra Jumala sanoi: katso, Adam on ollut niin kuin yksi meistä, tietäen hyvän ja pahan; mutta nyt ettei hän ojentaisi kättänsä, ja ottaisi myös elämän puusta, söisi ja eläisi ijankaikkisesti:","Ja Herra Jumala sanoi: katso, Adam on ollut niin kuin yksi meistä, tietäen hyvän ja pahan; mutta nyt ettei hän ojentaisi kättänsä, ja ottaisi myös elämän puusta, söisi ja eläisi ijankaikkisesti:"],[3,23,"Niin Herra Jumala johdatti hänen ulos Edenin Paradisista maata viljelemään, josta hän otettu oli.","Niin Herra Jumala johdatti hänen ulos Edenin Paradisista maata viljelemään, josta hän otettu oli."],[3,24,"Ja ajoi Adamin ulos, ja pani idän puolelle Edenin Paradisia Kerubimin paljaalla, lyöväisellä miekalla elämän puun tietä vartioitsemaan.","Ja ajoi Adamin ulos, ja pani idän puolelle Edenin Paradisia Kerubimin paljaalla, lyöväisellä miekalla elämän puun tietä vartioitsemaan."],[4,1,"Ja Adam tunsi emäntänsä Hevan, ja hän tuli raskaaksi, ja synnytti Kainin, ja sanoi: minulla on mies Herra.","Ja Adam tunsi emäntänsä Hevan, ja hän tuli raskaaksi, ja synnytti Kainin, ja sanoi: minulla on mies Herra."],[4,2,"Ja taas hän synnytti hänen veljensä Habelin. Ja Habel tuli lampuriksi, mutta Kain peltomieheksi.","Ja taas hän synnytti hänen veljensä Habelin. Ja Habel tuli lampuriksi, mutta Kain peltomieheksi."],[4,3,"Ja tapahtui muutamain päiväin perästä, että Kain uhrasi Herralle lahjan maan hedelmistä.","Ja tapahtui muutamain päiväin perästä, että Kain uhrasi Herralle lahjan maan hedelmistä."],[4,4,"Ja Habel myös uhrasi laumansa esikoisista, ja heidän lihavuudestansa. Ja Herra katsoi (leppyisesti) Habelin ja hänen uhrinsa puoleen.","Ja Habel myös uhrasi laumansa esikoisista, ja heidän lihavuudestansa. Ja Herra katsoi (leppyisesti) Habelin ja hänen uhrinsa puoleen."],[4,5,"Mutta Kainin ja hänen uhrinsa puoleen ei hän (leppyisesti) katsonut: silloin Kain vihastui sangen kovin, ja hänen hahmonsa muuttui.","Mutta Kainin ja hänen uhrinsa puoleen ei hän (leppyisesti) katsonut: silloin Kain vihastui sangen kovin, ja hänen hahmonsa muuttui."],[4,6,"Niin Herra sanoi Kainille: miksis olet vihainen? Ja miksi hahmos muuttuu?","Niin Herra sanoi Kainille: miksis olet vihainen? Ja miksi hahmos muuttuu?"],[4,7,"Eikö se niin ole? jos hyvin teet niin syntis anteeksi annetaan; ja jolles hyvin tee, niin synti väijyy oven edessä, ja hänen himonsa on sinun tykös, vaan hallitse sinä häntä.","Eikö se niin ole? jos hyvin teet niin syntis anteeksi annetaan; ja jolles hyvin tee, niin synti väijyy oven edessä, ja hänen himonsa on sinun tykös, vaan hallitse sinä häntä."],[4,8,"Ja Kain puhui veljensä Habelin kanssa. Ja tapahtui heidän kedolla ollessansa, että Kain karkasi veljensä Habelin päälle, ja tappoi hänen.","Ja Kain puhui veljensä Habelin kanssa. Ja tapahtui heidän kedolla ollessansa, että Kain karkasi veljensä Habelin päälle, ja tappoi hänen."],[4,9,"Niin Herra sanoi Kainille: kussa on Habel sinun veljes? hän vastasi: en minä tiedä: olenko minä veljeni vartia?","Niin Herra sanoi Kainille: kussa on Habel sinun veljes? hän vastasi: en minä tiedä: olenko minä veljeni vartia?"],[4,10,"Ja hän sanoi: mitäs tehnyt olet? veljes veren ääni huutaa minun tyköni maasta.","Ja hän sanoi: mitäs tehnyt olet? veljes veren ääni huutaa minun tyköni maasta."],[4,11,"Ja nyt kirottu ole sinä: (kirottu) maan päältä, joka avasi suunsa ottamaan veljes verta sinun kädestäs.","Ja nyt kirottu ole sinä: (kirottu) maan päältä, joka avasi suunsa ottamaan veljes verta sinun kädestäs."],[4,12,"Koskas maata viljelet, niin ei pidä sen tästedes sinulle väkeänsä antaman; kulkian ja pakenevaisen pitää sinun oleman maan päällä.","Koskas maata viljelet, niin ei pidä sen tästedes sinulle väkeänsä antaman; kulkian ja pakenevaisen pitää sinun oleman maan päällä."],[4,13,"Ja Kain sanoi Herralle: minun rangaistukseni on suurempi, kuin että se on kannettava.","Ja Kain sanoi Herralle: minun rangaistukseni on suurempi, kuin että se on kannettava."],[4,14,"Katsos, sinä ajat minun pois tänäpäivänä maalta, ja minun pitää sinun kasvois edestä lymymän ja tulen kulkiaksi ja pakenevaiseksi maan päällä. Ja niin minun käy, kuka ikänänsä minun löytää, se tappaa minun.","Katsos, sinä ajat minun pois tänäpäivänä maalta, ja minun pitää sinun kasvois edestä lymymän ja tulen kulkiaksi ja pakenevaiseksi maan päällä. Ja niin minun käy, kuka ikänänsä minun löytää, se tappaa minun."],[4,15,"Mutta Herra sanoi hänelle: Sentähden, kuka ikänänsä Kainin tappaa, se pitää seitsemän kertaisesti kostettaman. Ja Herra pani merkin Kainiin, ettei kenkään häntä tappaisi, joka hänen löytäisi.","Mutta Herra sanoi hänelle: Sentähden, kuka ikänänsä Kainin tappaa, se pitää seitsemän kertaisesti kostettaman. Ja Herra pani merkin Kainiin, ettei kenkään häntä tappaisi, joka hänen löytäisi."],[4,16,"Ja niin Kain läksi Herran kasvoin edestä, ja asui Nodin maalla, itään päin Edenistä.","Ja niin Kain läksi Herran kasvoin edestä, ja asui Nodin maalla, itään päin Edenistä."],[4,17,"Ja Kain tunsi emäntänsä, joka tuli raskaaksi, ja synnytti Hanokin. Ja hän rakensi kaupungin, jonka hän kutsui poikansa nimellä Hanok.","Ja Kain tunsi emäntänsä, joka tuli raskaaksi, ja synnytti Hanokin. Ja hän rakensi kaupungin, jonka hän kutsui poikansa nimellä Hanok."],[4,18,"Mutta Hanok siitti Iradin. Irad siitti Mahujaelin. Mahujael siitti Metusaelin. Metusael siitti Lamekin.","Mutta Hanok siitti Iradin. Irad siitti Mahujaelin. Mahujael siitti Metusaelin. Metusael siitti Lamekin."],[4,19,"Mutta Lamek otti kaksi emäntää, yhden nimi oli Ada, ja toisen nimi Zilla.","Mutta Lamek otti kaksi emäntää, yhden nimi oli Ada, ja toisen nimi Zilla."],[4,20,"Ja Ada synnytti Jabalin, joka oli niiden isä, jotka majoissa asuivat, ja karjaa kasvattivat.","Ja Ada synnytti Jabalin, joka oli niiden isä, jotka majoissa asuivat, ja karjaa kasvattivat."],[4,21,"Ja hänen veljensä nimi oli Jubal, josta kantelein ja huiluin soittajat tulivat.","Ja hänen veljensä nimi oli Jubal, josta kantelein ja huiluin soittajat tulivat."],[4,22,"Zilla myös synnytti TubalKainin, joka oli taitava kaikkinaisissa vaski-ja rautatöissä, ja Tubalkainin sisar oli Naema.","Zilla myös synnytti TubalKainin, joka oli taitava kaikkinaisissa vaski-ja rautatöissä, ja Tubalkainin sisar oli Naema."],[4,23,"Ja Lamek sanoi emännillensä, Adalle ja Zillalle: te Lamekin emännät, kuulkaat minun ääntäni, ja vaari ottakaat siitä kuin minä sanon: minä olen miehen tappanut minulleni haavaksi, ja nuorukaisen minulleni sinimarjaksi:","Ja Lamek sanoi emännillensä, Adalle ja Zillalle: te Lamekin emännät, kuulkaat minun ääntäni, ja vaari ottakaat siitä kuin minä sanon: minä olen miehen tappanut minulleni haavaksi, ja nuorukaisen minulleni sinimarjaksi:"],[4,24,"Kain kostetaan seitsemän kertaisesti, mutta Lamek seitsemän ja seitsemänkymmenen kertaisesti.","Kain kostetaan seitsemän kertaisesti, mutta Lamek seitsemän ja seitsemänkymmenen kertaisesti."],[4,25,"Ja Adam taas tunsi emäntänsä, ja hän synnytti pojan, ja kutsui hänen nimensä Set, sanoen: Jumala on minulle toisen siemenen antanut Habelin edestä, jonka Kain tappoi.","Ja Adam taas tunsi emäntänsä, ja hän synnytti pojan, ja kutsui hänen nimensä Set, sanoen: Jumala on minulle toisen siemenen antanut Habelin edestä, jonka Kain tappoi."],[4,26,"Ja Set myös siitti pojan, ja kutsui hänen Enos. Silloin ruvettiin saarnaamaan Herran nimestä.","Ja Set myös siitti pojan, ja kutsui hänen Enos. Silloin ruvettiin saarnaamaan Herran nimestä."],[5,1,"Tämä on ihmisen sukukunnan kirja, siihen aikaan, koska Jumala loi ihmisen, ja teki hänen Jumalan muotoiseksi.","Tämä on ihmisen sukukunnan kirja, siihen aikaan, koska Jumala loi ihmisen, ja teki hänen Jumalan muotoiseksi."],[5,2,"Mieheksi ja vaimoksi loi hän heidät ja siunasi heitä, ja kutsui heidän nimensä ihminen, sinä päivänä jona he luotiin.","Mieheksi ja vaimoksi loi hän heidät ja siunasi heitä, ja kutsui heidän nimensä ihminen, sinä päivänä jona he luotiin."],[5,3,"Ja Adam oli sadan ja kolmenkymmenen ajastajan vanha, ja siitti pojan, joka hänen kuvansa kaltainen oli, ja kutsui hänen nimensä Set.","Ja Adam oli sadan ja kolmenkymmenen ajastajan vanha, ja siitti pojan, joka hänen kuvansa kaltainen oli, ja kutsui hänen nimensä Set."],[5,4,"Ja eli sitte kahdeksansataa ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kahdeksansataa ajastaikaa, ja siitti poikia ja tyttäriä."],[5,5,"Ja koko hänen ikänsä oli yhdeksänsataa ja kolmekymmentä ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli yhdeksänsataa ja kolmekymmentä ajastaikaa, ja kuoli."],[5,6,"Set oli sadan ja viiden ajastajan vanha, ja siitti Enoksen.","Set oli sadan ja viiden ajastajan vanha, ja siitti Enoksen."],[5,7,"Ja eli sitte kahdeksansataa ja seitsemän ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kahdeksansataa ja seitsemän ajastaikaa, ja siitti poikia ja tyttäriä."],[5,8,"Ja koko hänen ikänsä oli yhdeksänsataa ja kaksitoistakymmentä ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli yhdeksänsataa ja kaksitoistakymmentä ajastaikaa, ja kuoli."],[5,9,"Enos oli yhdeksänkymmenen ajastajan vanha, ja siitti Kenanin.","Enos oli yhdeksänkymmenen ajastajan vanha, ja siitti Kenanin."],[5,10,"Ja eli sitte kahdeksansataa ja viisitoistakymmentä ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kahdeksansataa ja viisitoistakymmentä ajastaikaa, ja siitti poikia ja tyttäriä."],[5,11,"Ja koko hänen ikänsä oli yhdeksänsataa ja viisi ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli yhdeksänsataa ja viisi ajastaikaa, ja kuoli."],[5,12,"Kenan oli seitsemänkymmenen ajastajan vanha, ja siitti Mahalaleelin.","Kenan oli seitsemänkymmenen ajastajan vanha, ja siitti Mahalaleelin."],[5,13,"Ja eli sitte kahdeksansataa ja neljäkymmentä ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kahdeksansataa ja neljäkymmentä ajastaikaa, ja siitti poikia ja tyttäriä."],[5,14,"Ja koko hänen ikänsä oli yhdeksänsataa ja kymmenen ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli yhdeksänsataa ja kymmenen ajastaikaa, ja kuoli."],[5,15,"Mahalaleel oli viiden ajastajan seitsemättäkymmentä vanha, ja siitti Jaredin.","Mahalaleel oli viiden ajastajan seitsemättäkymmentä vanha, ja siitti Jaredin."],[5,16,"Ja eli sitte kahdeksansataa ja kolmekymmentä ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kahdeksansataa ja kolmekymmentä ajastaikaa, ja siitti poikia ja tyttäriä."],[5,17,"Ja koko hänen ikänsä oli kahdeksansataa yhdeksänkymmentä ja viisi ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli kahdeksansataa yhdeksänkymmentä ja viisi ajastaikaa, ja kuoli."],[5,18,"Jared oli sadan ja kahdenseitsemättäkymmentä ajastajan vanha, ja siitti Henokin.","Jared oli sadan ja kahdenseitsemättäkymmentä ajastajan vanha, ja siitti Henokin."],[5,19,"Ja eli sitte kahdeksansataa ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kahdeksansataa ajastaikaa, ja siitti poikia ja tyttäriä."],[5,20,"Ja koko hänen ikänsä oli yhdeksänsataa ja kaksiseitsemättäkymmentä ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli yhdeksänsataa ja kaksiseitsemättäkymmentä ajastaikaa, ja kuoli."],[5,21,"Henok oli viidenseitsemättäkymmentä ajastajan vanha, ja siitti Metusalan.","Henok oli viidenseitsemättäkymmentä ajastajan vanha, ja siitti Metusalan."],[5,22,"Ja sitte kuin hän oli Metusalan siittänyt, pysyi hän jumalisessa elämässä kolmesataa ajastaikaa, ja siitti poikia ja tyttäriä.","Ja sitte kuin hän oli Metusalan siittänyt, pysyi hän jumalisessa elämässä kolmesataa ajastaikaa, ja siitti poikia ja tyttäriä."],[5,23,"Ja koko hänen ikänsä oli kolmesataa ja viisiseitsemättäkymmentä ajastaikaa.","Ja koko hänen ikänsä oli kolmesataa ja viisiseitsemättäkymmentä ajastaikaa."],[5,24,"Ja hän eli jumalisesti: ja ei enää ollut; sillä Jumala otti hänen pois.","Ja hän eli jumalisesti: ja ei enää ollut; sillä Jumala otti hänen pois."],[5,25,"Metusalah oli sadan ja seitsemän ajastajan yhdeksättäkymmentä vanha, ja siitti Lamekin.","Metusalah oli sadan ja seitsemän ajastajan yhdeksättäkymmentä vanha, ja siitti Lamekin."],[5,26,"Ja eli sitte seitsemänsataa ja kaksiyhdeksättäkymmentä ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte seitsemänsataa ja kaksiyhdeksättäkymmentä ajastaikaa, ja siitti poikia ja tyttäriä."],[5,27,"Ja koko hänen ikänsä oli yhdeksänsataa ja yhdeksänseitsemättäkymmentä ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli yhdeksänsataa ja yhdeksänseitsemättäkymmentä ajastaikaa, ja kuoli."],[5,28,"Lamek oli sadan ja kahden ajastajan yhdeksättäkymmentä vanha, ja siitti pojan.","Lamek oli sadan ja kahden ajastajan yhdeksättäkymmentä vanha, ja siitti pojan."],[5,29,"Ja kutsui hänen nimensä Noa, sanoen: tämä on lohduttava meitä meidän vaivassamme ja töissämme maan päällä, jonka Herra kironnut on.","Ja kutsui hänen nimensä Noa, sanoen: tämä on lohduttava meitä meidän vaivassamme ja töissämme maan päällä, jonka Herra kironnut on."],[5,30,"Sitte eli hän viisisataa yhdeksänkymmentä ja viisi ajastaikaa, ja siitti poikia ja tyttäriä.","Sitte eli hän viisisataa yhdeksänkymmentä ja viisi ajastaikaa, ja siitti poikia ja tyttäriä."],[5,31,"Ja koko hänen ikänsä oli seitsemänsataa ja seitsemänkahdeksattakymmentä ajastaikaa, ja kuoli.","Ja koko hänen ikänsä oli seitsemänsataa ja seitsemänkahdeksattakymmentä ajastaikaa, ja kuoli."],[5,32,"Noa oli viidensadan ajastajan vanha, ja siitti Semin, Hamin ja Japhetin.","Noa oli viidensadan ajastajan vanha, ja siitti Semin, Hamin ja Japhetin."],[6,1,"Ja tapahtui, koska ihmiset rupesivat lisääntymään maan päällä, ja siittivät tyttäriä;","Ja tapahtui, koska ihmiset rupesivat lisääntymään maan päällä, ja siittivät tyttäriä;"],[6,2,"Niin Jumalan pojat näkivät ihmisten tyttäret kauniiksi, ja ottivat emänniksensä kaikesta kuin he valitsivat.","Niin Jumalan pojat näkivät ihmisten tyttäret kauniiksi, ja ottivat emänniksensä kaikesta kuin he valitsivat."],[6,3,"Silloin sanoi Herra: ei minun henkeni pidä nuhteleman ihmistä (sanan kautta) ijankaikkisesti, sillä hän on liha; sentähden olkoon hänellä aikaa, sata ja kaksikymmentä ajastaikaa.","Silloin sanoi Herra: ei minun henkeni pidä nuhteleman ihmistä (sanan kautta) ijankaikkisesti, sillä hän on liha; sentähden olkoon hänellä aikaa, sata ja kaksikymmentä ajastaikaa."],[6,4,"Siihen aikaan olivat sankarit maan päällä: ja myös sitte, kuin Jumalan pojat makasivat ihmisten tytärten kanssa, ja he olivat siittäneet heille (lapsia): nämä olivat valtiaat, ne muinen kuuluisat miehet.","Siihen aikaan olivat sankarit maan päällä: ja myös sitte, kuin Jumalan pojat makasivat ihmisten tytärten kanssa, ja he olivat siittäneet heille (lapsia): nämä olivat valtiaat, ne muinen kuuluisat miehet."],[6,5,"Mutta Herra näki ihmisen pahuuden suureksi maan päällä; ja kaikki hänen sydämensä aivoitus ja ajatus oli ainoastansa paha joka aika.","Mutta Herra näki ihmisen pahuuden suureksi maan päällä; ja kaikki hänen sydämensä aivoitus ja ajatus oli ainoastansa paha joka aika."],[6,6,"Ja Herra katui ihmisen tehneensä maan päälle, ja tuli murheelliseksi sydämessänsä.","Ja Herra katui ihmisen tehneensä maan päälle, ja tuli murheelliseksi sydämessänsä."],[6,7,"Ja Herra sanoi: Minä tahdon ihmisen, jonka minä loin, hukuttaa maan päältä, hamasta ihmisestä niin karjaan asti, matoihin ja ja taivaan lintuihin asti; sillä minä kadun, että minä niitä tehnyt olen.","Ja Herra sanoi: Minä tahdon ihmisen, jonka minä loin, hukuttaa maan päältä, hamasta ihmisestä niin karjaan asti, matoihin ja ja taivaan lintuihin asti; sillä minä kadun, että minä niitä tehnyt olen."],[6,8,"Mutta Noa löysi armon Herran edessä.","Mutta Noa löysi armon Herran edessä."],[6,9,"Tämä on Noan sukukunta: Noa oli hurskas ja vakaa mies ajallansa, ja eli jumalisesti:","Tämä on Noan sukukunta: Noa oli hurskas ja vakaa mies ajallansa, ja eli jumalisesti:"],[6,10,"Ja siitti kolme poikaa, Semin, Hamin ja Japhetin.","Ja siitti kolme poikaa, Semin, Hamin ja Japhetin."],[6,11,"Mutta maa oli turmeltu Jumalan kasvoin edessä, ja täynnänsä väkivaltaa.","Mutta maa oli turmeltu Jumalan kasvoin edessä, ja täynnänsä väkivaltaa."],[6,12,"Silloin katsahti Jumala maan päälle, ja katso, se oli turmeltu: sillä kaikki liha oli turmellut tiensä maan päällä.","Silloin katsahti Jumala maan päälle, ja katso, se oli turmeltu: sillä kaikki liha oli turmellut tiensä maan päällä."],[6,13,"Ja Jumala sanoi Noalle: kaiken lihan loppu on minun eteeni tullut: sillä maa on heistä täynnänsä väkivaltaa, ja katso, minä hukutan heitä ynnä maan kanssa.","Ja Jumala sanoi Noalle: kaiken lihan loppu on minun eteeni tullut: sillä maa on heistä täynnänsä väkivaltaa, ja katso, minä hukutan heitä ynnä maan kanssa."],[6,14,"Tee sinulles arkki hongasta, ja tee sisälle olinsijat, ja tervaa se sisältä ja ulkoa.","Tee sinulles arkki hongasta, ja tee sisälle olinsijat, ja tervaa se sisältä ja ulkoa."],[6,15,"Ja tee häntä näin: Kolmesataa kyynärää pitää oleman arkin pituuden, viisikymmentä kyynärää hänen leveytensä ja kolmekymmentä kyynärää korkeutensa.","Ja tee häntä näin: Kolmesataa kyynärää pitää oleman arkin pituuden, viisikymmentä kyynärää hänen leveytensä ja kolmekymmentä kyynärää korkeutensa."],[6,16,"Arkin akkunan sinun pitää tekemän, ja kyynärällä päättämän sen ylhäältä: Ja arkin oven pitää sinun paneman sivuun. Ja hänellä pitää oleman kolme pohjaa, yksi alinna, toinen keskellä ja kolmas ylinnä.","Arkin akkunan sinun pitää tekemän, ja kyynärällä päättämän sen ylhäältä: Ja arkin oven pitää sinun paneman sivuun. Ja hänellä pitää oleman kolme pohjaa, yksi alinna, toinen keskellä ja kolmas ylinnä."],[6,17,"Ja minä, katso, minä annan tulla vedenpaisumuksen maan päälle hukuttamaan kaikkea lihaa, jossa elävä henki on taivaan alla, ja kaikki, mitä maan päällä on, pitää hukkuman.","Ja minä, katso, minä annan tulla vedenpaisumuksen maan päälle hukuttamaan kaikkea lihaa, jossa elävä henki on taivaan alla, ja kaikki, mitä maan päällä on, pitää hukkuman."],[6,18,"Mutta sinun kanssas minä minun liittoni teen, ja sinun pitää arkkiin sisälle menemän, sinun ja sinun poikas, ja sinun emäntäs, ja poikais emännät sinun kanssas.","Mutta sinun kanssas minä minun liittoni teen, ja sinun pitää arkkiin sisälle menemän, sinun ja sinun poikas, ja sinun emäntäs, ja poikais emännät sinun kanssas."],[6,19,"Ja sinun pitää saattaman arkkiin kaikkinaiset eläimet kaikesta lihasta kaksittain, koiraksen ja naaraksen, jäämään elämään kanssas.","Ja sinun pitää saattaman arkkiin kaikkinaiset eläimet kaikesta lihasta kaksittain, koiraksen ja naaraksen, jäämään elämään kanssas."],[6,20,"Linnuista lajistansa, karjasta lajistansa, kaikkinaisista madoista maan päällä lajistansa. Kaikista näistä pitää kaksittain sinun tykös käymän, jäämän elämään.","Linnuista lajistansa, karjasta lajistansa, kaikkinaisista madoista maan päällä lajistansa. Kaikista näistä pitää kaksittain sinun tykös käymän, jäämän elämään."],[6,21,"Ja sinun pitää ottaman tykös kaikkinaista ruokaa, jota syödään, ja kokooman sinun tykös, sinulle ja heille elatukseksi.","Ja sinun pitää ottaman tykös kaikkinaista ruokaa, jota syödään, ja kokooman sinun tykös, sinulle ja heille elatukseksi."],[6,22,"Ja Noa teki sen: kaikki mitä Jumala hänen käski, niin hän teki.","Ja Noa teki sen: kaikki mitä Jumala hänen käski, niin hän teki."],[7,1,"Ja Herra sanoi Noalle: mene sinä ja koko sinun huonees arkkiin: sillä sinun minä olen nähnyt hurskaaksi minun edessäni tällä ajalla.","Ja Herra sanoi Noalle: mene sinä ja koko sinun huonees arkkiin: sillä sinun minä olen nähnyt hurskaaksi minun edessäni tällä ajalla."],[7,2,"Kaikista puhtaista eläimistä ota tykös seitsemän ja seitsemän, koiras ja naaras, mutta saastaisista eläimistä kaksin, koiras ja naaras.","Kaikista puhtaista eläimistä ota tykös seitsemän ja seitsemän, koiras ja naaras, mutta saastaisista eläimistä kaksin, koiras ja naaras."],[7,3,"Niin myös taivaan linnuista seitsemän ja seitsemän, koiras ja naaras, että siemen jäis elämään koko maan päällä.","Niin myös taivaan linnuista seitsemän ja seitsemän, koiras ja naaras, että siemen jäis elämään koko maan päällä."],[7,4,"Sillä vielä seitsemän päivän perästä annan minä sataa maan päälle neljäkymmentä päivää ja neljäkymmentä yötä, ja hukutan maan päältä kaikki elävät luontokappaleet, jotka minä tehnyt olen.","Sillä vielä seitsemän päivän perästä annan minä sataa maan päälle neljäkymmentä päivää ja neljäkymmentä yötä, ja hukutan maan päältä kaikki elävät luontokappaleet, jotka minä tehnyt olen."],[7,5,"Ja Noa teki kaiken sen jälkeen kuin Herra hänelle käski.","Ja Noa teki kaiken sen jälkeen kuin Herra hänelle käski."],[7,6,"Ja Noa oli kuudensadan ajastajan vanha, koska vedenpaisumus tuli maan päälle.","Ja Noa oli kuudensadan ajastajan vanha, koska vedenpaisumus tuli maan päälle."],[7,7,"Ja Noa meni arkkiin poikinensa, emäntinensä, ja hänen poikainsa emännät hänen kanssansa, vedenpaisumisen edestä.","Ja Noa meni arkkiin poikinensa, emäntinensä, ja hänen poikainsa emännät hänen kanssansa, vedenpaisumisen edestä."],[7,8,"Puhtaista eläimistä ja saastaisista, ja linnuista ja kaikista, kuin matelevat maan päällä,","Puhtaista eläimistä ja saastaisista, ja linnuista ja kaikista, kuin matelevat maan päällä,"],[7,9,"Menivät Noan tykö arkkiin kaksittain, koiras ja naaras, niinkuin Herra Noalle käskenyt oli.","Menivät Noan tykö arkkiin kaksittain, koiras ja naaras, niinkuin Herra Noalle käskenyt oli."],[7,10,"Ja tapahtui, koska seitsemän päivää kuluneet olivat, tuli vedenpaisumus maan päälle.","Ja tapahtui, koska seitsemän päivää kuluneet olivat, tuli vedenpaisumus maan päälle."],[7,11,"Kuudennella sadalla ajastajalla Noan ijästä, toisella kuukaudella, seitsemäntenätoista kymmenentenä päivänä kuusta, sinä päivänä kuohuivat kaikki syvyyden lähteet, ja taivaan akkunat aukenivat.","Kuudennella sadalla ajastajalla Noan ijästä, toisella kuukaudella, seitsemäntenätoista kymmenentenä päivänä kuusta, sinä päivänä kuohuivat kaikki syvyyden lähteet, ja taivaan akkunat aukenivat."],[7,12,"Ja maan päälle satoi neljäkymmentä päivää ja neljäkymmentä yötä.","Ja maan päälle satoi neljäkymmentä päivää ja neljäkymmentä yötä."],[7,13,"Juuri sinä päivänä meni Noa ja Sem, ja Ham, ja Japhet, Noan pojat, ja Noan emäntä, ja kolme hänen poikainsa emäntää hänen kanssansa arkkiin.","Juuri sinä päivänä meni Noa ja Sem, ja Ham, ja Japhet, Noan pojat, ja Noan emäntä, ja kolme hänen poikainsa emäntää hänen kanssansa arkkiin."],[7,14,"He ja kaikki pedot lajistansa, ja kaikki matelevaiset, jotka matelevat maan päällä, lajistansa, ja kaikki linnut lajistansa, kaikki lentäväiset, joilla siivet olivat.","He ja kaikki pedot lajistansa, ja kaikki matelevaiset, jotka matelevat maan päällä, lajistansa, ja kaikki linnut lajistansa, kaikki lentäväiset, joilla siivet olivat."],[7,15,"Ja menivät Noan tykö arkkiin kaksittain kaikesta lihasta, jossa elävä henki oli.","Ja menivät Noan tykö arkkiin kaksittain kaikesta lihasta, jossa elävä henki oli."],[7,16,"Je ne olivat koirakset ja naarakset kaikkinaisesta lihasta, ja menivät sisälle niinkuin Jumala hänelle käskenyt oli. Ja Herra sulki hänen jälkeensä.","Je ne olivat koirakset ja naarakset kaikkinaisesta lihasta, ja menivät sisälle niinkuin Jumala hänelle käskenyt oli. Ja Herra sulki hänen jälkeensä."],[7,17,"Silloin tuli vedenpaisumus neljäkymmentä päivää maan päälle, ja vedet paisuivat, ja nostivat arkin ylös, ja veivät korkialle maasta.","Silloin tuli vedenpaisumus neljäkymmentä päivää maan päälle, ja vedet paisuivat, ja nostivat arkin ylös, ja veivät korkialle maasta."],[7,18,"Niin vedet saivat vallan, ja paisuivat sangen suuresti maan päälle, niin että arkki oli vesiajolla.","Niin vedet saivat vallan, ja paisuivat sangen suuresti maan päälle, niin että arkki oli vesiajolla."],[7,19,"Ja vedet saivat sangen suuren vallan, ja enänivät niin suuresti maan päälle, että kaikki korkiat vuoret koko taivaan alla peitettiin.","Ja vedet saivat sangen suuren vallan, ja enänivät niin suuresti maan päälle, että kaikki korkiat vuoret koko taivaan alla peitettiin."],[7,20,"Viisitoistakymmentä kyynärää korkialla olivat vedet vuorten päällä, jotka he peittivät.","Viisitoistakymmentä kyynärää korkialla olivat vedet vuorten päällä, jotka he peittivät."],[7,21,"Silloin hukkui kaikki liha, joka maan päällä matelee, linnut, karja, pedot, ja kaikki, jotka maan päällä liikkuvat, ja kaikki ihmiset.","Silloin hukkui kaikki liha, joka maan päällä matelee, linnut, karja, pedot, ja kaikki, jotka maan päällä liikkuvat, ja kaikki ihmiset."],[7,22,"Ja kaikki, joilla elävä henki oli kuivan maan päällä, ne kuolivat.","Ja kaikki, joilla elävä henki oli kuivan maan päällä, ne kuolivat."],[7,23,"Niin hukutettiin kaikki ne, kuin maan päällä olivat, ihmisestä niin karjaan asti, ja matoihin, ja taivaan lintuihin asti, kaikki hukutettiin maan päältä, ainoastansa Noa jäi, ja ne jotka hänen kanssansa olivat arkissa.","Niin hukutettiin kaikki ne, kuin maan päällä olivat, ihmisestä niin karjaan asti, ja matoihin, ja taivaan lintuihin asti, kaikki hukutettiin maan päältä, ainoastansa Noa jäi, ja ne jotka hänen kanssansa olivat arkissa."],[7,24,"Ja vedet seisoivat valtiasna maan päällä sata ja viisikymmentä päivää.","Ja vedet seisoivat valtiasna maan päällä sata ja viisikymmentä päivää."],[8,1,"Silloin Jumala muisti Noaa ja kaikkia eläviä, ja kaikkea karjaa, kuin hänen kanssansa olivat arkissa, ja Jumala nosti tuulen maan päälle, ja vedet seisahtivat.","Silloin Jumala muisti Noaa ja kaikkia eläviä, ja kaikkea karjaa, kuin hänen kanssansa olivat arkissa, ja Jumala nosti tuulen maan päälle, ja vedet seisahtivat."],[8,2,"Ja syvyyden lähteet tukittiin, ja taivaan akkunat, ja sateet taivaasta asetettiin.","Ja syvyyden lähteet tukittiin, ja taivaan akkunat, ja sateet taivaasta asetettiin."],[8,3,"Ja vedet maan päältä enemmin ja enemmin juoksivat pois, ja vähenivät sadan ja viidenkymmenen päivän perästä.","Ja vedet maan päältä enemmin ja enemmin juoksivat pois, ja vähenivät sadan ja viidenkymmenen päivän perästä."],[8,4,"Ja seitsemäntenätoistakymmenentenä päivänä, seitsemännessä kuukaudessa jäi arkki Araratin vuorelle.","Ja seitsemäntenätoistakymmenentenä päivänä, seitsemännessä kuukaudessa jäi arkki Araratin vuorelle."],[8,5,"Mutta vedet juoksivat pois, ja vähenivät hamaan kymmenenteen kuukauteen asti. Ensimäisnä päivänä kymmenentenä kuukautena näkyivät vuorten kukkulat.","Mutta vedet juoksivat pois, ja vähenivät hamaan kymmenenteen kuukauteen asti. Ensimäisnä päivänä kymmenentenä kuukautena näkyivät vuorten kukkulat."],[8,6,"Neljänkymmenen päivän perästä avasi Noa arkin akkunan, jonka hän tehnyt oli.","Neljänkymmenen päivän perästä avasi Noa arkin akkunan, jonka hän tehnyt oli."],[8,7,"Ja antoi kaarneen lentää ulos, joka lensi kahtiapäin, siihen asti kuin vedet maan päältä kuivuivat.","Ja antoi kaarneen lentää ulos, joka lensi kahtiapäin, siihen asti kuin vedet maan päältä kuivuivat."],[8,8,"Sitte lähetti hän kyhkyisen tyköänsä, koettelemaan, jos vedet olisivat juosseet pois maan päältä.","Sitte lähetti hän kyhkyisen tyköänsä, koettelemaan, jos vedet olisivat juosseet pois maan päältä."],[8,9,"Koska ei kyhkyinen löytänyt kussa hän sai jalkansa levätä, palasi hän hänen tykönsä arkkiin: sillä vedet olivat vielä koko maan päällä, niin hän ojensi kätensä, otti hänen ja toi arkkiin.","Koska ei kyhkyinen löytänyt kussa hän sai jalkansa levätä, palasi hän hänen tykönsä arkkiin: sillä vedet olivat vielä koko maan päällä, niin hän ojensi kätensä, otti hänen ja toi arkkiin."],[8,10,"Ja odotti vielä toiset seitsemän päivää, ja antoi taas kyhkyisen lentää arkista.","Ja odotti vielä toiset seitsemän päivää, ja antoi taas kyhkyisen lentää arkista."],[8,11,"Se palasi hänen tykönsä, ehtoopuolella, ja katso, hän toi suussansa öljypuun lehden, jonka hän murtanut oli. Niin Noa ymmärsi vedet maan päältä juosseeksi pois.","Se palasi hänen tykönsä, ehtoopuolella, ja katso, hän toi suussansa öljypuun lehden, jonka hän murtanut oli. Niin Noa ymmärsi vedet maan päältä juosseeksi pois."],[8,12,"Mutta hän odotti vielä seitsemän päivää, ja antoi kyhkyisen lentää ulos, joka ei enää palannut.","Mutta hän odotti vielä seitsemän päivää, ja antoi kyhkyisen lentää ulos, joka ei enää palannut."],[8,13,"Ja kuudennella sadalla ja ensimäisellä ajastajalla (Noan ijästä) ensimäisenä päivänä ensimäisessä kuukaudessa, kuivuivat vedet maan päältä. Niin avasi Noa arkin katon, ja näki, ja katso, maa oli kuivunut.","Ja kuudennella sadalla ja ensimäisellä ajastajalla (Noan ijästä) ensimäisenä päivänä ensimäisessä kuukaudessa, kuivuivat vedet maan päältä. Niin avasi Noa arkin katon, ja näki, ja katso, maa oli kuivunut."],[8,14,"Niin maa tuli peräti kuivaksi seitsemäntenäkolmattakymmenentenä päivänä toisessa kuukaudessa.","Niin maa tuli peräti kuivaksi seitsemäntenäkolmattakymmenentenä päivänä toisessa kuukaudessa."],[8,15,"Niin Jumala puhui Noalle sanoen:","Niin Jumala puhui Noalle sanoen:"],[8,16,"Lähde arkista, sinä ja sinun emäntäs, ja sinun poikas, ja sinun poikais emännät sinun kanssas.","Lähde arkista, sinä ja sinun emäntäs, ja sinun poikas, ja sinun poikais emännät sinun kanssas."],[8,17,"Kaikkinaiset eläimet, jotka sinun tykönäs ovat, kaikkinaisesta lihasta, sekä linnuista että karjasta, ja kaikista matelevaisista maan päällä, johdata ne ulos kanssas: ja kävelköön ne maan päällä, ja olkoon hedelmälliset ja lisääntyköön maan päällä.","Kaikkinaiset eläimet, jotka sinun tykönäs ovat, kaikkinaisesta lihasta, sekä linnuista että karjasta, ja kaikista matelevaisista maan päällä, johdata ne ulos kanssas: ja kävelköön ne maan päällä, ja olkoon hedelmälliset ja lisääntyköön maan päällä."],[8,18,"Niin Noa meni ulos poikinensa, ja emäntinensä, ja poikainsa emännät hänen kanssansa.","Niin Noa meni ulos poikinensa, ja emäntinensä, ja poikainsa emännät hänen kanssansa."],[8,19,"Kaikkinaiset eläimet, kaikkinaiset matelevaiset, kaikkinaiset linnut, ja kaikki kuin maalla matelevat: läksivät arkista, jokainen kaltaisensa tykö.","Kaikkinaiset eläimet, kaikkinaiset matelevaiset, kaikkinaiset linnut, ja kaikki kuin maalla matelevat: läksivät arkista, jokainen kaltaisensa tykö."],[8,20,"Ja Noa rakensi Herralle alttarin: ja otti kaikkinaisesta puhtaasta karjasta, ja kaikkinaisista puhtaista linnuista, ja uhrasi polttouhria alttarilla.","Ja Noa rakensi Herralle alttarin: ja otti kaikkinaisesta puhtaasta karjasta, ja kaikkinaisista puhtaista linnuista, ja uhrasi polttouhria alttarilla."],[8,21,"Ja Herra haisti lepytyshajun, ja Herra sanoi sydämessänsä: en minä silleen enää maata kiroo ihmisen tähden: vaikka ihmisen sydämen aivoitus on paha hamasta lapsuudesta: ja en minä silleen enää lyö kaikkia kuin elävät, niinkuin minä tehnyt olen.","Ja Herra haisti lepytyshajun, ja Herra sanoi sydämessänsä: en minä silleen enää maata kiroo ihmisen tähden: vaikka ihmisen sydämen aivoitus on paha hamasta lapsuudesta: ja en minä silleen enää lyö kaikkia kuin elävät, niinkuin minä tehnyt olen."],[8,22,"Niin kauvan kuin maa seisoo, ei pidä kylväminen ja niittäminen, vilu ja helle, suvi ja talvi, päivä ja yö lakkaaman.","Niin kauvan kuin maa seisoo, ei pidä kylväminen ja niittäminen, vilu ja helle, suvi ja talvi, päivä ja yö lakkaaman."],[9,1,"Ja Jumala siunasi Noan ja hänen poikansa, ja sanoi heille: olkaat hedelmälliset, lisääntykäät ja täyttäkäät maata.","Ja Jumala siunasi Noan ja hänen poikansa, ja sanoi heille: olkaat hedelmälliset, lisääntykäät ja täyttäkäät maata."],[9,2,"Ja teidän pelkonne ja hämmästyksenne olkoon kaikissa eläimissä maan päällä, ja kaikissa linnuissa taivaan alla; ja kaikissa, jotka maalla matelevat, ja kaikissa kaloissa meressä: ne ovat teidän käsiinne annetut.","Ja teidän pelkonne ja hämmästyksenne olkoon kaikissa eläimissä maan päällä, ja kaikissa linnuissa taivaan alla; ja kaikissa, jotka maalla matelevat, ja kaikissa kaloissa meressä: ne ovat teidän käsiinne annetut."],[9,3,"Kaikki, jotka liikkuvat ja elävät, olkoon teille ruaksi: niinkuin viheriäisen ruohon, olen minä kaikki teille antanut.","Kaikki, jotka liikkuvat ja elävät, olkoon teille ruaksi: niinkuin viheriäisen ruohon, olen minä kaikki teille antanut."],[9,4,"Ainoastansa älkäät syökö lihaa, jossa vielä on veri itsessänsä:","Ainoastansa älkäät syökö lihaa, jossa vielä on veri itsessänsä:"],[9,5,"Ja totisesti minä tahdon vaatia teidän ruumiinne veren, kaikilta eläimiltä minä sen tahdon vaatia: ja ihmisen kädestä, ja myös itsekunkin hänen veljensä kädestä tahdon minä vaatia ihmisen hengen.","Ja totisesti minä tahdon vaatia teidän ruumiinne veren, kaikilta eläimiltä minä sen tahdon vaatia: ja ihmisen kädestä, ja myös itsekunkin hänen veljensä kädestä tahdon minä vaatia ihmisen hengen."],[9,6,"Se kuin ihmisen veren vuodattaa, hänen verensä pitää ihmisen kautta vuodatettaman: sillä Jumala on ihmisen tehnyt kuvaksensa.","Se kuin ihmisen veren vuodattaa, hänen verensä pitää ihmisen kautta vuodatettaman: sillä Jumala on ihmisen tehnyt kuvaksensa."],[9,7,"Olkaat siis hedelmälliset, lisääntykäät ja enentäkäät teitänne maassa, ja tulkaat siinä moneksi.","Olkaat siis hedelmälliset, lisääntykäät ja enentäkäät teitänne maassa, ja tulkaat siinä moneksi."],[9,8,"Ja Jumala puhui Noalle ja hänen pojillensa hänen kanssansa, sanoen:","Ja Jumala puhui Noalle ja hänen pojillensa hänen kanssansa, sanoen:"],[9,9,"Ja minä, katso, minä teen teidän kanssanne minun liittoni, ja teidän siemenenne kanssa teidän jälkeenne.","Ja minä, katso, minä teen teidän kanssanne minun liittoni, ja teidän siemenenne kanssa teidän jälkeenne."],[9,10,"Ja jokaisen elävän hengen kanssa, jotka teidän tykönänne ovat, sekä linnuissa että karjassa, ja kaikissa eläimissä maan päällä, jotka teidän tykönänne ovat, kaikissa niissä, jotka arkista läksivät, mikä ikänänsä eläin se maassa on.","Ja jokaisen elävän hengen kanssa, jotka teidän tykönänne ovat, sekä linnuissa että karjassa, ja kaikissa eläimissä maan päällä, jotka teidän tykönänne ovat, kaikissa niissä, jotka arkista läksivät, mikä ikänänsä eläin se maassa on."],[9,11,"Ja teen minun liittoni teidän kanssanne: ettei tästedes enää pidä kaikkea lihaa hukutettaman vedenpaisumisella: ja ei pidä tästedes enää vedenpaisumus tuleman maata turmelemaan.","Ja teen minun liittoni teidän kanssanne: ettei tästedes enää pidä kaikkea lihaa hukutettaman vedenpaisumisella: ja ei pidä tästedes enää vedenpaisumus tuleman maata turmelemaan."],[9,12,"Ja Jumala sanoi: tämä on sen liiton merkki, jonka minä annan minun ja teidän välillenne, ja joka elävän hengen välille teidän tykönänne, tästedes ijankaikkiseen.","Ja Jumala sanoi: tämä on sen liiton merkki, jonka minä annan minun ja teidän välillenne, ja joka elävän hengen välille teidän tykönänne, tästedes ijankaikkiseen."],[9,13,"Minun kaareni minä olen pannut pilviin: sen pitää oleman liiton merkki, minun ja maan välillä.","Minun kaareni minä olen pannut pilviin: sen pitää oleman liiton merkki, minun ja maan välillä."],[9,14,"Ja koska niin tapahtuu, että minä tuotan pilven maan ylitse: niin pitää kaari pilvissä nähtämän.","Ja koska niin tapahtuu, että minä tuotan pilven maan ylitse: niin pitää kaari pilvissä nähtämän."],[9,15,"Ja niin minä muistan minun liittoni, minun ja teidän välillänne, ja joka elävän hengen kaikkinaisessa lihassa; ettei enää vedenpaisumus pidä tuleman kaikkea lihaa hukuttamaan.","Ja niin minä muistan minun liittoni, minun ja teidän välillänne, ja joka elävän hengen kaikkinaisessa lihassa; ettei enää vedenpaisumus pidä tuleman kaikkea lihaa hukuttamaan."],[9,16,"Sentähden pitää kaaren pilvissä oleman, että minä katson sitä, ja muistan sen ijankaikkisen liiton Jumalan välillä ja joka elävän hengen, kaikkinaisessa lihassa, kuin maan päällä on.","Sentähden pitää kaaren pilvissä oleman, että minä katson sitä, ja muistan sen ijankaikkisen liiton Jumalan välillä ja joka elävän hengen, kaikkinaisessa lihassa, kuin maan päällä on."],[9,17,"Ja Jumala sanoi Noalle: tämä on sen liiton merkki, jonka minä olen tehnyt minun ja kaiken lihan välille maan päällä.","Ja Jumala sanoi Noalle: tämä on sen liiton merkki, jonka minä olen tehnyt minun ja kaiken lihan välille maan päällä."],[9,18,"Ja Noan pojat, jotka läksivät arkista, olivat Sem, Ham, ja Japhet. Ja Ham oli Kanaanin Isä.","Ja Noan pojat, jotka läksivät arkista, olivat Sem, Ham, ja Japhet. Ja Ham oli Kanaanin Isä."],[9,19,"Nämä ovat kolme Noan poikaa, ja heistä ovat ne, jotka hajoitetut ovat kaikkeen maahan.","Nämä ovat kolme Noan poikaa, ja heistä ovat ne, jotka hajoitetut ovat kaikkeen maahan."],[9,20,"Ja Noa rupesi olemaan peltomiesnä, ja istutti viinamäen.","Ja Noa rupesi olemaan peltomiesnä, ja istutti viinamäen."],[9,21,"Ja hän joi viinaa; ja juopui ja makasi peittämättä majassansa.","Ja hän joi viinaa; ja juopui ja makasi peittämättä majassansa."],[9,22,"Koska Ham, Kanaanin Isä, näki hänen isänsä hävyn, sanoi hän sen molemmille veljillensä, jotka ulkona olivat.","Koska Ham, Kanaanin Isä, näki hänen isänsä hävyn, sanoi hän sen molemmille veljillensä, jotka ulkona olivat."],[9,23,"Niin otti Sem ja Japhet vaatteen, ja panivat molempain heidän hartioillensa, ja menivät seljittäin, ja peittivät isänsä hävyn. Ja heidän kasvonsa olivat käännetyt pois, niin etteivät he nähneet isänsä häpyä.","Niin otti Sem ja Japhet vaatteen, ja panivat molempain heidän hartioillensa, ja menivät seljittäin, ja peittivät isänsä hävyn. Ja heidän kasvonsa olivat käännetyt pois, niin etteivät he nähneet isänsä häpyä."],[9,24,"Koska Noa heräsi viinastansa, ja sai tietää, mitä hänen nuorin poikansa hänelle tehnyt oli:","Koska Noa heräsi viinastansa, ja sai tietää, mitä hänen nuorin poikansa hänelle tehnyt oli:"],[9,25,"Niin sanoi hän: kirottu olkoon Kanaan: olkoon hän orjain orja, hänen veljeinsä seassa.","Niin sanoi hän: kirottu olkoon Kanaan: olkoon hän orjain orja, hänen veljeinsä seassa."],[9,26,"Ja vielä sanoi: Kiitetty olkoon Herra Semin Jumala, ja Kanaan olkoon hänen orjansa.","Ja vielä sanoi: Kiitetty olkoon Herra Semin Jumala, ja Kanaan olkoon hänen orjansa."],[9,27,"Jumala levittäköön Japhetin, ja hän asukoon Semin majoissa, ja Kanaan olkoon hänen orjansa.","Jumala levittäköön Japhetin, ja hän asukoon Semin majoissa, ja Kanaan olkoon hänen orjansa."],[9,28,"Ja Noa eli, vedenpaisumisen jälkeen kolmesataa ja viisikymmentä ajastaikaa.","Ja Noa eli, vedenpaisumisen jälkeen kolmesataa ja viisikymmentä ajastaikaa."],[9,29,"Ja koko Noan ikä oli yhdeksänsataa ja viisikymmentä ajastaikaa, ja kuoli.","Ja koko Noan ikä oli yhdeksänsataa ja viisikymmentä ajastaikaa, ja kuoli."],[10,1,"Tämä on Noan lasten sukukunta: Semin, Hamin ja Japhetin: ja heille syntyi lapsia vedenpaisumisen jälkeen.","Tämä on Noan lasten sukukunta: Semin, Hamin ja Japhetin: ja heille syntyi lapsia vedenpaisumisen jälkeen."],[10,2,"Japhetin lapset: Gomer, Magog, Madai, Javan ja Tubal: Mesek ja Tiras.","Japhetin lapset: Gomer, Magog, Madai, Javan ja Tubal: Mesek ja Tiras."],[10,3,"Mutta Gomerin lapset: Askenas, Riphad ja Togarma.","Mutta Gomerin lapset: Askenas, Riphad ja Togarma."],[10,4,"Javanin lapset: Elisa ja Tarsis: Kittim ja Dodanim.","Javanin lapset: Elisa ja Tarsis: Kittim ja Dodanim."],[10,5,"Näistä ovat hajoitetut pakanain luodot, heidän maakunnissansa, itsekukin oman kielensä jälkeen: heidän sukukuntainsa jälkeen, heidän kansoissansa.","Näistä ovat hajoitetut pakanain luodot, heidän maakunnissansa, itsekukin oman kielensä jälkeen: heidän sukukuntainsa jälkeen, heidän kansoissansa."],[10,6,"Hamin lapset: Kus, Misraim, Put ja Kanaan.","Hamin lapset: Kus, Misraim, Put ja Kanaan."],[10,7,"Kuksen lapset: Seba, Hevila, Sabta, Naema ja Sabteka. Naeman lapset: Skepa ja Dedan.","Kuksen lapset: Seba, Hevila, Sabta, Naema ja Sabteka. Naeman lapset: Skepa ja Dedan."],[10,8,"Mutta Kus siitti Nimrodin: hän rupesi olemaan valtias maalla.","Mutta Kus siitti Nimrodin: hän rupesi olemaan valtias maalla."],[10,9,"Ja hän oli jalo metsämies Herran edessä. Siitä on sananlasku: se on jalo metsämies Herran edessä, niinkuin Nimrod.","Ja hän oli jalo metsämies Herran edessä. Siitä on sananlasku: se on jalo metsämies Herran edessä, niinkuin Nimrod."],[10,10,"Ja hänen valtakuntansa alku oli Babel, Erek, Akad ja Kalne, Sinearin maalla.","Ja hänen valtakuntansa alku oli Babel, Erek, Akad ja Kalne, Sinearin maalla."],[10,11,"Siitä maakunnasta tuli hän Assyriaan: ja rakensi Niniven, ja Rehobotin kaupungin, ja Kalan.","Siitä maakunnasta tuli hän Assyriaan: ja rakensi Niniven, ja Rehobotin kaupungin, ja Kalan."],[10,12,"Ja myös Ressen, Niniven ja Kalan vaiheelle: joka on suuri kaupunki.","Ja myös Ressen, Niniven ja Kalan vaiheelle: joka on suuri kaupunki."],[10,13,"Misraim siitti Ludimin, Anamimin, Leabimin, Naphtuhimin.","Misraim siitti Ludimin, Anamimin, Leabimin, Naphtuhimin."],[10,14,"Patrusimin ja Kasluhimin; joista tulleet ovat Philistim ja Kaphtorim.","Patrusimin ja Kasluhimin; joista tulleet ovat Philistim ja Kaphtorim."],[10,15,"Mutta Kanaan siitti esikoisensa Sidonin ja Hetin.","Mutta Kanaan siitti esikoisensa Sidonin ja Hetin."],[10,16,"Ja Jebusin, Emorin, Girgosin.","Ja Jebusin, Emorin, Girgosin."],[10,17,"Hivin, Arkin, Sinin,","Hivin, Arkin, Sinin,"],[10,18,"Ja Arvadin, Semarin ja Hamatin. Sitten ovat hajoitetut Kanaanealaisten suvut.","Ja Arvadin, Semarin ja Hamatin. Sitten ovat hajoitetut Kanaanealaisten suvut."],[10,19,"Ja Kanaanealaisten rajat olivat Sidonista Gerarin kautta hamaan Gatsaan: Sodomaan, ja Gomorraan, ja Adamaan, Seboimiin päin, Lasaan asti.","Ja Kanaanealaisten rajat olivat Sidonista Gerarin kautta hamaan Gatsaan: Sodomaan, ja Gomorraan, ja Adamaan, Seboimiin päin, Lasaan asti."],[10,20,"Nämät ovat Hamin lapset heidän sukukuntainsa ja kieltensä jälkeen: heidän maakunnissansa ja kansoissansa.","Nämät ovat Hamin lapset heidän sukukuntainsa ja kieltensä jälkeen: heidän maakunnissansa ja kansoissansa."],[10,21,"Mutta myös itse Semille syntyi lapsia: hän oli kaikkein Eberin lasten isä: Japhetin sen vanhimman veli.","Mutta myös itse Semille syntyi lapsia: hän oli kaikkein Eberin lasten isä: Japhetin sen vanhimman veli."],[10,22,"(Ja nämät ovat) Semin lapset: Elam ja Assur: Arphaksad, Lud ja Aram.","(Ja nämät ovat) Semin lapset: Elam ja Assur: Arphaksad, Lud ja Aram."],[10,23,"Ja Aramin lapset: Uts, Hul, Geter ja Mas.","Ja Aramin lapset: Uts, Hul, Geter ja Mas."],[10,24,"Mutta Arphaksad siitti Salan: Sala siitti Eberin.","Mutta Arphaksad siitti Salan: Sala siitti Eberin."],[10,25,"Eberille syntyi kaksi poikaa: yksi kutsuttiin Peleg, että hänen aikanansa maailma jaettiin: hänen veljensä kutsuttiin Joktan.","Eberille syntyi kaksi poikaa: yksi kutsuttiin Peleg, että hänen aikanansa maailma jaettiin: hänen veljensä kutsuttiin Joktan."],[10,26,"Joktan siitti Almodadin ja Salephin: Hasarmavetin ja Jaran.","Joktan siitti Almodadin ja Salephin: Hasarmavetin ja Jaran."],[10,27,"Hadoramin, Usalin, Dikelan.","Hadoramin, Usalin, Dikelan."],[10,28,"Obalin, Abimaelin, Seban.","Obalin, Abimaelin, Seban."],[10,29,"Ophirin, Hevilan ja Jobabin. Kaikki nämä ovat Joktanin pojat.","Ophirin, Hevilan ja Jobabin. Kaikki nämä ovat Joktanin pojat."],[10,30,"Ja heidän asumasiansa oli Mesasta: siihen asti kuin Sephariin tullaan, vuoren tykö, itään päin.","Ja heidän asumasiansa oli Mesasta: siihen asti kuin Sephariin tullaan, vuoren tykö, itään päin."],[10,31,"Nämät ovat Semin lapset, sukukuntainsa ja kieltensä jälkeen: heidän maakunnissansa, kansainsa jälkeen.","Nämät ovat Semin lapset, sukukuntainsa ja kieltensä jälkeen: heidän maakunnissansa, kansainsa jälkeen."],[10,32,"Nämät ovat Noan lasten sukukunnat, heidän heimokuntainsa jälkeen, heidän kansoissansa. Ja näistä ovat kansat jaetut maan päälle vedenpaisumisen jälkeen.","Nämät ovat Noan lasten sukukunnat, heidän heimokuntainsa jälkeen, heidän kansoissansa. Ja näistä ovat kansat jaetut maan päälle vedenpaisumisen jälkeen."],[11,1,"Ja koko maailmalla oli yhtäläinen kieli ja yhtäläinen puheenparsi.","Ja koko maailmalla oli yhtäläinen kieli ja yhtäläinen puheenparsi."],[11,2,"Ja koska he matkustivat idästä, löysivät he kedon Sinearin maalla, ja asuivat siellä.","Ja koska he matkustivat idästä, löysivät he kedon Sinearin maalla, ja asuivat siellä."],[11,3,"Ja sanoivat keskenänsä: käykäämme tiilejä tekemään ja polttamaan. Ja heillä olivat tiilit kivein siassa, ja maan pihka siteeksi.","Ja sanoivat keskenänsä: käykäämme tiilejä tekemään ja polttamaan. Ja heillä olivat tiilit kivein siassa, ja maan pihka siteeksi."],[11,4,"Ja sanoivat: käykäämme, rakentakaamme meillemme kaupunki ja torni, joka taivaaseen ulottuisi, tehdäksemme meillemme nimeä; ettei meitä hajoitettaisi kaikkiin maihin.","Ja sanoivat: käykäämme, rakentakaamme meillemme kaupunki ja torni, joka taivaaseen ulottuisi, tehdäksemme meillemme nimeä; ettei meitä hajoitettaisi kaikkiin maihin."],[11,5,"Silloin Herra astui alas katsomaan kaupunkia ja tornia, jota ihmisten lapset rakensivat.","Silloin Herra astui alas katsomaan kaupunkia ja tornia, jota ihmisten lapset rakensivat."],[11,6,"Ja Herra sanoi: katso, se on yhtäläinen kansa, ja yhtäläinen kieli on kaikkein heidän seassansa, ja he ovat ruvenneet tätä tekemään: ja nyt ei heitä taideta estettää mistään, kuin he ovat aikoneet tehdä.","Ja Herra sanoi: katso, se on yhtäläinen kansa, ja yhtäläinen kieli on kaikkein heidän seassansa, ja he ovat ruvenneet tätä tekemään: ja nyt ei heitä taideta estettää mistään, kuin he ovat aikoneet tehdä."],[11,7,"Käykäämme, astukaamme alas ja sekoittakaamme siellä heidän kielensä; niin ettei kenkään ymmärtäisi toisensa kieltä.","Käykäämme, astukaamme alas ja sekoittakaamme siellä heidän kielensä; niin ettei kenkään ymmärtäisi toisensa kieltä."],[11,8,"Ja niin Herra hajoitti heidät sieltä kaikkiin maihin; ja he lakkasivat sitä kaupunkia rakentamasta.","Ja niin Herra hajoitti heidät sieltä kaikkiin maihin; ja he lakkasivat sitä kaupunkia rakentamasta."],[11,9,"Ja sentähden kutsuttiin hänen nimensä Babel: sillä siellä Herra sekoitti koko maan kielen: ja Herra hajoitti heidät sieltä kaikkiin maihin.","Ja sentähden kutsuttiin hänen nimensä Babel: sillä siellä Herra sekoitti koko maan kielen: ja Herra hajoitti heidät sieltä kaikkiin maihin."],[11,10,"Nämät ovat Semin sukukunnat: Sem oli sadan ajastajan vanha, ja siitti Arphaksadin, kaksi ajastaikaa vedenpaisumisen jälkeen.","Nämät ovat Semin sukukunnat: Sem oli sadan ajastajan vanha, ja siitti Arphaksadin, kaksi ajastaikaa vedenpaisumisen jälkeen."],[11,11,"Ja eli sitte viisisataa ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte viisisataa ajastaikaa, ja siitti poikia ja tyttäriä."],[11,12,"Arphaksad oli viidenneljättäkymmentä ajastajan vanha, ja siitti Salan.","Arphaksad oli viidenneljättäkymmentä ajastajan vanha, ja siitti Salan."],[11,13,"Ja eli sitte neljäsataa ja kolme ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte neljäsataa ja kolme ajastaikaa, ja siitti poikia ja tyttäriä."],[11,14,"Sala oli kolmenkymmenen ajastajan vanha, ja siitti Eberin.","Sala oli kolmenkymmenen ajastajan vanha, ja siitti Eberin."],[11,15,"Ja eli sitte neljäsataa ja kolme ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte neljäsataa ja kolme ajastaikaa, ja siitti poikia ja tyttäriä."],[11,16,"Eber oli neljänneljättäkymmentä ajastajan vanha, ja siitti Pelegin.","Eber oli neljänneljättäkymmentä ajastajan vanha, ja siitti Pelegin."],[11,17,"Ja eli sitte neljäsataa ja kolmekymmentä ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte neljäsataa ja kolmekymmentä ajastaikaa, ja siitti poikia ja tyttäriä."],[11,18,"Peleg oli kolmenkymmenen ajastajan vanha, ja siitti Regun.","Peleg oli kolmenkymmenen ajastajan vanha, ja siitti Regun."],[11,19,"Ja eli sitte kaksisataa ja yhdeksän ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kaksisataa ja yhdeksän ajastaikaa, ja siitti poikia ja tyttäriä."],[11,20,"Regu oli kahdenneljättäkymmentä ajastajan vanha, ja siitti Serugin.","Regu oli kahdenneljättäkymmentä ajastajan vanha, ja siitti Serugin."],[11,21,"Ja eli sitte kaksisataa ja seitsemän ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kaksisataa ja seitsemän ajastaikaa, ja siitti poikia ja tyttäriä."],[11,22,"Serug oli kolmenkymmenen ajastajan vanha ja siitti Nahorin.","Serug oli kolmenkymmenen ajastajan vanha ja siitti Nahorin."],[11,23,"Ja eli sitte kaksisataa ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte kaksisataa ajastaikaa, ja siitti poikia ja tyttäriä."],[11,24,"Nahor oli yhdeksänkolmattakymmentä ajastajan vanha, ja siitti Taran.","Nahor oli yhdeksänkolmattakymmentä ajastajan vanha, ja siitti Taran."],[11,25,"Ja eli sitte sata ja yhdeksäntoistakymmentä ajastaikaa, ja siitti poikia ja tyttäriä.","Ja eli sitte sata ja yhdeksäntoistakymmentä ajastaikaa, ja siitti poikia ja tyttäriä."],[11,26,"Tara oli seitsemänkymmenen ajastajan vanha, ja siitti Abramin, Nahorin ja Haranin.","Tara oli seitsemänkymmenen ajastajan vanha, ja siitti Abramin, Nahorin ja Haranin."],[11,27,"Nämät ovat Taran sukukunnat: Tara siitti Abramin, Nahorin ja Haranin. Haran siitti Lotin.","Nämät ovat Taran sukukunnat: Tara siitti Abramin, Nahorin ja Haranin. Haran siitti Lotin."],[11,28,"Ja Haran kuoli isänsä, Taran edessä, isänsä maalla Kaldean Uurissa.","Ja Haran kuoli isänsä, Taran edessä, isänsä maalla Kaldean Uurissa."],[11,29,"Silloin Abram ja Nahor ottivat heillensä emännät: Abramin emännän nimi oli Sarai, ja Nahorin emännän nimi oli Milka, Haranin tytär, joka oli Milkan ja Jiskan isä.","Silloin Abram ja Nahor ottivat heillensä emännät: Abramin emännän nimi oli Sarai, ja Nahorin emännän nimi oli Milka, Haranin tytär, joka oli Milkan ja Jiskan isä."],[11,30,"Mutta Sarai oli hedelmätöin, eikä ollut hänellä lasta.","Mutta Sarai oli hedelmätöin, eikä ollut hänellä lasta."],[11,31,"Ja Tara otti poikansa Abramin ja Lotin Haranin pojan, poikansa pojan, ja miniänsä Sarain, poikansa Abramin emännän, ja he läksivät ulos ynnä Kaldean Uurista menemään Kanaanin maalle, ja tulivat Haraniin, ja asuivat siellä.","Ja Tara otti poikansa Abramin ja Lotin Haranin pojan, poikansa pojan, ja miniänsä Sarain, poikansa Abramin emännän, ja he läksivät ulos ynnä Kaldean Uurista menemään Kanaanin maalle, ja tulivat Haraniin, ja asuivat siellä."],[11,32,"Ja Tara oli kahdensadan ja viiden ajastajan vanha ja kuoli Haranissa.","Ja Tara oli kahdensadan ja viiden ajastajan vanha ja kuoli Haranissa."],[12,1,"Ja Herra oli sanonut Abramille: Lähde maaltas, ja suvustas, ja isäs huoneesta: sille maalle, jonka minä sinulle osoitan.","Ja Herra oli sanonut Abramille: Lähde maaltas, ja suvustas, ja isäs huoneesta: sille maalle, jonka minä sinulle osoitan."],[12,2,"Ja minä teen sinun suureksi kansaksi, ja siunaan sinun, ja teen sinulle suuren nimen, ja sinä olet siunaus.","Ja minä teen sinun suureksi kansaksi, ja siunaan sinun, ja teen sinulle suuren nimen, ja sinä olet siunaus."],[12,3,"Minä siunaan niitä, jotka sinua siunaavat, ja kiroon niitä, jotka sinua kiroovat. Ja sinussa pitää kaikki sukukunnat maan päällä siunatuiksi tuleman.","Minä siunaan niitä, jotka sinua siunaavat, ja kiroon niitä, jotka sinua kiroovat. Ja sinussa pitää kaikki sukukunnat maan päällä siunatuiksi tuleman."],[12,4,"Niin Abram läksi, niinkuin Herra hänelle sanonut oli, ja Lot meni hänen kanssansa: Mutta Abram oli viidenkahdeksattakymmentä ajastajan vanha Haranista lähteissänsä.","Niin Abram läksi, niinkuin Herra hänelle sanonut oli, ja Lot meni hänen kanssansa: Mutta Abram oli viidenkahdeksattakymmentä ajastajan vanha Haranista lähteissänsä."],[12,5,"Niin otti Abram emäntänsä Sarain, ja Lotin, veljensä pojan, tavaroinensa, jotka he olivat panneet kokoon, ja sielut, jotka he olivat saaneet Haranissa, ja läksivät matkustamaan Kanaanin maalle; tulivat myös Kanaanin maalle.","Niin otti Abram emäntänsä Sarain, ja Lotin, veljensä pojan, tavaroinensa, jotka he olivat panneet kokoon, ja sielut, jotka he olivat saaneet Haranissa, ja läksivät matkustamaan Kanaanin maalle; tulivat myös Kanaanin maalle."],[12,6,"Ja Abram vaelsi sen maakunnan lävitse, hamaan Sikemin paikkakuntaan, Moren lakeuteen asti. Ja siihen aikaan asuivat Kanaanealaiset maalla.","Ja Abram vaelsi sen maakunnan lävitse, hamaan Sikemin paikkakuntaan, Moren lakeuteen asti. Ja siihen aikaan asuivat Kanaanealaiset maalla."],[12,7,"Silloin näkyi Herra Abramille, ja sanoi: sinun siemenelles annan minä tämän maan. Ja hän rakensi siinä alttarin Herralle, joka hänelle näkynyt oli.","Silloin näkyi Herra Abramille, ja sanoi: sinun siemenelles annan minä tämän maan. Ja hän rakensi siinä alttarin Herralle, joka hänelle näkynyt oli."],[12,8,"Sitte siirsi hän itsensä edemmä vuoren tykö, BetElistä itään päin, ja pani siihen majansa, niin että BetEl oli lännen puolella ja Ai idän puolella, ja rakensi siinä alttarin Herralle, ja saarnasi Herran nimestä.","Sitte siirsi hän itsensä edemmä vuoren tykö, BetElistä itään päin, ja pani siihen majansa, niin että BetEl oli lännen puolella ja Ai idän puolella, ja rakensi siinä alttarin Herralle, ja saarnasi Herran nimestä."],[12,9,"Ja Abram läksi sieltä edemmä, ja vaelsi etelään päin.","Ja Abram läksi sieltä edemmä, ja vaelsi etelään päin."],[12,10,"Niin tuli kova aika maalle, ja Abram meni alas Egyptiin, olemaan muukalaisna siellä: sillä sangen kova aika oli maalla.","Niin tuli kova aika maalle, ja Abram meni alas Egyptiin, olemaan muukalaisna siellä: sillä sangen kova aika oli maalla."],[12,11,"Ja tapahtui, koska hän lähestyi Egyptiä, puhui hän emännällensä Saraille: katso armaani, minä tiedän sinun ihanaksi vaimoksi nähdä.","Ja tapahtui, koska hän lähestyi Egyptiä, puhui hän emännällensä Saraille: katso armaani, minä tiedän sinun ihanaksi vaimoksi nähdä."],[12,12,"Koska Egyptiläiset saavat sinun nähdä, niin he sanovat: tämä on hänen emäntänsä, ja tappavat minun, ja antavat sinun elää.","Koska Egyptiläiset saavat sinun nähdä, niin he sanovat: tämä on hänen emäntänsä, ja tappavat minun, ja antavat sinun elää."],[12,13,"Sanos siis itses minun sisarekseni; että minulle hyvin olis sinun tähtes, ja minä eläisin sinun vuokses.","Sanos siis itses minun sisarekseni; että minulle hyvin olis sinun tähtes, ja minä eläisin sinun vuokses."],[12,14,"Koska Abram tuli Egyptiin, näkivät Egyptiläiset vaimon juuri ihanaksi.","Koska Abram tuli Egyptiin, näkivät Egyptiläiset vaimon juuri ihanaksi."],[12,15,"Ja Pharaon ruhtinaat näkivät hänen, ja ylistivät häntä Pharaon edessä: silloin vietiin vaimo Pharaon huoneeseen.","Ja Pharaon ruhtinaat näkivät hänen, ja ylistivät häntä Pharaon edessä: silloin vietiin vaimo Pharaon huoneeseen."],[12,16,"Ja Abramille tehtiin hyvin hänen tähtensä. Ja hänellä oli lampaita ja karjaa, ja aaseja, ja palvelioita, ja piikoja, ja aasintammoja ja kameleja.","Ja Abramille tehtiin hyvin hänen tähtensä. Ja hänellä oli lampaita ja karjaa, ja aaseja, ja palvelioita, ja piikoja, ja aasintammoja ja kameleja."],[12,17,"Mutta Herra vitsasi Pharaota suurilla vitsauksilla, ja hänen huonettansa, Sarain Abramin emännän tähden.","Mutta Herra vitsasi Pharaota suurilla vitsauksilla, ja hänen huonettansa, Sarain Abramin emännän tähden."],[12,18,"Silloin kutsui Pharao Abramin tykönsä, ja sanoi: miksis tämän minulle teit? miksi et ilmoittanut minulle häntä emännäkses?","Silloin kutsui Pharao Abramin tykönsä, ja sanoi: miksis tämän minulle teit? miksi et ilmoittanut minulle häntä emännäkses?"],[12,19,"Miksis sanoit, hän on sisareni? että minä ottaisin hänen emännäkseni? katso tässä on sinun emäntäs, ota häntä ja mene.","Miksis sanoit, hän on sisareni? että minä ottaisin hänen emännäkseni? katso tässä on sinun emäntäs, ota häntä ja mene."],[12,20,"Ja Pharao antoi käskyn hänestä miehillensä: ja he saattoivat hänen ulos ja hänen emäntänsä, ja kaikki kuin hänellä oli.","Ja Pharao antoi käskyn hänestä miehillensä: ja he saattoivat hänen ulos ja hänen emäntänsä, ja kaikki kuin hänellä oli."],[13,1,"Niin Abram vaelsi ylös Egyptistä emäntänsä ja kaiken kalunsa kanssa, ja Lot hänen kanssansa, etelään päin.","Niin Abram vaelsi ylös Egyptistä emäntänsä ja kaiken kalunsa kanssa, ja Lot hänen kanssansa, etelään päin."],[13,2,"Ja Abramilla oli sangen paljo karjaa, hopiaa ja kultaa.","Ja Abramilla oli sangen paljo karjaa, hopiaa ja kultaa."],[13,3,"Ja hän matkusti edespäin etelästä BetEliin asti, hamaan siihen paikkaan, jossa hänen majansa oli ennen ollut, BetElin ja Ain vaiheella:","Ja hän matkusti edespäin etelästä BetEliin asti, hamaan siihen paikkaan, jossa hänen majansa oli ennen ollut, BetElin ja Ain vaiheella:"],[13,4,"Juuri siihen paikkaan, johon hän ennen alttarin oli rakentanut; ja Abram saarnasi siinä Herran nimestä.","Juuri siihen paikkaan, johon hän ennen alttarin oli rakentanut; ja Abram saarnasi siinä Herran nimestä."],[13,5,"Mutta Lotilla, joka Abramia seurasi, oli myös lampaita, ja karjaa, ja majoja.","Mutta Lotilla, joka Abramia seurasi, oli myös lampaita, ja karjaa, ja majoja."],[13,6,"Ja ei heitä vetänyt maa yhdessä asumaan; sillä heillä oli paljo tavaraa, eikä taitaneet yhdessä asua.","Ja ei heitä vetänyt maa yhdessä asumaan; sillä heillä oli paljo tavaraa, eikä taitaneet yhdessä asua."],[13,7,"Ja riita oli Abramin paimenien ja Lotin paimenien välillä: Ja siihen aikaan asuivat myös Kanaanealaiset ja Pheresiläiset maalla.","Ja riita oli Abramin paimenien ja Lotin paimenien välillä: Ja siihen aikaan asuivat myös Kanaanealaiset ja Pheresiläiset maalla."],[13,8,"Niin Abram sanoi Lotille: älkään olko riita minun ja sinun välilläs, ja minun ja sinun paimentes välillä: sillä me olemme miehet veljekset.","Niin Abram sanoi Lotille: älkään olko riita minun ja sinun välilläs, ja minun ja sinun paimentes välillä: sillä me olemme miehet veljekset."],[13,9,"Eikö koko maa ole edessäs altis? eroita sinus minusta, jos sinä menet vasemmalle puolelle, minä menen oikialle, eli jos sinä menet oikialle, minä menen vasemmalle.","Eikö koko maa ole edessäs altis? eroita sinus minusta, jos sinä menet vasemmalle puolelle, minä menen oikialle, eli jos sinä menet oikialle, minä menen vasemmalle."],[13,10,"Niin Lot nosti silmänsä, ja katseli kaiken Jordanin lakeuden; sillä se oli vedestä viljainen: ennen kuin Herra Sodoman ja Gomorran hukutti, oli se niinkuin Herran yrttitarha, niinkuin Egyptin maa, siihenasti kuin Zoariin tullaan.","Niin Lot nosti silmänsä, ja katseli kaiken Jordanin lakeuden; sillä se oli vedestä viljainen: ennen kuin Herra Sodoman ja Gomorran hukutti, oli se niinkuin Herran yrttitarha, niinkuin Egyptin maa, siihenasti kuin Zoariin tullaan."],[13,11,"Ja Lot vallitsi itsellensä koko sen lakeuden Jordanin tykönä, ja matkusti itään päin: ja niin veljekset erkanivat toinen toisestansa:","Ja Lot vallitsi itsellensä koko sen lakeuden Jordanin tykönä, ja matkusti itään päin: ja niin veljekset erkanivat toinen toisestansa:"],[13,12,"Että Abram asui Kanaanin maalla, ja Lot asui lakeuden kaupungeissa, ja pani majansa Sodoman puoleen.","Että Abram asui Kanaanin maalla, ja Lot asui lakeuden kaupungeissa, ja pani majansa Sodoman puoleen."],[13,13,"Mutta Sodoman kansa oli paha, ja rikkoi kovin Herraa vastaan.","Mutta Sodoman kansa oli paha, ja rikkoi kovin Herraa vastaan."],[13,14,"Ja Herra sanoi Abramille, sitte kuin Lot oli eroittanut itsensä Abramista: nosta nyt silmäs ja katso siitä, kussas asut, pohjan puoleen, etelän puoleen, idän puoleen ja lännen puoleen.","Ja Herra sanoi Abramille, sitte kuin Lot oli eroittanut itsensä Abramista: nosta nyt silmäs ja katso siitä, kussas asut, pohjan puoleen, etelän puoleen, idän puoleen ja lännen puoleen."],[13,15,"Sillä kaiken sen maan, minkä sinä näet, annan minä sinulle, ja sinun siemenelles ijankaikkiseksi.","Sillä kaiken sen maan, minkä sinä näet, annan minä sinulle, ja sinun siemenelles ijankaikkiseksi."],[13,16,"Ja teen sinun siemenes niinkuin tomun maan päällä: että jos joku taita lukea tomun maan päällä, niin hän myös taitaa sinun siemenes lukea.","Ja teen sinun siemenes niinkuin tomun maan päällä: että jos joku taita lukea tomun maan päällä, niin hän myös taitaa sinun siemenes lukea."],[13,17,"Nouse ja vaella maata pitkin ja poikin: sillä sinulle minä sen annan.","Nouse ja vaella maata pitkin ja poikin: sillä sinulle minä sen annan."],[13,18,"Niin Abram siirsi majansa, ja tuli, ja asui Mamren lakeudella, joka on Hebronissa: ja rakensi siinä alttarin Herralle.","Niin Abram siirsi majansa, ja tuli, ja asui Mamren lakeudella, joka on Hebronissa: ja rakensi siinä alttarin Herralle."],[14,1,"Ja tapahtui Amraphelin Sinearin kuninkaan, Ariokin Elassarin kuninkaan, Kedorlaomerin Elamin kuninkaan, ja Tidealin pakanoitten kuninkaan aikana:","Ja tapahtui Amraphelin Sinearin kuninkaan, Ariokin Elassarin kuninkaan, Kedorlaomerin Elamin kuninkaan, ja Tidealin pakanoitten kuninkaan aikana:"],[14,2,"Että he sotivat Bereaa Sodoman kuningasta, ja Birsaa Gomorran kuningasta, ja Sineabia Adaman kuningasta, ja Semeberiä Zeboimin kuningasta, ja Belan, se on Zoarin, kuningasta vastaan.","Että he sotivat Bereaa Sodoman kuningasta, ja Birsaa Gomorran kuningasta, ja Sineabia Adaman kuningasta, ja Semeberiä Zeboimin kuningasta, ja Belan, se on Zoarin, kuningasta vastaan."],[14,3,"Nämät kaikki tulivat yhteen Siddimin laaksossa; se on suolainen meri:","Nämät kaikki tulivat yhteen Siddimin laaksossa; se on suolainen meri:"],[14,4,"Sillä he olivat olleet kaksitoistakymmentä ajastaikaa kuningas Kedorlaomerin alla; mutta kolmantenatoistakymmenentenä ajastaikana olivat he hänestä luopuneet.","Sillä he olivat olleet kaksitoistakymmentä ajastaikaa kuningas Kedorlaomerin alla; mutta kolmantenatoistakymmenentenä ajastaikana olivat he hänestä luopuneet."],[14,5,"Neljäntenätoistakymmenentenä ajastaikana tuli Kedorlaomer, ja ne kuninkaat, kuin hänen kanssansa olivat, ja löivät ne Kalevan pojat Karnaimin Astarotissa, ja Susimin Hammissa; niin myös Emimin Sjaven Kirjataimissa:","Neljäntenätoistakymmenentenä ajastaikana tuli Kedorlaomer, ja ne kuninkaat, kuin hänen kanssansa olivat, ja löivät ne Kalevan pojat Karnaimin Astarotissa, ja Susimin Hammissa; niin myös Emimin Sjaven Kirjataimissa:"],[14,6,"Ja Horilaiset Seirin vuorella; siihen lakiaan paikkaan Pharaniin asti, korpea liki.","Ja Horilaiset Seirin vuorella; siihen lakiaan paikkaan Pharaniin asti, korpea liki."],[14,7,"Ja he palasivat ja tulivat Mispatin lähteen tykö, se on Kades, ja löivät koko Amalekilaisten maan; niin myös Amorilaiset, jotka asuivat Hasesonin Tamarissa.","Ja he palasivat ja tulivat Mispatin lähteen tykö, se on Kades, ja löivät koko Amalekilaisten maan; niin myös Amorilaiset, jotka asuivat Hasesonin Tamarissa."],[14,8,"Niin läksivät Sodoman kuningas, ja Gomorran kuningas, ja Adaman kuningas, ja Zeboimin kuningas, ja Belan, se on Zoarin kuningas: ja hankitsivat sotaan heitä vastaan Siddimin laaksossa:","Niin läksivät Sodoman kuningas, ja Gomorran kuningas, ja Adaman kuningas, ja Zeboimin kuningas, ja Belan, se on Zoarin kuningas: ja hankitsivat sotaan heitä vastaan Siddimin laaksossa:"],[14,9,"Kedorlaomeria Elamin kuningasta, ja Tibealia pakanoitten kuningasta, ja Amraphelia Sinearin kuningasta, ja Ariokia Elassarin kuningasta vastaan: neljä kuningasta viittä vastaan.","Kedorlaomeria Elamin kuningasta, ja Tibealia pakanoitten kuningasta, ja Amraphelia Sinearin kuningasta, ja Ariokia Elassarin kuningasta vastaan: neljä kuningasta viittä vastaan."],[14,10,"Ja Siddimin laaksossa oli monta maanpihkakuoppaa. Mutta Sodoman ja Gomorran kuningas siinä pakoon ja maahan lyötiin, ja jääneet pakenivat vuorille.","Ja Siddimin laaksossa oli monta maanpihkakuoppaa. Mutta Sodoman ja Gomorran kuningas siinä pakoon ja maahan lyötiin, ja jääneet pakenivat vuorille."],[14,11,"Ja he ottivat kaiken Sodoman ja Gomorran tavaran, ja kaiken heidän elatuksensa, ja menivät matkaansa.","Ja he ottivat kaiken Sodoman ja Gomorran tavaran, ja kaiken heidän elatuksensa, ja menivät matkaansa."],[14,12,"Ja ottivat myös Lotin Abramin veljen pojan kanssansa, ja hänen tavaransa, ja menivät matkaansa, sillä hän asui Sodomassa.","Ja ottivat myös Lotin Abramin veljen pojan kanssansa, ja hänen tavaransa, ja menivät matkaansa, sillä hän asui Sodomassa."],[14,13,"Silloin tuli yksi joka päässyt oli, ja ilmoitti sen Abramille Hebrealaiselle, joka asui Mamren Amorilaisen lakeudella, joka Eskolin ja Anerin veli oli. Nämät olivat liitossa Abramin kanssa.","Silloin tuli yksi joka päässyt oli, ja ilmoitti sen Abramille Hebrealaiselle, joka asui Mamren Amorilaisen lakeudella, joka Eskolin ja Anerin veli oli. Nämät olivat liitossa Abramin kanssa."],[14,14,"Koska Abram kuuli veljensä otetuksi kiini, varusti hän omaa kotona syntynyttä palveliaansa kolmesataa ja kahdeksantoistakymmentä, ja ajoi takaa heitä Daniin asti.","Koska Abram kuuli veljensä otetuksi kiini, varusti hän omaa kotona syntynyttä palveliaansa kolmesataa ja kahdeksantoistakymmentä, ja ajoi takaa heitä Daniin asti."],[14,15,"Jakoi itsensä ja karkasi heidän päällensä yöllä palvelioinensa, ja löi heitä: ja ajoi takaa hamaan Hobaan, joka on vasemmalla puolella Damaskua.","Jakoi itsensä ja karkasi heidän päällensä yöllä palvelioinensa, ja löi heitä: ja ajoi takaa hamaan Hobaan, joka on vasemmalla puolella Damaskua."],[14,16,"Ja toi jällensä kaiken tavaran: ja myös veljensä Lotin ja hänen tavaransa toi hän jällensä, niin myös vaimot ja väen.","Ja toi jällensä kaiken tavaran: ja myös veljensä Lotin ja hänen tavaransa toi hän jällensä, niin myös vaimot ja väen."],[14,17,"Silloin meni Sodoman kuningas häntä vastaan, koska hän palasi lyömästä Kedorlaomeria, ja niitä kuninkaita hänen kanssansa: Sjaven lakeudella, joka kuninkaan laaksoksi kutsutaan.","Silloin meni Sodoman kuningas häntä vastaan, koska hän palasi lyömästä Kedorlaomeria, ja niitä kuninkaita hänen kanssansa: Sjaven lakeudella, joka kuninkaan laaksoksi kutsutaan."],[14,18,"Mutta Melkisedek Salemin kuningas toi leivän ja viinan: ja hän oli ylimmäisen Jumalan pappi.","Mutta Melkisedek Salemin kuningas toi leivän ja viinan: ja hän oli ylimmäisen Jumalan pappi."],[14,19,"Ja siunasi häntä, ja sanoi: siunattu ole sinä Abram sille kaikkein korkeimmalle Jumalalle, jonka taivas ja maa oma on.","Ja siunasi häntä, ja sanoi: siunattu ole sinä Abram sille kaikkein korkeimmalle Jumalalle, jonka taivas ja maa oma on."],[14,20,"Ja kiitetty olkoon kaikkein korkein Jumala, joka sinun vihollises antoi sinun käsiis. Ja (Abram) antoi hänelle kymmenykset kaikista.","Ja kiitetty olkoon kaikkein korkein Jumala, joka sinun vihollises antoi sinun käsiis. Ja (Abram) antoi hänelle kymmenykset kaikista."],[14,21,"Silloin Sodoman kuningas sanoi Abramille: anna minulle väki, ja pidä itse tavara.","Silloin Sodoman kuningas sanoi Abramille: anna minulle väki, ja pidä itse tavara."],[14,22,"Ja Abram sanoi Sodoman kuninkaalle: Minä nostan minun käteni Herran kaikkein korkeimman Jumalan tykö, jonka taivas ja maa oma on:","Ja Abram sanoi Sodoman kuninkaalle: Minä nostan minun käteni Herran kaikkein korkeimman Jumalan tykö, jonka taivas ja maa oma on:"],[14,23,"Etten minä ota kaikesta sinun omastas lankaakaan eli kengän rihmaa, ettes sanoisi: minä olen Abramin äveriääksi tehnyt:","Etten minä ota kaikesta sinun omastas lankaakaan eli kengän rihmaa, ettes sanoisi: minä olen Abramin äveriääksi tehnyt:"],[14,24,"Ei suinkaan, paitsi sitä kuin nämät nuoret miehet syöneet ovat; ja niiden miesten osan, jotka minua seurasivat: Aner, Eskol ja Mamre, he saakoon osansa.","Ei suinkaan, paitsi sitä kuin nämät nuoret miehet syöneet ovat; ja niiden miesten osan, jotka minua seurasivat: Aner, Eskol ja Mamre, he saakoon osansa."],[15,1,"Kuin nämä olivat niin tapahtuneet, tuli Herran sana Abramin tykö näyssä, sanoen: älä pelkää Abram, minä olen sinun kilpes, ja sangen suuri palkkas.","Kuin nämä olivat niin tapahtuneet, tuli Herran sana Abramin tykö näyssä, sanoen: älä pelkää Abram, minä olen sinun kilpes, ja sangen suuri palkkas."],[15,2,"Mutta Abram sanoi: Herra, Herra, mitäs minulle annat? minä lähden lapsetoinna täältä, ja minun huoneeni haltia on tämä Eleasari Damaskusta.","Mutta Abram sanoi: Herra, Herra, mitäs minulle annat? minä lähden lapsetoinna täältä, ja minun huoneeni haltia on tämä Eleasari Damaskusta."],[15,3,"Ja Abram taas sanoi: mutta minulle et sinä antanut siementä. Ja katsos, minun kotopalkolliseni tulee minun perillisekseni.","Ja Abram taas sanoi: mutta minulle et sinä antanut siementä. Ja katsos, minun kotopalkolliseni tulee minun perillisekseni."],[15,4,"Ja katso, Herran sana tuli hänen tykönsä, sanoen: ei tämä sinua peri: vaan joka sinun ruumiistas tulee, se tulee sinun perillisekses.","Ja katso, Herran sana tuli hänen tykönsä, sanoen: ei tämä sinua peri: vaan joka sinun ruumiistas tulee, se tulee sinun perillisekses."],[15,5,"Niin hän vei hänen ulos, ja sanoi: katso taivaaseen ja lue tähdet, jos sinä ne taidat lukea. Ja sanoi hänelle: niin sinun siemenes on oleva.","Niin hän vei hänen ulos, ja sanoi: katso taivaaseen ja lue tähdet, jos sinä ne taidat lukea. Ja sanoi hänelle: niin sinun siemenes on oleva."],[15,6,"(Abram) uskoi Herran, ja hän luki hänelle sen vanhurskaudeksi.","(Abram) uskoi Herran, ja hän luki hänelle sen vanhurskaudeksi."],[15,7,"Ja sanoi hänelle: minä se Herra olen, joka vein sinun ulos Kaldean Uurista, antaakseni sinulle tämän maan omakses.","Ja sanoi hänelle: minä se Herra olen, joka vein sinun ulos Kaldean Uurista, antaakseni sinulle tämän maan omakses."],[15,8,"Ja hän sanoi: Herra, Herra, mistä minä tietäisin sen omistavani?","Ja hän sanoi: Herra, Herra, mistä minä tietäisin sen omistavani?"],[15,9,"Ja hän sanoi hänelle: ota minulle kolmivuotinen hehkonen, ja kolmivuotinen vuohi, ja kolmivuotinen oinas: niin myös mettinen, ja nuori kyhkyläinen.","Ja hän sanoi hänelle: ota minulle kolmivuotinen hehkonen, ja kolmivuotinen vuohi, ja kolmivuotinen oinas: niin myös mettinen, ja nuori kyhkyläinen."],[15,10,"Ja hän otti hänelle nämät kaikki, ja jakoi keskeltä kahtia, ja pani itsekunkin osan toinen toisensa kohdalle; vaan lintuja ei hän jakanut.","Ja hän otti hänelle nämät kaikki, ja jakoi keskeltä kahtia, ja pani itsekunkin osan toinen toisensa kohdalle; vaan lintuja ei hän jakanut."],[15,11,"Niin linnut tulivat lihain päälle; ja Abram karkotti ne.","Niin linnut tulivat lihain päälle; ja Abram karkotti ne."],[15,12,"Ja tapahtui auringon laskeissa, että raskas uni lankesi Abramin päälle: ja katso, hämmästys ja synkkä pimeys tuli hänen päällensä.","Ja tapahtui auringon laskeissa, että raskas uni lankesi Abramin päälle: ja katso, hämmästys ja synkkä pimeys tuli hänen päällensä."],[15,13,"Niin hän sanoi Abramille: sinun pitää totisesti tietämän, että sinun siemenes tulee muukalaiseksi sille maalle, joka ei heidän omansa ole, ja he saattavat heitä orjaksi, ja vaivaavat heitä neljäsataa ajastaikaa.","Niin hän sanoi Abramille: sinun pitää totisesti tietämän, että sinun siemenes tulee muukalaiseksi sille maalle, joka ei heidän omansa ole, ja he saattavat heitä orjaksi, ja vaivaavat heitä neljäsataa ajastaikaa."],[15,14,"Mutta sille kansalle, jonka orjana he ovat, kostan minä: ja sitte he lähtevät ulos suurella tavaralla.","Mutta sille kansalle, jonka orjana he ovat, kostan minä: ja sitte he lähtevät ulos suurella tavaralla."],[15,15,"Ja sinä menet isäis tykö rauhassa, ja haudataan hyvässä ijässä.","Ja sinä menet isäis tykö rauhassa, ja haudataan hyvässä ijässä."],[15,16,"Vaan neljännessä miespolvessa he tänne palajavat: sillä Amorilaisten pahuus ei ole vielä täytetty.","Vaan neljännessä miespolvessa he tänne palajavat: sillä Amorilaisten pahuus ei ole vielä täytetty."],[15,17,"Ja koska aurinko oli laskenut, ja pimeys joutunut: katso, pätsi suitsi, ja liekki kävi kappaleitten keskeltä.","Ja koska aurinko oli laskenut, ja pimeys joutunut: katso, pätsi suitsi, ja liekki kävi kappaleitten keskeltä."],[15,18,"Sinä päivänä teki Herra liiton Abramin kanssa, sanoen: sinun siemenelles annan minä tämän maan, hamasta Egyptin virrasta, niin suureen virtaan Phratiin asti.","Sinä päivänä teki Herra liiton Abramin kanssa, sanoen: sinun siemenelles annan minä tämän maan, hamasta Egyptin virrasta, niin suureen virtaan Phratiin asti."],[15,19,"Keniläiset, ja Kenitsiläiset, ja Kadmonilaiset,","Keniläiset, ja Kenitsiläiset, ja Kadmonilaiset,"],[15,20,"Ja Hetiläiset, ja Pheresiläiset, ja Kalevan pojat,","Ja Hetiläiset, ja Pheresiläiset, ja Kalevan pojat,"],[15,21,"Ja Amorilaiset, ja Kanaanealaiset, ja Gergesiläiset, ja Jebusilaiset.","Ja Amorilaiset, ja Kanaanealaiset, ja Gergesiläiset, ja Jebusilaiset."],[16,1,"Ja Sarai Abramin emäntä ei synnyttänyt hänelle. Mutta hänellä oli Egyptiläinen piika, jonka nimi oli Hagar.","Ja Sarai Abramin emäntä ei synnyttänyt hänelle. Mutta hänellä oli Egyptiläinen piika, jonka nimi oli Hagar."],[16,2,"Ja Sarai sanoi Abramille: katso nyt; Herra on minun sulkenut synnyttämästä, menes siis minun piikani sivuun, jos minä sittenkin saisin lapsia hänestä. Ja Abram otti Sarain sanan.","Ja Sarai sanoi Abramille: katso nyt; Herra on minun sulkenut synnyttämästä, menes siis minun piikani sivuun, jos minä sittenkin saisin lapsia hänestä. Ja Abram otti Sarain sanan."],[16,3,"Ja Sarai Abramin emäntä otti Egyptiläisen piikansa Hagarin, sitte kun Abram kymmenen ajastaikaa oli asunut Kanaanin maalla: ja antoi sen miehellensä Abramille emännäksi.","Ja Sarai Abramin emäntä otti Egyptiläisen piikansa Hagarin, sitte kun Abram kymmenen ajastaikaa oli asunut Kanaanin maalla: ja antoi sen miehellensä Abramille emännäksi."],[16,4,"Ja hän makasi Hagarin tykönä, joka tuli raskaaksi. Koska hän tunsi itsensä raskaaksi, tuli hänen emäntänsä halvaksi hänen silmissänsä.","Ja hän makasi Hagarin tykönä, joka tuli raskaaksi. Koska hän tunsi itsensä raskaaksi, tuli hänen emäntänsä halvaksi hänen silmissänsä."],[16,5,"Niin sanoi Sarai Abramille: minulle tapahtunut vääryys lankee sinun päälles; minä annoin minun piikani sinun sivuus; ja että hän tunsi itsensä raskaaksi, halpenin minä hänen edessänsä: Herra tuomitkoon minun ja sinun välilläs.","Niin sanoi Sarai Abramille: minulle tapahtunut vääryys lankee sinun päälles; minä annoin minun piikani sinun sivuus; ja että hän tunsi itsensä raskaaksi, halpenin minä hänen edessänsä: Herra tuomitkoon minun ja sinun välilläs."],[16,6,"Mutta Abram sanoi Saraille: katso, sinun piikas on sinun käsissäs, tee hänen kanssansa mitäs tahdot: Niin Sarai kuritti häntä, ja hän pakeni hänen tyköänsä.","Mutta Abram sanoi Saraille: katso, sinun piikas on sinun käsissäs, tee hänen kanssansa mitäs tahdot: Niin Sarai kuritti häntä, ja hän pakeni hänen tyköänsä."],[16,7,"Mutta Herran enkeli löysi hänen vesilähteen tykönä korvessa: lähteen tykönä Surrin tiellä.","Mutta Herran enkeli löysi hänen vesilähteen tykönä korvessa: lähteen tykönä Surrin tiellä."],[16,8,"Ja sanoi: Hagar, Sarain piika, kustas tulet? ja kuhunkas menet? hän sanoi: minä pakenin emäntääni Saraita.","Ja sanoi: Hagar, Sarain piika, kustas tulet? ja kuhunkas menet? hän sanoi: minä pakenin emäntääni Saraita."],[16,9,"Ja Herran enkeli sanoi hänelle: palaja emäntäs tykö, ja nöyryytä itses hänen kätensä alle.","Ja Herran enkeli sanoi hänelle: palaja emäntäs tykö, ja nöyryytä itses hänen kätensä alle."],[16,10,"Ja Herran enkeli sanoi hänelle: minä lisään suuresti sinun siemenes, niin ettei sitä taideta luettaa paljouden tähden.","Ja Herran enkeli sanoi hänelle: minä lisään suuresti sinun siemenes, niin ettei sitä taideta luettaa paljouden tähden."],[16,11,"Ja Herran enkeli sanoi (vielä) hänelle: katso, sinä olet raskas, ja synnytät pojan: ja sinun pitää kutsuman hänen nimensä Ismael: sillä Herra on kuullut sinun vaivas.","Ja Herran enkeli sanoi (vielä) hänelle: katso, sinä olet raskas, ja synnytät pojan: ja sinun pitää kutsuman hänen nimensä Ismael: sillä Herra on kuullut sinun vaivas."],[16,12,"Hän tulee tylyksi mieheksi, ja hänen kätensä jokaista vastaan, ja jokaisen käsi häntä vastaan, ja hän on asuva kaikkein veljeinsä edessä.","Hän tulee tylyksi mieheksi, ja hänen kätensä jokaista vastaan, ja jokaisen käsi häntä vastaan, ja hän on asuva kaikkein veljeinsä edessä."],[16,13,"Ja hän kutsui Herran nimen, joka häntä puhutteli, sinä Jumala, joka näet minun, sillä hän sanoi: enkö minä ole katsonut hänen peräänsä, joka minun näkee?","Ja hän kutsui Herran nimen, joka häntä puhutteli, sinä Jumala, joka näet minun, sillä hän sanoi: enkö minä ole katsonut hänen peräänsä, joka minun näkee?"],[16,14,"Sentähden nimitti hän sen kaivon, sen elävän kaivoksi, joka minun näkee, joka on Kadeksen ja Baredin välillä.","Sentähden nimitti hän sen kaivon, sen elävän kaivoksi, joka minun näkee, joka on Kadeksen ja Baredin välillä."],[16,15,"Ja Hagar synnytti Abramille pojan: ja Abram kutsui poikansa nimen, jonka Hagar synnytti, Ismael.","Ja Hagar synnytti Abramille pojan: ja Abram kutsui poikansa nimen, jonka Hagar synnytti, Ismael."],[16,16,"Ja Abram oli kuudenyhdeksättäkymmentä ajastajan vanha, koska Hagar synnytti Ismaelin Abramille.","Ja Abram oli kuudenyhdeksättäkymmentä ajastajan vanha, koska Hagar synnytti Ismaelin Abramille."],[17,1,"Koska Abram oli yhdeksänkymmenen ja yhdeksän ajastaikainen, näkyi Herra Abramille ja sanoi hänelle: Minä olen Jumala kaikkivaltias: vaella minun edessäni, ja ole vakaa.","Koska Abram oli yhdeksänkymmenen ja yhdeksän ajastaikainen, näkyi Herra Abramille ja sanoi hänelle: Minä olen Jumala kaikkivaltias: vaella minun edessäni, ja ole vakaa."],[17,2,"Ja minä teen liittoni minun ja sinun välilles, ja lisään sinun sangen suuresti.","Ja minä teen liittoni minun ja sinun välilles, ja lisään sinun sangen suuresti."],[17,3,"Ja Abram lankesi kasvoillensa: Ja Jumala puhui hänen kanssansa, sanoen:","Ja Abram lankesi kasvoillensa: Ja Jumala puhui hänen kanssansa, sanoen:"],[17,4,"Katso, Minä olen, ja minun liittoni on sinun kanssas, ja sinä tulet paljon kansan isäksi.","Katso, Minä olen, ja minun liittoni on sinun kanssas, ja sinä tulet paljon kansan isäksi."],[17,5,"Sentähden ei sinua pidä enää kutsuttaman Abram; mutta Abrahamin pitää oleman sinun nimes: sillä minä olen tehnyt sinun paljon kansan isäksi.","Sentähden ei sinua pidä enää kutsuttaman Abram; mutta Abrahamin pitää oleman sinun nimes: sillä minä olen tehnyt sinun paljon kansan isäksi."],[17,6,"Ja teen sinun sangen suuresti hedelmälliseksi, ja asetan sinun kansoiksi: ja kuninkaat tulevat sinusta.","Ja teen sinun sangen suuresti hedelmälliseksi, ja asetan sinun kansoiksi: ja kuninkaat tulevat sinusta."],[17,7,"Ja minä teen minun liittoni minun vaiheelleni ja sinun, ja sinun siemenes sinun jälkees, heidän suvuissansa ijankaikkiseksi liitoksi: että minä olen sinun Jumalas, ja sinun siemenes sinun jälkees.","Ja minä teen minun liittoni minun vaiheelleni ja sinun, ja sinun siemenes sinun jälkees, heidän suvuissansa ijankaikkiseksi liitoksi: että minä olen sinun Jumalas, ja sinun siemenes sinun jälkees."],[17,8,"Ja annan sinulle ja sinun siemenelles sinun jälkees, sen maan, jossa sinä muukalainen olet; koko Kanaanin maan ijäiseksi omaisuudeksi: ja olen heidän Jumalansa.","Ja annan sinulle ja sinun siemenelles sinun jälkees, sen maan, jossa sinä muukalainen olet; koko Kanaanin maan ijäiseksi omaisuudeksi: ja olen heidän Jumalansa."],[17,9,"Ja Jumala sanoi Abrahamille: pidä siis minun liittoni, sinä ja sinun siemenes sinun jälkees, heidän suvuissansa.","Ja Jumala sanoi Abrahamille: pidä siis minun liittoni, sinä ja sinun siemenes sinun jälkees, heidän suvuissansa."],[17,10,"Ja tämä on liitto, jonka teidän pitämän pitää, minun vaiheellani ja teidän, ja sinun siemenes vaiheella sinun jälkees: kaikki miehenpuoli pitää teidän seassanne ympärileikattaman.","Ja tämä on liitto, jonka teidän pitämän pitää, minun vaiheellani ja teidän, ja sinun siemenes vaiheella sinun jälkees: kaikki miehenpuoli pitää teidän seassanne ympärileikattaman."],[17,11,"Ja teidän pitää ympärileikkaaman teidän esinahkanne lihan: sen pitää oleman liiton merkiksi minun ja teidän vaiheellanne.","Ja teidän pitää ympärileikkaaman teidän esinahkanne lihan: sen pitää oleman liiton merkiksi minun ja teidän vaiheellanne."],[17,12,"Kahdeksan päiväinen poikalapsi pitää ympärileikattaman teidän seassanne, kaikki miehenpuoli teidän suvuissanne: kotona syntynyt, eli kaikkinaiselta muukalaiselta rahalla ostettu, joka ei ole sinun siemenestäs.","Kahdeksan päiväinen poikalapsi pitää ympärileikattaman teidän seassanne, kaikki miehenpuoli teidän suvuissanne: kotona syntynyt, eli kaikkinaiselta muukalaiselta rahalla ostettu, joka ei ole sinun siemenestäs."],[17,13,"Kaiketi pitää ympärileikattaman sekä kotonas syntynyt, että rahallas ostettu; ja niin minun liittoni on oleva teidän lihassanne ijankaikkiseksi liitoksi.","Kaiketi pitää ympärileikattaman sekä kotonas syntynyt, että rahallas ostettu; ja niin minun liittoni on oleva teidän lihassanne ijankaikkiseksi liitoksi."],[17,14,"Ja jonka esinahallisen miehenpuolen esinahan liha ei ympärileikata, se sielu pitää hukutettaman kansastansa: hän on minun liittoni rikkonut.","Ja jonka esinahallisen miehenpuolen esinahan liha ei ympärileikata, se sielu pitää hukutettaman kansastansa: hän on minun liittoni rikkonut."],[17,15,"Ja Jumala sanoi Abrahamille: Saraita sinun emäntääs ei pidä sinun enää kutsuman Sarai; vaan Saara pitää oleman hänen nimensä:","Ja Jumala sanoi Abrahamille: Saraita sinun emäntääs ei pidä sinun enää kutsuman Sarai; vaan Saara pitää oleman hänen nimensä:"],[17,16,"Sillä minä siunaan häntä, ja annan myös hänestä sinulle pojan; sillä minä siunaan hänen, ja hän on tuleva kansoiksi, ja kansain kuninkaat tulevat hänestä.","Sillä minä siunaan häntä, ja annan myös hänestä sinulle pojan; sillä minä siunaan hänen, ja hän on tuleva kansoiksi, ja kansain kuninkaat tulevat hänestä."],[17,17,"Ja Abraham lankesi kasvoillensa ja naurahti, ja sanoi sydämessänsä: syntyneekö sadanajastaikaiselle poika? ja Saara yhdeksänkymmenen ajastaikainen synnyttäneekö?","Ja Abraham lankesi kasvoillensa ja naurahti, ja sanoi sydämessänsä: syntyneekö sadanajastaikaiselle poika? ja Saara yhdeksänkymmenen ajastaikainen synnyttäneekö?"],[17,18,"Ja Abraham sanoi Jumalalle: josko Ismael sais elää sinun edessäs!","Ja Abraham sanoi Jumalalle: josko Ismael sais elää sinun edessäs!"],[17,19,"Niin sanoi Jumala: Tosin Saara sinun emäntäs synnyttää sinulle pojan ja sinun pitää hänen nimensä kutsuman Isaak: ja minä teen minun liittoni hänen kanssansa ijankaikkiseksi liitoksi, hänen siemenellensä hänen jälkeensä.","Niin sanoi Jumala: Tosin Saara sinun emäntäs synnyttää sinulle pojan ja sinun pitää hänen nimensä kutsuman Isaak: ja minä teen minun liittoni hänen kanssansa ijankaikkiseksi liitoksi, hänen siemenellensä hänen jälkeensä."],[17,20,"Ismaelista olen minä myös sinun rukoukses kuullut, katso, minä olen siunannut häntä, ja teen hänen hedelmälliseksi, ja lisään hänen sangen suuresti: kaksitoistakymmentä ruhtinasta pitää hänen siittämän, ja minä teen hänen suureksi kansaksi.","Ismaelista olen minä myös sinun rukoukses kuullut, katso, minä olen siunannut häntä, ja teen hänen hedelmälliseksi, ja lisään hänen sangen suuresti: kaksitoistakymmentä ruhtinasta pitää hänen siittämän, ja minä teen hänen suureksi kansaksi."],[17,21,"Mutta minun liittoni teen minä Isaakin kanssa; jonka Saara on sinulle synnyttävä, tähän aikaan tulevana vuonna.","Mutta minun liittoni teen minä Isaakin kanssa; jonka Saara on sinulle synnyttävä, tähän aikaan tulevana vuonna."],[17,22,"Ja kuin puhe oli päätetty hänen kanssansa, meni Jumala ylös Abrahamin tyköä.","Ja kuin puhe oli päätetty hänen kanssansa, meni Jumala ylös Abrahamin tyköä."],[17,23,"Ja Abraham otti poikansa Ismaelin, ja kaikki kotona syntyneet, ja kaikki ostetut: kaiken miehenpuolen Abrahamin huoneessa: ja ympärileikkasi heidän esinahkansa lihan, kohta sinä päivänä kuin Jumala oli puhunut hänen kanssansa.","Ja Abraham otti poikansa Ismaelin, ja kaikki kotona syntyneet, ja kaikki ostetut: kaiken miehenpuolen Abrahamin huoneessa: ja ympärileikkasi heidän esinahkansa lihan, kohta sinä päivänä kuin Jumala oli puhunut hänen kanssansa."],[17,24,"Ja Abraham oli yhdeksän ja yhdeksänkymmenen ajastaikainen, koska hänen esinahkansa liha ympärileikattiin.","Ja Abraham oli yhdeksän ja yhdeksänkymmenen ajastaikainen, koska hänen esinahkansa liha ympärileikattiin."],[17,25,"Mutta Ismael hänen poikansa oli kolmentoistakymmenen ajastaikainen, koska hänen esinahkansa liha ympärileikattiin.","Mutta Ismael hänen poikansa oli kolmentoistakymmenen ajastaikainen, koska hänen esinahkansa liha ympärileikattiin."],[17,26,"Yhtenä päivänä ympärileikattiin Abraham, ja Ismael hänen poikansa.","Yhtenä päivänä ympärileikattiin Abraham, ja Ismael hänen poikansa."],[17,27,"Ja kaikki miehenpuoli hänen huoneessansa, kotona syntyneet ja muukalaisilta ostetut, ympärileikattiin hänen kanssansa.","Ja kaikki miehenpuoli hänen huoneessansa, kotona syntyneet ja muukalaisilta ostetut, ympärileikattiin hänen kanssansa."],[18,1,"Ja Herra näkyi hänelle Mamren lakeudella; jossa hän istui majan ovella, koska päivä oli palavimmallansa.","Ja Herra näkyi hänelle Mamren lakeudella; jossa hän istui majan ovella, koska päivä oli palavimmallansa."],[18,2,"Koska hän silmänsä nosti ja näki, katso kolme miestä seisoivat hänen edessänsä: ja kuin hän näki heidät, juoksi hän heitä vastaan majan ovelta, ja kumarsi itsensä maahan.","Koska hän silmänsä nosti ja näki, katso kolme miestä seisoivat hänen edessänsä: ja kuin hän näki heidät, juoksi hän heitä vastaan majan ovelta, ja kumarsi itsensä maahan."],[18,3,"Ja sanoi: Herra, jos minä olen armon löytänyt sinun edessäs, niin älä mene palvelias ohitse.","Ja sanoi: Herra, jos minä olen armon löytänyt sinun edessäs, niin älä mene palvelias ohitse."],[18,4,"Ja sallikaat tuotaa vähä vettä pestäksenne teidän jalkanne, ja levätkäät teitänne puun alla.","Ja sallikaat tuotaa vähä vettä pestäksenne teidän jalkanne, ja levätkäät teitänne puun alla."],[18,5,"Ja minä tuon teidän eteenne kappaleen leipää, virvottaaksenne teidän sydäntänne, ja sitte menkäät: sillä sentähden te poikkesitte teidän palvelianne tykö. Ja he sanoivat: tee niin kuin sinä olet puhunut.","Ja minä tuon teidän eteenne kappaleen leipää, virvottaaksenne teidän sydäntänne, ja sitte menkäät: sillä sentähden te poikkesitte teidän palvelianne tykö. Ja he sanoivat: tee niin kuin sinä olet puhunut."],[18,6,"Niin Abraham riensi majaan Saaran tykö, ja sanoi: riennä sinuas ja tuo kolme mittaa sämpyläjauhoja, sotke ja leivo kaltiaisia.","Niin Abraham riensi majaan Saaran tykö, ja sanoi: riennä sinuas ja tuo kolme mittaa sämpyläjauhoja, sotke ja leivo kaltiaisia."],[18,7,"Ja Abraham juoksi karjan tykö: ja toi nuoren ja kauniin vasikan, ja antoi palveliallensa, joka riensi valmistamaan sitä.","Ja Abraham juoksi karjan tykö: ja toi nuoren ja kauniin vasikan, ja antoi palveliallensa, joka riensi valmistamaan sitä."],[18,8,"Ja hän toi voita ja maitoa, ja vasikasta, jota hän valmistanut oli, ja pani heidän eteensä: ja hän seisoi heidän edessänsä puun alla ja he söivät.","Ja hän toi voita ja maitoa, ja vasikasta, jota hän valmistanut oli, ja pani heidän eteensä: ja hän seisoi heidän edessänsä puun alla ja he söivät."],[18,9,"Niin sanoivat he hänelle: kussa on Saara sinun emäntäs? hän vastasi: täällä majassa.","Niin sanoivat he hänelle: kussa on Saara sinun emäntäs? hän vastasi: täällä majassa."],[18,10,"Ja hän sanoi: tosin minä palajan sinun tykös, liki tällä vuoden ajalla, ja katso, Saaralla emännälläs on poika. Ja Saara kuuli sen majan ovelle, joka oli hänen takanansa.","Ja hän sanoi: tosin minä palajan sinun tykös, liki tällä vuoden ajalla, ja katso, Saaralla emännälläs on poika. Ja Saara kuuli sen majan ovelle, joka oli hänen takanansa."],[18,11,"Mutta Abraham ja Saara olivat vanhat ja ijälliseksi joutuneet; niin että Saaralta olivat lakanneet vaimolliset menot.","Mutta Abraham ja Saara olivat vanhat ja ijälliseksi joutuneet; niin että Saaralta olivat lakanneet vaimolliset menot."],[18,12,"Sentähden nauroi Saara itsellensä, ja sanoi: nyt koska minä vanha olen, antanenko minä itseni hekumaan? ja minun herrani on vanhentunut.","Sentähden nauroi Saara itsellensä, ja sanoi: nyt koska minä vanha olen, antanenko minä itseni hekumaan? ja minun herrani on vanhentunut."],[18,13,"Ja Herra sanoi Abrahamille: miksi Saara nauroi, sanoen: pitäneeköstä todellakin minun synnyttämän, joka olen vanhaksi tullut?","Ja Herra sanoi Abrahamille: miksi Saara nauroi, sanoen: pitäneeköstä todellakin minun synnyttämän, joka olen vanhaksi tullut?"],[18,14,"Onko Herralle jotakin mahdotointa? Määrättyyn aikaan, koska minä palajan sinun tykös, tällä vuoden ajalla, niin Saaralla on poika.","Onko Herralle jotakin mahdotointa? Määrättyyn aikaan, koska minä palajan sinun tykös, tällä vuoden ajalla, niin Saaralla on poika."],[18,15,"Niin Saara kielsi, sanoen: en minä nauranut: sillä hän hämmästyi. Mutta hän sanoi: ei ole niin, sinä nauroit.","Niin Saara kielsi, sanoen: en minä nauranut: sillä hän hämmästyi. Mutta hän sanoi: ei ole niin, sinä nauroit."],[18,16,"Silloin nousivat miehet sieltä, ja käänsivät heitänsä Sodomaan päin: ja Abraham meni heidän kanssansa, saattamaan heitä.","Silloin nousivat miehet sieltä, ja käänsivät heitänsä Sodomaan päin: ja Abraham meni heidän kanssansa, saattamaan heitä."],[18,17,"Ja Herra sanoi: kuinka minä salaan Abrahamilta, jota minä teen?","Ja Herra sanoi: kuinka minä salaan Abrahamilta, jota minä teen?"],[18,18,"Että Abraham tulee suureksi ja väkeväksi kansaksi, ja kaikki kansat maan päällä pitää hänessä siunatuksi tuleman.","Että Abraham tulee suureksi ja väkeväksi kansaksi, ja kaikki kansat maan päällä pitää hänessä siunatuksi tuleman."],[18,19,"Sillä minä tunnen hänen, että hän käskee lapsiansa ja huonettansa hänen jälkeensä Herran tietä pitämään, ja tekemään hurskautta ja oikeutta: että Herra saattais Abrahamille kaikki, kuin hän hänelle luvannut on.","Sillä minä tunnen hänen, että hän käskee lapsiansa ja huonettansa hänen jälkeensä Herran tietä pitämään, ja tekemään hurskautta ja oikeutta: että Herra saattais Abrahamille kaikki, kuin hän hänelle luvannut on."],[18,20,"Ja Herra sanoi: Sodomassa ja Gomorrassa on suuri huuto, ja heidän syntinsä ovat sangen raskaat.","Ja Herra sanoi: Sodomassa ja Gomorrassa on suuri huuto, ja heidän syntinsä ovat sangen raskaat."],[18,21,"Minä astun nyt alas ja katson, jos he täydellisesti tehneet ovat huudon jälkeen, joka minun eteeni tullut on; taikka jos ei niin ole, että minä sen tietäisin.","Minä astun nyt alas ja katson, jos he täydellisesti tehneet ovat huudon jälkeen, joka minun eteeni tullut on; taikka jos ei niin ole, että minä sen tietäisin."],[18,22,"Ja miehet käänsivät itsensä sieltä, ja menivät Sodomaan päin. Mutta Abraham jäi seisomaan vielä Herran eteen.","Ja miehet käänsivät itsensä sieltä, ja menivät Sodomaan päin. Mutta Abraham jäi seisomaan vielä Herran eteen."],[18,23,"Ja Abraham astui hänen tykönsä, ja sanoi: hukutatkos myös vanhurskaan jumalattoman kanssa?","Ja Abraham astui hänen tykönsä, ja sanoi: hukutatkos myös vanhurskaan jumalattoman kanssa?"],[18,24,"Jos kaupungissa olisi viisikymmentä vanhurskasta, hukuttaisitkos myös ne, ja et säästäisi sitä siaa viidenkymmenen vanhurskaan tähden, jotka siellä olisivat?","Jos kaupungissa olisi viisikymmentä vanhurskasta, hukuttaisitkos myös ne, ja et säästäisi sitä siaa viidenkymmenen vanhurskaan tähden, jotka siellä olisivat?"],[18,25,"Pois se sinusta, ettäs sen tekisit, ja kuolettaisit vanhurskaan jumalattoman kanssa, ja että vanhurskaalle kävis niinkuin jumalattomallekin. Pois se sinusta: Eikö kaiken maailman tuomari oikein tuomitsisi?","Pois se sinusta, ettäs sen tekisit, ja kuolettaisit vanhurskaan jumalattoman kanssa, ja että vanhurskaalle kävis niinkuin jumalattomallekin. Pois se sinusta: Eikö kaiken maailman tuomari oikein tuomitsisi?"],[18,26,"Herra sanoi: jos minä löydän viisikymmentä vanhurskasta Sodoman kaupungissa; niin minä säästän kaiken sen paikan heidän tähtensä.","Herra sanoi: jos minä löydän viisikymmentä vanhurskasta Sodoman kaupungissa; niin minä säästän kaiken sen paikan heidän tähtensä."],[18,27,"Abraham vastasi ja sanoi: katso, minä olen ruvennut puhumaan minun Herrani kanssa; ehkä minä tomu ja tuhka olen.","Abraham vastasi ja sanoi: katso, minä olen ruvennut puhumaan minun Herrani kanssa; ehkä minä tomu ja tuhka olen."],[18,28,"Mitämaks, jos oli vailla viisi niistä viidestäkymmenestä vanhurskaasta, kadottaisitkos viiden tähden koko kaupungin? ja hän sanoi: en kadota, jos minä löydän siellä viisiviidettäkymmentä.","Mitämaks, jos oli vailla viisi niistä viidestäkymmenestä vanhurskaasta, kadottaisitkos viiden tähden koko kaupungin? ja hän sanoi: en kadota, jos minä löydän siellä viisiviidettäkymmentä."],[18,29,"Ja hän puhui vielä hänelle, ja sanoi: mitämaks, siinä löyttäisiin neljäkymmentä? ja hän sanoi: en tee minä neljänkymmenen tähden.","Ja hän puhui vielä hänelle, ja sanoi: mitämaks, siinä löyttäisiin neljäkymmentä? ja hän sanoi: en tee minä neljänkymmenen tähden."],[18,30,"Abraham sanoi: älköön minun Herrani vihastuko, että minä vielä puhun: mitämaks, löyttäisiin siellä kolmekymmentä? ja hän sanoi: en minä tee, jos minä löydän siellä kolmekymmentä.","Abraham sanoi: älköön minun Herrani vihastuko, että minä vielä puhun: mitämaks, löyttäisiin siellä kolmekymmentä? ja hän sanoi: en minä tee, jos minä löydän siellä kolmekymmentä."],[18,31,"Ja hän sanoi taas: katso, minä olen ruvennut puhumaan minun Herrani kanssa: mitämaks, löyttäisiin siellä kaksikymmentä? ja hän sanoi: en kadota heitä kahdenkymmenen tähden.","Ja hän sanoi taas: katso, minä olen ruvennut puhumaan minun Herrani kanssa: mitämaks, löyttäisiin siellä kaksikymmentä? ja hän sanoi: en kadota heitä kahdenkymmenen tähden."],[18,32,"Ja hän vielä sanoi: älköön minun Herrani vihastuko, jos minä ainoastansa tällä erällä puhu: mitämaks, siellä löyttäisiin kymmenen? ja hän sanoi: en kadota heitä kymmenen tähden.","Ja hän vielä sanoi: älköön minun Herrani vihastuko, jos minä ainoastansa tällä erällä puhu: mitämaks, siellä löyttäisiin kymmenen? ja hän sanoi: en kadota heitä kymmenen tähden."],[18,33,"Ja Herra meni pois sitte kuin hän oli Abrahamin kanssa puhunut: ja Abraham palasi kotiansa.","Ja Herra meni pois sitte kuin hän oli Abrahamin kanssa puhunut: ja Abraham palasi kotiansa."],[19,1,"Ja kaksi enkeliä tulivat ehtoona Sodomaan, ja Lot istui Sodoman portissa: ja kuin hän näki heidät, nousi hän heitä vastaan, ja kumarsi kasvoillensa maahan.","Ja kaksi enkeliä tulivat ehtoona Sodomaan, ja Lot istui Sodoman portissa: ja kuin hän näki heidät, nousi hän heitä vastaan, ja kumarsi kasvoillensa maahan."],[19,2,"Ja sanoi: katso, minun Herrani, poiketkaat teidän palvelianne huoneeseen yöksi, ja antakaat pestä jalkanne, ja aamulla varhain noustuanne menette matkaan. Ja he sanoivat: ei suinkaan, vaan kadulla me yötä pidämme.","Ja sanoi: katso, minun Herrani, poiketkaat teidän palvelianne huoneeseen yöksi, ja antakaat pestä jalkanne, ja aamulla varhain noustuanne menette matkaan. Ja he sanoivat: ei suinkaan, vaan kadulla me yötä pidämme."],[19,3,"Ja hän kovin vaati heitä, ja he poikkesivat hänen tykönsä, ja tulivat hänen huoneeseensa. Ja hän valmisti heille aterian, ja leipoi happamattomia leipiä, ja he söivät.","Ja hän kovin vaati heitä, ja he poikkesivat hänen tykönsä, ja tulivat hänen huoneeseensa. Ja hän valmisti heille aterian, ja leipoi happamattomia leipiä, ja he söivät."],[19,4,"Ennenkuin he levätä panivat, tulivat kaupungin miehet, Sodomalaiset, nuoret ja vanhat: kaikki kansa joka kulmalta, ja piirittivät huoneen.","Ennenkuin he levätä panivat, tulivat kaupungin miehet, Sodomalaiset, nuoret ja vanhat: kaikki kansa joka kulmalta, ja piirittivät huoneen."],[19,5,"Ja huusivat Lotin, ja sanoivat hänelle: kussa ovat ne miehet, jotka sinun tykös yöllä tulivat? tuo heitä meidän tykömme tutaksemme heitä.","Ja huusivat Lotin, ja sanoivat hänelle: kussa ovat ne miehet, jotka sinun tykös yöllä tulivat? tuo heitä meidän tykömme tutaksemme heitä."],[19,6,"Silloin Lot meni ulos heidän tykönsä oven eteen, ja sulki oven jälkeensä.","Silloin Lot meni ulos heidän tykönsä oven eteen, ja sulki oven jälkeensä."],[19,7,"Ja sanoi: älkäät te, rakkaat veljeni, tehkö niin pahoin.","Ja sanoi: älkäät te, rakkaat veljeni, tehkö niin pahoin."],[19,8,"Katso, minulla on kaksi tytärtä, jotka ei vielä miehestä mitään tiedä: ne minä tuotan teille, tehkäät heille mitä te tahdotte: ainoastansa näille miehille älkäät mitään pahaa tehkö; sillä sentähden ovat he tulleet minun kattoni varjon ala.","Katso, minulla on kaksi tytärtä, jotka ei vielä miehestä mitään tiedä: ne minä tuotan teille, tehkäät heille mitä te tahdotte: ainoastansa näille miehille älkäät mitään pahaa tehkö; sillä sentähden ovat he tulleet minun kattoni varjon ala."],[19,9,"Mutta he sanoivat: tule tänne. Ja sanoivat: tuleeko joku muukalaiseksi, ja kuitenkin tahtoo kokonansa hallita? nyt, me teemme enemmän pahaa sinulle kuin heille: ja he tekivät suurella väkivallalla miehelle Lotille ylläkön, ja juoksivat ovea särkemään.","Mutta he sanoivat: tule tänne. Ja sanoivat: tuleeko joku muukalaiseksi, ja kuitenkin tahtoo kokonansa hallita? nyt, me teemme enemmän pahaa sinulle kuin heille: ja he tekivät suurella väkivallalla miehelle Lotille ylläkön, ja juoksivat ovea särkemään."],[19,10,"Niin miehet ojensivat kätensä ulos, ja tempasivat Lotin tykönsä huoneesen, ja paiskasivat oven kiinni.","Niin miehet ojensivat kätensä ulos, ja tempasivat Lotin tykönsä huoneesen, ja paiskasivat oven kiinni."],[19,11,"Ja miehet, kuin huoneen oven edessä olivat, löivät he sokeudella, pienet ja suuret, niin että he väsyivät ovea etseissänsä.","Ja miehet, kuin huoneen oven edessä olivat, löivät he sokeudella, pienet ja suuret, niin että he väsyivät ovea etseissänsä."],[19,12,"Ja miehet sanoivat Lotille: onko sinulla vielä tässä joku? vävyjä, eli poikia taikka tyttäriä, eli kaikkia mitä sinulla on tässä kaupungissa? vie ne ulos tästä siasta.","Ja miehet sanoivat Lotille: onko sinulla vielä tässä joku? vävyjä, eli poikia taikka tyttäriä, eli kaikkia mitä sinulla on tässä kaupungissa? vie ne ulos tästä siasta."],[19,13,"Sillä me hukutamme tämän paikan: että heidän huutonsa on suuri Herran edessä, niin Herra lähetti meidät heitä hukuttamaan.","Sillä me hukutamme tämän paikan: että heidän huutonsa on suuri Herran edessä, niin Herra lähetti meidät heitä hukuttamaan."],[19,14,"Niin Lot meni ulos ja puhutteli vävyjänsä, jotka piti saaman hänen tyttärensä, ja sanoi: nouskaat ja lähtekäät tästä siasta: sillä Herra hukuttaa tämän kaupungin: mutta hän oli niinkuin leikkiä tekevä hänen vävyinsä silmäin edessä.","Niin Lot meni ulos ja puhutteli vävyjänsä, jotka piti saaman hänen tyttärensä, ja sanoi: nouskaat ja lähtekäät tästä siasta: sillä Herra hukuttaa tämän kaupungin: mutta hän oli niinkuin leikkiä tekevä hänen vävyinsä silmäin edessä."],[19,15,"Koska aamurusko kävi ylös, kiiruhtivat enkelit Lotin joutumaan, ja sanoivat: nouse, ota emäntäs, ja kaksi tytärtäs, jotka saapuvilla ovat, ettet sinä myös hukkuisi tämän kaupungin pahuudessa.","Koska aamurusko kävi ylös, kiiruhtivat enkelit Lotin joutumaan, ja sanoivat: nouse, ota emäntäs, ja kaksi tytärtäs, jotka saapuvilla ovat, ettet sinä myös hukkuisi tämän kaupungin pahuudessa."],[19,16,"Koska hän viipyi, tarttuivat miehet hänen käteensä, ja hänen emäntänsä, ja hänen kahden tyttärensä käteen, sillä Herra tahtoi säästää heitä: ja taluttivat hänen ulos ja jättivät hänen ulkopuolelle kaupunkia.","Koska hän viipyi, tarttuivat miehet hänen käteensä, ja hänen emäntänsä, ja hänen kahden tyttärensä käteen, sillä Herra tahtoi säästää heitä: ja taluttivat hänen ulos ja jättivät hänen ulkopuolelle kaupunkia."],[19,17,"Ja koska he johdattivat heitä ulos, sanoivat he: pelasta sinun sielus, ja älä katsahda taakses, ja älä myös seisahda koko tälle lakeudelle; vaan turvaa sinuas vuorelle, ettes hukkuisi.","Ja koska he johdattivat heitä ulos, sanoivat he: pelasta sinun sielus, ja älä katsahda taakses, ja älä myös seisahda koko tälle lakeudelle; vaan turvaa sinuas vuorelle, ettes hukkuisi."],[19,18,"Ja Lot sanoi heille: Ei Herra.","Ja Lot sanoi heille: Ei Herra."],[19,19,"Katso, sinun palvelias on löytänyt armon sinun edessäs, sinä olet tehnyt sinun laupeutes suureksi, jonkas minulle osotit, pelastaakses minun sieluani: en taida minä pelastaa minuani vuorella, ettei minulle jotakuta pahaa tapahtuisi, ja kuolisin.","Katso, sinun palvelias on löytänyt armon sinun edessäs, sinä olet tehnyt sinun laupeutes suureksi, jonkas minulle osotit, pelastaakses minun sieluani: en taida minä pelastaa minuani vuorella, ettei minulle jotakuta pahaa tapahtuisi, ja kuolisin."],[19,20,"Katsos, tuo kaupunki on läsnä, paeta sinne: ja hän on vähä: salli minua siellä pelastettaa: eikö hän ole vähäinen? että minun sieluni siellä elävänä pysyis.","Katsos, tuo kaupunki on läsnä, paeta sinne: ja hän on vähä: salli minua siellä pelastettaa: eikö hän ole vähäinen? että minun sieluni siellä elävänä pysyis."],[19,21,"Niin sanoi hän hänelle: katso, tässä asiassa olen minä myös sinun rukoukses päälle katsonut: etten minä kukista sitä kaupunkia, jostas puhuit.","Niin sanoi hän hänelle: katso, tässä asiassa olen minä myös sinun rukoukses päälle katsonut: etten minä kukista sitä kaupunkia, jostas puhuit."],[19,22,"Riennä, pelasta sinuas siellä: sillä en minä taida tehdä mitään, siihenasti ettäs sinne sisälle tulet. Sentähden kutsui hän sen kaupungin Zoar.","Riennä, pelasta sinuas siellä: sillä en minä taida tehdä mitään, siihenasti ettäs sinne sisälle tulet. Sentähden kutsui hän sen kaupungin Zoar."],[19,23,"Aurinko oli noussut maan päälle, ja Lot tuli Zoariin sisälle.","Aurinko oli noussut maan päälle, ja Lot tuli Zoariin sisälle."],[19,24,"Ja Herra antoi sataa Sodoman ja Gomorran päälle tulikiveä ja tulta: Herralta taivaasta.","Ja Herra antoi sataa Sodoman ja Gomorran päälle tulikiveä ja tulta: Herralta taivaasta."],[19,25,"Ja kukisti ne kaupungit, ja kaiken sen lakeuden: niin myös kaikki niiden kaupunkein asuvaiset, ja maan kasvon.","Ja kukisti ne kaupungit, ja kaiken sen lakeuden: niin myös kaikki niiden kaupunkein asuvaiset, ja maan kasvon."],[19,26,"Ja Lotin emäntä käänsi kasvonsa takaisin hänestä; ja muuttui suolapatsaaksi.","Ja Lotin emäntä käänsi kasvonsa takaisin hänestä; ja muuttui suolapatsaaksi."],[19,27,"Mutta Abraham nousi varhain aamulla, ja meni siihen paikkaan, kussa hän oli ennen seisonut Herran edessä.","Mutta Abraham nousi varhain aamulla, ja meni siihen paikkaan, kussa hän oli ennen seisonut Herran edessä."],[19,28,"Ja katsahti Sodomaa ja Gomorraa päin, ja kaiken sen maan lakeuteen; ja näki että savu nousi maasta niinkuin pätsin savu.","Ja katsahti Sodomaa ja Gomorraa päin, ja kaiken sen maan lakeuteen; ja näki että savu nousi maasta niinkuin pätsin savu."],[19,29,"Ja tapahtui, koska Jumala kukisti sen lakeuden kaupungit, muisti Jumala Abrahamin: ja johdatti Lotin ulos hävityksen keskeltä, koska hän kukisti ne kaupungit, joissa Lot asui.","Ja tapahtui, koska Jumala kukisti sen lakeuden kaupungit, muisti Jumala Abrahamin: ja johdatti Lotin ulos hävityksen keskeltä, koska hän kukisti ne kaupungit, joissa Lot asui."],[19,30,"Ja Lot läksi Zoarista, ja asui vuorella, ja kaksi hänen tytärtänsä hänen kanssansa; sillä hän pelkäsi asua Zoarissa: ja oli luolassa ja kaksi hänen tytärtänsä hänen kanssansa.","Ja Lot läksi Zoarista, ja asui vuorella, ja kaksi hänen tytärtänsä hänen kanssansa; sillä hän pelkäsi asua Zoarissa: ja oli luolassa ja kaksi hänen tytärtänsä hänen kanssansa."],[19,31,"Niin sanoi vanhempi nuoremmalle: meidän isämme on vanha: eikä ole muuta miestä maan päällä, makaamaan meidän kanssamme, koko maan tavan jälkeen.","Niin sanoi vanhempi nuoremmalle: meidän isämme on vanha: eikä ole muuta miestä maan päällä, makaamaan meidän kanssamme, koko maan tavan jälkeen."],[19,32,"Käykäämme, juottakaamme meidän isämme viinalla, ja maatkaamme hänen kanssansa, herättääksemme isästämme siementä.","Käykäämme, juottakaamme meidän isämme viinalla, ja maatkaamme hänen kanssansa, herättääksemme isästämme siementä."],[19,33,"Niin he juottivat isänsä sinä yönä viinalla. Ja vanhempi tuli ja makasi isänsä kanssa, ja ei hän huomainnut koska hän levätä tuli, ja koska hän nousi.","Niin he juottivat isänsä sinä yönä viinalla. Ja vanhempi tuli ja makasi isänsä kanssa, ja ei hän huomainnut koska hän levätä tuli, ja koska hän nousi."],[19,34,"Toisena päivänä sanoi vanhempi nuoremmalle: katso, minä makasin menneenä yönä isäni kanssa: juottakaamme häntä tänäkin yönä viinalla, ja mene sinä ja makaa hänen kanssansa, herättääksemme isästämme siementä.","Toisena päivänä sanoi vanhempi nuoremmalle: katso, minä makasin menneenä yönä isäni kanssa: juottakaamme häntä tänäkin yönä viinalla, ja mene sinä ja makaa hänen kanssansa, herättääksemme isästämme siementä."],[19,35,"Niin he juottivat myös sinä yönä isänsä viinalla: ja nuorempi meni ja makasi hänen kanssansa, ja ei hän huomainnut koska hän levätä tuli, ja koska hän nousi.","Niin he juottivat myös sinä yönä isänsä viinalla: ja nuorempi meni ja makasi hänen kanssansa, ja ei hän huomainnut koska hän levätä tuli, ja koska hän nousi."],[19,36,"Ja niin molemmat Lotin tyttäret tulivat isästänsä raskaaksi.","Ja niin molemmat Lotin tyttäret tulivat isästänsä raskaaksi."],[19,37,"Ja vanhempi synnytti pojan, ja kutsui hänen nimensä Moab: hänestä ovat Moabilaiset tulleet, hamaan tähän päivään asti.","Ja vanhempi synnytti pojan, ja kutsui hänen nimensä Moab: hänestä ovat Moabilaiset tulleet, hamaan tähän päivään asti."],[19,38,"Ja nuorempi myös synnytti pojan, ja kutsui hänen nimensä BenAmmi: hänestä tulivat Ammonin lapset, hamaan tähän päivään asti.","Ja nuorempi myös synnytti pojan, ja kutsui hänen nimensä BenAmmi: hänestä tulivat Ammonin lapset, hamaan tähän päivään asti."],[20,1,"Niin Abraham vaelsi sieltä etelään päin, ja asui Kadeksen ja Surrin vaiheella: ja oli muukalainen Gerarissa.","Niin Abraham vaelsi sieltä etelään päin, ja asui Kadeksen ja Surrin vaiheella: ja oli muukalainen Gerarissa."],[20,2,"Ja Abraham sanoi emännästänsä Saarasta: hän on minun sisareni. Niin Abimelek Gerarin kuningas lähetti ja antoi noutaa Saaran tykönsä.","Ja Abraham sanoi emännästänsä Saarasta: hän on minun sisareni. Niin Abimelek Gerarin kuningas lähetti ja antoi noutaa Saaran tykönsä."],[20,3,"Mutta Jumala tuli Abimelekin tykö yöllä unessa: ja sanoi hänelle: katso, sinun pitää kuoleman sen vaimon tähden, jonkas ottanut olet; sillä hän on yhden miehen aviovaimo.","Mutta Jumala tuli Abimelekin tykö yöllä unessa: ja sanoi hänelle: katso, sinun pitää kuoleman sen vaimon tähden, jonkas ottanut olet; sillä hän on yhden miehen aviovaimo."],[20,4,"Mutta Abimelek ei ollut ryhtynyt häneen, ja sanoi: Herra tahdotkos myös surmata hurskaan kansan?","Mutta Abimelek ei ollut ryhtynyt häneen, ja sanoi: Herra tahdotkos myös surmata hurskaan kansan?"],[20,5,"Eikö hän sanonut minulle: hän on minun sisareni, ja hän myös itse sanoi: hän on minun veljeni: yksivakaisella sydämellä ja viattomilla käsillä olen minä sen tehnyt.","Eikö hän sanonut minulle: hän on minun sisareni, ja hän myös itse sanoi: hän on minun veljeni: yksivakaisella sydämellä ja viattomilla käsillä olen minä sen tehnyt."],[20,6,"Ja Jumala sanoi hänelle unessa: minä myös tiedän, ettäs sydämes yksivakaisuudessa sen tehnyt olet. Sentähden minä myös estin sinun, ettes rikkoisi minua vastaan; jonka tähden en minä sallinut sinua ryhtymään häneen.","Ja Jumala sanoi hänelle unessa: minä myös tiedän, ettäs sydämes yksivakaisuudessa sen tehnyt olet. Sentähden minä myös estin sinun, ettes rikkoisi minua vastaan; jonka tähden en minä sallinut sinua ryhtymään häneen."],[20,7,"Niin anna nyt miehelle hänen emäntänsä jälleen; sillä hän on propheta: ja hän on rukoileva sinun edestäs, ettäs saat elää. Mutta jos et sinä anna häntä jälleen, niin tiedä, ettäs totisesti kuolet, ja kaikki mitä sinulla on.","Niin anna nyt miehelle hänen emäntänsä jälleen; sillä hän on propheta: ja hän on rukoileva sinun edestäs, ettäs saat elää. Mutta jos et sinä anna häntä jälleen, niin tiedä, ettäs totisesti kuolet, ja kaikki mitä sinulla on."],[20,8,"Niin Abimelek nousi varhain aamulla, ja kutsui kaikki palveliansa, ja puhui kaikki nämät sanat heidän kuultensa: ja miehet pelkäsivät suuresti.","Niin Abimelek nousi varhain aamulla, ja kutsui kaikki palveliansa, ja puhui kaikki nämät sanat heidän kuultensa: ja miehet pelkäsivät suuresti."],[20,9,"Ja Abimelek kutsui Abrahamin, ja sanoi hänelle: mitäs meille teit? ja mitä minä olen rikkonut sinua vastaan, ettäs saattaisit minulle ja minun valtakunnalleni niin suuren rikoksen? sinä olet tehnyt minua vastaan niitä töitä joita ei sovi tehdä.","Ja Abimelek kutsui Abrahamin, ja sanoi hänelle: mitäs meille teit? ja mitä minä olen rikkonut sinua vastaan, ettäs saattaisit minulle ja minun valtakunnalleni niin suuren rikoksen? sinä olet tehnyt minua vastaan niitä töitä joita ei sovi tehdä."],[20,10,"Ja Abimelek sanoi vielä Abrahamille: mitäs näit, ettäs tämän teit?","Ja Abimelek sanoi vielä Abrahamille: mitäs näit, ettäs tämän teit?"],[20,11,"Abraham sanoi: minä ajattelin: kukaties ei tässä paikassa ole yhtään Jumalan pelkoa: ja he surmaavat minun, emäntäni tähden.","Abraham sanoi: minä ajattelin: kukaties ei tässä paikassa ole yhtään Jumalan pelkoa: ja he surmaavat minun, emäntäni tähden."],[20,12,"Ja hän on tosin minun sisareni: sillä hän on minun isäni tytär, vaan ei äitini tytär: ja minä otin hänen emännäkseni.","Ja hän on tosin minun sisareni: sillä hän on minun isäni tytär, vaan ei äitini tytär: ja minä otin hänen emännäkseni."],[20,13,"Koska Jumala laski minun kulkemaan isäni huoneesta, sanoin minä hänelle: tämä on sinun lempes, jonka sinun minua kohtaan pitää tekemän: kuhunka paikkaan ikänänsä me tulemme, sano minusta: hän on minun veljeni.","Koska Jumala laski minun kulkemaan isäni huoneesta, sanoin minä hänelle: tämä on sinun lempes, jonka sinun minua kohtaan pitää tekemän: kuhunka paikkaan ikänänsä me tulemme, sano minusta: hän on minun veljeni."],[20,14,"Niin Abimelek otti lampaita, ja karjaa, ja palvelioita, ja piikoja, ja antoi Abrahamille: ja antoi hänelle jälleen Saaran hänen emäntänsä.","Niin Abimelek otti lampaita, ja karjaa, ja palvelioita, ja piikoja, ja antoi Abrahamille: ja antoi hänelle jälleen Saaran hänen emäntänsä."],[20,15,"Ja Abimelek sanoi: katso, minun maani on altis sinun edessäs: asu kussa sinulle parhain kelpaa.","Ja Abimelek sanoi: katso, minun maani on altis sinun edessäs: asu kussa sinulle parhain kelpaa."],[20,16,"Ja sanoi Saaralle: katso, minä olen antanut veljelles tuhannen hopiapenninkiä, katso, ne pitää oleman sinulle silmäin peitteeksi, kaikkein edessä, jotka sinun kanssas ovat, ja kaikkein muiden edessä. Ja niin vahvistettiin (hänen nuhteettomuutensa).","Ja sanoi Saaralle: katso, minä olen antanut veljelles tuhannen hopiapenninkiä, katso, ne pitää oleman sinulle silmäin peitteeksi, kaikkein edessä, jotka sinun kanssas ovat, ja kaikkein muiden edessä. Ja niin vahvistettiin (hänen nuhteettomuutensa)."],[20,17,"Ja Abraham rukoili Jumalaa: ja Jumala paransi Abimelekin, ja hänen emäntänsä, ja hänen piikansa, ja ne siittivät.","Ja Abraham rukoili Jumalaa: ja Jumala paransi Abimelekin, ja hänen emäntänsä, ja hänen piikansa, ja ne siittivät."],[20,18,"Sillä Herra oli peräti sulkenut kaikki kohdut Abimelekin huoneessa, Saaran Abrahamin emännän tähden.","Sillä Herra oli peräti sulkenut kaikki kohdut Abimelekin huoneessa, Saaran Abrahamin emännän tähden."],[21,1,"Ja Herra etsi Saaraa, niinkuin hän sanonut oli: ja Herra teki Saaralle niinkuin hän puhunut oli.","Ja Herra etsi Saaraa, niinkuin hän sanonut oli: ja Herra teki Saaralle niinkuin hän puhunut oli."],[21,2,"Ja Saara tuli raskaaksi, ja synnytti Abrahamille pojan hänen vanhuudessansa; sillä ajalla kuin Jumala hänelle sanonut oli.","Ja Saara tuli raskaaksi, ja synnytti Abrahamille pojan hänen vanhuudessansa; sillä ajalla kuin Jumala hänelle sanonut oli."],[21,3,"Ja Abraham kutsui poikansa nimen, joka hänelle syntynyt oli, ja jonka Saara hänelle synnyttänyt oli, Isaak.","Ja Abraham kutsui poikansa nimen, joka hänelle syntynyt oli, ja jonka Saara hänelle synnyttänyt oli, Isaak."],[21,4,"Ja Abraham ympärileikkasi poikansa Isaakin kahdeksan päiväisenä: niinkuin Jumala hänen käskenyt oli.","Ja Abraham ympärileikkasi poikansa Isaakin kahdeksan päiväisenä: niinkuin Jumala hänen käskenyt oli."],[21,5,"Ja Abraham oli sadan ajastaikainen, koska Isaak hänen poikansa hänelle syntyi.","Ja Abraham oli sadan ajastaikainen, koska Isaak hänen poikansa hänelle syntyi."],[21,6,"Ja Saara sanoi: Jumala on tehnyt minulle nauron: kuka ikänä sen saa kuulla, hän nauraa minua.","Ja Saara sanoi: Jumala on tehnyt minulle nauron: kuka ikänä sen saa kuulla, hän nauraa minua."],[21,7,"Ja sanoi vielä: kuka olis taitanut sanoa Abrahamille: Saara on lapsia imettävä; sillä minä olen synnyttänyt pojan hänen vanhuudessansa.","Ja sanoi vielä: kuka olis taitanut sanoa Abrahamille: Saara on lapsia imettävä; sillä minä olen synnyttänyt pojan hänen vanhuudessansa."],[21,8,"Ja lapsi kasvoi ja vieroitettiin: ja Abraham teki suuren pidon sinä päivänä, jona Isaak vieroitettiin.","Ja lapsi kasvoi ja vieroitettiin: ja Abraham teki suuren pidon sinä päivänä, jona Isaak vieroitettiin."],[21,9,"Ja Saara näki Egyptiläisen Hagarin pojan, jonka se Abrahamille synnyttänyt oli, pilkkaajaksi.","Ja Saara näki Egyptiläisen Hagarin pojan, jonka se Abrahamille synnyttänyt oli, pilkkaajaksi."],[21,10,"Ja sanoi Abrahamille: aja ulos tämä palkkavaimo poikinensa: sillä palkkavaimon pojan ei pidä perimän minun poikani Isaakin kanssa.","Ja sanoi Abrahamille: aja ulos tämä palkkavaimo poikinensa: sillä palkkavaimon pojan ei pidä perimän minun poikani Isaakin kanssa."],[21,11,"Ja tämä sana oli Abrahamin mielestä sangen karvas, hänen poikansa tähden.","Ja tämä sana oli Abrahamin mielestä sangen karvas, hänen poikansa tähden."],[21,12,"Mutta Jumala sanoi Abrahamille: älä ota sitä pahakses pojasta ja palkkapiiastas: kaikki mitä Saara sinulle sanoo, niin kuule häntä: sillä Isaakissa pitää sinulle siemen kutsuttaman.","Mutta Jumala sanoi Abrahamille: älä ota sitä pahakses pojasta ja palkkapiiastas: kaikki mitä Saara sinulle sanoo, niin kuule häntä: sillä Isaakissa pitää sinulle siemen kutsuttaman."],[21,13,"Minä teen myös piikas pojan (suureksi) kansaksi; että hän sinun siemenes on.","Minä teen myös piikas pojan (suureksi) kansaksi; että hän sinun siemenes on."],[21,14,"Niin nousi Abraham aamulla varhain, ja otti leipiä ja vesileilin; ja antoi Hagarille, ja pani hänen selkäänsä, ja (antoi hänelle) pojan, ja laski hänen menemään. Ja hän meni matkaansa, ja eksyi BerSaban korvessa.","Niin nousi Abraham aamulla varhain, ja otti leipiä ja vesileilin; ja antoi Hagarille, ja pani hänen selkäänsä, ja (antoi hänelle) pojan, ja laski hänen menemään. Ja hän meni matkaansa, ja eksyi BerSaban korvessa."],[21,15,"Koska vesi oli loppunut leilistä, heitti hän pojan puun alle.","Koska vesi oli loppunut leilistä, heitti hän pojan puun alle."],[21,16,"Ja meni pois, ja istui hänen kohdallensa taamma, liki joutsen kantamalle; sillä hän sanoi: en minä voi nähdä pojan kuolemaa. Ja hän istui hänen kohdallensa, korotti äänensä ja itki.","Ja meni pois, ja istui hänen kohdallensa taamma, liki joutsen kantamalle; sillä hän sanoi: en minä voi nähdä pojan kuolemaa. Ja hän istui hänen kohdallensa, korotti äänensä ja itki."],[21,17,"Ja Jumala kuuli pojan äänen, ja Jumalan enkeli huusi Hagaria taivaasta, ja sanoi hänelle: mikä sinun on, Hagar? älä pelkää; sillä Jumala on kuullut pojan äänen, kussa hän makaa.","Ja Jumala kuuli pojan äänen, ja Jumalan enkeli huusi Hagaria taivaasta, ja sanoi hänelle: mikä sinun on, Hagar? älä pelkää; sillä Jumala on kuullut pojan äänen, kussa hän makaa."],[21,18,"Nouse, ota poika, ja tue häntä kädelläs: sillä minä teen hänen suureksi kansaksi.","Nouse, ota poika, ja tue häntä kädelläs: sillä minä teen hänen suureksi kansaksi."],[21,19,"Ja Jumala avasi hänen silmänsä, että hän näki vesikaivon; niin hän meni ja täytti leilin vedellä, ja antoi pojan juoda.","Ja Jumala avasi hänen silmänsä, että hän näki vesikaivon; niin hän meni ja täytti leilin vedellä, ja antoi pojan juoda."],[21,20,"Ja Jumala oli pojan kanssa, ja hän kasvoi; ja asui korvessa, ja tuli tarkaksi joutsimieheksi.","Ja Jumala oli pojan kanssa, ja hän kasvoi; ja asui korvessa, ja tuli tarkaksi joutsimieheksi."],[21,21,"Ja asui Paranin korvessa; ja hänen äitinsä otti hänelle emännän Egyptin maalta.","Ja asui Paranin korvessa; ja hänen äitinsä otti hänelle emännän Egyptin maalta."],[21,22,"Sillä ajalla puhui Abimelek ja hänen sotapäämiehensä Phikol Abrahamille, sanoen: Jumala on sinun kanssas kaikissa mitä sinä teet.","Sillä ajalla puhui Abimelek ja hänen sotapäämiehensä Phikol Abrahamille, sanoen: Jumala on sinun kanssas kaikissa mitä sinä teet."],[21,23,"Niin vanno nyt minulle tässä Jumalan kautta, ettes ole minulle, ja minun pojalleni, ja poikanipojalle petollinen; vaan sen laupiuden jälkeen, jonka minä tein sinun kanssas, tee sinä myös minun kanssani, ja sen maan kanssa, jossa sinä olet muukalainen.","Niin vanno nyt minulle tässä Jumalan kautta, ettes ole minulle, ja minun pojalleni, ja poikanipojalle petollinen; vaan sen laupiuden jälkeen, jonka minä tein sinun kanssas, tee sinä myös minun kanssani, ja sen maan kanssa, jossa sinä olet muukalainen."],[21,24,"Niin sanoi Abraham: minä vannon.","Niin sanoi Abraham: minä vannon."],[21,25,"Ja Abraham nuhteli Abimelekiä, sen vesikaivon tähden, kun Abimelekin palveliat olivat väkivallalla ottaneet.","Ja Abraham nuhteli Abimelekiä, sen vesikaivon tähden, kun Abimelekin palveliat olivat väkivallalla ottaneet."],[21,26,"Ja Abimelek sanoi: en ole minä tietänyt kuka sen teki; etkä sinä ilmoittanut minulle; enkä minä sitä ole ennen kuullut, kuin tänä päivänä.","Ja Abimelek sanoi: en ole minä tietänyt kuka sen teki; etkä sinä ilmoittanut minulle; enkä minä sitä ole ennen kuullut, kuin tänä päivänä."],[21,27,"Niin otti Abraham lampaita ja karjaa, ja antoi Abimelekille; ja he tekivät molemmat liiton keskenänsä.","Niin otti Abraham lampaita ja karjaa, ja antoi Abimelekille; ja he tekivät molemmat liiton keskenänsä."],[21,28,"Ja Abraham asetti seitsemän karitsaa laumasta erinänsä.","Ja Abraham asetti seitsemän karitsaa laumasta erinänsä."],[21,29,"Ja Abimelek sanoi Abrahamille: mihinkä ne seitsemän karitsaa, jotkas olet asettanut erinänsä?","Ja Abimelek sanoi Abrahamille: mihinkä ne seitsemän karitsaa, jotkas olet asettanut erinänsä?"],[21,30,"Hän vastasi: nämät seitsemän karitsaa pitää sinun ottaman minun kädestäni, todistukseksi minulle, että minä olen tämän kaivon kaivanut.","Hän vastasi: nämät seitsemän karitsaa pitää sinun ottaman minun kädestäni, todistukseksi minulle, että minä olen tämän kaivon kaivanut."],[21,31,"Sentähden kutsui hän sen sian BerSaba: sillä siinä he molemmat vannoivat keskenänsä.","Sentähden kutsui hän sen sian BerSaba: sillä siinä he molemmat vannoivat keskenänsä."],[21,32,"Ja niin he tekivät liiton BerSabassa. Ja Abimelek nousi ja Phikol hänen sotapäämiehensä, ja palasivat Philistealaisten maalle.","Ja niin he tekivät liiton BerSabassa. Ja Abimelek nousi ja Phikol hänen sotapäämiehensä, ja palasivat Philistealaisten maalle."],[21,33,"Ja Abraham istutti puita BerSabassa; ja saarnasi siinä Herran ijankaikkisen Jumalan nimestä.","Ja Abraham istutti puita BerSabassa; ja saarnasi siinä Herran ijankaikkisen Jumalan nimestä."],[21,34,"Ja oli muukalainen Philistealaisten maalla kauvan aikaa.","Ja oli muukalainen Philistealaisten maalla kauvan aikaa."],[22,1,"Ja koska se oli tapahtunut, koetteli Jumala Abrahamia, ja sanoi hänelle: Abraham. Ja hän vastasi: Katso, tässä minä olen.","Ja koska se oli tapahtunut, koetteli Jumala Abrahamia, ja sanoi hänelle: Abraham. Ja hän vastasi: Katso, tässä minä olen."],[22,2,"Ja hän sanoi: ota nyt Isaak sinun ainoa poikas, jotas rakastat, ja mene Morian maalle; ja uhraa häntä siellä polttouhriksi yhdellä niistä vuorista, jonka minä sinulle sanova olen.","Ja hän sanoi: ota nyt Isaak sinun ainoa poikas, jotas rakastat, ja mene Morian maalle; ja uhraa häntä siellä polttouhriksi yhdellä niistä vuorista, jonka minä sinulle sanova olen."],[22,3,"Niin Abraham nousi varhain aamulla, ja valjasti aasinsa, ja otti kaksi palveliaansa kanssansa, ja poikansa Isaakin; ja halkoili puita polttouhriin, ja valmisti itsensä, ja meni sille paikalle, minkä Jumala oli hänelle sanonut.","Niin Abraham nousi varhain aamulla, ja valjasti aasinsa, ja otti kaksi palveliaansa kanssansa, ja poikansa Isaakin; ja halkoili puita polttouhriin, ja valmisti itsensä, ja meni sille paikalle, minkä Jumala oli hänelle sanonut."],[22,4,"Kolmantena päivänä nosti Abraham silmänsä, ja näki sen paikan taampana.","Kolmantena päivänä nosti Abraham silmänsä, ja näki sen paikan taampana."],[22,5,"Silloin Abraham sanoi palvelioillensa: olkaat te tässä itseksenne aasin tykönä; mutta minä ja poika käymme tuonne. Ja koska me olemme rukoilleet, niin me palajamme teidän tykönne.","Silloin Abraham sanoi palvelioillensa: olkaat te tässä itseksenne aasin tykönä; mutta minä ja poika käymme tuonne. Ja koska me olemme rukoilleet, niin me palajamme teidän tykönne."],[22,6,"Ja Abraham otti polttouhrin halvot, ja sälytti poikansa Isaakin selkään, vaan itse hän otti tulen ja veitsen käteensä; ja he kävivät molemmat ynnä.","Ja Abraham otti polttouhrin halvot, ja sälytti poikansa Isaakin selkään, vaan itse hän otti tulen ja veitsen käteensä; ja he kävivät molemmat ynnä."],[22,7,"Niin sanoi Isaak isällensä Abrahamille: minun isäni. Hän vastasi: katso, tässä minä olen, poikani. Ja hän sanoi: katso, tässä on tuli ja halvot; mutta kussa on lammas polttouhriksi?","Niin sanoi Isaak isällensä Abrahamille: minun isäni. Hän vastasi: katso, tässä minä olen, poikani. Ja hän sanoi: katso, tässä on tuli ja halvot; mutta kussa on lammas polttouhriksi?"],[22,8,"Abraham vastasi: Jumala on edeskatsova itsellensä lampaan polttouhriksi, poikani. Ja he kävivät molemmat ynnä.","Abraham vastasi: Jumala on edeskatsova itsellensä lampaan polttouhriksi, poikani. Ja he kävivät molemmat ynnä."],[22,9,"Ja kuin he tulivat sille paikalle, josta Jumala oli hänelle sanonut, teki Abraham siihen alttarin, ja pani halvot; ja sitoi poikansa Isaakin, ja pani hänen alttarille halkoin päälle.","Ja kuin he tulivat sille paikalle, josta Jumala oli hänelle sanonut, teki Abraham siihen alttarin, ja pani halvot; ja sitoi poikansa Isaakin, ja pani hänen alttarille halkoin päälle."],[22,10,"Ja ojensi kätensä, ja sivalsi veitsen, teurastaaksensa poikaansa.","Ja ojensi kätensä, ja sivalsi veitsen, teurastaaksensa poikaansa."],[22,11,"Niin Herran enkeli huusi häntä taivaasta, sanoen: Abraham, Abraham. Hän vastasi: tässä minä olen.","Niin Herran enkeli huusi häntä taivaasta, sanoen: Abraham, Abraham. Hän vastasi: tässä minä olen."],[22,12,"Hän sanoi: älä satuta kättäs poikaan, älä myös hänelle mitään tee: sillä nyt minä tiedän, että sinä pelkäät Jumalaa, ja et ole säästänyt ainokaista poikaas minun tähteni.","Hän sanoi: älä satuta kättäs poikaan, älä myös hänelle mitään tee: sillä nyt minä tiedän, että sinä pelkäät Jumalaa, ja et ole säästänyt ainokaista poikaas minun tähteni."],[22,13,"Niin Abraham nosti silmänsä, ja äkkäsi oinaan takanansa, sarvista sekaantuneena tihkiään pensastoon. Niin Abraham meni, ja otti oinaan ja uhrasi polttouhriksi poikansa edestä.","Niin Abraham nosti silmänsä, ja äkkäsi oinaan takanansa, sarvista sekaantuneena tihkiään pensastoon. Niin Abraham meni, ja otti oinaan ja uhrasi polttouhriksi poikansa edestä."],[22,14,"Ja Abraham nimitti sen paikan, Herra on edeskatsova: josta vielä tänäpänä sanotaan, Herran vuorella edeskatsotaan.","Ja Abraham nimitti sen paikan, Herra on edeskatsova: josta vielä tänäpänä sanotaan, Herran vuorella edeskatsotaan."],[22,15,"Mutta Herran enkeli huusi Abrahamia toistamiseen taivaasta.","Mutta Herran enkeli huusi Abrahamia toistamiseen taivaasta."],[22,16,"Ja sanoi: Minä olen vannonut itse kauttani, sanoo Herra: ettäs tämän teit, ja et säästänyt sinun ainoaa poikaas;","Ja sanoi: Minä olen vannonut itse kauttani, sanoo Herra: ettäs tämän teit, ja et säästänyt sinun ainoaa poikaas;"],[22,17,"Niin minä suuresti siunaan sinun, ja runsaasti lisään sinun siemenes niinkuin taivaan tähdet, ja niinkuin sannan meren reunalla. Ja sinun siemenes on perivä vihollistensa portit.","Niin minä suuresti siunaan sinun, ja runsaasti lisään sinun siemenes niinkuin taivaan tähdet, ja niinkuin sannan meren reunalla. Ja sinun siemenes on perivä vihollistensa portit."],[22,18,"Ja sinun siemenessäs pitää kaikki kansat maan päällä siunatuksi tuleman, ettäs minun äänelleni kuuliainen olit.","Ja sinun siemenessäs pitää kaikki kansat maan päällä siunatuksi tuleman, ettäs minun äänelleni kuuliainen olit."],[22,19,"Sitte palasi Abraham palveliainsa tykö, ja he nousivat, ja ynnä matkustivat BerSabaan. Ja Abraham asui BerSabassa.","Sitte palasi Abraham palveliainsa tykö, ja he nousivat, ja ynnä matkustivat BerSabaan. Ja Abraham asui BerSabassa."],[22,20,"Ja koska nämät olivat tapahtuneet, ilmoitettiin Abrahamille sanoen: katso, Milka on myös synnyttänyt poikia sinun veljelles Nahorille.","Ja koska nämät olivat tapahtuneet, ilmoitettiin Abrahamille sanoen: katso, Milka on myös synnyttänyt poikia sinun veljelles Nahorille."],[22,21,"Esikoisensa Utsin, ja Butsin hänen veljensä, ja Kemuelin Aramin isän.","Esikoisensa Utsin, ja Butsin hänen veljensä, ja Kemuelin Aramin isän."],[22,22,"Ja Kesedin ja Hasonin, ja Pildaksen ja Jedlaphen, ja Betuelin.","Ja Kesedin ja Hasonin, ja Pildaksen ja Jedlaphen, ja Betuelin."],[22,23,"Mutta Betuel siitti Rebekan. Nämät kahdeksan synnytti Milka Nahorille Abrahamin veljelle.","Mutta Betuel siitti Rebekan. Nämät kahdeksan synnytti Milka Nahorille Abrahamin veljelle."],[22,24,"Mutta hänen jalkavaimonsa, Rehuma nimeltä, synnytti Teban, Gahamin, Tehaksen ja Maakan.","Mutta hänen jalkavaimonsa, Rehuma nimeltä, synnytti Teban, Gahamin, Tehaksen ja Maakan."],[23,1,"Ja Saaran elinaika oli sata ja seitsemänkolmattakymmentä ajastaikaa: ne olivat Saaran ikävuodet.","Ja Saaran elinaika oli sata ja seitsemänkolmattakymmentä ajastaikaa: ne olivat Saaran ikävuodet."],[23,2,"Ja Saara kuoli Arban kaupungissa, joka (on) Hebron Kanaanin maalla. Niin tuli Abraham murehtimaan Saaraa ja itkemään häntä.","Ja Saara kuoli Arban kaupungissa, joka (on) Hebron Kanaanin maalla. Niin tuli Abraham murehtimaan Saaraa ja itkemään häntä."],[23,3,"Sitte nousi hän kuolleensa tyköä; ja puhui Hetin lapsille sanoen:","Sitte nousi hän kuolleensa tyköä; ja puhui Hetin lapsille sanoen:"],[23,4,"Minä olen muukalainen ja kuitenkin asuvainen teidän tykönänne, antakaat minulle perintöhauta teidän tykönänne, haudatakseni minun kuolleeni, joka on minun edessäni.","Minä olen muukalainen ja kuitenkin asuvainen teidän tykönänne, antakaat minulle perintöhauta teidän tykönänne, haudatakseni minun kuolleeni, joka on minun edessäni."],[23,5,"Niin vastasivat Hetin lapset Abrahamia, sanoen hänelle:","Niin vastasivat Hetin lapset Abrahamia, sanoen hänelle:"],[23,6,"Kuule meitä, rakas herra: sinä olet Jumalan ruhtinas meidän seassamme, hautaa sinun kuollees meidän parhaisiin hautoihimme: ei yksikään meistä sinua kiellä hautaamasta kuolluttas hänen hautaansa.","Kuule meitä, rakas herra: sinä olet Jumalan ruhtinas meidän seassamme, hautaa sinun kuollees meidän parhaisiin hautoihimme: ei yksikään meistä sinua kiellä hautaamasta kuolluttas hänen hautaansa."],[23,7,"Niin Abraham nousi ja kumarsi itsensä maan kansan edessä, (nimittäin) Hetin lasten edessä.","Niin Abraham nousi ja kumarsi itsensä maan kansan edessä, (nimittäin) Hetin lasten edessä."],[23,8,"Ja hän puhui heille, sanoen: jos teidän mielenne on, että minä hautaan minun kuolleeni, joka minun edessäni on; niin kuulkaat minua, ja rukoilkaat minun edestäni Ephronia Zoarin poikaa.","Ja hän puhui heille, sanoen: jos teidän mielenne on, että minä hautaan minun kuolleeni, joka minun edessäni on; niin kuulkaat minua, ja rukoilkaat minun edestäni Ephronia Zoarin poikaa."],[23,9,"Että hän antais minulle Makpelan luolan, joka hänellä on, vainionsa perällä: täyden hinnan edestä antakaan sen minulle teidän keskellänne perintöhaudaksi.","Että hän antais minulle Makpelan luolan, joka hänellä on, vainionsa perällä: täyden hinnan edestä antakaan sen minulle teidän keskellänne perintöhaudaksi."],[23,10,"Sillä Ephron asui Hetin lasten seassa. Niin vastasi Ephron Hetiläinen Abrahamia, Hetin poikain kuullen, kaikkein sisälle ja ulos käyväisten hänen kaupunkinsa portista, sanoen:","Sillä Ephron asui Hetin lasten seassa. Niin vastasi Ephron Hetiläinen Abrahamia, Hetin poikain kuullen, kaikkein sisälle ja ulos käyväisten hänen kaupunkinsa portista, sanoen:"],[23,11,"Ei, minun herrani, vaan kuule minua; vainion minä annan sinulle, ja luolan, joka siinä on, annan minä sinulle: minun kansani lasten nähden annan minä sen sinulle; hautaa kuollees.","Ei, minun herrani, vaan kuule minua; vainion minä annan sinulle, ja luolan, joka siinä on, annan minä sinulle: minun kansani lasten nähden annan minä sen sinulle; hautaa kuollees."],[23,12,"Abraham kumarsi maan kansan edessä.","Abraham kumarsi maan kansan edessä."],[23,13,"Ja puhui Ephronille maan kansan kuullen, sanoen: jos sinä minua kuulet: minä annan rahan vainion edestä, ota se minulta, ja minä hautaan minun kuolleeni siihen.","Ja puhui Ephronille maan kansan kuullen, sanoen: jos sinä minua kuulet: minä annan rahan vainion edestä, ota se minulta, ja minä hautaan minun kuolleeni siihen."],[23,14,"Ephron vastasi Abrahamia, sanoen hänelle:","Ephron vastasi Abrahamia, sanoen hänelle:"],[23,15,"Minun herrani, kuule minua: maa maksaa neljäsataa sikliä hopiaa; vaan mitä se on minun ja sinun välilläs? hautaa sinun kuollees.","Minun herrani, kuule minua: maa maksaa neljäsataa sikliä hopiaa; vaan mitä se on minun ja sinun välilläs? hautaa sinun kuollees."],[23,16,"Abraham kuuli Ephronia, ja punnitsi hänelle rahan, jonka hän nimittänyt oli Hetin lasten kuullen: neljäsataa sikliä hopiaa, käypää rahaa.","Abraham kuuli Ephronia, ja punnitsi hänelle rahan, jonka hän nimittänyt oli Hetin lasten kuullen: neljäsataa sikliä hopiaa, käypää rahaa."],[23,17,"Ja niin vahvistettiin Ephronin vainio, joka Makpelassa on Mamren kohdalla, sekä pelto että luola joka siinä on, ja kaikki puut siinä vainiossa, jotka ympäri kaikissa sen rajoissa ovat.","Ja niin vahvistettiin Ephronin vainio, joka Makpelassa on Mamren kohdalla, sekä pelto että luola joka siinä on, ja kaikki puut siinä vainiossa, jotka ympäri kaikissa sen rajoissa ovat."],[23,18,"(Kaikki ne tulivat) Abrahamille omaisuudeksi Hetin lasten nähden: kaikkein (nähden), jotka sisällekävivät hänen kaupunkinsa portista.","(Kaikki ne tulivat) Abrahamille omaisuudeksi Hetin lasten nähden: kaikkein (nähden), jotka sisällekävivät hänen kaupunkinsa portista."],[23,19,"Ja sitte hautasi Abraham emäntänsä Saaran siihen luolaan, joka oli Makpelan vainiossa Mamren kohdalla; se on Hebron Kanaanin maalla:","Ja sitte hautasi Abraham emäntänsä Saaran siihen luolaan, joka oli Makpelan vainiossa Mamren kohdalla; se on Hebron Kanaanin maalla:"],[23,20,"Niin vahvistettiin siis vainio ja luola, joka siinä oli, Abrahamille perintöhaudaksi, Hetin lapsilta.","Niin vahvistettiin siis vainio ja luola, joka siinä oli, Abrahamille perintöhaudaksi, Hetin lapsilta."],[24,1,"Ja Abraham oli vanha ja joutunut ijälliseksi: ja Herra oli siunannut hänen kaikissa.","Ja Abraham oli vanha ja joutunut ijälliseksi: ja Herra oli siunannut hänen kaikissa."],[24,2,"Niin sanoi Abraham vanhimmalle huoneensa palvelialle, joka kaikki hallitsi, mitä hänellä oli: laske nyt kätes minun kupeeni alle.","Niin sanoi Abraham vanhimmalle huoneensa palvelialle, joka kaikki hallitsi, mitä hänellä oli: laske nyt kätes minun kupeeni alle."],[24,3,"Ja minä vannotan sinua Herran taivaan ja maan Jumalan kautta; ettes ota emäntää minun pojalleni Kanaanealaisten tyttäristä, joiden seassa minä asun.","Ja minä vannotan sinua Herran taivaan ja maan Jumalan kautta; ettes ota emäntää minun pojalleni Kanaanealaisten tyttäristä, joiden seassa minä asun."],[24,4,"Vaan mene minun isäni maalle ja minun sukuni tykö; ja ota minun pojalleni Isaakille emäntä.","Vaan mene minun isäni maalle ja minun sukuni tykö; ja ota minun pojalleni Isaakille emäntä."],[24,5,"Ja palvelia sanoi: jos niin tapahtuis, ettei vaimo tahtoisi seurata minua tähän maahan: pitääkö minun kumminkin viemän jällensä sinun poikas sille maalle, jostas lähtenyt olet?","Ja palvelia sanoi: jos niin tapahtuis, ettei vaimo tahtoisi seurata minua tähän maahan: pitääkö minun kumminkin viemän jällensä sinun poikas sille maalle, jostas lähtenyt olet?"],[24,6,"Abraham sanoi hänelle: kavahda sinuas, ettes vie minun poikaani sinne jällensä.","Abraham sanoi hänelle: kavahda sinuas, ettes vie minun poikaani sinne jällensä."],[24,7,"Herra taivaan Jumala, joka minun otti isäni huoneesta ja syntymä-maaltani, ja joka minun kanssani puhui, ja myös vannoi minulle, sanoen: sinun siemenelles minä annan tämän maan: hän lähettää enkelinsä sinun edelläs, ettäs ottaisit minun pojalleni emännän sieltä.","Herra taivaan Jumala, joka minun otti isäni huoneesta ja syntymä-maaltani, ja joka minun kanssani puhui, ja myös vannoi minulle, sanoen: sinun siemenelles minä annan tämän maan: hän lähettää enkelinsä sinun edelläs, ettäs ottaisit minun pojalleni emännän sieltä."],[24,8,"Jos ei vaimo tahtoisi seurata sinua, niin sinä olet vapaa tästä minun valastani; ainoastansa älä vie minun poikaani sinne jälleen.","Jos ei vaimo tahtoisi seurata sinua, niin sinä olet vapaa tästä minun valastani; ainoastansa älä vie minun poikaani sinne jälleen."],[24,9,"Niin laski palvelia kätensä herransa Abrahamin kupeen alle; ja vannoi hänelle sen.","Niin laski palvelia kätensä herransa Abrahamin kupeen alle; ja vannoi hänelle sen."],[24,10,"Niin otti palvelia kymmenen kamelia herransa kameleista, ja läksi matkaan, ja otti myötänsä kaikkinaisesta herransa tavarasta: ja vaelsi Mesopotamiaan Nahorin kaupunkiin.","Niin otti palvelia kymmenen kamelia herransa kameleista, ja läksi matkaan, ja otti myötänsä kaikkinaisesta herransa tavarasta: ja vaelsi Mesopotamiaan Nahorin kaupunkiin."],[24,11,"Ja hän antoi kamelein laskea polvillensa ulkona kaupungista vesikaivon tykönä; ehtoopuolella, jolla ajalla vaimoväen tapa oli lähteä vettä ammuntamaan.","Ja hän antoi kamelein laskea polvillensa ulkona kaupungista vesikaivon tykönä; ehtoopuolella, jolla ajalla vaimoväen tapa oli lähteä vettä ammuntamaan."],[24,12,"Ja sanoi: Herra, minun herrani Abrahamin Jumala, anna minun kohdata tänäpänä (herrani morsiamen); ja tee laupius minun herrani Abrahamin kanssa.","Ja sanoi: Herra, minun herrani Abrahamin Jumala, anna minun kohdata tänäpänä (herrani morsiamen); ja tee laupius minun herrani Abrahamin kanssa."],[24,13,"Katso, minä seison tässä vesikaivon tykönä: ja heidän tyttärensä, jotka asuvat tässä kaupungissa, tulevat vettä ammuntamaan.","Katso, minä seison tässä vesikaivon tykönä: ja heidän tyttärensä, jotka asuvat tässä kaupungissa, tulevat vettä ammuntamaan."],[24,14,"Jos joku piika tulee, jolle minä sanon: kallista tänne vesiastias juodakseni, ja hän sanoo: juo, minä juotan myös sinun kamelis: että hän on se, jonkas olet edeskatsonut palvelialles Isaakille, ja siitä ymmärtäisin tehnees laupiuden minun herrani kanssa.","Jos joku piika tulee, jolle minä sanon: kallista tänne vesiastias juodakseni, ja hän sanoo: juo, minä juotan myös sinun kamelis: että hän on se, jonkas olet edeskatsonut palvelialles Isaakille, ja siitä ymmärtäisin tehnees laupiuden minun herrani kanssa."],[24,15,"Ja ennenkuin hän lakkasi puhumasta, katso, Rebekka tuli, joka syntynyt oli Betuelille, Milkan, Abrahamin veljen Nahorin emännän pojalle. Ja hänellä vesiastiansa olallansa.","Ja ennenkuin hän lakkasi puhumasta, katso, Rebekka tuli, joka syntynyt oli Betuelille, Milkan, Abrahamin veljen Nahorin emännän pojalle. Ja hänellä vesiastiansa olallansa."],[24,16,"Ja piika oli sangen ihana nähdä, ja vielä neitsy, ja ei yksikään mies ollut häneen ryhtynyt: hän meni alas kaivon tykö, ja täytti astiansa, ja tuli ylös.","Ja piika oli sangen ihana nähdä, ja vielä neitsy, ja ei yksikään mies ollut häneen ryhtynyt: hän meni alas kaivon tykö, ja täytti astiansa, ja tuli ylös."],[24,17,"Niin palvelia juoksi häntä vastaan, ja sanoi: annas minun juoda vähä vettä astiastas.","Niin palvelia juoksi häntä vastaan, ja sanoi: annas minun juoda vähä vettä astiastas."],[24,18,"Hän sanoi: juo minun herrani: ja hän kiiruusti laski alas vesiastiansa kätensä päälle, ja antoi hänen juoda.","Hän sanoi: juo minun herrani: ja hän kiiruusti laski alas vesiastiansa kätensä päälle, ja antoi hänen juoda."],[24,19,"Ja kuin hän oli antanut hänen juoda, sanoi hän: minä myös ammunnan vettä kameleilles, niinkauvan että he kaikki saavat juoda.","Ja kuin hän oli antanut hänen juoda, sanoi hän: minä myös ammunnan vettä kameleilles, niinkauvan että he kaikki saavat juoda."],[24,20,"Ja hän kaasi kohta veden astiastansa ruuheen, ja juoksi taas kaivolle ammuntamaan: ja ammunsi kaikille hänen kameleillensa.","Ja hän kaasi kohta veden astiastansa ruuheen, ja juoksi taas kaivolle ammuntamaan: ja ammunsi kaikille hänen kameleillensa."],[24,21,"Mutta mies ihmetteli häntä: ja oli ääneti, ja tahtoi tietää, jos Herra oli tehnyt hänen matkansa onnelliseksi, taikka ei.","Mutta mies ihmetteli häntä: ja oli ääneti, ja tahtoi tietää, jos Herra oli tehnyt hänen matkansa onnelliseksi, taikka ei."],[24,22,"Ja koska kaikki kamelit olivat juoneet, antoi mies hänelle kulta-otsalehden, joka painoi puolen sikliä: niin myös kaksi rannerengasta hänen käsiinsä, jotka painoivat kymmenen sikliä kultaa.","Ja koska kaikki kamelit olivat juoneet, antoi mies hänelle kulta-otsalehden, joka painoi puolen sikliä: niin myös kaksi rannerengasta hänen käsiinsä, jotka painoivat kymmenen sikliä kultaa."],[24,23,"Ja sanoi: kenenkäs tytär olet? sanos minulle se: onko isäs huoneessa siaa meidän yötä ollaksemme?","Ja sanoi: kenenkäs tytär olet? sanos minulle se: onko isäs huoneessa siaa meidän yötä ollaksemme?"],[24,24,"Hän sanoi hänelle: minä olen Betuelin, Milkan pojan, tytär, jonka hän synnytti Nahorille.","Hän sanoi hänelle: minä olen Betuelin, Milkan pojan, tytär, jonka hän synnytti Nahorille."],[24,25,"Ja hän vielä sanoi hänelle: on myös olkia ja karjan ruokaa kyllä meillä: ja myös siaa yötä olla.","Ja hän vielä sanoi hänelle: on myös olkia ja karjan ruokaa kyllä meillä: ja myös siaa yötä olla."],[24,26,"Ja mies kumarsi maahan ja rukoili Herraa:","Ja mies kumarsi maahan ja rukoili Herraa:"],[24,27,"Ja sanoi: kiitetty olkoon Herra, minun herrani Abrahamin Jumala, joka ei ottanut pois laupiuttansa ja totuuttansa minun herraltani: minua on Herra johdattanut tällä tiellä, minun herrani veljen huoneesen.","Ja sanoi: kiitetty olkoon Herra, minun herrani Abrahamin Jumala, joka ei ottanut pois laupiuttansa ja totuuttansa minun herraltani: minua on Herra johdattanut tällä tiellä, minun herrani veljen huoneesen."],[24,28,"Niin piika juoksi ja ilmoitti nämät asiat äitinsä huoneessa.","Niin piika juoksi ja ilmoitti nämät asiat äitinsä huoneessa."],[24,29,"Oli myös Rebekalla veli, jonka nimi oli Laban: ja Laban juoksi miehen tykö lähteelle.","Oli myös Rebekalla veli, jonka nimi oli Laban: ja Laban juoksi miehen tykö lähteelle."],[24,30,"Sillä koska hän näki otsalehden ja rannerenkaat sisarensa käsissä, ja kuuli sisarensa Rebekan puheet, sanovan: näin on mies puhunut minulle; tuli hän miehen tykö, ja katso, hän seisoi kamelein tykönä lähteellä.","Sillä koska hän näki otsalehden ja rannerenkaat sisarensa käsissä, ja kuuli sisarensa Rebekan puheet, sanovan: näin on mies puhunut minulle; tuli hän miehen tykö, ja katso, hän seisoi kamelein tykönä lähteellä."],[24,31,"Ja sanoi: tule sisälle, sinä Herran siunattu, mitäs seisot ulkona? minä olen huoneen valmistanut, ja sian kameleille.","Ja sanoi: tule sisälle, sinä Herran siunattu, mitäs seisot ulkona? minä olen huoneen valmistanut, ja sian kameleille."],[24,32,"Niin meni mies huoneesen, ja riisui kamelit: ja hän antoi olkia ja ruokaa kameleille, ja vettä pestä hänen jalkojansa, ja miesten jalkoja, jotka hänen kanssansa olivat.","Niin meni mies huoneesen, ja riisui kamelit: ja hän antoi olkia ja ruokaa kameleille, ja vettä pestä hänen jalkojansa, ja miesten jalkoja, jotka hänen kanssansa olivat."],[24,33,"Sitte pantiin ruokaa hänen eteensä: mutta hän sanoi: en minä syö ennenkuin minä olen puhunut minun asiani. He vastasivat: puhu.","Sitte pantiin ruokaa hänen eteensä: mutta hän sanoi: en minä syö ennenkuin minä olen puhunut minun asiani. He vastasivat: puhu."],[24,34,"Hän sanoi: minä olen Abrahamin palvelia.","Hän sanoi: minä olen Abrahamin palvelia."],[24,35,"Ja Herra on runsaasti siunannut minun herrani, ja hän on suureksi tullut, ja on antanut hänelle lampaita ja karjaa, hopiaa ja kultaa, palvelioita ja piikoja, kameleja ja aaseja.","Ja Herra on runsaasti siunannut minun herrani, ja hän on suureksi tullut, ja on antanut hänelle lampaita ja karjaa, hopiaa ja kultaa, palvelioita ja piikoja, kameleja ja aaseja."],[24,36,"Niin myös Saara minun herrani emäntä on synnyttänyt minun herralleni pojan, vanhalla ijällänsä: hänelle on hän antanut kaikki mitä hänellä on.","Niin myös Saara minun herrani emäntä on synnyttänyt minun herralleni pojan, vanhalla ijällänsä: hänelle on hän antanut kaikki mitä hänellä on."],[24,37,"Ja minun herrani vannotti minua, sanoen: ei sinun pidä ottaman minun pojalleni emäntää Kanaanealaisten tyttäristä, joiden maalla minä asun.","Ja minun herrani vannotti minua, sanoen: ei sinun pidä ottaman minun pojalleni emäntää Kanaanealaisten tyttäristä, joiden maalla minä asun."],[24,38,"Vaan mene minun isäni huoneesen, ja minun sukuni tykö; ja ota (sieltä) minun pojalleni emäntä.","Vaan mene minun isäni huoneesen, ja minun sukuni tykö; ja ota (sieltä) minun pojalleni emäntä."],[24,39,"Mutta minä sanoin minun herralleni: taitais tapahtua, ettei vaimo seuraisi minua?","Mutta minä sanoin minun herralleni: taitais tapahtua, ettei vaimo seuraisi minua?"],[24,40,"Niin hän sanoi minulle: Herra, jonka edessä minä vaellan, lähettää enkelinsä sinun kanssas, joka tekee sinun matkas onnelliseksi, ottamaan minun pojalleni emäntä minun suvustani ja minun isäni huoneesta.","Niin hän sanoi minulle: Herra, jonka edessä minä vaellan, lähettää enkelinsä sinun kanssas, joka tekee sinun matkas onnelliseksi, ottamaan minun pojalleni emäntä minun suvustani ja minun isäni huoneesta."],[24,41,"Silloin sinä tulet vapaaksi minun valastani, koskas tulet minun sukuni tykö: ja jos ei he anna sinulle, niin sinä olet vapaa valastani.","Silloin sinä tulet vapaaksi minun valastani, koskas tulet minun sukuni tykö: ja jos ei he anna sinulle, niin sinä olet vapaa valastani."],[24,42,"Niin tulin minä tänäpänä lähteelle, ja sanoin: Herra, minun herrani Abrahamin Jumala, jos sinä olet tehnyt minun matkani onnelliseksi, jota minä nyt vaellan.","Niin tulin minä tänäpänä lähteelle, ja sanoin: Herra, minun herrani Abrahamin Jumala, jos sinä olet tehnyt minun matkani onnelliseksi, jota minä nyt vaellan."],[24,43,"Katso, niin seison minä tässä vesilähteen tykönä: koska yksi piika tulee vettä ammuntamaan, ja minä sanon hänelle: annas minulle vähä vettä juoda astiastas:","Katso, niin seison minä tässä vesilähteen tykönä: koska yksi piika tulee vettä ammuntamaan, ja minä sanon hänelle: annas minulle vähä vettä juoda astiastas:"],[24,44,"Ja hän sanoo minulle: juo sinä, minä ammunnan myös sinun kameleilles: se on se vaimo, jonka Herra on edeskatsonut minun herrani pojalle.","Ja hän sanoo minulle: juo sinä, minä ammunnan myös sinun kameleilles: se on se vaimo, jonka Herra on edeskatsonut minun herrani pojalle."],[24,45,"En minä vielä päässyt puhumasta sydämessäni, katso, niin Rebekka tuli, ja hänen vesiastiansa hänen olallansa, astui alas lähteelle ja ammunsi: ja minä sanoin hänelle: annas minun juoda.","En minä vielä päässyt puhumasta sydämessäni, katso, niin Rebekka tuli, ja hänen vesiastiansa hänen olallansa, astui alas lähteelle ja ammunsi: ja minä sanoin hänelle: annas minun juoda."],[24,46,"Ja hän riensi ja laski vesiastian olaltansa alas, ja sanoi: juo, minä juotan myös kamelis. Niin minä join, ja hän juotti myös kamelit.","Ja hän riensi ja laski vesiastian olaltansa alas, ja sanoi: juo, minä juotan myös kamelis. Niin minä join, ja hän juotti myös kamelit."],[24,47,"Ja minä kysyin häneltä, ja sanoin: kenekä tytär sinä olet? hän vastasi: minä olen Betuelin tytär, Nahorin pojan, jonka Milka hänelle synnytti. Niin minä panin otsalehden hänen otsaansa, ja rannerenkaat hänen käsiinsä:","Ja minä kysyin häneltä, ja sanoin: kenekä tytär sinä olet? hän vastasi: minä olen Betuelin tytär, Nahorin pojan, jonka Milka hänelle synnytti. Niin minä panin otsalehden hänen otsaansa, ja rannerenkaat hänen käsiinsä:"],[24,48,"Ja kumarsin itseni maahan ja rukoilin Herraa: ja kiitin Herraa, minun herrani Abrahamin Jumalaa, joka minun oli johdattanut oikiaa tietä, ottamaan hänen pojallensa minun herrani veljen tytärtä.","Ja kumarsin itseni maahan ja rukoilin Herraa: ja kiitin Herraa, minun herrani Abrahamin Jumalaa, joka minun oli johdattanut oikiaa tietä, ottamaan hänen pojallensa minun herrani veljen tytärtä."],[24,49,"Ja nyt, jos te olette ne, jotka osotatte minun herralleni laupiuden ja totuuden, niin sanokaat minulle: ja jos ei, niin sanokaat myös minulle, että minä kääntäisin itseni oikialle taikka vasemmalle puolelle.","Ja nyt, jos te olette ne, jotka osotatte minun herralleni laupiuden ja totuuden, niin sanokaat minulle: ja jos ei, niin sanokaat myös minulle, että minä kääntäisin itseni oikialle taikka vasemmalle puolelle."],[24,50,"Niin vastasi Laban ja Betuel, ja sanoivat: tämä asia on tullut Herralta; sentähden emme taida sinua vastaan puhua, pahaa taikka hyvää.","Niin vastasi Laban ja Betuel, ja sanoivat: tämä asia on tullut Herralta; sentähden emme taida sinua vastaan puhua, pahaa taikka hyvää."],[24,51,"Siinä on Rebekka edessäs, ota häntä ja mene, ja olkaan sinun herras pojan emäntä, niinkuin Herra on sanonut.","Siinä on Rebekka edessäs, ota häntä ja mene, ja olkaan sinun herras pojan emäntä, niinkuin Herra on sanonut."],[24,52,"Ja koska Abrahamin palvelia kuuli heidän sanansa; kumarsi hän maahan Herran eteen.","Ja koska Abrahamin palvelia kuuli heidän sanansa; kumarsi hän maahan Herran eteen."],[24,53,"Ja palvelia toi hopia- ja kultakalut, ja vaatteet, ja antoi Rebekalle: vaan hänen veljellensä ja äidillensä antoi hän (muita) kalleita kaluja.","Ja palvelia toi hopia- ja kultakalut, ja vaatteet, ja antoi Rebekalle: vaan hänen veljellensä ja äidillensä antoi hän (muita) kalleita kaluja."],[24,54,"Niin he söivät ja joivat, hän ja miehet, jotka hänen kanssansa olivat, ja siellä pitivät yötä: ja he nousivat aamulla varhain: ja hän sanoi: päästäkäät minua herrani tykö.","Niin he söivät ja joivat, hän ja miehet, jotka hänen kanssansa olivat, ja siellä pitivät yötä: ja he nousivat aamulla varhain: ja hän sanoi: päästäkäät minua herrani tykö."],[24,55,"Mutta hänen veljensä ja äitinsä sanoivat: olkaan piika meidän tykönämme edes kymmenenkin päivää: sitte sinä saat mennä.","Mutta hänen veljensä ja äitinsä sanoivat: olkaan piika meidän tykönämme edes kymmenenkin päivää: sitte sinä saat mennä."],[24,56,"Niin sanoi hän heille: älkäät viivyttäkö minua: sillä Herra on tehnyt minun matkani onnelliseksi: laskekaat minua menemään minun herrani tykö.","Niin sanoi hän heille: älkäät viivyttäkö minua: sillä Herra on tehnyt minun matkani onnelliseksi: laskekaat minua menemään minun herrani tykö."],[24,57,"Niin he sanoivat: kutsukaamme piika, ja kysykäämme mitä hän sanoo.","Niin he sanoivat: kutsukaamme piika, ja kysykäämme mitä hän sanoo."],[24,58,"Ja he kutsuivat Rebekan, ja sanoivat hänelle: tahdotkos mennä tämän miehen kanssa? hän vastasi: menen.","Ja he kutsuivat Rebekan, ja sanoivat hänelle: tahdotkos mennä tämän miehen kanssa? hän vastasi: menen."],[24,59,"Niin he laskivat sisarensa Rebekan menemään, ja hänen imettäjänsä, Abrahamin palvelian kanssa; ja ne jotka hänen seurassansa olivat.","Niin he laskivat sisarensa Rebekan menemään, ja hänen imettäjänsä, Abrahamin palvelian kanssa; ja ne jotka hänen seurassansa olivat."],[24,60,"Ja he siunasivat Rebekkaa ja sanoivat hänelle: sinä olet meidän sisaremme, lisäänny tuhannen tuhanteen; ja sinun siemenes omistakoon vihamiestensä portit.","Ja he siunasivat Rebekkaa ja sanoivat hänelle: sinä olet meidän sisaremme, lisäänny tuhannen tuhanteen; ja sinun siemenes omistakoon vihamiestensä portit."],[24,61,"Niin Rebekka nousi piikoinensa, ja istuivat kamelein päälle, ja seurasivat sitä miestä. Ja palvelia otti Rebekan, ja meni matkaansa.","Niin Rebekka nousi piikoinensa, ja istuivat kamelein päälle, ja seurasivat sitä miestä. Ja palvelia otti Rebekan, ja meni matkaansa."],[24,62,"Mutta Isaak palasi siltä kaivolta, joka kutsuttiin sen elävän, joka minun näkee: sillä hän asui etelän maalla.","Mutta Isaak palasi siltä kaivolta, joka kutsuttiin sen elävän, joka minun näkee: sillä hän asui etelän maalla."],[24,63,"Ja oli lähtenyt rukoilemaan kedolle ehtoopuolella: ja nosti silmänsä, ja näki, ja katso, kamelit lähestyivät.","Ja oli lähtenyt rukoilemaan kedolle ehtoopuolella: ja nosti silmänsä, ja näki, ja katso, kamelit lähestyivät."],[24,64,"Ja Rebekka nosti silmänsä ja näki Isaakin: ja pudotti itsensä maahan kamelin päältä:","Ja Rebekka nosti silmänsä ja näki Isaakin: ja pudotti itsensä maahan kamelin päältä:"],[24,65,"Ja sanoi palvelialle: mikä mies tämä on, joka kedolla käy meitä vastaan? palvelia vastasi: se on minun herrani: niin hän otti vaatteen ja peitti itsensä.","Ja sanoi palvelialle: mikä mies tämä on, joka kedolla käy meitä vastaan? palvelia vastasi: se on minun herrani: niin hän otti vaatteen ja peitti itsensä."],[24,66,"Ja palvelia jutteli Isaakille kaiken asian, kuin hän oli toimittanut.","Ja palvelia jutteli Isaakille kaiken asian, kuin hän oli toimittanut."],[24,67,"Ja Isaak vei hänen äitinsä Saaran majaan: ja otti Rebekan emännäksensä, ja rakasti häntä: ja niin Isaak lohdutettiin äitinsä jälkeen.","Ja Isaak vei hänen äitinsä Saaran majaan: ja otti Rebekan emännäksensä, ja rakasti häntä: ja niin Isaak lohdutettiin äitinsä jälkeen."],[25,1,"Ja Abraham taas otti emännän nimeltä Ketura.","Ja Abraham taas otti emännän nimeltä Ketura."],[25,2,"Hän synnytti hänelle Simran ja Joksan, ja Medan ja Midian, ja Jesbakin ja Suan.","Hän synnytti hänelle Simran ja Joksan, ja Medan ja Midian, ja Jesbakin ja Suan."],[25,3,"Mutta Joksan siitti Seban ja Dedanin. Dedanin lapset olivat: Asserim, Letusin ja Luumim.","Mutta Joksan siitti Seban ja Dedanin. Dedanin lapset olivat: Asserim, Letusin ja Luumim."],[25,4,"Midianin lapset olivat: Epha, Epher, Hanok, Abida, ja Eldaa: nämät kaikki ovat Keturan pojat.","Midianin lapset olivat: Epha, Epher, Hanok, Abida, ja Eldaa: nämät kaikki ovat Keturan pojat."],[25,5,"Ja Abraham antoi kaikki mitä hänellä oli Iisakille.","Ja Abraham antoi kaikki mitä hänellä oli Iisakille."],[25,6,"Mutta niille lapsille, jotka jalkavaimoista olivat, antoi hän lahjoja, ja lähetti heidät pois poikansa Isaakin tyköä, vielä eläissänsä, idän puoleen, itäiselle maalle.","Mutta niille lapsille, jotka jalkavaimoista olivat, antoi hän lahjoja, ja lähetti heidät pois poikansa Isaakin tyköä, vielä eläissänsä, idän puoleen, itäiselle maalle."],[25,7,"Ja tämä on Abrahamin elinaika, kuin hän eli: sata ja viisikahdeksattakymmentä ajastaikaa.","Ja tämä on Abrahamin elinaika, kuin hän eli: sata ja viisikahdeksattakymmentä ajastaikaa."],[25,8,"Ja hän tuli riutuneeksi, ja kuoli levollisessa ijässä, vanhana ja elämästä kyllänsä saanut: ja koottiin kansansa tykö.","Ja hän tuli riutuneeksi, ja kuoli levollisessa ijässä, vanhana ja elämästä kyllänsä saanut: ja koottiin kansansa tykö."],[25,9,"Ja hänen poikansa Isaak ja Ismael hautasivat hänen Makpelan luolaan: Ephronin Hetiläisen Zoarin pojan vainiossa, Mamren kohdalle:","Ja hänen poikansa Isaak ja Ismael hautasivat hänen Makpelan luolaan: Ephronin Hetiläisen Zoarin pojan vainiossa, Mamren kohdalle:"],[25,10,"Sille kedolle, jonka Abraham oli ostanut Hetin lapsilta: siihen on Abraham haudattu, ja Saara hänen emäntänsä.","Sille kedolle, jonka Abraham oli ostanut Hetin lapsilta: siihen on Abraham haudattu, ja Saara hänen emäntänsä."],[25,11,"Ja Abrahamin kuoleman jälkeen siunasi Jumala hänen poikansa Isaakin: Ja Isaak asui sen elävän, joka minun näkee, kaivon tykönä.","Ja Abrahamin kuoleman jälkeen siunasi Jumala hänen poikansa Isaakin: Ja Isaak asui sen elävän, joka minun näkee, kaivon tykönä."],[25,12,"Mutta nämät ovat Ismaelin Abrahamin pojan sukukunnat, jonka Hagar Egyptiläinen Saaran piika synnytti.","Mutta nämät ovat Ismaelin Abrahamin pojan sukukunnat, jonka Hagar Egyptiläinen Saaran piika synnytti."],[25,13,"Ja nämä ovat Ismaelin poikain nimet, heidän nimeinsä ja sukukuntainsa jälkeen: Ismaelin esikoinen oli Nebaot, Kedar, Abdeel, Mibsam,","Ja nämä ovat Ismaelin poikain nimet, heidän nimeinsä ja sukukuntainsa jälkeen: Ismaelin esikoinen oli Nebaot, Kedar, Abdeel, Mibsam,"],[25,14,"Misma, Duma, Masa,","Misma, Duma, Masa,"],[25,15,"Hadar, Tema, Jetur, Naphis ja Kedma.","Hadar, Tema, Jetur, Naphis ja Kedma."],[25,16,"Nämät ovat Ismaelin lapset, ja nämät heidän nimensä, heidän kylissänsä ja kaupungeissansa: kaksitoistakymmentä ruhtinasta heidän kansoissansa.","Nämät ovat Ismaelin lapset, ja nämät heidän nimensä, heidän kylissänsä ja kaupungeissansa: kaksitoistakymmentä ruhtinasta heidän kansoissansa."],[25,17,"Ja tämä on Ismaelin ikä: sata ja seitsemänneljättäkymmentä ajastaikaa: ja hän tuli riutuneeksi, ja kuoli, ja koottiin kansansa tykö.","Ja tämä on Ismaelin ikä: sata ja seitsemänneljättäkymmentä ajastaikaa: ja hän tuli riutuneeksi, ja kuoli, ja koottiin kansansa tykö."],[25,18,"Mutta he asuivat Hevilasta hamaan Surriin asti, joka on Egyptin kohdalla Assyriaan mentäissä. Kaikkein hänen veljeinsä kohdalle lankesi (hänen arpansa).","Mutta he asuivat Hevilasta hamaan Surriin asti, joka on Egyptin kohdalla Assyriaan mentäissä. Kaikkein hänen veljeinsä kohdalle lankesi (hänen arpansa)."],[25,19,"Ja nämät ovat Isaakin Abrahamin pojan sukukunnat: Abraham siitti Isaakin.","Ja nämät ovat Isaakin Abrahamin pojan sukukunnat: Abraham siitti Isaakin."],[25,20,"Ja Isaak oli neljänkymmenen ajastaikainen, koska hän otti Rebekan Betuelin Syrialaisen tyttären Mesopotamiasta, Labanin syrialaisen sisaren, itsellensä emännäksi.","Ja Isaak oli neljänkymmenen ajastaikainen, koska hän otti Rebekan Betuelin Syrialaisen tyttären Mesopotamiasta, Labanin syrialaisen sisaren, itsellensä emännäksi."],[25,21,"Ja Isaak rukoili Herraa emäntänsä edestä; sillä hän oli hedelmätöin, ja Herra kuuli häntä: niin Rebekka hänen emäntänsä tuli raskaaksi.","Ja Isaak rukoili Herraa emäntänsä edestä; sillä hän oli hedelmätöin, ja Herra kuuli häntä: niin Rebekka hänen emäntänsä tuli raskaaksi."],[25,22,"Ja lapset sysäsivät toinen toistansa hänen kohdussansa. Niin hän sanoi: jos näin piti käymän, miksi minä olen (raskaaksi tullut?) ja meni kysymään Herralta.","Ja lapset sysäsivät toinen toistansa hänen kohdussansa. Niin hän sanoi: jos näin piti käymän, miksi minä olen (raskaaksi tullut?) ja meni kysymään Herralta."],[25,23,"Ja Herra sanoi hänelle: kaksi kansaa ovat sinun kohdussas, ja kahtalainen väki erkanee sinun ruumiistas: mutta toinen kansa voittaa toisen, ja suurempi palvelee vähempää.","Ja Herra sanoi hänelle: kaksi kansaa ovat sinun kohdussas, ja kahtalainen väki erkanee sinun ruumiistas: mutta toinen kansa voittaa toisen, ja suurempi palvelee vähempää."],[25,24,"Koska aika tuli synnyttää; katso, kaksoiset olivat hänen kohdussansa.","Koska aika tuli synnyttää; katso, kaksoiset olivat hänen kohdussansa."],[25,25,"Ensimäinen joka tuli ulos, oli ruskia ja karvainen niinkuin vaate: sentähden kutsuivat he hänen nimensä Esau.","Ensimäinen joka tuli ulos, oli ruskia ja karvainen niinkuin vaate: sentähden kutsuivat he hänen nimensä Esau."],[25,26,"Senjälkeen tuli ulos hänen veljensä, joka piti kädellänsä Esaun kantapäästä, ja se kutsuivat hänen nimensä Jakob. Kuudenkymmenen ajastaikainen oli Isaak heidän syntyissänsä.","Senjälkeen tuli ulos hänen veljensä, joka piti kädellänsä Esaun kantapäästä, ja se kutsuivat hänen nimensä Jakob. Kuudenkymmenen ajastaikainen oli Isaak heidän syntyissänsä."],[25,27,"Ja poikaiset kasvoivat, ja Esau tuli jaloksi metsä- ja peltomieheksi. Mutta Jakob oli yksivakainen mies, ja asui majoissa.","Ja poikaiset kasvoivat, ja Esau tuli jaloksi metsä- ja peltomieheksi. Mutta Jakob oli yksivakainen mies, ja asui majoissa."],[25,28,"Ja Isaak rakasti Esauta; sillä hän söi mielellänsä hänen metsäsaalistansa. Mutta Rebekka rakasti Jakobia.","Ja Isaak rakasti Esauta; sillä hän söi mielellänsä hänen metsäsaalistansa. Mutta Rebekka rakasti Jakobia."],[25,29,"Koska Jakob oli keittänyt herkun, tuli Esau metsästä, ja oli väsyksissä.","Koska Jakob oli keittänyt herkun, tuli Esau metsästä, ja oli väsyksissä."],[25,30,"Ja Esau sanoi Jakobille: anna minun syödä tästä ruskiasta herkusta: sillä minä olen väsyksissä. Sentähden kutsutaan hänen nimensä Edom.","Ja Esau sanoi Jakobille: anna minun syödä tästä ruskiasta herkusta: sillä minä olen väsyksissä. Sentähden kutsutaan hänen nimensä Edom."],[25,31,"Mutta Jakob sanoi: myy minulle tänäpänä sinun esikoisuutes.","Mutta Jakob sanoi: myy minulle tänäpänä sinun esikoisuutes."],[25,32,"Esau vastasi: katso, minä kuolen kuitenkin; mitä minun esikoisuudesta on?","Esau vastasi: katso, minä kuolen kuitenkin; mitä minun esikoisuudesta on?"],[25,33,"Ja Jakob sanoi: niin vanno minulle tänäpänä: ja hän vannoi hänelle, ja myi Jakobille esikoisuutensa.","Ja Jakob sanoi: niin vanno minulle tänäpänä: ja hän vannoi hänelle, ja myi Jakobille esikoisuutensa."],[25,34,"Niin Jakob antoi Esaulle leivän, ja sen ruskian herneherkun, ja hän söi ja joi, ja nousi ja meni pois. Ja niin Esau katsoi esikoisuutensa ylön.","Niin Jakob antoi Esaulle leivän, ja sen ruskian herneherkun, ja hän söi ja joi, ja nousi ja meni pois. Ja niin Esau katsoi esikoisuutensa ylön."],[26,1,"Niin kallis aika tuli maalle sen entisen jälkeen, joka oli Abrahamin ajalla: ja Isaak meni Abimelekin Philistealaisten kuninkaan tykö Gerariin.","Niin kallis aika tuli maalle sen entisen jälkeen, joka oli Abrahamin ajalla: ja Isaak meni Abimelekin Philistealaisten kuninkaan tykö Gerariin."],[26,2,"Niin Herra ilmestyi hänelle, ja sanoi: älä mene Egyptiin, vaan asu sillä maalla, jonka minä sanon sinulle.","Niin Herra ilmestyi hänelle, ja sanoi: älä mene Egyptiin, vaan asu sillä maalla, jonka minä sanon sinulle."],[26,3,"Ole muukalainen tällä maalla, ja minä olen sinun kanssas, ja siunaan sinua: sillä sinulle ja sinun siemenelles minä annan kaikki nämät maat, ja vahvistan sen valan, jonka minä Abrahamille sinun isälles vannonut olen.","Ole muukalainen tällä maalla, ja minä olen sinun kanssas, ja siunaan sinua: sillä sinulle ja sinun siemenelles minä annan kaikki nämät maat, ja vahvistan sen valan, jonka minä Abrahamille sinun isälles vannonut olen."],[26,4,"Ja enennän sinun siemenes niinkuin taivaan tähdet: ja annan sinun siemenelles kaikki nämät maat: Ja sinun siemenes kautta pitää kaikki kansat maan päällä siunatuksi tuleman:","Ja enennän sinun siemenes niinkuin taivaan tähdet: ja annan sinun siemenelles kaikki nämät maat: Ja sinun siemenes kautta pitää kaikki kansat maan päällä siunatuksi tuleman:"],[26,5,"Sillä Abraham oli kuuliainen minun äänelleni, ja piti minun oikeuteni, käskyni, säätyni ja lakini.","Sillä Abraham oli kuuliainen minun äänelleni, ja piti minun oikeuteni, käskyni, säätyni ja lakini."],[26,6,"Niin Isaak asui Gerarissa.","Niin Isaak asui Gerarissa."],[26,7,"Ja koska sen maan kansa kysyi hänen emännästänsä, sanoi hän: hän on minun sisareni; sillä hän pelkäsi sanoa: hän on minun emäntäni (ajatellen), ettei he joskus löisi minua kuoliaksi Rebekan tähden: sillä hän oli ihana kasvoilta.","Ja koska sen maan kansa kysyi hänen emännästänsä, sanoi hän: hän on minun sisareni; sillä hän pelkäsi sanoa: hän on minun emäntäni (ajatellen), ettei he joskus löisi minua kuoliaksi Rebekan tähden: sillä hän oli ihana kasvoilta."],[26,8,"Ja tapahtui, koska hän siellä kappaleen aikaa viipyi, katsoi Abimelek Philistealaisten kuningas akkunasta, ja näki Isaakin hyväilevän emäntäänsä.","Ja tapahtui, koska hän siellä kappaleen aikaa viipyi, katsoi Abimelek Philistealaisten kuningas akkunasta, ja näki Isaakin hyväilevän emäntäänsä."],[26,9,"Niin kutsui Abimelek Isaakin, ja sanoi: katso, totisesti hän on sinun emäntäs: miksis olet sanonut: hän on minun sisareni? Ja Isaak sanoi hänelle: minä ajattelin, etten minä tapettaisi hänen tähtensä.","Niin kutsui Abimelek Isaakin, ja sanoi: katso, totisesti hän on sinun emäntäs: miksis olet sanonut: hän on minun sisareni? Ja Isaak sanoi hänelle: minä ajattelin, etten minä tapettaisi hänen tähtensä."],[26,10,"Abimelek sanoi: miksis tämän meille teit? olis pikaisesti tapahtunut, että joku kansasta olis maannut sinun emäntäs kanssa, ja niin sinä olisit saattanut meidän päällemme rikoksen.","Abimelek sanoi: miksis tämän meille teit? olis pikaisesti tapahtunut, että joku kansasta olis maannut sinun emäntäs kanssa, ja niin sinä olisit saattanut meidän päällemme rikoksen."],[26,11,"Niin Abimelek antoi käskyn kaikelle kansalle, sanoen: joka ryhtyy tähän mieheen, tahi hänen emäntäänsä, hänen pitää totisesti kuoleman.","Niin Abimelek antoi käskyn kaikelle kansalle, sanoen: joka ryhtyy tähän mieheen, tahi hänen emäntäänsä, hänen pitää totisesti kuoleman."],[26,12,"Ja Isaak kylvi sillä maalla, ja sai sinä vuonna satakertaisesti: sillä Herra siunasi hänen.","Ja Isaak kylvi sillä maalla, ja sai sinä vuonna satakertaisesti: sillä Herra siunasi hänen."],[26,13,"Ja mies tuli voimalliseksi: ja menestyi sangen suuresti siihen asti, että hän juuri suureksi joutui.","Ja mies tuli voimalliseksi: ja menestyi sangen suuresti siihen asti, että hän juuri suureksi joutui."],[26,14,"Ja hänellä oli paljo tavaraa lampaissa ja karjassa, oli myös paljo perhettä: sentähden Philistealaiset kadehtivat häntä.","Ja hänellä oli paljo tavaraa lampaissa ja karjassa, oli myös paljo perhettä: sentähden Philistealaiset kadehtivat häntä."],[26,15,"Ja he tukitsivat kaikki kaivot, jotka hänen isänsä palveliat olivat kaivaneet, hänen isänsä Abrahamin aikana, ja täyttivät ne mullalla.","Ja he tukitsivat kaikki kaivot, jotka hänen isänsä palveliat olivat kaivaneet, hänen isänsä Abrahamin aikana, ja täyttivät ne mullalla."],[26,16,"Ja Abimelek sanoi Isaakille: mene pois meidän tyköämme: sillä sinä olet tullut paljo väkevämmäksi meitä.","Ja Abimelek sanoi Isaakille: mene pois meidän tyköämme: sillä sinä olet tullut paljo väkevämmäksi meitä."],[26,17,"Niin Isaak läksi sieltä: ja teki majansa Gerarin laaksoon, ja asui siinä.","Niin Isaak läksi sieltä: ja teki majansa Gerarin laaksoon, ja asui siinä."],[26,18,"Ja Isaak antoi jällensä kaivaa ne vesikaivot, jotka he olivat kaivaneet hänen isänsä Abrahamin aikana, ja jotka Philistealaiset Abrahamin kuoleman jälkeen olivat tukinneet: ja nimitti ne niillä nimillä, joilla hänen isänsä ne kutsunut oli.","Ja Isaak antoi jällensä kaivaa ne vesikaivot, jotka he olivat kaivaneet hänen isänsä Abrahamin aikana, ja jotka Philistealaiset Abrahamin kuoleman jälkeen olivat tukinneet: ja nimitti ne niillä nimillä, joilla hänen isänsä ne kutsunut oli."],[26,19,"Niin kaivoivat myös Isaakin palveliat siihen laaksoon: ja löysivät sieltä luontolähteen.","Niin kaivoivat myös Isaakin palveliat siihen laaksoon: ja löysivät sieltä luontolähteen."],[26,20,"Mutta Gerarin paimenet riitelivät Isaakin paimenten kanssa, ja sanoivat: tämä on meidän vetemme. Niin hän kutsui sen kaivon Esek, että he riitelivät hänen kanssansa.","Mutta Gerarin paimenet riitelivät Isaakin paimenten kanssa, ja sanoivat: tämä on meidän vetemme. Niin hän kutsui sen kaivon Esek, että he riitelivät hänen kanssansa."],[26,21,"Niin kaivoivat he myös toisen kaivon, ja he riitelivät myös siitä: niin hän nimitti sen Sitna.","Niin kaivoivat he myös toisen kaivon, ja he riitelivät myös siitä: niin hän nimitti sen Sitna."],[26,22,"Niin hän siirsi itsensä sieltä, ja kaivoi toisen kaivon, josta ei he riidelleet. Sen tähden nimitti hän sen Rehobot, ja sanoi: nyt Herra on antanut meille laviamman sian, ja on antanut meidän kasvaa maan päällä.","Niin hän siirsi itsensä sieltä, ja kaivoi toisen kaivon, josta ei he riidelleet. Sen tähden nimitti hän sen Rehobot, ja sanoi: nyt Herra on antanut meille laviamman sian, ja on antanut meidän kasvaa maan päällä."],[26,23,"Sitte meni hän BerSabaan.","Sitte meni hän BerSabaan."],[26,24,"Niin Herra ilmestyi hänelle sinä yönä ja sanoi: minä olen sinun isäs Abrahamin Jumala: älä pelkää, sillä minä olen kanssas, ja siunaan sinun, ja annan lisääntyä sinun siemenes, minun palveliani Abrahamin tähden.","Niin Herra ilmestyi hänelle sinä yönä ja sanoi: minä olen sinun isäs Abrahamin Jumala: älä pelkää, sillä minä olen kanssas, ja siunaan sinun, ja annan lisääntyä sinun siemenes, minun palveliani Abrahamin tähden."],[26,25,"Ja hän rakensi siinä alttarin, ja saarnasi Herran nimestä, ja teki siihen majansa: ja hänen palveliansa kaivoivat siihen kaivon.","Ja hän rakensi siinä alttarin, ja saarnasi Herran nimestä, ja teki siihen majansa: ja hänen palveliansa kaivoivat siihen kaivon."],[26,26,"Niin Abimelek meni hänen tykönsä Gerarista: ja Ahusat hänen ystävänsä, ja Phikol hänen sotajoukkonsa päämies.","Niin Abimelek meni hänen tykönsä Gerarista: ja Ahusat hänen ystävänsä, ja Phikol hänen sotajoukkonsa päämies."],[26,27,"Mutta Isaak sanoi heille: miksi te tulitte minun tyköni: ja te vainositte minua, ja ajoitte minun pois teidän tyköänne.","Mutta Isaak sanoi heille: miksi te tulitte minun tyköni: ja te vainositte minua, ja ajoitte minun pois teidän tyköänne."],[26,28,"He sanoivat: me näimme ilmeissänsä, että Herra on sinun kanssas, sentähden me sanoimme: olkoon nyt vala meidän molempain vaiheellamme, meidän ja sinun välilläs, ja me teemme liiton sinun kanssas.","He sanoivat: me näimme ilmeissänsä, että Herra on sinun kanssas, sentähden me sanoimme: olkoon nyt vala meidän molempain vaiheellamme, meidän ja sinun välilläs, ja me teemme liiton sinun kanssas."],[26,29,"Ettes tekisi meille mitään vahinkoa, niinkuin emme mekään ole sinuun ryhtyneet, ja niinkuin emme myös tehneet sinulle muuta kuin hyvää, ja laskimme sinun rauhassa menemään. Sinä olet nyt Herran siunattu.","Ettes tekisi meille mitään vahinkoa, niinkuin emme mekään ole sinuun ryhtyneet, ja niinkuin emme myös tehneet sinulle muuta kuin hyvää, ja laskimme sinun rauhassa menemään. Sinä olet nyt Herran siunattu."],[26,30,"Ja hän valmisti heille pidon, ja he söivät ja joivat.","Ja hän valmisti heille pidon, ja he söivät ja joivat."],[26,31,"Ja nousivat aamulla varhain, ja vannoivat toinen toisellensa, ja Isaak laski heidät menemään, ja menivät pois hänen tyköänsä rauhassa.","Ja nousivat aamulla varhain, ja vannoivat toinen toisellensa, ja Isaak laski heidät menemään, ja menivät pois hänen tyköänsä rauhassa."],[26,32,"Sinä samana päivänä tulivat Isaakin palveliat, ja ilmoittivat hänelle kaivosta, jonka he kaivaneet olivat, ja sanoivat hänelle: me löysimme veden.","Sinä samana päivänä tulivat Isaakin palveliat, ja ilmoittivat hänelle kaivosta, jonka he kaivaneet olivat, ja sanoivat hänelle: me löysimme veden."],[26,33,"Ja hän kutsui hänen Saba: siltä nimitetään kaupunki BerSaba, hamaan tähän päivään asti.","Ja hän kutsui hänen Saba: siltä nimitetään kaupunki BerSaba, hamaan tähän päivään asti."],[26,34,"Koska Esau oli neljänkymmenen ajastaikainen, otti hän Juditin Hetiläisen Berin tyttären emännäksensä: Ja Basmatin Hetiläisen Elonin tyttären:","Koska Esau oli neljänkymmenen ajastaikainen, otti hän Juditin Hetiläisen Berin tyttären emännäksensä: Ja Basmatin Hetiläisen Elonin tyttären:"],[26,35,"Jotka olivat Isaakille ja Rebekalle mielikarvaudeksi.","Jotka olivat Isaakille ja Rebekalle mielikarvaudeksi."],[27,1,"Ja tapahtui, koska Isaak tuli vanhaksi, ja hänen silmänsä pimiäksi, ettei hän nähnyt, niin kutsui hän Esaun vanhemman poikansa, ja sanoi hänelle: minun poikani: hän vastasi häntä: tässä minä olen.","Ja tapahtui, koska Isaak tuli vanhaksi, ja hänen silmänsä pimiäksi, ettei hän nähnyt, niin kutsui hän Esaun vanhemman poikansa, ja sanoi hänelle: minun poikani: hän vastasi häntä: tässä minä olen."],[27,2,"Ja hän sanoi: katso, minä olen vanhennut: enkä tiedä minun kuolemanpäivääni.","Ja hän sanoi: katso, minä olen vanhennut: enkä tiedä minun kuolemanpäivääni."],[27,3,"Ota siis nyt sinun kalus, viines ja joutses; ja mene kedolle, ja pyydä minulle metsän-otus.","Ota siis nyt sinun kalus, viines ja joutses; ja mene kedolle, ja pyydä minulle metsän-otus."],[27,4,"Ja tee minulle himoruokaa, senkaltaista jota minä rakastan, ja tuo syödäkseni: että minun sieluni siunais sinua, ennenkuin minä kuolen.","Ja tee minulle himoruokaa, senkaltaista jota minä rakastan, ja tuo syödäkseni: että minun sieluni siunais sinua, ennenkuin minä kuolen."],[27,5,"Mutta Rebekka kuuli Isaakin näitä puhuvan poikansa Esaun kanssa. Ja Esau meni metsään, pyytämään metsänotusta, tuodaksensa.","Mutta Rebekka kuuli Isaakin näitä puhuvan poikansa Esaun kanssa. Ja Esau meni metsään, pyytämään metsänotusta, tuodaksensa."],[27,6,"Niin puhui Rebekka pojallensa Jakobille, sanoen: katso, minä kuulin isäs puhuvan veljes Esaun kanssa, ja sanovan:","Niin puhui Rebekka pojallensa Jakobille, sanoen: katso, minä kuulin isäs puhuvan veljes Esaun kanssa, ja sanovan:"],[27,7,"Tuo minulle metsänotus, ja tee minulle himoruokaa syödäkseni; että siunaisin sinua Herran edessä, ennen kuin minä kuolen.","Tuo minulle metsänotus, ja tee minulle himoruokaa syödäkseni; että siunaisin sinua Herran edessä, ennen kuin minä kuolen."],[27,8,"Niin kuule nyt poikani minun ääneni, mitä minä sinulle käsken.","Niin kuule nyt poikani minun ääneni, mitä minä sinulle käsken."],[27,9,"Mene laumaan, ota sieltä minulle kaksi hyvää vohlaa; tehdäkseni isälles niistä himoruokaa, niinkuin hän rakastaa.","Mene laumaan, ota sieltä minulle kaksi hyvää vohlaa; tehdäkseni isälles niistä himoruokaa, niinkuin hän rakastaa."],[27,10,"Ja vie se isälles hänen syödäksensä; että hän siunais sinua, ennen kuin hän kuolee.","Ja vie se isälles hänen syödäksensä; että hän siunais sinua, ennen kuin hän kuolee."],[27,11,"Niin Jakob sanoi äidillensä Rebekalle: katso, veljeni Esau on karvainen, mutta minä olen paljas.","Niin Jakob sanoi äidillensä Rebekalle: katso, veljeni Esau on karvainen, mutta minä olen paljas."],[27,12,"Mitämaks, isäni sivelee minua, ja luulee minun häntä pettävän: ja minä saatan päälleni kirouksen, ja en siunausta.","Mitämaks, isäni sivelee minua, ja luulee minun häntä pettävän: ja minä saatan päälleni kirouksen, ja en siunausta."],[27,13,"Niin hänen äitinsä sanoi hänelle: sinun kiroukses tulkoon minun päälleni, minun poikani: ainoastansa ole minun äänelleni kuuliainen, mene ja tuo se minulle.","Niin hänen äitinsä sanoi hänelle: sinun kiroukses tulkoon minun päälleni, minun poikani: ainoastansa ole minun äänelleni kuuliainen, mene ja tuo se minulle."],[27,14,"Niin hän meni ja otti ja toi äidillensä; ja hänen äitinsä valmisti himoruan, jota hänen isänsä rakasti.","Niin hän meni ja otti ja toi äidillensä; ja hänen äitinsä valmisti himoruan, jota hänen isänsä rakasti."],[27,15,"Ja Rebekka otti vanhemman poikansa Esaun parhaat vaatteet, jotka huoneessa hänen tykönänsä olivat: ja puetti nuoremman poikansa Jakobin niihin.","Ja Rebekka otti vanhemman poikansa Esaun parhaat vaatteet, jotka huoneessa hänen tykönänsä olivat: ja puetti nuoremman poikansa Jakobin niihin."],[27,16,"Vaan vohlain nahat kääri hän hänen käsiinsä, ja paljaaseen kaulaansa.","Vaan vohlain nahat kääri hän hänen käsiinsä, ja paljaaseen kaulaansa."],[27,17,"Ja antoi sen himoruan ja leivän, kun hän valmistanut oli, poikansa Jakobin käteen.","Ja antoi sen himoruan ja leivän, kun hän valmistanut oli, poikansa Jakobin käteen."],[27,18,"Ja hän tuli isänsä tykö, ja sanoi: minun isäni. Hän vastasi: tässä minä olen. Kukas olet, minun poikani.","Ja hän tuli isänsä tykö, ja sanoi: minun isäni. Hän vastasi: tässä minä olen. Kukas olet, minun poikani."],[27,19,"Jakob sanoi isällensä: minä olen Esau sinun esikoises; minä olen niin tehnyt kuin sinä minulle käskit: nouse siis, istu, ja syö minun saalistani, että sinun sielus siunaisi minua.","Jakob sanoi isällensä: minä olen Esau sinun esikoises; minä olen niin tehnyt kuin sinä minulle käskit: nouse siis, istu, ja syö minun saalistani, että sinun sielus siunaisi minua."],[27,20,"Mutta Isaak sanoi pojallensa: minun poikani, kuinkas olet niin nopiasti löytänyt? ja hän vastasi: Herra sinun Jumalas antoi minun sen kohdata.","Mutta Isaak sanoi pojallensa: minun poikani, kuinkas olet niin nopiasti löytänyt? ja hän vastasi: Herra sinun Jumalas antoi minun sen kohdata."],[27,21,"Niin sanoi Isaak Jakobille: tules tänne minun poikani sivelläkseni: jos olet minun poikani Esau taikka et.","Niin sanoi Isaak Jakobille: tules tänne minun poikani sivelläkseni: jos olet minun poikani Esau taikka et."],[27,22,"Niin Jakob astui isäntä Isaakin tykö: ja kuin hän siveli häntä, sanoi hän: ääni on Jakobin ääni, mutta kädet ovat Esaun kädet.","Niin Jakob astui isäntä Isaakin tykö: ja kuin hän siveli häntä, sanoi hän: ääni on Jakobin ääni, mutta kädet ovat Esaun kädet."],[27,23,"Ja ei tuntenut häntä: sillä hänen kätensä olivat niinkuin Esaun veljensä kädet, karvaiset: ja niin hän siunasi häntä.","Ja ei tuntenut häntä: sillä hänen kätensä olivat niinkuin Esaun veljensä kädet, karvaiset: ja niin hän siunasi häntä."],[27,24,"Ja sanoi hänelle: oletkos minun poikani Esau? hän vastasi: olen.","Ja sanoi hänelle: oletkos minun poikani Esau? hän vastasi: olen."],[27,25,"Niin hän sanoi: tuo siis tänne syödäkseni minun poikani saalista, että minun sieluni siunaisi sinua: niin hän toi sen hänelle, ja hän söi, toi myös hänelle viinaa, ja hän joi.","Niin hän sanoi: tuo siis tänne syödäkseni minun poikani saalista, että minun sieluni siunaisi sinua: niin hän toi sen hänelle, ja hän söi, toi myös hänelle viinaa, ja hän joi."],[27,26,"Ja Isaak hänen isänsä sanoi hänelle: tules nyt liki, minun poikani, ja anna minun suuta.","Ja Isaak hänen isänsä sanoi hänelle: tules nyt liki, minun poikani, ja anna minun suuta."],[27,27,"Ja hän astui liki, ja suuta antoi hänen. Niin hän tunsi hänen vaatteensa hajun, ja siunasi häntä, ja sanoi: katso, minun poikani haju, on niinkuin kedon haju, jonka Herra siunannut on.","Ja hän astui liki, ja suuta antoi hänen. Niin hän tunsi hänen vaatteensa hajun, ja siunasi häntä, ja sanoi: katso, minun poikani haju, on niinkuin kedon haju, jonka Herra siunannut on."],[27,28,"Jumala antakoon sinulle taivaan kasteesta, ja maan lihavuudesta; yltäkyllä jyviä ja viinaa.","Jumala antakoon sinulle taivaan kasteesta, ja maan lihavuudesta; yltäkyllä jyviä ja viinaa."],[27,29,"Kansat palvelkoon sinua, ja sukukunnat kumartakoon sinua. Ole sinun veljeis herra, ja sinun äitis lapset langetkoon sinun jalkais juureen: kirottu olkoon se, joka sinua kiroo, ja siunattu olkoon se, joka sinua siunaa.","Kansat palvelkoon sinua, ja sukukunnat kumartakoon sinua. Ole sinun veljeis herra, ja sinun äitis lapset langetkoon sinun jalkais juureen: kirottu olkoon se, joka sinua kiroo, ja siunattu olkoon se, joka sinua siunaa."],[27,30,"Koska Isaak oli päättänyt siunauksensa Jakobille, ja Jakob siitä siihen oli lähtenyt isänsä Isaakin tyköä; niin Esau hänen veljensä tuli pyydyksiltänsä.","Koska Isaak oli päättänyt siunauksensa Jakobille, ja Jakob siitä siihen oli lähtenyt isänsä Isaakin tyköä; niin Esau hänen veljensä tuli pyydyksiltänsä."],[27,31,"Ja hän myös valmisti himoruan, ja vei isällensä, ja sanoi hänelle: nouskaan minun isäni, ja syökään poikansa saalista, että sinun sielus siunaisi minua.","Ja hän myös valmisti himoruan, ja vei isällensä, ja sanoi hänelle: nouskaan minun isäni, ja syökään poikansa saalista, että sinun sielus siunaisi minua."],[27,32,"Niin vastasi Isaak hänen isänsä häntä: kukas olet? hän sanoi: minä olen sinun poikas, sinun esikoises Esau.","Niin vastasi Isaak hänen isänsä häntä: kukas olet? hän sanoi: minä olen sinun poikas, sinun esikoises Esau."],[27,33,"Niin Isaak vapisi hämmästyksestä sangen kovin, ja sanoi: kuka? kussasta siis se metsämies on, joka minulle sen toi? ja minä söin kaikista, ennen kuin sinä tulit ja minä siunasin hänen: hänen pitää myös siunatun oleman.","Niin Isaak vapisi hämmästyksestä sangen kovin, ja sanoi: kuka? kussasta siis se metsämies on, joka minulle sen toi? ja minä söin kaikista, ennen kuin sinä tulit ja minä siunasin hänen: hänen pitää myös siunatun oleman."],[27,34,"Koska Esau kuuli isänsä puheen, huusi hän suurella äänellä, ja hänen mielensä tuli sangen karvaaksi: ja hän sanoi isällensä: siunaa myös minuakin, minun isäni.","Koska Esau kuuli isänsä puheen, huusi hän suurella äänellä, ja hänen mielensä tuli sangen karvaaksi: ja hän sanoi isällensä: siunaa myös minuakin, minun isäni."],[27,35,"Niin hän sanoi: sinun veljes on tullut kavaluudella, ja vienyt pois siunauksen sinulta.","Niin hän sanoi: sinun veljes on tullut kavaluudella, ja vienyt pois siunauksen sinulta."],[27,36,"Niin hän sanoi: eiköstä hän myös oikein kutsuta Jakob? sillä hän jo kahdesti minun on polkenut, minun esikoisuuteni hän sai, ja katso, nyt hän vei pois minun siunaukseni minulta: ja hän sanoi: etkös yhtäkään siunausta minun varakseni pitänyt?","Niin hän sanoi: eiköstä hän myös oikein kutsuta Jakob? sillä hän jo kahdesti minun on polkenut, minun esikoisuuteni hän sai, ja katso, nyt hän vei pois minun siunaukseni minulta: ja hän sanoi: etkös yhtäkään siunausta minun varakseni pitänyt?"],[27,37,"Niin vastasi Isaak, ja sanoi Esaulle: Katso, minä olen asettanut hänen sinun herrakses, ja kaikki hänen veljensä olen minä hänelle palveliaksi pannut, jyvillä ja viinalla olen minä hänen varustanut: mitästä minä siis nyt sinulle teen, minun poikani?","Niin vastasi Isaak, ja sanoi Esaulle: Katso, minä olen asettanut hänen sinun herrakses, ja kaikki hänen veljensä olen minä hänelle palveliaksi pannut, jyvillä ja viinalla olen minä hänen varustanut: mitästä minä siis nyt sinulle teen, minun poikani?"],[27,38,"Ja Esau sanoi isällensä: yksiköstä siunaus sinulla vaivoin onkin, minun isäni? siunaa myös minuakin, minun isäni: ja Esau korotti äänensä ja itki.","Ja Esau sanoi isällensä: yksiköstä siunaus sinulla vaivoin onkin, minun isäni? siunaa myös minuakin, minun isäni: ja Esau korotti äänensä ja itki."],[27,39,"Niin vastasi Isaak, hänen isänsä, ja sanoi hänelle: Katso, lihava asuinsia pitää sinulla oleman maan päällä, ja kastetta taivaasta ylhäältä.","Niin vastasi Isaak, hänen isänsä, ja sanoi hänelle: Katso, lihava asuinsia pitää sinulla oleman maan päällä, ja kastetta taivaasta ylhäältä."],[27,40,"Sinun miekallas pitää sinun elättämän itses, ja palveleman sinun veljeäs. Ja tapahtuu, että sinä myös tulet herraksi, ja särjet hänen ikeensä niskastas.","Sinun miekallas pitää sinun elättämän itses, ja palveleman sinun veljeäs. Ja tapahtuu, että sinä myös tulet herraksi, ja särjet hänen ikeensä niskastas."],[27,41,"Ja Esau vihastui Jakobin päälle siunauksen tähden, jolla hänen isänsä hänen siunannut oli; ja sanoi sydämessänsä: minun isäni murhepäivät lähestyvät: ja minä tapan veljeni Jakobin.","Ja Esau vihastui Jakobin päälle siunauksen tähden, jolla hänen isänsä hänen siunannut oli; ja sanoi sydämessänsä: minun isäni murhepäivät lähestyvät: ja minä tapan veljeni Jakobin."],[27,42,"Mutta Rebekalle ilmoitettiin Esaun hänen vanhemman poikansa sanat: joka lähetti ja kutsui Jakobin nuoremman poikansa, ja sanoi hänelle: katso, veljes Esau lohduttaa itsiänsä siitä, että hän sinun tappaa.","Mutta Rebekalle ilmoitettiin Esaun hänen vanhemman poikansa sanat: joka lähetti ja kutsui Jakobin nuoremman poikansa, ja sanoi hänelle: katso, veljes Esau lohduttaa itsiänsä siitä, että hän sinun tappaa."],[27,43,"Nyt, minun poikani, ole minun äänelleni kuuliainen: valmista sinus ja pakene kohta minun veljeni Labanin tykö Haraniin.","Nyt, minun poikani, ole minun äänelleni kuuliainen: valmista sinus ja pakene kohta minun veljeni Labanin tykö Haraniin."],[27,44,"Ja ole hänen tykönänsä kappale aikaa: siihenasti että veljes kiukku asettuu.","Ja ole hänen tykönänsä kappale aikaa: siihenasti että veljes kiukku asettuu."],[27,45,"Ja siihenasti että hänen vihansa lakkaa sinusta, ja hän unhottaa mitäs häntä vastaan tehnyt olet. Niin minä lähetän ja tuotan sinun sieltä. Miksi teidän molempain pitäis yhtenä päivänä minulta tuleman pois?","Ja siihenasti että hänen vihansa lakkaa sinusta, ja hän unhottaa mitäs häntä vastaan tehnyt olet. Niin minä lähetän ja tuotan sinun sieltä. Miksi teidän molempain pitäis yhtenä päivänä minulta tuleman pois?"],[27,46,"Ja Rebekka sanoi Isaakille: minä suutun minun elämääni, Hetin tytärten tähden: jos Jakob ottaa vaimon Hetin tyttäristä, jotka ovat niinkuin tämän maan tyttäret, mitä minun sitte auttaa elämään?","Ja Rebekka sanoi Isaakille: minä suutun minun elämääni, Hetin tytärten tähden: jos Jakob ottaa vaimon Hetin tyttäristä, jotka ovat niinkuin tämän maan tyttäret, mitä minun sitte auttaa elämään?"],[28,1,"Niin Isaak kutsui poikansa Jakobin ja siunasi häntä, käski ja sanoi hänelle: älä ota emäntää Kanaanin tyttäristä.","Niin Isaak kutsui poikansa Jakobin ja siunasi häntä, käski ja sanoi hänelle: älä ota emäntää Kanaanin tyttäristä."],[28,2,"Vaan valmista ja mene Mesopotamiaan, Betuelin sinun äitis isän huoneesen: ja ota sinulles sieltä emäntä, Labanin sinun enos tyttäristä.","Vaan valmista ja mene Mesopotamiaan, Betuelin sinun äitis isän huoneesen: ja ota sinulles sieltä emäntä, Labanin sinun enos tyttäristä."],[28,3,"Ja Jumala kaikkivaltias siunatkoon sinua, ja tehköön sinun hedelmälliseksi ja enätköön sinun, ettäs tulisit (suureksi) kansain joukoksi.","Ja Jumala kaikkivaltias siunatkoon sinua, ja tehköön sinun hedelmälliseksi ja enätköön sinun, ettäs tulisit (suureksi) kansain joukoksi."],[28,4,"Antakoon myös sinulle Abrahamin siunauksen, sinulle ja sinun siemenelles sinun kanssas: periäkses sitä maata, jossas muukalainen olet, jonka Jumala Abrahamille antanut on.","Antakoon myös sinulle Abrahamin siunauksen, sinulle ja sinun siemenelles sinun kanssas: periäkses sitä maata, jossas muukalainen olet, jonka Jumala Abrahamille antanut on."],[28,5,"Niin lähetti Isaak Jakobin tyköänsä menemään Mesopotamiaan, Labanin, Betuelin Syrialaisen pojan tykö, Rebekan, Jakobin ja Esaun äidin, veljen.","Niin lähetti Isaak Jakobin tyköänsä menemään Mesopotamiaan, Labanin, Betuelin Syrialaisen pojan tykö, Rebekan, Jakobin ja Esaun äidin, veljen."],[28,6,"Koska Esau näki, että Isaak oli siunannut Jakobin, ja lähettänyt hänen Mesopotamiaan ottamaan sieltä itsellensä emäntää: ja että hän, sittekuin hän hänen siunannut oli, käski häntä ja sanoi: ei sinun pidä ottaman emäntää Kanaanin tyttäristä.","Koska Esau näki, että Isaak oli siunannut Jakobin, ja lähettänyt hänen Mesopotamiaan ottamaan sieltä itsellensä emäntää: ja että hän, sittekuin hän hänen siunannut oli, käski häntä ja sanoi: ei sinun pidä ottaman emäntää Kanaanin tyttäristä."],[28,7,"Ja että Jakob oli isällensä ja äidillensä kuuliainen; ja meni Mesopotamiaan.","Ja että Jakob oli isällensä ja äidillensä kuuliainen; ja meni Mesopotamiaan."],[28,8,"Esau näki myös, ettei Isaak hänen isänsä voinut nähdä Kanaanin tyttäriä;","Esau näki myös, ettei Isaak hänen isänsä voinut nähdä Kanaanin tyttäriä;"],[28,9,"Meni Esau Ismaelin tykö: ja otti Mahalatin Ismaelin Abrahamin pojan tyttären, Nabojotin sisaren, emännäksensä, paitsi entisiä.","Meni Esau Ismaelin tykö: ja otti Mahalatin Ismaelin Abrahamin pojan tyttären, Nabojotin sisaren, emännäksensä, paitsi entisiä."],[28,10,"Niin Jakob läksi BerSabasta: ja meni Haraniin.","Niin Jakob läksi BerSabasta: ja meni Haraniin."],[28,11,"Ja joutui yhteen paikkaan, ja oli siinä yötä: sillä aurinko oli laskenut, ja otti kiven siitä paikasta, ja pani päänsä alaiseksi, ja makasi siinä paikassa.","Ja joutui yhteen paikkaan, ja oli siinä yötä: sillä aurinko oli laskenut, ja otti kiven siitä paikasta, ja pani päänsä alaiseksi, ja makasi siinä paikassa."],[28,12,"Ja näki unta, ja katso, tikapuut seisoivat maan päällä, joiden pää ulottui taivaasen: ja katso, Jumalan enkelit kävivät ylös ja alas niitä myöten.","Ja näki unta, ja katso, tikapuut seisoivat maan päällä, joiden pää ulottui taivaasen: ja katso, Jumalan enkelit kävivät ylös ja alas niitä myöten."],[28,13,"Ja katso, Herra seisoi niiden päällä, ja sanoi: Minä olen Herra, Abrahamin sinun isäs Jumala, ja Isaakin Jumala: tämän maan, jonka päällä sinä makaat, annan minä sinulle ja sinun siemenelles.","Ja katso, Herra seisoi niiden päällä, ja sanoi: Minä olen Herra, Abrahamin sinun isäs Jumala, ja Isaakin Jumala: tämän maan, jonka päällä sinä makaat, annan minä sinulle ja sinun siemenelles."],[28,14,"Ja sinun siemenes pitää oleman niinkuin maan tomu, ja sinun pitää leviämän länteen ja itään, pohjaan ja etelään päin. Ja sinussa pitää kaikki sukukunnat maan päällä siunatuksi tuleman, ja sinun siemenessäs.","Ja sinun siemenes pitää oleman niinkuin maan tomu, ja sinun pitää leviämän länteen ja itään, pohjaan ja etelään päin. Ja sinussa pitää kaikki sukukunnat maan päällä siunatuksi tuleman, ja sinun siemenessäs."],[28,15,"Ja katso, minä olen sinun kanssas, ja varjelen sinua, kuhunkas ikänänsä joudut, ja saatan sinun jällensä tälle maalle: sillä en minä hylkää sinua siihenasti, että minä kaikki teen, mitä minä sinulle puhunut olen.","Ja katso, minä olen sinun kanssas, ja varjelen sinua, kuhunkas ikänänsä joudut, ja saatan sinun jällensä tälle maalle: sillä en minä hylkää sinua siihenasti, että minä kaikki teen, mitä minä sinulle puhunut olen."],[28,16,"Koska Jakob heräsi unestansa, niin hän sanoi: totisesti on Herra tässä paikassa: ja en minä sitä tietänyt.","Koska Jakob heräsi unestansa, niin hän sanoi: totisesti on Herra tässä paikassa: ja en minä sitä tietänyt."],[28,17,"Niin hän pelkäsi, ja sanoi: kuinka peljättävä on tämä paikka! ei tässä muu ole kuin Jumalan huone ja taivaan ovi.","Niin hän pelkäsi, ja sanoi: kuinka peljättävä on tämä paikka! ei tässä muu ole kuin Jumalan huone ja taivaan ovi."],[28,18,"Ja Jakob nousi varhain aamulla, ja otti kiven, jonka hän oli pannut päänsä alaiseksi, ja pani sen pystyälle muistopatsaaksi: ja vuodatti öljyä sen päälle.","Ja Jakob nousi varhain aamulla, ja otti kiven, jonka hän oli pannut päänsä alaiseksi, ja pani sen pystyälle muistopatsaaksi: ja vuodatti öljyä sen päälle."],[28,19,"Kutsui siis sen paikan BetEl; vaan muinaisiin aikoin se kutsuttiin Luts.","Kutsui siis sen paikan BetEl; vaan muinaisiin aikoin se kutsuttiin Luts."],[28,20,"Niin Jakob teki lupauksen, sanoen: jos Jumala on minun kanssani, ja varjelee minua tällä tiellä, jota minä vaellan, antaa myös minulle leipää syödäkseni, ja vaatetta verhokseni:","Niin Jakob teki lupauksen, sanoen: jos Jumala on minun kanssani, ja varjelee minua tällä tiellä, jota minä vaellan, antaa myös minulle leipää syödäkseni, ja vaatetta verhokseni:"],[28,21,"Ja tulen takaperin rauhassa kotia isäni tykö: ja Herra on minun Jumalani.","Ja tulen takaperin rauhassa kotia isäni tykö: ja Herra on minun Jumalani."],[28,22,"Niin tämä kivi, jonka minä panin pystyälle muistopatsaaksi, pitää oleman Jumalan huone: ja kaikista, jotkas minulle annat, annan minä tosin sinulle kymmenykset.","Niin tämä kivi, jonka minä panin pystyälle muistopatsaaksi, pitää oleman Jumalan huone: ja kaikista, jotkas minulle annat, annan minä tosin sinulle kymmenykset."],[29,1,"Niin Jakob läksi matkaan: ja tuli itäiselle maalle.","Niin Jakob läksi matkaan: ja tuli itäiselle maalle."],[29,2,"Ja katseli ympärillensä, ja katso, kaivo oli kedolla. Ja katso, siellä makasi myös kolme lammaslaumaa sen tykönä, sillä siitä kaivosta juottivat he laumat: ja suuri kivi oli kaivon suulla.","Ja katseli ympärillensä, ja katso, kaivo oli kedolla. Ja katso, siellä makasi myös kolme lammaslaumaa sen tykönä, sillä siitä kaivosta juottivat he laumat: ja suuri kivi oli kaivon suulla."],[29,3,"Sillä sinne koottiin kaikki laumat, ja vieritettiin kivi kaivon suulta, ja he juottivat lampaita: ja vierittivät kiven jälleen siallensa kaivon suulle.","Sillä sinne koottiin kaikki laumat, ja vieritettiin kivi kaivon suulta, ja he juottivat lampaita: ja vierittivät kiven jälleen siallensa kaivon suulle."],[29,4,"Ja Jakob sanoi heille: minun veljeni, kusta te olette? he vastasivat: Haranista me olemme.","Ja Jakob sanoi heille: minun veljeni, kusta te olette? he vastasivat: Haranista me olemme."],[29,5,"Hän sanoi heille: tunnetteko Labanin, Nahorin pojan? he sanoivat: tunnemme kyllä.","Hän sanoi heille: tunnetteko Labanin, Nahorin pojan? he sanoivat: tunnemme kyllä."],[29,6,"Hän sanoi: onko hän rauhassa? he vastasivat: rauhassa hän on. Ja katso, Rakel hänen tyttärensä tulee lammasten kanssa.","Hän sanoi: onko hän rauhassa? he vastasivat: rauhassa hän on. Ja katso, Rakel hänen tyttärensä tulee lammasten kanssa."],[29,7,"Niin hän sanoi: katso, vielä on paljo päivää, eikä vielä ole aika karjaa koota: niin juottakaat siis lampaita, menkäät ja kaitkaat heitä.","Niin hän sanoi: katso, vielä on paljo päivää, eikä vielä ole aika karjaa koota: niin juottakaat siis lampaita, menkäät ja kaitkaat heitä."],[29,8,"He sanoivat: emme saa siihenasti kuin kaikki laumat kootaan, ja vieritämme kiven kaivon suulta, juottaaksemme lampaat.","He sanoivat: emme saa siihenasti kuin kaikki laumat kootaan, ja vieritämme kiven kaivon suulta, juottaaksemme lampaat."],[29,9,"Vielä hänen puhuissansa heidän kanssansa, tuli Rakel isänsä lammasten kanssa: sillä hän kaitsi lampaita.","Vielä hänen puhuissansa heidän kanssansa, tuli Rakel isänsä lammasten kanssa: sillä hän kaitsi lampaita."],[29,10,"Ja tapahtui, koska Jakob näki Rakelin enonsa Labanin tyttären, ja enonsa Labanin lampaat: niin meni Jakob hänen tykönsä, ja vieritti kiven kaivon suulta. Ja juotti enonsa Labanin lampaat.","Ja tapahtui, koska Jakob näki Rakelin enonsa Labanin tyttären, ja enonsa Labanin lampaat: niin meni Jakob hänen tykönsä, ja vieritti kiven kaivon suulta. Ja juotti enonsa Labanin lampaat."],[29,11,"Ja Jakob suuta antoi Rakelin: ja korotti äänensä ja itki.","Ja Jakob suuta antoi Rakelin: ja korotti äänensä ja itki."],[29,12,"Ja ilmoitti hänelle, että hän oli hänen isänsä veli, Rebekan poika. Niin juoksi hän ja ilmoitti sen isällensä.","Ja ilmoitti hänelle, että hän oli hänen isänsä veli, Rebekan poika. Niin juoksi hän ja ilmoitti sen isällensä."],[29,13,"Ja koska Laban kuuli sanoman Jakobista sisarensa pojasta, juoksi hän häntä vastaan, ja otti hänen syliinsä, ja suuta antoi hänen, ja vei hänen huoneesensa: ja hän jutteli Labanille kaiken asian.","Ja koska Laban kuuli sanoman Jakobista sisarensa pojasta, juoksi hän häntä vastaan, ja otti hänen syliinsä, ja suuta antoi hänen, ja vei hänen huoneesensa: ja hän jutteli Labanille kaiken asian."],[29,14,"Niin sanoi Laban hänelle: tosin sinä olet minun luuni ja lihani. Ja hän oli hänen tykönänsä koko kuukauden.","Niin sanoi Laban hänelle: tosin sinä olet minun luuni ja lihani. Ja hän oli hänen tykönänsä koko kuukauden."],[29,15,"Sitte sanoi Laban Jakobille: vaikkas olet minun veljeni, palveletkos sentähden minua ilman mitäkään? ilmoita minulle, mikä sinun palkkas olis.","Sitte sanoi Laban Jakobille: vaikkas olet minun veljeni, palveletkos sentähden minua ilman mitäkään? ilmoita minulle, mikä sinun palkkas olis."],[29,16,"Ja Labanilla oli kaksi tytärtä: vanhemman nimi oli Lea, ja nuoremman nimi oli Rakel.","Ja Labanilla oli kaksi tytärtä: vanhemman nimi oli Lea, ja nuoremman nimi oli Rakel."],[29,17,"Mutta Lea oli pehmiä silmistä; vaan Rakel oli kauniin muotoinen, ja ihana kasvoilta.","Mutta Lea oli pehmiä silmistä; vaan Rakel oli kauniin muotoinen, ja ihana kasvoilta."],[29,18,"Ja Jakob rakasti Rakelia: ja sanoi: minä palvelen sinua seitsemän ajastaikaa Rakelin, sinun nuoremman tyttäres tähden.","Ja Jakob rakasti Rakelia: ja sanoi: minä palvelen sinua seitsemän ajastaikaa Rakelin, sinun nuoremman tyttäres tähden."],[29,19,"Laban vastasi: parempi on, että minä hänen annan sinulle, kuin jollekin toiselle: ole minun tykönäni.","Laban vastasi: parempi on, että minä hänen annan sinulle, kuin jollekin toiselle: ole minun tykönäni."],[29,20,"Niin palveli Jakob Rakelin tähden seitsemän ajastaikaa: ja ne olivat hänen silmissänsä niinkuin muutamat päivät, rakastaissansa häntä.","Niin palveli Jakob Rakelin tähden seitsemän ajastaikaa: ja ne olivat hänen silmissänsä niinkuin muutamat päivät, rakastaissansa häntä."],[29,21,"Ja Jakob sanoi Labanille: anna minun emäntäni minulle: sillä minun aikani on täytetty mennä hänen tykönsä.","Ja Jakob sanoi Labanille: anna minun emäntäni minulle: sillä minun aikani on täytetty mennä hänen tykönsä."],[29,22,"Niin Laban kutsui kokoon kaiken sen paikkakunnan miehet, ja piti häät.","Niin Laban kutsui kokoon kaiken sen paikkakunnan miehet, ja piti häät."],[29,23,"Mutta ehtoona otti hän tyttärensä Lean, ja vei sen hänen tykönsä: ja hän makasi sen tykönä.","Mutta ehtoona otti hän tyttärensä Lean, ja vei sen hänen tykönsä: ja hän makasi sen tykönä."],[29,24,"Ja Laban antoi tyttärellensä Lealle piikansa Silpan piiaksi.","Ja Laban antoi tyttärellensä Lealle piikansa Silpan piiaksi."],[29,25,"Aamulla, katso, se oli Lea. Ja hän sanoi Labanille: miksis tämän minulle teit? enkö minä Rakelin tähden palvellut sinua? miksis minun petit?","Aamulla, katso, se oli Lea. Ja hän sanoi Labanille: miksis tämän minulle teit? enkö minä Rakelin tähden palvellut sinua? miksis minun petit?"],[29,26,"Vastasi Laban: ei niin ole meidän maan tapa, että nuorempi annetaan ennen vanhempaa.","Vastasi Laban: ei niin ole meidän maan tapa, että nuorempi annetaan ennen vanhempaa."],[29,27,"Täytä tämän viikko; niin se myös sinulle annetaan, siitä palveluksesta kun sinä palvelet minua vielä toiset seitsemän ajastaikaa.","Täytä tämän viikko; niin se myös sinulle annetaan, siitä palveluksesta kun sinä palvelet minua vielä toiset seitsemän ajastaikaa."],[29,28,"Jakob teki niin, ja täytti hänen viikkonsa: ja hän antoi hänelle tyttärensä Rakelin emännäksi.","Jakob teki niin, ja täytti hänen viikkonsa: ja hän antoi hänelle tyttärensä Rakelin emännäksi."],[29,29,"Ja Laban antoi tyttärellensä Rakelille piikansa Bilhan, piiaksi.","Ja Laban antoi tyttärellensä Rakelille piikansa Bilhan, piiaksi."],[29,30,"Niin hän makasi myös Rakelin kanssa, ja piti Rakelin rakkaampana kuin Lean; ja palveli häntä vielä toiset seitsemän ajastaikaa.","Niin hän makasi myös Rakelin kanssa, ja piti Rakelin rakkaampana kuin Lean; ja palveli häntä vielä toiset seitsemän ajastaikaa."],[29,31,"Ja koska Herra näki Lean katsottavan ylön, teki hän hänen hedelmälliseksi; mutta Rakel oli hedelmätöin.","Ja koska Herra näki Lean katsottavan ylön, teki hän hänen hedelmälliseksi; mutta Rakel oli hedelmätöin."],[29,32,"Niin Lea tuli raskaaksi, ja synnytti pojan, ja kutsui hänen nimensä Ruben, ja sanoi: Herra on katsonut minun ahdistukseni puoleen, nyt siis minun mieheni rakastaa minua.","Niin Lea tuli raskaaksi, ja synnytti pojan, ja kutsui hänen nimensä Ruben, ja sanoi: Herra on katsonut minun ahdistukseni puoleen, nyt siis minun mieheni rakastaa minua."],[29,33,"Ja hän taas tuli raskaaksi, ja synnytti pojan, ja sanoi: Herra on kuullut minua katsottavan ylön, ja on myös tämän minulle antanut: ja kutsui hänen nimensä Simeon.","Ja hän taas tuli raskaaksi, ja synnytti pojan, ja sanoi: Herra on kuullut minua katsottavan ylön, ja on myös tämän minulle antanut: ja kutsui hänen nimensä Simeon."],[29,34,"Ja hän jälleen tuli raskaaksi ja synnytti pojan, ja sanoi: nyt taas minun mieheni pysyy minun tykönäni: sillä minä synnytin hänelle kolme poikaa. Sentähden hän kutsui hänen nimensä Levi.","Ja hän jälleen tuli raskaaksi ja synnytti pojan, ja sanoi: nyt taas minun mieheni pysyy minun tykönäni: sillä minä synnytin hänelle kolme poikaa. Sentähden hän kutsui hänen nimensä Levi."],[29,35,"Ja hän tuli vielä raskaaksi, ja synnytti pojan, ja sanoi: nyt minä kiitän Herraa; sentähden kutsui hän hänen nimensä Juuda: ja lakkasi synnyttämästä.","Ja hän tuli vielä raskaaksi, ja synnytti pojan, ja sanoi: nyt minä kiitän Herraa; sentähden kutsui hän hänen nimensä Juuda: ja lakkasi synnyttämästä."],[30,1,"Koska Rakel näki, ettei hän synnyttänyt Jakobille, kadehti hän sisartansa, ja sanoi Jakobille: anna minun lapsia, eli minä kuolen.","Koska Rakel näki, ettei hän synnyttänyt Jakobille, kadehti hän sisartansa, ja sanoi Jakobille: anna minun lapsia, eli minä kuolen."],[30,2,"Jakob vihastui kovin Rakelin päälle, ja sanoi: olenko minä Jumalan siassa, joka on sinulta kieltänyt kohdun hedelmän?","Jakob vihastui kovin Rakelin päälle, ja sanoi: olenko minä Jumalan siassa, joka on sinulta kieltänyt kohdun hedelmän?"],[30,3,"Ja hän sanoi: tässä on minun piikani Bilha, makaa hänen kanssansa; että hän synnyttäis minun helmaani, ja saisin sittenkin hänestä lapsia.","Ja hän sanoi: tässä on minun piikani Bilha, makaa hänen kanssansa; että hän synnyttäis minun helmaani, ja saisin sittenkin hänestä lapsia."],[30,4,"Niin hän antoi hänelle piikansa Bilhan emännäksi: ja Jakob makasi hänen kanssansa.","Niin hän antoi hänelle piikansa Bilhan emännäksi: ja Jakob makasi hänen kanssansa."],[30,5,"Niin Bilha tuli raskaaksi ja synnytti Jakobille pojan.","Niin Bilha tuli raskaaksi ja synnytti Jakobille pojan."],[30,6,"Ja Rakel sanoi: Jumala ratkasi minun asiani, ja kuuli myös minun ääneni, ja antoi minulle pojan; sentähden kutsui hän hänen nimensä Dan.","Ja Rakel sanoi: Jumala ratkasi minun asiani, ja kuuli myös minun ääneni, ja antoi minulle pojan; sentähden kutsui hän hänen nimensä Dan."],[30,7,"Ja taas Bilha Rakelin piika tuli raskaaksi, ja synnytti Jakobille toisen pojan.","Ja taas Bilha Rakelin piika tuli raskaaksi, ja synnytti Jakobille toisen pojan."],[30,8,"Niin sanoi Rakel: minä olen jalosti kilvoitellut minun sisareni kanssa, ja olen myös voittanut: ja hän kutsui hänen nimensä Naphtali.","Niin sanoi Rakel: minä olen jalosti kilvoitellut minun sisareni kanssa, ja olen myös voittanut: ja hän kutsui hänen nimensä Naphtali."],[30,9,"Koska Lea näki, että hän lakkasi synnyttämästä; otti hän piikansa Silpan, ja antoi sen Jakobille emännäksi.","Koska Lea näki, että hän lakkasi synnyttämästä; otti hän piikansa Silpan, ja antoi sen Jakobille emännäksi."],[30,10,"Niin synnytti Silpa, Lean piika, Jakobille pojan.","Niin synnytti Silpa, Lean piika, Jakobille pojan."],[30,11,"Ja Lea sanoi: joukko tulee: ja kutsui hänen nimensä Gad.","Ja Lea sanoi: joukko tulee: ja kutsui hänen nimensä Gad."],[30,12,"Ja Silpa, Lean piika, synnytti Jakobille toisen pojan.","Ja Silpa, Lean piika, synnytti Jakobille toisen pojan."],[30,13,"Ja Lea sanoi: autuasta minua, sillä tyttäret sanovat minua autuaaksi: ja hän kutsui hänen nimensä Asser.","Ja Lea sanoi: autuasta minua, sillä tyttäret sanovat minua autuaaksi: ja hän kutsui hänen nimensä Asser."],[30,14,"Ja Ruben meni ulos nisun elonaikana, ja löysi dudaimia vainioilta, ja toi ne Lealle äidillensä. Niin sanoi Rakel Lealle: anna minulle poikas dudaimista.","Ja Ruben meni ulos nisun elonaikana, ja löysi dudaimia vainioilta, ja toi ne Lealle äidillensä. Niin sanoi Rakel Lealle: anna minulle poikas dudaimista."],[30,15,"Hän vastasi häntä: vähäkö sinun siinä on, ettäs olet minulta miehen vienyt, mutta tahdot myös ottaa poikani dudaimit? Ja Rakel sanoi: sentähden maatkaan hän tänä yönä sinun kanssas poikas dudaimien tähden.","Hän vastasi häntä: vähäkö sinun siinä on, ettäs olet minulta miehen vienyt, mutta tahdot myös ottaa poikani dudaimit? Ja Rakel sanoi: sentähden maatkaan hän tänä yönä sinun kanssas poikas dudaimien tähden."],[30,16,"Koska Jakob ehtoona kedolta palasi, meni Lea häntä vastaan, ja sanoi: minun kanssani pitää sinun makaaman: sillä minä olen sinun kallisti ostanut poikani dudaimilla. Ja hän makasi sen yön hänen kanssansa.","Koska Jakob ehtoona kedolta palasi, meni Lea häntä vastaan, ja sanoi: minun kanssani pitää sinun makaaman: sillä minä olen sinun kallisti ostanut poikani dudaimilla. Ja hän makasi sen yön hänen kanssansa."],[30,17,"Ja Jumala kuuli Lean, ja hän tuli raskaaksi, ja synnytti Jakobille viidennen pojan.","Ja Jumala kuuli Lean, ja hän tuli raskaaksi, ja synnytti Jakobille viidennen pojan."],[30,18,"Ja Lea sanoi: Jumala on maksanut sen minulle, että minä annoin piikani miehelleni: ja kutsui hänen nimensä Isaskar.","Ja Lea sanoi: Jumala on maksanut sen minulle, että minä annoin piikani miehelleni: ja kutsui hänen nimensä Isaskar."],[30,19,"Ja Lea taas tuli raskaaksi, ja synnytti Jakobille kuudennen pojan.","Ja Lea taas tuli raskaaksi, ja synnytti Jakobille kuudennen pojan."],[30,20,"Ja Lea sanoi: Jumala on minun hyvästi lahjoittanut, nyt taas asuu minun mieheni minun tykönäni: sillä minä olen synnyttänyt hänelle kuusi poikaa. Ja kutsui hänen nimensä Sebulon.","Ja Lea sanoi: Jumala on minun hyvästi lahjoittanut, nyt taas asuu minun mieheni minun tykönäni: sillä minä olen synnyttänyt hänelle kuusi poikaa. Ja kutsui hänen nimensä Sebulon."],[30,21,"Sitte synnytti hän tyttären, ja kutsui hänen nimensä Dina.","Sitte synnytti hän tyttären, ja kutsui hänen nimensä Dina."],[30,22,"Mutta Jumala muisti myös Rakelin, ja Jumala kuuli hänen, ja saatti hedelmälliseksi.","Mutta Jumala muisti myös Rakelin, ja Jumala kuuli hänen, ja saatti hedelmälliseksi."],[30,23,"Niin hän tuli raskaaksi ja synnytti pojan, ja sanoi: Jumala on ottanut pois minun häväistykseni.","Niin hän tuli raskaaksi ja synnytti pojan, ja sanoi: Jumala on ottanut pois minun häväistykseni."],[30,24,"Ja kutsui hänen nimensä Joseph, sanoen: Herra lisätköön minulle vielä toisen pojan.","Ja kutsui hänen nimensä Joseph, sanoen: Herra lisätköön minulle vielä toisen pojan."],[30,25,"Ja tapahtui, koska Rakel oli synnyttänyt Josephin; sanoi Jakob Labanille: päästä minua menemään kotiani ja maalleni.","Ja tapahtui, koska Rakel oli synnyttänyt Josephin; sanoi Jakob Labanille: päästä minua menemään kotiani ja maalleni."],[30,26,"Anna minulle minun emäntäni ja lapseni, joiden tähden minä olen sinua palvellut, että minä menisin pois: sillä sinä tiedät minun palvelukseni, kuin minä olen sinua palvellut.","Anna minulle minun emäntäni ja lapseni, joiden tähden minä olen sinua palvellut, että minä menisin pois: sillä sinä tiedät minun palvelukseni, kuin minä olen sinua palvellut."],[30,27,"Ja Laban sanoi hänelle: anna minun löytää armo sinun edessäs, minä ymmärrän, että Herra on siunannut minun sinun tähtes.","Ja Laban sanoi hänelle: anna minun löytää armo sinun edessäs, minä ymmärrän, että Herra on siunannut minun sinun tähtes."],[30,28,"Ja sanoi (vielä): määrää siis sinun palkkas minulle, ja minä annan.","Ja sanoi (vielä): määrää siis sinun palkkas minulle, ja minä annan."],[30,29,"Mutta hän sanoi hänelle: sinä tiedät, kuinka minä olen palvellut sinua: ja kuinka paljo sinun karjaas on minun haltuuni annettu.","Mutta hän sanoi hänelle: sinä tiedät, kuinka minä olen palvellut sinua: ja kuinka paljo sinun karjaas on minun haltuuni annettu."],[30,30,"Sinulla oli vähä ennenkuin minä tulin, mutta nyt se on paljoksi kasvanut, ja Herra on siunannut sinun, minun jalkajuonteni kautta. Koska minä siis oman huoneeni parasta katson?","Sinulla oli vähä ennenkuin minä tulin, mutta nyt se on paljoksi kasvanut, ja Herra on siunannut sinun, minun jalkajuonteni kautta. Koska minä siis oman huoneeni parasta katson?"],[30,31,"Ja (Laban) sanoi: mitästä minä sinulle annan? Ja Jakob sanoi: ei sinun pidä mitään antaman minulle. Mutta jos sinä tämän minulle teet, niin minä vielä tästälähin kaitsen ja varjelen sinun laumaas:","Ja (Laban) sanoi: mitästä minä sinulle annan? Ja Jakob sanoi: ei sinun pidä mitään antaman minulle. Mutta jos sinä tämän minulle teet, niin minä vielä tästälähin kaitsen ja varjelen sinun laumaas:"],[30,32,"Minä käyn tänäpänä kaiken sinun laumas lävitse, eroittaen sieltä kaikki pilkulliset ja kirjavat lampaat, ja kaikki hallavat karitsain seassa, ja kirjavat ja pilkulliset vuohten seassa, (mitä sitte kirjavaksi ja pilkulliseksi tulee) se olkoon minun palkkani.","Minä käyn tänäpänä kaiken sinun laumas lävitse, eroittaen sieltä kaikki pilkulliset ja kirjavat lampaat, ja kaikki hallavat karitsain seassa, ja kirjavat ja pilkulliset vuohten seassa, (mitä sitte kirjavaksi ja pilkulliseksi tulee) se olkoon minun palkkani."],[30,33,"Niin minun vanhurskauteni on todistava tästedes minusta, koska se siihen tulee, että minun pitää palkkani sinun nähtes saaman: niin että kaikki, jotka ei ole pilkulliset taikka kirjavat vohlista, eikä hallavat karitsoista, se olkoon varkaus minun tykönäni.","Niin minun vanhurskauteni on todistava tästedes minusta, koska se siihen tulee, että minun pitää palkkani sinun nähtes saaman: niin että kaikki, jotka ei ole pilkulliset taikka kirjavat vohlista, eikä hallavat karitsoista, se olkoon varkaus minun tykönäni."],[30,34,"Niin sanoi Laban: katso, joska se olis sanas jälkeen.","Niin sanoi Laban: katso, joska se olis sanas jälkeen."],[30,35,"Ja sinä päivänä eroitti hän pilkulliset ja kirjavat kauriit ja kaikki pilkulliset ja kirjavat vuohet, kaikki joissa jotakin valkeutta oli, ja kaikki hallavat karitsat: ja antoi ne lastensa haltuun.","Ja sinä päivänä eroitti hän pilkulliset ja kirjavat kauriit ja kaikki pilkulliset ja kirjavat vuohet, kaikki joissa jotakin valkeutta oli, ja kaikki hallavat karitsat: ja antoi ne lastensa haltuun."],[30,36,"Ja asetti kolmen päiväkunnan matkan, itsensä ja Jakobin vaiheelle: ja Jakob kaitsi niitä, jotka Labanin laumasta jäivät.","Ja asetti kolmen päiväkunnan matkan, itsensä ja Jakobin vaiheelle: ja Jakob kaitsi niitä, jotka Labanin laumasta jäivät."],[30,37,"Mutta Jakob otti viherjäisiä haapaisia sauvoja, mandelpuisia ja plataneapuisia; ja kuori niihin valkiat juonteet, valkian paikan paljastamisella, joka sauvain päällä oli.","Mutta Jakob otti viherjäisiä haapaisia sauvoja, mandelpuisia ja plataneapuisia; ja kuori niihin valkiat juonteet, valkian paikan paljastamisella, joka sauvain päällä oli."],[30,38,"Ja pani ne sauvat, jotka hän kuorinut oli, laumain eteen, vesiruuhiin, ja juoma-astioihin, lauman eteen, joihin he tulivat juomaan, että he juomalle tultuansa siittäisivät.","Ja pani ne sauvat, jotka hän kuorinut oli, laumain eteen, vesiruuhiin, ja juoma-astioihin, lauman eteen, joihin he tulivat juomaan, että he juomalle tultuansa siittäisivät."],[30,39,"Ja niin laumat siittivät niiden sauvain päällä, ja kantoivat pilkullisia, juonteisia ja kirjavia.","Ja niin laumat siittivät niiden sauvain päällä, ja kantoivat pilkullisia, juonteisia ja kirjavia."],[30,40,"Niin Jakob eroitti karitsat, ja asetti lauman kasvot, siinä valkiassa laumassa, niitä pilkullisia ja hallavia päin: ja teki itsellensä eri lauman, ja ei laskenut niitä Labanin lauman sekaan.","Niin Jakob eroitti karitsat, ja asetti lauman kasvot, siinä valkiassa laumassa, niitä pilkullisia ja hallavia päin: ja teki itsellensä eri lauman, ja ei laskenut niitä Labanin lauman sekaan."],[30,41,"Ja koska se varhain kantava lauma oli sikoillansa, pani Jakob sauvat laumain silmäin eteen ruuhiin: että he siittäisivät sauvain päällä.","Ja koska se varhain kantava lauma oli sikoillansa, pani Jakob sauvat laumain silmäin eteen ruuhiin: että he siittäisivät sauvain päällä."],[30,42,"Mutta koska ne hiljain juoksivat, niin ei hän pannut niitä sisälle. Niin tulivat äpöiset Labanille ja varhain kannetut Jakobille.","Mutta koska ne hiljain juoksivat, niin ei hän pannut niitä sisälle. Niin tulivat äpöiset Labanille ja varhain kannetut Jakobille."],[30,43,"Siitä tuli mies sangen äveriääksi, niin että hänellä oli paljo lampaita ja piikoja ja palvelioita, ja kameleja ja aaseja.","Siitä tuli mies sangen äveriääksi, niin että hänellä oli paljo lampaita ja piikoja ja palvelioita, ja kameleja ja aaseja."],[31,1,"Ja hänen eteensä tuli Labanin lasten puhe, että he sanoivat: Jakob on saattanut itsellensä kaiken meidän isämme tavaran: ja siitä meidän isämme hyvyydestä on hän saattanut itsellensä kaiken tämän tavaran.","Ja hänen eteensä tuli Labanin lasten puhe, että he sanoivat: Jakob on saattanut itsellensä kaiken meidän isämme tavaran: ja siitä meidän isämme hyvyydestä on hän saattanut itsellensä kaiken tämän tavaran."],[31,2,"Ja Jakob näki Labanin kasvon: ja katso, ei ollut se häntä kohtaan, niinkuin eilen ja entispäivänä.","Ja Jakob näki Labanin kasvon: ja katso, ei ollut se häntä kohtaan, niinkuin eilen ja entispäivänä."],[31,3,"Ja Herra sanoi Jakobille: palaja sinun isäis maalle, ja sukuis tykö: ja minä olen sinun kanssas.","Ja Herra sanoi Jakobille: palaja sinun isäis maalle, ja sukuis tykö: ja minä olen sinun kanssas."],[31,4,"Niin lähetti Jakob ja kutsui Rakelin ja Lean kedolle laumansa tykö.","Niin lähetti Jakob ja kutsui Rakelin ja Lean kedolle laumansa tykö."],[31,5,"Ja sanoi heille: minä näen teidän isänne kasvon, ettei hän ole minua kohtaan niinkuin eilen ja entispäivänä, mutta minun isäni Jumala on ollut minun kanssani.","Ja sanoi heille: minä näen teidän isänne kasvon, ettei hän ole minua kohtaan niinkuin eilen ja entispäivänä, mutta minun isäni Jumala on ollut minun kanssani."],[31,6,"Ja te itse tiedätte, että minä olen kaikella minun väelläni palvellut teidän isäänne.","Ja te itse tiedätte, että minä olen kaikella minun väelläni palvellut teidän isäänne."],[31,7,"Mutta teidän isänne on vietellyt minua, ja muuttanut minun palkkani jo kymmenen kertaa: ei kuitenkaan sallinut Jumala hänen vahinkoa tehdä minulle.","Mutta teidän isänne on vietellyt minua, ja muuttanut minun palkkani jo kymmenen kertaa: ei kuitenkaan sallinut Jumala hänen vahinkoa tehdä minulle."],[31,8,"Koska hän sanoi: kirjavat pitää oleman sinun palkkas, niin kaikki lauma kantoi kirjavia. Mutta jos hän sanoi: pilkulliset pitää oleman sinun palkkas, niin kaikki lauma kantoi pilkullisia.","Koska hän sanoi: kirjavat pitää oleman sinun palkkas, niin kaikki lauma kantoi kirjavia. Mutta jos hän sanoi: pilkulliset pitää oleman sinun palkkas, niin kaikki lauma kantoi pilkullisia."],[31,9,"Niin on Jumala ottanut teidän isänne hyvyyden ja antanut minulle.","Niin on Jumala ottanut teidän isänne hyvyyden ja antanut minulle."],[31,10,"Ja tapahtui lauman siittämisen ajalla, nostin minä silmäni ja näin unessa: ja katso, kauriit, jotka nousivat laumain päälle, olivat juonteiset, pilkulliset ja kirjavat.","Ja tapahtui lauman siittämisen ajalla, nostin minä silmäni ja näin unessa: ja katso, kauriit, jotka nousivat laumain päälle, olivat juonteiset, pilkulliset ja kirjavat."],[31,11,"Ja Jumalan enkeli sanoi minulle unessa: Jakob; ja minä vastasin: tässä minä olen.","Ja Jumalan enkeli sanoi minulle unessa: Jakob; ja minä vastasin: tässä minä olen."],[31,12,"Mutta hän sanoi: nosta silmäs, ja katso, kaikki kauriit, jotka nousevat laumain päälle, ovat juonteiset, pilkulliset ja kirjavat: sillä minä olen nähnyt kaikki, mitä Laban sinulle tekee.","Mutta hän sanoi: nosta silmäs, ja katso, kaikki kauriit, jotka nousevat laumain päälle, ovat juonteiset, pilkulliset ja kirjavat: sillä minä olen nähnyt kaikki, mitä Laban sinulle tekee."],[31,13,"Minä olen Jumala BetElissä, jossa sinä voitelit kiven, ja jossas teit minulle lupauksen: nouse siis nyt ja lähde tältä maalta, ja palaja syntymä-maalles.","Minä olen Jumala BetElissä, jossa sinä voitelit kiven, ja jossas teit minulle lupauksen: nouse siis nyt ja lähde tältä maalta, ja palaja syntymä-maalles."],[31,14,"Niin vastasivat Rakel ja Lea, ja sanoivat hänelle: onko meillä enää osaa, eli perimistä meidän isämme huoneessa?","Niin vastasivat Rakel ja Lea, ja sanoivat hänelle: onko meillä enää osaa, eli perimistä meidän isämme huoneessa?"],[31,15,"Eikö hän ole pitänyt meitä muukalaisina? Sillä hän on myynyt meidät, ja peräti syönyt meidän hintamme.","Eikö hän ole pitänyt meitä muukalaisina? Sillä hän on myynyt meidät, ja peräti syönyt meidän hintamme."],[31,16,"Sentähden kaikki hyvyys, jonka Jumala on ottanut meidän isältämme, se tulee oikeudella meille ja meidän lapsillemme: Nyt siis kaikki, mitä Jumala sinulle on käskenyt, se tee.","Sentähden kaikki hyvyys, jonka Jumala on ottanut meidän isältämme, se tulee oikeudella meille ja meidän lapsillemme: Nyt siis kaikki, mitä Jumala sinulle on käskenyt, se tee."],[31,17,"Niin nousi Jakob; ja nosti lapsensa ja emäntänsä kamelein päälle.","Niin nousi Jakob; ja nosti lapsensa ja emäntänsä kamelein päälle."],[31,18,"Ja vei pois kaiken karjansa, ja kaiken tavaransa, minkä hän oli pannut kokoon, sen oman karjansa, kun hän oli saanut Mesopotamiassa: mennäksensä isänsä Isaakin tykö Kanaanin maalle.","Ja vei pois kaiken karjansa, ja kaiken tavaransa, minkä hän oli pannut kokoon, sen oman karjansa, kun hän oli saanut Mesopotamiassa: mennäksensä isänsä Isaakin tykö Kanaanin maalle."],[31,19,"Mutta Laban oli mennyt keritsemään laumaansa. Ja Rakel varasti isänsä epäjumalat.","Mutta Laban oli mennyt keritsemään laumaansa. Ja Rakel varasti isänsä epäjumalat."],[31,20,"Niin varasti Jakob Labanin Syrialaisen sydämen, siinä ettei hän ilmoittanut hänelle, että hän pakeni.","Niin varasti Jakob Labanin Syrialaisen sydämen, siinä ettei hän ilmoittanut hänelle, että hän pakeni."],[31,21,"Niin hän pakeni, ja kaikki, mitä hänellä oli, nousi ja meni virran ylitse; ja meni Gileadin vuorta kohden.","Niin hän pakeni, ja kaikki, mitä hänellä oli, nousi ja meni virran ylitse; ja meni Gileadin vuorta kohden."],[31,22,"Kolmantena päivänä ilmoitettiin Labanille, että Jakob oli paennut.","Kolmantena päivänä ilmoitettiin Labanille, että Jakob oli paennut."],[31,23,"Niin hän otti veljensä kanssansa, ja ajoi häntä takaa seitsemän päiväkunnan matkan: ja saavutti hänen Gileadin vuorella.","Niin hän otti veljensä kanssansa, ja ajoi häntä takaa seitsemän päiväkunnan matkan: ja saavutti hänen Gileadin vuorella."],[31,24,"Mutta Jumala oli tullut Labanin Syrialaisen tykö yöllä unessa ja sanonut hänelle: kavahda sinuas, ettes puhu Jakobille hyvää eli pahaa.","Mutta Jumala oli tullut Labanin Syrialaisen tykö yöllä unessa ja sanonut hänelle: kavahda sinuas, ettes puhu Jakobille hyvää eli pahaa."],[31,25,"Ja Laban lähestyi Jakobia. Mutta Jakob oli majansa tehnyt vuorelle. Ja Laban teki veljinensä myös majansa Gileadin vuorelle.","Ja Laban lähestyi Jakobia. Mutta Jakob oli majansa tehnyt vuorelle. Ja Laban teki veljinensä myös majansa Gileadin vuorelle."],[31,26,"Niin sanoi Laban Jakobille: mitäs olet tehnyt, ettäs varastit minun sydämeni ja olet vienyt pois minun tyttäreni niinkuin miekalla otetut?","Niin sanoi Laban Jakobille: mitäs olet tehnyt, ettäs varastit minun sydämeni ja olet vienyt pois minun tyttäreni niinkuin miekalla otetut?"],[31,27,"Ja miksis salaa pakenit ja varastit sinus minulta, ja et ilmoittanut minulle? että minä olisin sinua saattanut ilolla, ja lauluilla, ja trumpuilla, ja kanteleilla.","Ja miksis salaa pakenit ja varastit sinus minulta, ja et ilmoittanut minulle? että minä olisin sinua saattanut ilolla, ja lauluilla, ja trumpuilla, ja kanteleilla."],[31,28,"Ja et sallinut minun suuta antaa minun pojilleni ja tyttärilleni: tämän sinä olet tyhmästi tehnyt.","Ja et sallinut minun suuta antaa minun pojilleni ja tyttärilleni: tämän sinä olet tyhmästi tehnyt."],[31,29,"Ja minulla olis kyllä voimaa tehdä teille pahaa, mutta teidän isänne Jumala sanoi menneenä yönä minulle: kavahda itses puhumasta Jakobille hyvää eli pahaa.","Ja minulla olis kyllä voimaa tehdä teille pahaa, mutta teidän isänne Jumala sanoi menneenä yönä minulle: kavahda itses puhumasta Jakobille hyvää eli pahaa."],[31,30,"Ja nyt ettäs kumminkin menit pois, ja niin suuresti ikävoitsit isäs huoneeseen: miksis varastit minun jumalani.","Ja nyt ettäs kumminkin menit pois, ja niin suuresti ikävoitsit isäs huoneeseen: miksis varastit minun jumalani."],[31,31,"Ja Jakob vastasi, ja sanoi Labanille: minä pelkäsin ja luulin sinun väkivallalla ottavan pois minulta sinun tyttäres.","Ja Jakob vastasi, ja sanoi Labanille: minä pelkäsin ja luulin sinun väkivallalla ottavan pois minulta sinun tyttäres."],[31,32,"Mutta kenenkä tyköä sinä löydät jumalas, ei sen pidä elämän. Tunnustele meidän veljeimme läsnä ollessa, mitä omaas on minun tykönäni, ja ota pois se. Mutta ei Jakob tietänyt Rakelin niitä varastaneen.","Mutta kenenkä tyköä sinä löydät jumalas, ei sen pidä elämän. Tunnustele meidän veljeimme läsnä ollessa, mitä omaas on minun tykönäni, ja ota pois se. Mutta ei Jakob tietänyt Rakelin niitä varastaneen."],[31,33,"Niin Laban meni Jakobin majaan, ja Lean majaan, ja heidän molempain piikainsa majaan, ja ei löytänyt. Ja läksi Lean majasta, ja tuli Rakelin majaan.","Niin Laban meni Jakobin majaan, ja Lean majaan, ja heidän molempain piikainsa majaan, ja ei löytänyt. Ja läksi Lean majasta, ja tuli Rakelin majaan."],[31,34,"Mutta Rakel oli ottanut epäjumalat ja pannut kamelein satulan ala, ja istui siihen päälle; mutta Laban etsi kaiken majan ja ei löytänyt.","Mutta Rakel oli ottanut epäjumalat ja pannut kamelein satulan ala, ja istui siihen päälle; mutta Laban etsi kaiken majan ja ei löytänyt."],[31,35,"Ja hän sanoi isällensä: älköön minun herrani vihastuko, etten minä saa nousta sinun edessäs: sillä minulle tapahtuu vaimoin menon jälkeen: Ja hän etsi, ja ei löytänyt epäjumaliansa.","Ja hän sanoi isällensä: älköön minun herrani vihastuko, etten minä saa nousta sinun edessäs: sillä minulle tapahtuu vaimoin menon jälkeen: Ja hän etsi, ja ei löytänyt epäjumaliansa."],[31,36,"Ja Jakob vihastui ja riiteli Labanin kanssa; vastasi ja sanoi hänelle: mitä minä olen rikkonut, ja mikä minun pahatekoni on, ettäs minua olet niin vihaisesti ajanut takaa?","Ja Jakob vihastui ja riiteli Labanin kanssa; vastasi ja sanoi hänelle: mitä minä olen rikkonut, ja mikä minun pahatekoni on, ettäs minua olet niin vihaisesti ajanut takaa?"],[31,37,"Sinä olet etsiskellyt kaikki minun taloni kalut, mitäs olet löytänyt kaikista sinun talois kaluista? Tuo tähän minun ja sinun veljeis eteen, ratkaista meidän kahden vaiheellamme.","Sinä olet etsiskellyt kaikki minun taloni kalut, mitäs olet löytänyt kaikista sinun talois kaluista? Tuo tähän minun ja sinun veljeis eteen, ratkaista meidän kahden vaiheellamme."],[31,38,"Minä olen ollut sinun tykönäs jo kaksikymmentä ajastaikaa, ja sinun lampaas ja vuohes ei ole hedelmättömät olleet: ja en ole minä syönyt oinaita sinun laumastas.","Minä olen ollut sinun tykönäs jo kaksikymmentä ajastaikaa, ja sinun lampaas ja vuohes ei ole hedelmättömät olleet: ja en ole minä syönyt oinaita sinun laumastas."],[31,39,"Enkä ole tuonut sinulle pedolta haaskattua, mutta minun piti sen maksaman, sen olet sinä minun kädestäni vaatinut: niin myös mitä ikänänsä sinulta päivällä eli yöllä varastettu oli.","Enkä ole tuonut sinulle pedolta haaskattua, mutta minun piti sen maksaman, sen olet sinä minun kädestäni vaatinut: niin myös mitä ikänänsä sinulta päivällä eli yöllä varastettu oli."],[31,40,"Päivällä on minun helle väsyttänyt, ja yöllä vilu: ja uni on paennut minun silmistäni.","Päivällä on minun helle väsyttänyt, ja yöllä vilu: ja uni on paennut minun silmistäni."],[31,41,"Minä olen jo kaksikymmentä ajastaikaa ollut sinun huoneessas, neljätoistakymmentä ajastaikaa palvelin minä sinua kahden tyttäres tähden, ja kuusi ajastaikaa sinun laumas tähden: ja sinä olet muuttanut minun palkkani kymmenen kertaa.","Minä olen jo kaksikymmentä ajastaikaa ollut sinun huoneessas, neljätoistakymmentä ajastaikaa palvelin minä sinua kahden tyttäres tähden, ja kuusi ajastaikaa sinun laumas tähden: ja sinä olet muuttanut minun palkkani kymmenen kertaa."],[31,42,"Jollei minun isäni Jumala, Abrahamin Jumala ja Isaakin pelko olisi ollut minun puolellani; niin sinä peräti tyhjänä olisit minun päästänyt. Mutta Jumala on nähnyt minun vaivani ja kätteni työt, ja nuhteli menneenä yönä sinua.","Jollei minun isäni Jumala, Abrahamin Jumala ja Isaakin pelko olisi ollut minun puolellani; niin sinä peräti tyhjänä olisit minun päästänyt. Mutta Jumala on nähnyt minun vaivani ja kätteni työt, ja nuhteli menneenä yönä sinua."],[31,43,"Vastasi Laban, ja sanoi Jakobille: tyttäret ovat minun tyttäreni, ja pojat ovat minun poikani, ja laumat ovat minun laumani, ja kaikki mitä sinä näet ovat minun: mitä minä teen tänäpänä minun tyttärilleni taikka heidän lapsillensa, jotka he ovat synnyttäneet?","Vastasi Laban, ja sanoi Jakobille: tyttäret ovat minun tyttäreni, ja pojat ovat minun poikani, ja laumat ovat minun laumani, ja kaikki mitä sinä näet ovat minun: mitä minä teen tänäpänä minun tyttärilleni taikka heidän lapsillensa, jotka he ovat synnyttäneet?"],[31,44,"Tule siis nyt ja tehkäämme liitto, minä ja sinä; joka pitää oleman todistus minun ja sinun vaiheellas.","Tule siis nyt ja tehkäämme liitto, minä ja sinä; joka pitää oleman todistus minun ja sinun vaiheellas."],[31,45,"Niin otti Jakob kiven, ja pani pystyälle muistopatsaaksi.","Niin otti Jakob kiven, ja pani pystyälle muistopatsaaksi."],[31,46,"Ja Jakob sanoi veljillensä: kootkaat kiviä. Ja he toivat kiviä, ja tekivät roukkion; ja atrioitsivat siinä sen roukkion päällä.","Ja Jakob sanoi veljillensä: kootkaat kiviä. Ja he toivat kiviä, ja tekivät roukkion; ja atrioitsivat siinä sen roukkion päällä."],[31,47,"Ja Laban kutsui hänen Jegar Sahabuta: mutta Jakob kutsui hänen Gilead.","Ja Laban kutsui hänen Jegar Sahabuta: mutta Jakob kutsui hänen Gilead."],[31,48,"Niin Laban sanoi: tämä roukkio olkoon todistus tänäpänä minun ja sinun vaiheellas; sentähden kutsui hän hänen nimensä Gilead.","Niin Laban sanoi: tämä roukkio olkoon todistus tänäpänä minun ja sinun vaiheellas; sentähden kutsui hän hänen nimensä Gilead."],[31,49,"Ja Mitspa; sillä hän sanoi: Herra olkoon peräänkatsoja sinun ja minun vaiheellani, koska me erkanemme toinen toisestamme:","Ja Mitspa; sillä hän sanoi: Herra olkoon peräänkatsoja sinun ja minun vaiheellani, koska me erkanemme toinen toisestamme:"],[31,50,"Jos sinä vaivaat minun tyttäriäni, taikka otat muita emäntiä, paitsi minun tyttäriäni. Ei ole yhtään ihmistä (joka todistais) meidän kanssamme, mutta katso, Jumala on todistaja minun ja sinun vaiheellas.","Jos sinä vaivaat minun tyttäriäni, taikka otat muita emäntiä, paitsi minun tyttäriäni. Ei ole yhtään ihmistä (joka todistais) meidän kanssamme, mutta katso, Jumala on todistaja minun ja sinun vaiheellas."],[31,51,"Ja Laban sanoi (vielä) Jakobille: katso, tämä on roukkio, ja tämä on muistopatsas, jonka minä panen minun ja sinun vaiheelles.","Ja Laban sanoi (vielä) Jakobille: katso, tämä on roukkio, ja tämä on muistopatsas, jonka minä panen minun ja sinun vaiheelles."],[31,52,"Tämä roukkio olkoon todistus, ja tämä patsas olkoon myös todistus, etten minä käy ylitse tämän roukkion sinun tykös, etkä sinä käy ylitse tämän roukkion ja tämän patsaan minun tyköni, vahinkoa tekemään.","Tämä roukkio olkoon todistus, ja tämä patsas olkoon myös todistus, etten minä käy ylitse tämän roukkion sinun tykös, etkä sinä käy ylitse tämän roukkion ja tämän patsaan minun tyköni, vahinkoa tekemään."],[31,53,"Abrahamin Jumala ja Nahorin Jumala ja heidän isäinsä Jumala, ratkaiskoon meidän välillämme. Ja Jakob vannoi isänsä Isaakin pelvon kautta.","Abrahamin Jumala ja Nahorin Jumala ja heidän isäinsä Jumala, ratkaiskoon meidän välillämme. Ja Jakob vannoi isänsä Isaakin pelvon kautta."],[31,54,"Ja Jakob uhrasi vuorella, ja kutsui veljensä syömään leipää. Ja kuin he olivat syöneet, olivat he yötä vuorella.","Ja Jakob uhrasi vuorella, ja kutsui veljensä syömään leipää. Ja kuin he olivat syöneet, olivat he yötä vuorella."],[31,55,"Mutta aamulla varhain nousi Laban, ja suuta antoi poikainsa ja tytärtensä, ja siunasi heitä, ja meni matkaansa, ja palasi kotiansa.","Mutta aamulla varhain nousi Laban, ja suuta antoi poikainsa ja tytärtensä, ja siunasi heitä, ja meni matkaansa, ja palasi kotiansa."],[32,1,"Mutta Jakob meni tietänsä myöten, ja Jumalan enkelit tulivat häntä vastaan.","Mutta Jakob meni tietänsä myöten, ja Jumalan enkelit tulivat häntä vastaan."],[32,2,"Ja koska hän näki heidät, sanoi hän: Nämä ovat Jumalan sotajoukko. Ja hän kutsui sen paikan Mahanaim.","Ja koska hän näki heidät, sanoi hän: Nämä ovat Jumalan sotajoukko. Ja hän kutsui sen paikan Mahanaim."],[32,3,"Niin Jakob lähetti sanansaattajat edellänsä veljensä Esaun tykö, Seirin maakuntaan, Edomin maalle.","Niin Jakob lähetti sanansaattajat edellänsä veljensä Esaun tykö, Seirin maakuntaan, Edomin maalle."],[32,4,"Ja käski heitä, sanoen: sanokaat näin minun herralleni Esaulle: näin sanoo sinun palvelias Jakob: minä olen ollut muukalainen Labanin tykönä, ja viipynyt tähän asti.","Ja käski heitä, sanoen: sanokaat näin minun herralleni Esaulle: näin sanoo sinun palvelias Jakob: minä olen ollut muukalainen Labanin tykönä, ja viipynyt tähän asti."],[32,5,"Ja minulla on karjaa ja aaseja, lampaita, palvelioita ja piikoja: ja lähetin ilmoittamaan minun herralleni, löytääkseni armoa sinun edessäs.","Ja minulla on karjaa ja aaseja, lampaita, palvelioita ja piikoja: ja lähetin ilmoittamaan minun herralleni, löytääkseni armoa sinun edessäs."],[32,6,"Sanansaattajat palasivat Jakobin tykö, sanoen: me tulimme Esaun sinun veljes tykö; ja hän tulee sinua vastaan, ja neljäsataa miestä hänen kanssansa.","Sanansaattajat palasivat Jakobin tykö, sanoen: me tulimme Esaun sinun veljes tykö; ja hän tulee sinua vastaan, ja neljäsataa miestä hänen kanssansa."],[32,7,"Niin peljästyi Jakob kovin, ja ahdistus tuli hänen päällensä: ja jakoi väen, joka oli hänen kanssansa, ja lampaat, ja karjan ja kamelit kahteen joukkoon.","Niin peljästyi Jakob kovin, ja ahdistus tuli hänen päällensä: ja jakoi väen, joka oli hänen kanssansa, ja lampaat, ja karjan ja kamelit kahteen joukkoon."],[32,8,"Ja sanoi: jos Esau tulee yhden joukon päälle, ja lyö sen; niin jäänyt joukko pääsee.","Ja sanoi: jos Esau tulee yhden joukon päälle, ja lyö sen; niin jäänyt joukko pääsee."],[32,9,"Ja Jakob sanoi: minun isäni Abrahamin Jumala, ja minun isäni Isaakin Jumala, Herra joka sanoit minulle: palaja maalles ja sukuis tykö, ja minä teen sinulle hyvää.","Ja Jakob sanoi: minun isäni Abrahamin Jumala, ja minun isäni Isaakin Jumala, Herra joka sanoit minulle: palaja maalles ja sukuis tykö, ja minä teen sinulle hyvää."],[32,10,"Minä olen mahdotoin kaikkeen siihen armoon, ja kaikkeen siihen totuuteen, jonka sinä teit palvelialles. Sillä koska minä tämän Jordanin ylitse menin, ei minulla muuta ollut kuin minun sauvani; mutta nyt minulla on kaksi joukkoa.","Minä olen mahdotoin kaikkeen siihen armoon, ja kaikkeen siihen totuuteen, jonka sinä teit palvelialles. Sillä koska minä tämän Jordanin ylitse menin, ei minulla muuta ollut kuin minun sauvani; mutta nyt minulla on kaksi joukkoa."],[32,11,"Pelasta siis nyt minua minun veljeni Esaun käsistä: sillä minä pelkään hänen tulevan ja lyövän minun, ja äidin lapsinensa.","Pelasta siis nyt minua minun veljeni Esaun käsistä: sillä minä pelkään hänen tulevan ja lyövän minun, ja äidin lapsinensa."],[32,12,"Sinä olet kumminkin sanonut: minä teen kaiketi sinulle hyvää; ja lisään sinun siemenes niinkuin sannan meressä, joka paljouden tähden ei luettaa taideta.","Sinä olet kumminkin sanonut: minä teen kaiketi sinulle hyvää; ja lisään sinun siemenes niinkuin sannan meressä, joka paljouden tähden ei luettaa taideta."],[32,13,"Ja hän yötyi sinne, ja otti niistä, kuin olivat käsillä, lahjoja lähettääksensä veljellensä Esaulle:","Ja hän yötyi sinne, ja otti niistä, kuin olivat käsillä, lahjoja lähettääksensä veljellensä Esaulle:"],[32,14,"Kaksisataa vuohta, ja kaksikymmentä kaurista: kaksisataa lammasta ja kaksikymmentä jäärää:","Kaksisataa vuohta, ja kaksikymmentä kaurista: kaksisataa lammasta ja kaksikymmentä jäärää:"],[32,15,"Imettäviä kameleja varsoinensa kolmekymmentä: neljäkymmentä lehmää ja kymmenen härkää, kaksikymmentä aasia ja kymmenen varsaa.","Imettäviä kameleja varsoinensa kolmekymmentä: neljäkymmentä lehmää ja kymmenen härkää, kaksikymmentä aasia ja kymmenen varsaa."],[32,16,"Ja antoi ne palvelioittensa käsiin, itsekunkin lauman erinänsä; ja sanoi palvelioillensa: menkäät minun edelläni, ja pitäkäät väli jokaisen lauman vaiheella.","Ja antoi ne palvelioittensa käsiin, itsekunkin lauman erinänsä; ja sanoi palvelioillensa: menkäät minun edelläni, ja pitäkäät väli jokaisen lauman vaiheella."],[32,17,"Ja käski ensimäiselle, sanoen: Koska minun veljeni Esau kohtaa sinun, ja kysyy sinulta, kenenkäs olet, ja kuhunkas menet? ja kenenkä nämät ovat, joitas ajat edelläs?","Ja käski ensimäiselle, sanoen: Koska minun veljeni Esau kohtaa sinun, ja kysyy sinulta, kenenkäs olet, ja kuhunkas menet? ja kenenkä nämät ovat, joitas ajat edelläs?"],[32,18,"Niin sano: nämät ovat sinun palvelias Jakobin lahjat, lähetetyt minun herralleni Esaulle: ja katso, hän tulee myös itse meidän jälissämme.","Niin sano: nämät ovat sinun palvelias Jakobin lahjat, lähetetyt minun herralleni Esaulle: ja katso, hän tulee myös itse meidän jälissämme."],[32,19,"Niin käski hän myös toiselle ja kolmannelle, ja kaikille niille, jotka kävivät lauman jälissä, sanoen: tämän minun sanani jälkeen puhukaat Esaulle, koska te hänen löydätte.","Niin käski hän myös toiselle ja kolmannelle, ja kaikille niille, jotka kävivät lauman jälissä, sanoen: tämän minun sanani jälkeen puhukaat Esaulle, koska te hänen löydätte."],[32,20,"Ja sanokaat myös: katso, sinun palvelias Jakob on myös meidän jälissämme; sillä hän ajatteli: minä lepytän hänen lahjoilla, jotka minun edelläni menevät; sitte tahdon minä nähdä hänen kasvonsa, mitämaks, hän ottaa vastaan minun ystävällisesti.","Ja sanokaat myös: katso, sinun palvelias Jakob on myös meidän jälissämme; sillä hän ajatteli: minä lepytän hänen lahjoilla, jotka minun edelläni menevät; sitte tahdon minä nähdä hänen kasvonsa, mitämaks, hän ottaa vastaan minun ystävällisesti."],[32,21,"Niin lahjat menivät hänen edellänsä; mutta hän oli itse siinä yötä joukkoinensa.","Niin lahjat menivät hänen edellänsä; mutta hän oli itse siinä yötä joukkoinensa."],[32,22,"Ja nousi yöllä ja otti kaksi emäntäänsä, ja ne kaksi piikaansa, ja yksitoistakymmentä lastansa: ja meni ylitse Jabbokin luotuspaikkaan.","Ja nousi yöllä ja otti kaksi emäntäänsä, ja ne kaksi piikaansa, ja yksitoistakymmentä lastansa: ja meni ylitse Jabbokin luotuspaikkaan."],[32,23,"Ja otti ne ja vei heidät virran ylitse: ja vei myös ylitse kaikki, mitä hänellä oli.","Ja otti ne ja vei heidät virran ylitse: ja vei myös ylitse kaikki, mitä hänellä oli."],[32,24,"Mutta Jakob jäi sille puolelle yksinänsä. Silloin paineli yksi mies hänen kanssansa, siihenasti kuin aamurusko nousi.","Mutta Jakob jäi sille puolelle yksinänsä. Silloin paineli yksi mies hänen kanssansa, siihenasti kuin aamurusko nousi."],[32,25,"Ja kuin hän näki, ettei hän voittanut häntä, rupesi hän hänen reiteensä, niin että Jakobin reisiluu horjahtui painellessa hänen kanssansa.","Ja kuin hän näki, ettei hän voittanut häntä, rupesi hän hänen reiteensä, niin että Jakobin reisiluu horjahtui painellessa hänen kanssansa."],[32,26,"Ja hän sanoi: päästä minua, sillä aamurusko nousee. Mutta hän vastasi: en minä päästä sinua, jolles siunaa minua.","Ja hän sanoi: päästä minua, sillä aamurusko nousee. Mutta hän vastasi: en minä päästä sinua, jolles siunaa minua."],[32,27,"Ja hän sanoi hänelle: mikä sinun nimes on? hän vastasi: Jakob.","Ja hän sanoi hänelle: mikä sinun nimes on? hän vastasi: Jakob."],[32,28,"Ja hän sanoi: ei sinua sillen pidä kutsuttaman Jakob, vaan IsraEl: sillä sinä olet taistellut Jumalan ja ihmisten kanssa, ja olet voittanut.","Ja hän sanoi: ei sinua sillen pidä kutsuttaman Jakob, vaan IsraEl: sillä sinä olet taistellut Jumalan ja ihmisten kanssa, ja olet voittanut."],[32,29,"Ja Jakob kysyi häneltä, ja sanoi: sanos nyt sinun nimes. Mutta hän sanoi: miksis minun nimeäni kysyt? Ja hän siunasi häntä siinä paikassa.","Ja Jakob kysyi häneltä, ja sanoi: sanos nyt sinun nimes. Mutta hän sanoi: miksis minun nimeäni kysyt? Ja hän siunasi häntä siinä paikassa."],[32,30,"Ja Jakob kutsui sen paikan Pniel: sillä minä olen nähnyt Jumalan kasvosta kasvoon, ja minun sieluni on vapahdettu.","Ja Jakob kutsui sen paikan Pniel: sillä minä olen nähnyt Jumalan kasvosta kasvoon, ja minun sieluni on vapahdettu."],[32,31,"Ja aurinko nousi, koska hän Pnielin ohitse kävi, ja hän ontui reidestänsä.","Ja aurinko nousi, koska hän Pnielin ohitse kävi, ja hän ontui reidestänsä."],[32,32,"Sentähden ei syö Israelin lapset reisisuonta tähän päivään asti, että Jakobin reisiluu horjahtui.","Sentähden ei syö Israelin lapset reisisuonta tähän päivään asti, että Jakobin reisiluu horjahtui."],[33,1,"Ja Jakob nosti silmänsä ja näki, ja katso, Esau tuli, ja neljäsataa miestä hänen kanssansa: ja hän jakoi lapset Lealle ja Rakelille, ja molemmille piioille.","Ja Jakob nosti silmänsä ja näki, ja katso, Esau tuli, ja neljäsataa miestä hänen kanssansa: ja hän jakoi lapset Lealle ja Rakelille, ja molemmille piioille."],[33,2,"Ja asetti piiat lapsinensa ensimmäiseksi; sitälähin Lean hänen lastensa kanssa, ja Rakelin Josephin kanssa jälimmäiseksi.","Ja asetti piiat lapsinensa ensimmäiseksi; sitälähin Lean hänen lastensa kanssa, ja Rakelin Josephin kanssa jälimmäiseksi."],[33,3,"Mutta itse hän kävi heidän edellänsä: ja kumarsi maahan seitsemän kertaa, siihenasti kuin hän veljeänsä lähestyi.","Mutta itse hän kävi heidän edellänsä: ja kumarsi maahan seitsemän kertaa, siihenasti kuin hän veljeänsä lähestyi."],[33,4,"Ja Esau juoksi häntä vastaan, ja syliinsä otti hänen, ja halasi häntä kaulasta, ja suuta antoi hänen: ja he itkivät.","Ja Esau juoksi häntä vastaan, ja syliinsä otti hänen, ja halasi häntä kaulasta, ja suuta antoi hänen: ja he itkivät."],[33,5,"Ja hän nosti silmänsä, ja näki vaimot ja lapset, ja sanoi: kutka nämät kanssas ovat? Hän vastasi: ne ovat lapset, jotka Jumala on lahjoittanut sinun palvelialles.","Ja hän nosti silmänsä, ja näki vaimot ja lapset, ja sanoi: kutka nämät kanssas ovat? Hän vastasi: ne ovat lapset, jotka Jumala on lahjoittanut sinun palvelialles."],[33,6,"Niin piiat lähestyivät lapsinensa ja kumarsivat hänen edessänsä.","Niin piiat lähestyivät lapsinensa ja kumarsivat hänen edessänsä."],[33,7,"Ja lähestyi myös Lea lapsinensa, ja kumarsivat hänen edessänsä. Sitte tuli Joseph ja Rakel, jotka myös kumarsivat hänen edessänsä.","Ja lähestyi myös Lea lapsinensa, ja kumarsivat hänen edessänsä. Sitte tuli Joseph ja Rakel, jotka myös kumarsivat hänen edessänsä."],[33,8,"Ja hän sanoi: mitäs tahdot kaiken sen joukon kanssa, kuin minä kohdannut olen? Hän vastasi: löytääkseni armoa minun herrani edessä.","Ja hän sanoi: mitäs tahdot kaiken sen joukon kanssa, kuin minä kohdannut olen? Hän vastasi: löytääkseni armoa minun herrani edessä."],[33,9,"Ja Esau sanoi: minulla on kyllä, minun veljeni, pidä omas.","Ja Esau sanoi: minulla on kyllä, minun veljeni, pidä omas."],[33,10,"Niin Jakob vastasi: ei niin, mutta jos minä olen löytänyt armon sinun edessäs, niin ota minun lahjani minun kädestäni: sillä minä näin sinun kasvos, niinkuin minä olisin nähnyt Jumalan kasvot; ettäs olet minut hyväksi ottanut.","Niin Jakob vastasi: ei niin, mutta jos minä olen löytänyt armon sinun edessäs, niin ota minun lahjani minun kädestäni: sillä minä näin sinun kasvos, niinkuin minä olisin nähnyt Jumalan kasvot; ettäs olet minut hyväksi ottanut."],[33,11,"Ota siis se siunaus, jonka minä olen tuonut sinulle: sillä Jumala on sen minulle antanut, ja minulla on kyllä kaikkinaista. Niin hän vaati häntä ottamaan.","Ota siis se siunaus, jonka minä olen tuonut sinulle: sillä Jumala on sen minulle antanut, ja minulla on kyllä kaikkinaista. Niin hän vaati häntä ottamaan."],[33,12,"Ja (Esau) sanoi: lähtekäämme jo matkustamaan, minä vaellan sinun kanssas.","Ja (Esau) sanoi: lähtekäämme jo matkustamaan, minä vaellan sinun kanssas."],[33,13,"Niin hän sanoi hänelle: minun herrani tietää minulla olevan pieniä lapsia, ja imettäväisiä lampaita ja karjaa: jos ne yhtenä päivänä äkisti ajettaisiin, niin kuolis lauma.","Niin hän sanoi hänelle: minun herrani tietää minulla olevan pieniä lapsia, ja imettäväisiä lampaita ja karjaa: jos ne yhtenä päivänä äkisti ajettaisiin, niin kuolis lauma."],[33,14,"Niin menkään minun herrani palveliansa edellä: mutta minä seuraan hiljaksensa senjälkeen kuin karja ja lapset käydä voivat, siihenasti kuin minä tulen minun herrani tykö Seiriin.","Niin menkään minun herrani palveliansa edellä: mutta minä seuraan hiljaksensa senjälkeen kuin karja ja lapset käydä voivat, siihenasti kuin minä tulen minun herrani tykö Seiriin."],[33,15,"Ja Esau sanoi: minä jätän kuitenkin sinun tykös jotakin siitä väestä, kuin minun kanssani on. Hän vastasi: mihinkä se? Anna minun ainoastansa löytää armo minun herrani edessä.","Ja Esau sanoi: minä jätän kuitenkin sinun tykös jotakin siitä väestä, kuin minun kanssani on. Hän vastasi: mihinkä se? Anna minun ainoastansa löytää armo minun herrani edessä."],[33,16,"Niin Esau palasi sinä päivänä tietänsä myöten Seiriin.","Niin Esau palasi sinä päivänä tietänsä myöten Seiriin."],[33,17,"Mutta Jakob matkusti Sukkotiin, ja rakensi itsellensä huoneen, ja teki majat karjallensa. Sentähden kutsui hän sen paikan Sukkot.","Mutta Jakob matkusti Sukkotiin, ja rakensi itsellensä huoneen, ja teki majat karjallensa. Sentähden kutsui hän sen paikan Sukkot."],[33,18,"Sitte tuli Jakob rauhoitettuna siihen kaupunkiin Sikem, joka on Kanaanin maalla, sitte kuin hän oli tullut Mesopotamiasta; ja sioitti itsensä kaupungin kohdalle.","Sitte tuli Jakob rauhoitettuna siihen kaupunkiin Sikem, joka on Kanaanin maalla, sitte kuin hän oli tullut Mesopotamiasta; ja sioitti itsensä kaupungin kohdalle."],[33,19,"Ja osti murun peltoa, johonka hän teki majansa, Hemorin, Sikemin isän lapsilta, sadan penningin edestä.","Ja osti murun peltoa, johonka hän teki majansa, Hemorin, Sikemin isän lapsilta, sadan penningin edestä."],[33,20,"Ja rakensi siinä alttarin: ja rukoili väkevää Israelin Jumalan nimeä.","Ja rakensi siinä alttarin: ja rukoili väkevää Israelin Jumalan nimeä."],[34,1,"Ja Dina, Lean tytär, jonka hän Jakobille synnyttänyt oli, meni katselemaan sen maakunnan tyttäriä.","Ja Dina, Lean tytär, jonka hän Jakobille synnyttänyt oli, meni katselemaan sen maakunnan tyttäriä."],[34,2,"Koska Sikem, Hemorin Heviläisen, sen maakunnan ruhtinaan poika näki hänen, otti hän hänen ja makasi hänen, ja häpäisi hänen.","Koska Sikem, Hemorin Heviläisen, sen maakunnan ruhtinaan poika näki hänen, otti hän hänen ja makasi hänen, ja häpäisi hänen."],[34,3,"Ja hänen sydämensä paloi Dinan Jakobin tyttären perään; ja rakasti piikaa, ja puhutteli häntä suloisilla sanoilla.","Ja hänen sydämensä paloi Dinan Jakobin tyttären perään; ja rakasti piikaa, ja puhutteli häntä suloisilla sanoilla."],[34,4,"Ja Sikem puhui isällensä Hemorille, sanoen: ota minulle tämä piika emännäksi.","Ja Sikem puhui isällensä Hemorille, sanoen: ota minulle tämä piika emännäksi."],[34,5,"Ja Jakob kuuli, että he hänen tyttärensä Dinan olivat häväisseet, ja hänen poikansa olivat lauman kanssa kedolla. Ja Jakob vaikeni siihenasti kuin he tulivat.","Ja Jakob kuuli, että he hänen tyttärensä Dinan olivat häväisseet, ja hänen poikansa olivat lauman kanssa kedolla. Ja Jakob vaikeni siihenasti kuin he tulivat."],[34,6,"Ja Hemor Sikemin isä meni Jakobin tykö puhuttelemaan häntä.","Ja Hemor Sikemin isä meni Jakobin tykö puhuttelemaan häntä."],[34,7,"Silloin tulivat Jakobin pojat kedolta: ja koska he sen kuulivat, tulivat miehet surulliseksi, ja vihastuivat sangen kovin; että hän oli tehnyt tyhmyyden Israelissa, maaten Jakobin tyttären: sillä ei ollut se oikein tehty.","Silloin tulivat Jakobin pojat kedolta: ja koska he sen kuulivat, tulivat miehet surulliseksi, ja vihastuivat sangen kovin; että hän oli tehnyt tyhmyyden Israelissa, maaten Jakobin tyttären: sillä ei ollut se oikein tehty."],[34,8,"Niin puhui Hemor heidän kanssansa, sanoen: minun poikani Sikemin sydän halajaa teidän tyttärenne jälkeen; antakaat siis se hänelle emännäksi.","Niin puhui Hemor heidän kanssansa, sanoen: minun poikani Sikemin sydän halajaa teidän tyttärenne jälkeen; antakaat siis se hänelle emännäksi."],[34,9,"Naittakaat teitänne yhteen meidän kanssamme: antakaat teidän tyttärenne meille, ja ottakaat jällensä meidän tyttäremme teille.","Naittakaat teitänne yhteen meidän kanssamme: antakaat teidän tyttärenne meille, ja ottakaat jällensä meidän tyttäremme teille."],[34,10,"Ja asukaat meidän kanssamme: maan pitää oleman teillä alttiina, asukaat, myykäät ja ostakaat siinä, ja omistakaat maa.","Ja asukaat meidän kanssamme: maan pitää oleman teillä alttiina, asukaat, myykäät ja ostakaat siinä, ja omistakaat maa."],[34,11,"Ja Sikem sanoi hänen isällensä ja veljillensä: antakaat minun löytää armo teidän edessänne: ja mitä te sanotte minulle, sen minä annan.","Ja Sikem sanoi hänen isällensä ja veljillensä: antakaat minun löytää armo teidän edessänne: ja mitä te sanotte minulle, sen minä annan."],[34,12,"Anokaat minulta rohkiasti huomenlahja ja antimia, ja minä annan, mitä te anotte: antakaat minulle vaivoin se piika emännäksi.","Anokaat minulta rohkiasti huomenlahja ja antimia, ja minä annan, mitä te anotte: antakaat minulle vaivoin se piika emännäksi."],[34,13,"Niin vastasivat Jakobin pojat Sikemille, ja hänen isällensä Hemorille, ja puhuivat petoksella; että hän oli heidän sisarensa Dinan häväissyt.","Niin vastasivat Jakobin pojat Sikemille, ja hänen isällensä Hemorille, ja puhuivat petoksella; että hän oli heidän sisarensa Dinan häväissyt."],[34,14,"Ja sanoivat heille: emme taida sitä tehdä, että me annamme meidän sisaremme ympärileikkaamattomalle miehelle: sillä se olis meille häpiäksi.","Ja sanoivat heille: emme taida sitä tehdä, että me annamme meidän sisaremme ympärileikkaamattomalle miehelle: sillä se olis meille häpiäksi."],[34,15,"Mutta kuitenkin siinä me suostumme teihin; jos te tulette meidän kaltaiseksemme, että kaikki miehenpuoli teidän seassanne ympärileikattaisiin,","Mutta kuitenkin siinä me suostumme teihin; jos te tulette meidän kaltaiseksemme, että kaikki miehenpuoli teidän seassanne ympärileikattaisiin,"],[34,16,"Niin me annamme meidän tyttäremme teille, ja otamme teidän tyttärenne meille, ja asumme teidän kanssanne ja tulemme yhdeksi kansaksi.","Niin me annamme meidän tyttäremme teille, ja otamme teidän tyttärenne meille, ja asumme teidän kanssanne ja tulemme yhdeksi kansaksi."],[34,17,"Mutta jollette kuule meitä, ja anna teitänne ympärileikata; niin me otamme meidän tyttäremme, ja menemme matkaamme.","Mutta jollette kuule meitä, ja anna teitänne ympärileikata; niin me otamme meidän tyttäremme, ja menemme matkaamme."],[34,18,"Ja heidän puheensa kelpasi Hemorille, ja Sikemille Hemorin pojalle.","Ja heidän puheensa kelpasi Hemorille, ja Sikemille Hemorin pojalle."],[34,19,"Ja se nuori mies ei viivytellyt sitä tehdäksensä: sillä hän rakasti suuresti Jakobin tytärtä, ja hän oli kunniassa pidettävä kaikkein ylitse isänsä huoneessa.","Ja se nuori mies ei viivytellyt sitä tehdäksensä: sillä hän rakasti suuresti Jakobin tytärtä, ja hän oli kunniassa pidettävä kaikkein ylitse isänsä huoneessa."],[34,20,"Niin tuli Hemor ja hänen poikansa Sikem kaupunkinsa porttiin, ja puhuivat kaupunkinsa miehille, sanoen:","Niin tuli Hemor ja hänen poikansa Sikem kaupunkinsa porttiin, ja puhuivat kaupunkinsa miehille, sanoen:"],[34,21,"Nämät miehet ovat rauhalliset meidän kanssamme, ja tahtovat asua ja elää tällä maalla, ja katso, maa on kyllä avara heidän edessänsä: ottakaamme heidän tyttärensä meille emännäksi, ja antakaamme meidän tyttäremme heille.","Nämät miehet ovat rauhalliset meidän kanssamme, ja tahtovat asua ja elää tällä maalla, ja katso, maa on kyllä avara heidän edessänsä: ottakaamme heidän tyttärensä meille emännäksi, ja antakaamme meidän tyttäremme heille."],[34,22,"Mutta siihen ne miehet antavat meille suosionsa, asuaksensa meidän kanssamme ja tullaksensa yhdeksi kansaksi: jos meistä ympärileikataan kaikki miehenpuoli, niin kuin he myös ympärileikatut ovat.","Mutta siihen ne miehet antavat meille suosionsa, asuaksensa meidän kanssamme ja tullaksensa yhdeksi kansaksi: jos meistä ympärileikataan kaikki miehenpuoli, niin kuin he myös ympärileikatut ovat."],[34,23,"Heidän karjansa ja hyvyytensä, ja kaikki heidän eläimensä, eikö ne ole meidän omamme? Jos me muutoin olemme heidän tahtonsa jälkeen, niin että he asuvat meidän kanssamme.","Heidän karjansa ja hyvyytensä, ja kaikki heidän eläimensä, eikö ne ole meidän omamme? Jos me muutoin olemme heidän tahtonsa jälkeen, niin että he asuvat meidän kanssamme."],[34,24,"Ja he olivat Hemorille kuuliaiset, ja Sikemille hänen pojallensa, kaikki jotka hänen kaupunkinsa portista kävivät ulos: ja ympärileikkasivat itsensä, jokainen miehenpuoli, jotka hänen kaupunkinsa portista kävivät ulos.","Ja he olivat Hemorille kuuliaiset, ja Sikemille hänen pojallensa, kaikki jotka hänen kaupunkinsa portista kävivät ulos: ja ympärileikkasivat itsensä, jokainen miehenpuoli, jotka hänen kaupunkinsa portista kävivät ulos."],[34,25,"Ja tapahtui kolmantena päivänä, koska he kipiämmällänsä olivat, ottivat kaksi Jakobin poikaa Simeon ja Levi, Dinan veljet, kumpikin miekkansa, ja menivät rohkiasti kaupunkiin: ja tappoivat jokaisen miehenpuolen.","Ja tapahtui kolmantena päivänä, koska he kipiämmällänsä olivat, ottivat kaksi Jakobin poikaa Simeon ja Levi, Dinan veljet, kumpikin miekkansa, ja menivät rohkiasti kaupunkiin: ja tappoivat jokaisen miehenpuolen."],[34,26,"Ja tappoivat myös Hemorin, ja hänen poikansa Sikemin miekan terällä: ja ottivat Dinan Sikemin huoneesta, ja menivät pois.","Ja tappoivat myös Hemorin, ja hänen poikansa Sikemin miekan terällä: ja ottivat Dinan Sikemin huoneesta, ja menivät pois."],[34,27,"Niin tulivat Jakobin pojat tapettuiden päälle, ja ryöstivät kaupungin; että he olivat häväisseet heidän sisarensa.","Niin tulivat Jakobin pojat tapettuiden päälle, ja ryöstivät kaupungin; että he olivat häväisseet heidän sisarensa."],[34,28,"Ja veivät pois heidän lampaansa, karjansa, aasinsa, ja mitä sekä kaupungissa että kedolla oli.","Ja veivät pois heidän lampaansa, karjansa, aasinsa, ja mitä sekä kaupungissa että kedolla oli."],[34,29,"Ja kaikki heidän hyvyytensä, lapsensa ja heidän vaimonsa he ottivat vangiksi, ja ryöstivät; niin myös kaikki, mitä huoneissa oli.","Ja kaikki heidän hyvyytensä, lapsensa ja heidän vaimonsa he ottivat vangiksi, ja ryöstivät; niin myös kaikki, mitä huoneissa oli."],[34,30,"Ja Jakob sanoi Simeonille ja Leville: te olette minulle mielikarvauden tehneet, saattaen minun haisevaiseksi tämän maakunnan asuvaisille, Kanaanealaisille ja Pheresiläisille: ja minä olen vähä joukko, koska he heitänsä kokoovat minun päälleni, niin he tappavat minun, ja minä hukutetaan, ja minun huoneeni.","Ja Jakob sanoi Simeonille ja Leville: te olette minulle mielikarvauden tehneet, saattaen minun haisevaiseksi tämän maakunnan asuvaisille, Kanaanealaisille ja Pheresiläisille: ja minä olen vähä joukko, koska he heitänsä kokoovat minun päälleni, niin he tappavat minun, ja minä hukutetaan, ja minun huoneeni."],[34,31,"Mutta he vastasivat: pitiköstä heidän tekemän meidän sisaremme kanssa, niinkuin jonkun porton kanssa?","Mutta he vastasivat: pitiköstä heidän tekemän meidän sisaremme kanssa, niinkuin jonkun porton kanssa?"],[35,1,"Ja Jumala sanoi Jakobille: nouse ja mene ylös BetEliin, ja asu siellä: ja tee siihen alttari Jumalalle, joka sinulle ilmestyi, koska sinä pakenit veljes Esaun edestä.","Ja Jumala sanoi Jakobille: nouse ja mene ylös BetEliin, ja asu siellä: ja tee siihen alttari Jumalalle, joka sinulle ilmestyi, koska sinä pakenit veljes Esaun edestä."],[35,2,"Niin sanoi Jakob perheellensä, ja kaikille, jotka hänen kanssansa olivat: eroittakaat teistänne vieraat Jumalat, jotka teidän seassanne ovat, ja puhdistakaat teitänne, ja muuttakaat teidän vaatteenne.","Niin sanoi Jakob perheellensä, ja kaikille, jotka hänen kanssansa olivat: eroittakaat teistänne vieraat Jumalat, jotka teidän seassanne ovat, ja puhdistakaat teitänne, ja muuttakaat teidän vaatteenne."],[35,3,"Ja nouskaamme ja menkäämme ylös BetEliin; että minä tekisin siihen alttarin Jumalalle, joka minua kuuli minun hätäaikanani, ja on ollut minun kanssani tiellä, jota minä matkustin.","Ja nouskaamme ja menkäämme ylös BetEliin; että minä tekisin siihen alttarin Jumalalle, joka minua kuuli minun hätäaikanani, ja on ollut minun kanssani tiellä, jota minä matkustin."],[35,4,"Niin he antoivat Jakobille kaikki vieraat Jumalat, jotka heidän käsissänsä olivat, ja korvarenkaansa, jotka heidän korvissansa olivat. Ja Jakob kaivoi ne sen tammen alle, joka oli Sikemin tykönä.","Niin he antoivat Jakobille kaikki vieraat Jumalat, jotka heidän käsissänsä olivat, ja korvarenkaansa, jotka heidän korvissansa olivat. Ja Jakob kaivoi ne sen tammen alle, joka oli Sikemin tykönä."],[35,5,"Ja he matkustivat. Ja Jumalan pelko tuli niille kaupungeille, jotka olivat heidän ympärillänsä, ettei he ajaneet Jakobin poikia takaa.","Ja he matkustivat. Ja Jumalan pelko tuli niille kaupungeille, jotka olivat heidän ympärillänsä, ettei he ajaneet Jakobin poikia takaa."],[35,6,"Niin tuli Jakob Lutsiin Kanaanin maalle, se on BetEl, kaiken sen väen kanssa kuin hänen kanssansa oli.","Niin tuli Jakob Lutsiin Kanaanin maalle, se on BetEl, kaiken sen väen kanssa kuin hänen kanssansa oli."],[35,7,"Ja rakensi siihen alttarin, ja kutsui sen paikan ElBetEl; sillä Jumala ilmestyi siinä hänelle, paetessansa veljensä edestä.","Ja rakensi siihen alttarin, ja kutsui sen paikan ElBetEl; sillä Jumala ilmestyi siinä hänelle, paetessansa veljensä edestä."],[35,8,"Niin kuoli Debora Rebekan imettäjä, ja haudattiin alemmaiselle puolelle BetEliä, tammen alle: ja se kutsuttiin itkutammeksi.","Niin kuoli Debora Rebekan imettäjä, ja haudattiin alemmaiselle puolelle BetEliä, tammen alle: ja se kutsuttiin itkutammeksi."],[35,9,"Ja Jumala ilmestyi taas Jakobille, sitte kuin hän oli tullut Mesopotamiasta ja siunasi häntä.","Ja Jumala ilmestyi taas Jakobille, sitte kuin hän oli tullut Mesopotamiasta ja siunasi häntä."],[35,10,"Ja Jumala sanoi hänelle: sinun nimes on Jakob: mutta ei silleen pidä sinun nimes kutsuttaman Jakob, vaan IsraEl pitää sinun nimes oleman. Ja niin kutsuttiin hänen nimensä IsraEl.","Ja Jumala sanoi hänelle: sinun nimes on Jakob: mutta ei silleen pidä sinun nimes kutsuttaman Jakob, vaan IsraEl pitää sinun nimes oleman. Ja niin kutsuttiin hänen nimensä IsraEl."],[35,11,"Ja Jumala sanoi hänelle: Minä olen kaikkivaltias Jumala, ole hedelmällinen ja enäne, kansa ja kansain joukko pitää sinusta tuleman: ja kuninkaat pitää tuleman sinun kupeistas.","Ja Jumala sanoi hänelle: Minä olen kaikkivaltias Jumala, ole hedelmällinen ja enäne, kansa ja kansain joukko pitää sinusta tuleman: ja kuninkaat pitää tuleman sinun kupeistas."],[35,12,"Ja sen maan, jonka minä olen antanut Abrahamille ja Isaakille, annan minä sinulle: ja sinun siemenelles sinun jälkees, annan minä sen maan.","Ja sen maan, jonka minä olen antanut Abrahamille ja Isaakille, annan minä sinulle: ja sinun siemenelles sinun jälkees, annan minä sen maan."],[35,13,"Ja niin meni Jumala ylös hänen tyköänsä, siinä paikassa, kuin hän hänen kanssansa puhunut oli.","Ja niin meni Jumala ylös hänen tyköänsä, siinä paikassa, kuin hän hänen kanssansa puhunut oli."],[35,14,"Mutta Jakob asetti muistopatsaan siihen paikkaan, jossa hän hänen kanssansa puhunut oli, (nimittäin) kivisen patsaan: ja uhrasi juomauhria, ja kaasi öljyä sen päälle.","Mutta Jakob asetti muistopatsaan siihen paikkaan, jossa hän hänen kanssansa puhunut oli, (nimittäin) kivisen patsaan: ja uhrasi juomauhria, ja kaasi öljyä sen päälle."],[35,15,"Ja Jakob kutsui sen paikan, jossa Jumala hänen kanssansa puhunut oli, BetEl.","Ja Jakob kutsui sen paikan, jossa Jumala hänen kanssansa puhunut oli, BetEl."],[35,16,"Ja he matkustivat BetElistä, ja kuin vielä vähä matkaa oli Ephratiin, niin synnytti Rakel, ja synnyttäminen oli hänelle sangen raskas.","Ja he matkustivat BetElistä, ja kuin vielä vähä matkaa oli Ephratiin, niin synnytti Rakel, ja synnyttäminen oli hänelle sangen raskas."],[35,17,"Ja koska synnyttäminen oli hänelle raskaimmallansa; sanoi lastenämmä hänelle: älä pelkää, sillä tämä poika on sinulla myös oleva.","Ja koska synnyttäminen oli hänelle raskaimmallansa; sanoi lastenämmä hänelle: älä pelkää, sillä tämä poika on sinulla myös oleva."],[35,18,"Mutta hänen henkensä lähteissä, koska hänen piti kuoleman, kutsui hän hänen nimensä BenOni: mutta hänen isänsä kutsui hänen nimensä BenJamin.","Mutta hänen henkensä lähteissä, koska hänen piti kuoleman, kutsui hän hänen nimensä BenOni: mutta hänen isänsä kutsui hänen nimensä BenJamin."],[35,19,"Niin kuoli Rakel: ja hän haudattiin Ephratiin tien viereen, se on BetLehem.","Niin kuoli Rakel: ja hän haudattiin Ephratiin tien viereen, se on BetLehem."],[35,20,"Ja Jakob pani patsaan hänen hautansa päälle: tämä on Rakelin haudan patsas hamaan tähän päivään asti.","Ja Jakob pani patsaan hänen hautansa päälle: tämä on Rakelin haudan patsas hamaan tähän päivään asti."],[35,21,"Ja IsraEl matkusti edespäin, ja teki majansa tuolle puolelle Ederin tornia","Ja IsraEl matkusti edespäin, ja teki majansa tuolle puolelle Ederin tornia"],[35,22,"Ja se tapahtui, koska IsraEl asui siinä maakunnassa, meni Ruben ja makasi Bilhan isänsä jalkavaimon kanssa. Ja IsraEl sai sen kuulla. Ja Jakobilla oli kaksitoistakymmentä poikaa.","Ja se tapahtui, koska IsraEl asui siinä maakunnassa, meni Ruben ja makasi Bilhan isänsä jalkavaimon kanssa. Ja IsraEl sai sen kuulla. Ja Jakobilla oli kaksitoistakymmentä poikaa."],[35,23,"Lean pojat olivat nämät: Jakobin esikoinen Ruben; niin Simeon, ja Levi, ja Juuda, ja Isaskar ja Zebulon.","Lean pojat olivat nämät: Jakobin esikoinen Ruben; niin Simeon, ja Levi, ja Juuda, ja Isaskar ja Zebulon."],[35,24,"Rakelin pojat olivat: Joseph ja BenJamin.","Rakelin pojat olivat: Joseph ja BenJamin."],[35,25,"Bilhan Rakelin piian pojat olivat: Dan ja Naphtali.","Bilhan Rakelin piian pojat olivat: Dan ja Naphtali."],[35,26,"Silpan Lean piian pojat olivat: Gad ja Asser. Nämät ovat Jakobin pojat, jotka hänelle syntyneet olivat Mesopotamiassa.","Silpan Lean piian pojat olivat: Gad ja Asser. Nämät ovat Jakobin pojat, jotka hänelle syntyneet olivat Mesopotamiassa."],[35,27,"Ja Jakob tuli isänsä Isaakin tykö Mamreen, Arban kaupunkiin, joka on Hebron, jossa Abraham ja Isaak olivat muukalaiset olleet.","Ja Jakob tuli isänsä Isaakin tykö Mamreen, Arban kaupunkiin, joka on Hebron, jossa Abraham ja Isaak olivat muukalaiset olleet."],[35,28,"Ja Isaak oli sadan ja kahdeksankymmenen ajastaikainen:","Ja Isaak oli sadan ja kahdeksankymmenen ajastaikainen:"],[35,29,"Ja tuli riutuneeksi, ja kuoli, ja koottiin kansansa tykö, vanhana ja suuttununna elämästä. Ja hänen poikansa Esau ja Jakob hautasivat hänen.","Ja tuli riutuneeksi, ja kuoli, ja koottiin kansansa tykö, vanhana ja suuttununna elämästä. Ja hänen poikansa Esau ja Jakob hautasivat hänen."],[36,1,"Tämä on Esaun sukukunta, joka on Edom.","Tämä on Esaun sukukunta, joka on Edom."],[36,2,"Esau otti emännät Kanaanin tyttäristä: Adan, Hetiläisen Elonin tyttären, ja Oholibaman, Anan Heviläisen Zibeonin pojan tyttären.","Esau otti emännät Kanaanin tyttäristä: Adan, Hetiläisen Elonin tyttären, ja Oholibaman, Anan Heviläisen Zibeonin pojan tyttären."],[36,3,"Ja Basmatin, Ismaelin tyttären, Nebajotin sisaren.","Ja Basmatin, Ismaelin tyttären, Nebajotin sisaren."],[36,4,"Ada synnytti Esaulle Eliphan. Ja Basmat synnytti Reguelin.","Ada synnytti Esaulle Eliphan. Ja Basmat synnytti Reguelin."],[36,5,"Oholibama synnytti Jeun, Jaelamin ja Koran. Nämät ovat Esaun lapset, jotka hänelle syntyivät Kanaanin maalla.","Oholibama synnytti Jeun, Jaelamin ja Koran. Nämät ovat Esaun lapset, jotka hänelle syntyivät Kanaanin maalla."],[36,6,"Ja Esau otti emäntänsä, poikansa ja tyttärensä ja kaikki huoneensa sielut, ja karjansa ja kaikki juhtansa, ja kaiken sen tavaransa, kuin hän oli pannut kokoon Kanaanin maalla: ja meni (toiselle) maalle, veljensä Jakobin tyköä.","Ja Esau otti emäntänsä, poikansa ja tyttärensä ja kaikki huoneensa sielut, ja karjansa ja kaikki juhtansa, ja kaiken sen tavaransa, kuin hän oli pannut kokoon Kanaanin maalla: ja meni (toiselle) maalle, veljensä Jakobin tyköä."],[36,7,"Sillä heidän tavaransa oli niin suuri, ettei he taitaneet asua ynnä: ja se maa, jossa he muukalaiset olivat, ei vetänyt heitä heidän karjansa (paljouden) tähden.","Sillä heidän tavaransa oli niin suuri, ettei he taitaneet asua ynnä: ja se maa, jossa he muukalaiset olivat, ei vetänyt heitä heidän karjansa (paljouden) tähden."],[36,8,"Niin asui Esau Seirin vuorella, ja tämä Esau on Edom.","Niin asui Esau Seirin vuorella, ja tämä Esau on Edom."],[36,9,"Nämät ovat Esaun sukukunnat Edomilaisten isän Seirin vuorella.","Nämät ovat Esaun sukukunnat Edomilaisten isän Seirin vuorella."],[36,10,"Nämät ovat Esaun poikain nimet: Eliphas, Adan Esaun emännän poika: Reguel Basmatin Esaun emännän poika.","Nämät ovat Esaun poikain nimet: Eliphas, Adan Esaun emännän poika: Reguel Basmatin Esaun emännän poika."],[36,11,"Ja Eliphan pojat olivat: Teman, Omar, Zepho, ja Gaetam ja Kenas.","Ja Eliphan pojat olivat: Teman, Omar, Zepho, ja Gaetam ja Kenas."],[36,12,"Mutta Timna oli Eliphan Esaun pojan jalkavaimo, joka synnytti hänelle Amalekin. Ne ovat Adan Esaun emännän lapset.","Mutta Timna oli Eliphan Esaun pojan jalkavaimo, joka synnytti hänelle Amalekin. Ne ovat Adan Esaun emännän lapset."],[36,13,"Mutta Reguelin lapset ovat nämät: Nahat, ja Zera, Samma, Missa. Ne ovat Basmatin Esaun emännän lapset.","Mutta Reguelin lapset ovat nämät: Nahat, ja Zera, Samma, Missa. Ne ovat Basmatin Esaun emännän lapset."],[36,14,"Mutta nämät olivat Oholibaman Esaun emännän pojat, Anan tyttären Zibeonin pojan tyttären lapset; jotka hän synnytti Esaulle: Jeus ja Jaelam ja Kora.","Mutta nämät olivat Oholibaman Esaun emännän pojat, Anan tyttären Zibeonin pojan tyttären lapset; jotka hän synnytti Esaulle: Jeus ja Jaelam ja Kora."],[36,15,"Nämät ovat ruhtinaat Esaun lapsista: Eliphan Esaun esikoisen lapset ovat nämät: se ruhtinas Teman, se ruhtinas Omar, se ruhtinas Zepho, se ruhtinas Kenas.","Nämät ovat ruhtinaat Esaun lapsista: Eliphan Esaun esikoisen lapset ovat nämät: se ruhtinas Teman, se ruhtinas Omar, se ruhtinas Zepho, se ruhtinas Kenas."],[36,16,"Se ruhtinas Kora, se ruhtinas Gaetam, se ruhtinas Amalek. Nämät ovat ruhtinaat Eliphasta Edomin maalla, ja ovat Adan lapset.","Se ruhtinas Kora, se ruhtinas Gaetam, se ruhtinas Amalek. Nämät ovat ruhtinaat Eliphasta Edomin maalla, ja ovat Adan lapset."],[36,17,"Ja nämät ovat Reguelin Esaun pojan lapset: se ruhtinasa Nahat, se ruhtinas Sera, se ruhtinas Samma, se ruhtinas Missa. Nämät ovat ruhtinaat Reguelista Edomilaisten maalla ja ovat Basmatin Esaun emännän lapset.","Ja nämät ovat Reguelin Esaun pojan lapset: se ruhtinasa Nahat, se ruhtinas Sera, se ruhtinas Samma, se ruhtinas Missa. Nämät ovat ruhtinaat Reguelista Edomilaisten maalla ja ovat Basmatin Esaun emännän lapset."],[36,18,"Mutta nämät ovat Oholibaman Esaun emännän lapset: se ruhtinas Jeus, se ruhtinas Jaelam, se ruhtinas Kora. Nämät ovat ruhtinaat Oholibamasta, Anan tyttärestä, Esaun emännästä.","Mutta nämät ovat Oholibaman Esaun emännän lapset: se ruhtinas Jeus, se ruhtinas Jaelam, se ruhtinas Kora. Nämät ovat ruhtinaat Oholibamasta, Anan tyttärestä, Esaun emännästä."],[36,19,"Nämät ovat Esaun lapset, ja heidän ruhtinaansa. Hän on Edom.","Nämät ovat Esaun lapset, ja heidän ruhtinaansa. Hän on Edom."],[36,20,"Mutta nämät ovat Seirin Horilaisen lapset, jotka sillä maalla asuivat: Lotan, Sobal, Sibeon, Ana.","Mutta nämät ovat Seirin Horilaisen lapset, jotka sillä maalla asuivat: Lotan, Sobal, Sibeon, Ana."],[36,21,"Dison, Etser ja Disan. Nämät ovat Horilaisten ruhtinaat, Seirin lapset Edomin maalla.","Dison, Etser ja Disan. Nämät ovat Horilaisten ruhtinaat, Seirin lapset Edomin maalla."],[36,22,"Mutta Lotanin lapset ovat: Hori ja Heman: ja Lotanin sisar Timna.","Mutta Lotanin lapset ovat: Hori ja Heman: ja Lotanin sisar Timna."],[36,23,"Sobalin lapset olivat nämät: Alvan, Manahat, Ebal, Sepho ja Onam.","Sobalin lapset olivat nämät: Alvan, Manahat, Ebal, Sepho ja Onam."],[36,24,"Nämät olivat Sibeonin lapset: Aja ja Ana. Tämä on se Ana, joka korvessa löi Jeminiläiset, kaitessansa isänsä Sibeonin aaseja.","Nämät olivat Sibeonin lapset: Aja ja Ana. Tämä on se Ana, joka korvessa löi Jeminiläiset, kaitessansa isänsä Sibeonin aaseja."],[36,25,"Mutta Ananin lapset olivat: Dison ja Oholibama Ananin tytär.","Mutta Ananin lapset olivat: Dison ja Oholibama Ananin tytär."],[36,26,"Disonin lapset olivat: Hemdan, ja Esban, Jetran ja Karan.","Disonin lapset olivat: Hemdan, ja Esban, Jetran ja Karan."],[36,27,"Etserin lapset olivat: Bilhan, ja Savan ja Akan.","Etserin lapset olivat: Bilhan, ja Savan ja Akan."],[36,28,"Disanin lapset olivat: Uts ja Aran.","Disanin lapset olivat: Uts ja Aran."],[36,29,"Nämät ovat Horilaisten ruhtinaat: se ruhtinas Lotan, se ruhtinas Sobal, se ruhtinas Zibeon, se ruhtinas Ana.","Nämät ovat Horilaisten ruhtinaat: se ruhtinas Lotan, se ruhtinas Sobal, se ruhtinas Zibeon, se ruhtinas Ana."],[36,30,"Se ruhtinas Dison, se ruhtinas Etser, se ruhtinas Disan. Nämät ovat Horilaisten ruhtinaat, heidän ruhtinastensa seassa Seirin maalla.","Se ruhtinas Dison, se ruhtinas Etser, se ruhtinas Disan. Nämät ovat Horilaisten ruhtinaat, heidän ruhtinastensa seassa Seirin maalla."],[36,31,"Mutta kuninkaat kuin Edomin maalla hallitsivat, ennenkuin joku kuningas hallitsi Israelin lapsia, ovat nämät:","Mutta kuninkaat kuin Edomin maalla hallitsivat, ennenkuin joku kuningas hallitsi Israelin lapsia, ovat nämät:"],[36,32,"Niin hallitsi Edomissa Bela Beorin poika: ja hänen kaupunkinsa nimi on Dinhaba.","Niin hallitsi Edomissa Bela Beorin poika: ja hänen kaupunkinsa nimi on Dinhaba."],[36,33,"Ja koska Bela kuoli, tuli Jobab Seran poika Bosrasta kuninkaaksi hänen siaansa.","Ja koska Bela kuoli, tuli Jobab Seran poika Bosrasta kuninkaaksi hänen siaansa."],[36,34,"Kuin Jobab kuoli, tuli Husam Temanilaisten maalta kuninkaaksi hänen siaansa.","Kuin Jobab kuoli, tuli Husam Temanilaisten maalta kuninkaaksi hänen siaansa."],[36,35,"Koska Husam kuoli, tuli Hadad Bedadin poika kuninkaaksi hänen siaansa, joka löi Midianilaiset Moabilaisten kedolla, ja hänen kaupunkinsa nimi oli Avit.","Koska Husam kuoli, tuli Hadad Bedadin poika kuninkaaksi hänen siaansa, joka löi Midianilaiset Moabilaisten kedolla, ja hänen kaupunkinsa nimi oli Avit."],[36,36,"Koska Hadad kuoli, hallitsi Samla Masrekasta hänen siassansa.","Koska Hadad kuoli, hallitsi Samla Masrekasta hänen siassansa."],[36,37,"Koska Samla kuoli, tuli Saul kuninkaaksi hänen siaansa, Rehobotin virran tyköä.","Koska Samla kuoli, tuli Saul kuninkaaksi hänen siaansa, Rehobotin virran tyköä."],[36,38,"Koska Saul kuoli, tuli Baalhanan Akborin poika kuninkaaksi hänen siaansa.","Koska Saul kuoli, tuli Baalhanan Akborin poika kuninkaaksi hänen siaansa."],[36,39,"Koska Baalhanan Akborin poika kuoli, tuli Hadar kuninkaaksi hänen siaansa, ja hänen kaupunkinsa nimi oli Pagu: ja hänen emäntänsä nimi oli Mehetabeel, Matredin tytär, joka Mesahabin tytär oli.","Koska Baalhanan Akborin poika kuoli, tuli Hadar kuninkaaksi hänen siaansa, ja hänen kaupunkinsa nimi oli Pagu: ja hänen emäntänsä nimi oli Mehetabeel, Matredin tytär, joka Mesahabin tytär oli."],[36,40,"Ja nämät ovat Esaun ruhtinasten nimet heidän suvuissansa, paikoissansa ja nimissänsä: se ruhtinas Timna, se ruhtinas Alva, se ruhtinas Jetet.","Ja nämät ovat Esaun ruhtinasten nimet heidän suvuissansa, paikoissansa ja nimissänsä: se ruhtinas Timna, se ruhtinas Alva, se ruhtinas Jetet."],[36,41,"Se ruhtinas Oholibama, se ruhtinas Ela, se ruhtinas Pinon.","Se ruhtinas Oholibama, se ruhtinas Ela, se ruhtinas Pinon."],[36,42,"Se ruhtinas Kenas, se ruhtinas Teman, se ruhtinas Mibtsar.","Se ruhtinas Kenas, se ruhtinas Teman, se ruhtinas Mibtsar."],[36,43,"Se ruhtinas Magdiel, se ruhtinas Iram. Nämät ovat Edomin ruhtinaat, niin kuin he asuneet ovat perintömaallansa, ja Esau on Edomilaisten isä.","Se ruhtinas Magdiel, se ruhtinas Iram. Nämät ovat Edomin ruhtinaat, niin kuin he asuneet ovat perintömaallansa, ja Esau on Edomilaisten isä."],[37,1,"Ja Jakob asui sillä maalla, jossa hänen isänsä muukalainen oli ollut: (nimittäin) Kanaanin maalla.","Ja Jakob asui sillä maalla, jossa hänen isänsä muukalainen oli ollut: (nimittäin) Kanaanin maalla."],[37,2,"Ja nämät ovat Jakobin sukukunnat: Joseph oli seitsemäntoistakymmenen ajastaikainen, koska hän kaitsi karjaa veljeinsä kanssa, ja hän oli nuorella ijällänsä Bilhan ja Silpan, isänsä emäntäin lasten kanssa: ja Joseph ilmoitti isällensä, mikä paha sanoma heistä kuului.","Ja nämät ovat Jakobin sukukunnat: Joseph oli seitsemäntoistakymmenen ajastaikainen, koska hän kaitsi karjaa veljeinsä kanssa, ja hän oli nuorella ijällänsä Bilhan ja Silpan, isänsä emäntäin lasten kanssa: ja Joseph ilmoitti isällensä, mikä paha sanoma heistä kuului."],[37,3,"Mutta Israel rakasti Josephia enemmin kuin kaikkia muita lapsiansa, että hän oli syntynyt hänelle vanhalla ijällänsä: ja teki hänelle kirjavan hameen.","Mutta Israel rakasti Josephia enemmin kuin kaikkia muita lapsiansa, että hän oli syntynyt hänelle vanhalla ijällänsä: ja teki hänelle kirjavan hameen."],[37,4,"Kuin hänen veljensä näkivät, että hänen isänsä rakasti häntä enemmin kuin kaikkia hänen veljiänsä, vihasivat he häntä; ja ei voineet puhutella häntä ystävällisesti.","Kuin hänen veljensä näkivät, että hänen isänsä rakasti häntä enemmin kuin kaikkia hänen veljiänsä, vihasivat he häntä; ja ei voineet puhutella häntä ystävällisesti."],[37,5,"Niin Joseph näki unen, ja ilmoitti sen veljillensä, josta he rupesivat häntä enemmin vihaamaan.","Niin Joseph näki unen, ja ilmoitti sen veljillensä, josta he rupesivat häntä enemmin vihaamaan."],[37,6,"Sillä hän oli sanonut heille, kuulkaas tätä unta, jonka minä näin.","Sillä hän oli sanonut heille, kuulkaas tätä unta, jonka minä näin."],[37,7,"Katso, me olimme sitovanamme jalallisia vainiolla ja minun jalalliseni nousi ja seisoi; ja katso, teidän jalallisenne seisoivat ympärillä, ja kumarsivat minun jalallistani.","Katso, me olimme sitovanamme jalallisia vainiolla ja minun jalalliseni nousi ja seisoi; ja katso, teidän jalallisenne seisoivat ympärillä, ja kumarsivat minun jalallistani."],[37,8,"Niin sanoivat hänen veljensä hänelle: sinäkö tulet meidän kuninkaaksemme, kokonansa hallitsemaan meitä? Ja vihasivat häntä vielä enemmin, hänen unensa ja puheensa tähden.","Niin sanoivat hänen veljensä hänelle: sinäkö tulet meidän kuninkaaksemme, kokonansa hallitsemaan meitä? Ja vihasivat häntä vielä enemmin, hänen unensa ja puheensa tähden."],[37,9,"Ja hän taas näki toisen unen, ja jutteli sen veljillensä, ja sanoi: katso, minä näin vielä unta: ja katso, aurinko, kuu ja yksitoista tähteä kumarsivat minua.","Ja hän taas näki toisen unen, ja jutteli sen veljillensä, ja sanoi: katso, minä näin vielä unta: ja katso, aurinko, kuu ja yksitoista tähteä kumarsivat minua."],[37,10,"Ja kuin hän sitä saneli isällensä ja veljillensä, nuhteli hänen isänsä häntä ja sanoi hänelle: mikä uni se on, kuin sinä olet nähnyt? Pitääkö minun ja sinun äitis ja veljes tuleman ja kumartaman meitämme sinun edessäs maahan?","Ja kuin hän sitä saneli isällensä ja veljillensä, nuhteli hänen isänsä häntä ja sanoi hänelle: mikä uni se on, kuin sinä olet nähnyt? Pitääkö minun ja sinun äitis ja veljes tuleman ja kumartaman meitämme sinun edessäs maahan?"],[37,11,"Ja hänen veljensä kadehtivat häntä; mutta hänen isänsä piti nämät sanat mielessänsä.","Ja hänen veljensä kadehtivat häntä; mutta hänen isänsä piti nämät sanat mielessänsä."],[37,12,"Koska hänen veljensä menivät kaitsemaan karjaa Sikemiin,","Koska hänen veljensä menivät kaitsemaan karjaa Sikemiin,"],[37,13,"Sanoi Israel Josephille: eikö veljes kaitse karjaa Sikemissä? Tule, minä lähetän sinun heidän tykönsä; hän vastasi: tässä minä olen.","Sanoi Israel Josephille: eikö veljes kaitse karjaa Sikemissä? Tule, minä lähetän sinun heidän tykönsä; hän vastasi: tässä minä olen."],[37,14,"Hän sanoi: mene ja katso, ovatko veljes ja karja rauhassa, ja palaja minulle sitä sanomaan. Ja hän lähetti hänen Hebronin laaksosta; ja hän tuli Sikemiin.","Hän sanoi: mene ja katso, ovatko veljes ja karja rauhassa, ja palaja minulle sitä sanomaan. Ja hän lähetti hänen Hebronin laaksosta; ja hän tuli Sikemiin."],[37,15,"Niin yksi mies kohtasi hänen eksyksissä kedolla; ja kysyi häneltä sanoen: mitäs etsit?","Niin yksi mies kohtasi hänen eksyksissä kedolla; ja kysyi häneltä sanoen: mitäs etsit?"],[37,16,"Hän vastasi: minä etsin veljiäni: sanos minulle, kussa he kaitsevat karjaa.","Hän vastasi: minä etsin veljiäni: sanos minulle, kussa he kaitsevat karjaa."],[37,17,"Ja mies sanoi: he läksivät täältä; sillä minä kuulin heidän sanovan: käykäämme Dotaniin. Niin Joseph meni veljeinsä perään, ja löysi heidät Dotanista.","Ja mies sanoi: he läksivät täältä; sillä minä kuulin heidän sanovan: käykäämme Dotaniin. Niin Joseph meni veljeinsä perään, ja löysi heidät Dotanista."],[37,18,"Kuin he kaukana näkivät hänen, ja ennenkuin hän heitä lähestyi, pitivät he neuvoa häntä vastaan, tappaaksensa häntä.","Kuin he kaukana näkivät hänen, ja ennenkuin hän heitä lähestyi, pitivät he neuvoa häntä vastaan, tappaaksensa häntä."],[37,19,"Ja sanoivat toinen toisellensa: katso, tuo unennäkiä tulee.","Ja sanoivat toinen toisellensa: katso, tuo unennäkiä tulee."],[37,20,"Tulkaat siis, tappakaamme häntä, ja heittäkäämme häntä yhteen kuoppaan, ja sanokaamme: paha peto on hänen syönyt: niin saadaan nähdä, mihinkä hänen unensa joutuvat.","Tulkaat siis, tappakaamme häntä, ja heittäkäämme häntä yhteen kuoppaan, ja sanokaamme: paha peto on hänen syönyt: niin saadaan nähdä, mihinkä hänen unensa joutuvat."],[37,21,"Koska Ruben sen kuuli, tahtoi hän häntä pelastaa heidän käsistänsä, ja sanoi: älkäämme hänen henkeänsä ottako.","Koska Ruben sen kuuli, tahtoi hän häntä pelastaa heidän käsistänsä, ja sanoi: älkäämme hänen henkeänsä ottako."],[37,22,"Ja Ruben vielä sanoi heille: älkäät vuodattako verta, vaan heittäkäät häntä tähän kuoppaan, joka on korvessa, ja älkäät satuttako kättänne häneen; sillä hän tahtoi pelastaa häntä heidän käsistänsä, saattaaksensa häntä jälleen isänsä tykö.","Ja Ruben vielä sanoi heille: älkäät vuodattako verta, vaan heittäkäät häntä tähän kuoppaan, joka on korvessa, ja älkäät satuttako kättänne häneen; sillä hän tahtoi pelastaa häntä heidän käsistänsä, saattaaksensa häntä jälleen isänsä tykö."],[37,23,"Ja tapahtui, koska Joseph tuli veljeinsä tykö, riisuivat he häneltä hameen, (nimittäin) sen kirjavan hameen, joka hänen yllänsä oli;","Ja tapahtui, koska Joseph tuli veljeinsä tykö, riisuivat he häneltä hameen, (nimittäin) sen kirjavan hameen, joka hänen yllänsä oli;"],[37,24,"Ja ottivat hänen ja heittivät kuoppaan: ja kuoppa oli tyhjä, ja ei ollut siinä vettä.","Ja ottivat hänen ja heittivät kuoppaan: ja kuoppa oli tyhjä, ja ei ollut siinä vettä."],[37,25,"Sitte istuivat he syömään leipää: ja kuin he nostivat silmänsä ja katselivat, niin katso, Ismaelilaisten joukko tuli Gileadista; ja heidän kameleinsa kannatus oli styraks, mastiks ja ladanum, ja vaelsivat viemään niitä alas Egyptiin.","Sitte istuivat he syömään leipää: ja kuin he nostivat silmänsä ja katselivat, niin katso, Ismaelilaisten joukko tuli Gileadista; ja heidän kameleinsa kannatus oli styraks, mastiks ja ladanum, ja vaelsivat viemään niitä alas Egyptiin."],[37,26,"Niin sanoi Juuda veljillensä: mitä me siitä hyödymme, että me murhaamme meidän veljemme ja salaamme hänen verensä?","Niin sanoi Juuda veljillensä: mitä me siitä hyödymme, että me murhaamme meidän veljemme ja salaamme hänen verensä?"],[37,27,"Tulkaat ja myykäämme häntä Ismaelilaisille, ja älkäämme satuttako käsiämme häneen: sillä hän on meidän veljemme ja lihamme; ja he kuulivat häntä.","Tulkaat ja myykäämme häntä Ismaelilaisille, ja älkäämme satuttako käsiämme häneen: sillä hän on meidän veljemme ja lihamme; ja he kuulivat häntä."],[37,28,"Koska Midianilaisten kauppamiehet siitä menivät ohitse, vetivät he Josephin ja ottivat ylös kuopasta, ja myivät hänen Ismaelilaisille, kahteenkymmeneen hopiapenninkiin; jotka veivät Josephin pois Egyptiin.","Koska Midianilaisten kauppamiehet siitä menivät ohitse, vetivät he Josephin ja ottivat ylös kuopasta, ja myivät hänen Ismaelilaisille, kahteenkymmeneen hopiapenninkiin; jotka veivät Josephin pois Egyptiin."],[37,29,"Koska Ruben palasi kuopalle, niin katso, ei ollut Joseph kuopassa: ja hän repäisi vaatteensa","Koska Ruben palasi kuopalle, niin katso, ei ollut Joseph kuopassa: ja hän repäisi vaatteensa"],[37,30,"Ja palasi veljeinsä tykö, ja sanoi: ei ole nuorukainen siellä, voi minua! kuhunka minä menen?","Ja palasi veljeinsä tykö, ja sanoi: ei ole nuorukainen siellä, voi minua! kuhunka minä menen?"],[37,31,"Niin he ottivat Josephin hameen ja tappoivat kauriin, ja tahrasivat hameen vereen","Niin he ottivat Josephin hameen ja tappoivat kauriin, ja tahrasivat hameen vereen"],[37,32,"Ja lähettivät sen kirjavan hameen, ja antoivat kantaa isällensä, ja sanoivat: tämän me löysimme: tunnustele, jos tämä on poikas hame taikka ei?","Ja lähettivät sen kirjavan hameen, ja antoivat kantaa isällensä, ja sanoivat: tämän me löysimme: tunnustele, jos tämä on poikas hame taikka ei?"],[37,33,"Ja hän tunsi sen, ja sanoi: tämä on minun poikani hame, paha peto on hänen syönyt: raadellen on Joseph revelty.","Ja hän tunsi sen, ja sanoi: tämä on minun poikani hame, paha peto on hänen syönyt: raadellen on Joseph revelty."],[37,34,"Ja Jakob repäisi vaatteensa, ja kääri säkin kupeisiinsa; ja murehti poikaansa monta päivää.","Ja Jakob repäisi vaatteensa, ja kääri säkin kupeisiinsa; ja murehti poikaansa monta päivää."],[37,35,"Ja kaikki hänen poikansa ja tyttärensä nousivat häntä lohduttamaan; vaan ei hän tahtonut antaa itsiänsä lohdutettaa, mutta sanoi: minä menen murehtien alas poikani tykö hautaan. Ja hänen isänsä itki häntä.","Ja kaikki hänen poikansa ja tyttärensä nousivat häntä lohduttamaan; vaan ei hän tahtonut antaa itsiänsä lohdutettaa, mutta sanoi: minä menen murehtien alas poikani tykö hautaan. Ja hänen isänsä itki häntä."],[37,36,"Mutta Midianilaiset myivät hänen Egyptiin Potipharille, Pharaon kamaripalvelialle ja huovinhaltialle.","Mutta Midianilaiset myivät hänen Egyptiin Potipharille, Pharaon kamaripalvelialle ja huovinhaltialle."],[38,1,"Se tapahtui siihen aikaan, että Juuda meni alas veljeinsä tyköä, ja poikkesi yhden miehen tykö Odollamiin, jonka nimi oli Hira.","Se tapahtui siihen aikaan, että Juuda meni alas veljeinsä tyköä, ja poikkesi yhden miehen tykö Odollamiin, jonka nimi oli Hira."],[38,2,"Ja Juuda näki siellä Kanaanin miehen tyttären, hänen nimensä oli Sua: ja otti hänen, ja meni hänen tykönsä.","Ja Juuda näki siellä Kanaanin miehen tyttären, hänen nimensä oli Sua: ja otti hänen, ja meni hänen tykönsä."],[38,3,"Ja hän tuli raskaaksi ja synnytti pojan; ja kutsui hänen nimensä Ger.","Ja hän tuli raskaaksi ja synnytti pojan; ja kutsui hänen nimensä Ger."],[38,4,"Ja hän taas tuli raskaaksi ja synnytti pojan; ja kutsui hänen nimensä Onan.","Ja hän taas tuli raskaaksi ja synnytti pojan; ja kutsui hänen nimensä Onan."],[38,5,"Ja hän synnytti vielä pojan, ja kutsui hänen nimensä Sela. Ja Juuda oli Kesibissä, koska hän sen synnytti.","Ja hän synnytti vielä pojan, ja kutsui hänen nimensä Sela. Ja Juuda oli Kesibissä, koska hän sen synnytti."],[38,6,"Ja Juuda otti esikoisellensa Gerille emännän, jonka nimi oli Tamar.","Ja Juuda otti esikoisellensa Gerille emännän, jonka nimi oli Tamar."],[38,7,"Mutta Ger, Juudan esikoinen, oli paha Herran edessä: ja Herra kuoletti hänen.","Mutta Ger, Juudan esikoinen, oli paha Herran edessä: ja Herra kuoletti hänen."],[38,8,"Niin sanoi Juuda (pojallensa) Onanille: mene veljes emännän tykö, ja ota häntä aviokses, herättääkses veljelles siementä.","Niin sanoi Juuda (pojallensa) Onanille: mene veljes emännän tykö, ja ota häntä aviokses, herättääkses veljelles siementä."],[38,9,"Mutta Onan tiesi, ettei siemen olisi tullut hänen omaksensa: koska hän siis makasi veljensä emännän kanssa, antoi hän sen pudota maahan, ja turmeli sen, ettei hän olisi antanut veljellensä siementä.","Mutta Onan tiesi, ettei siemen olisi tullut hänen omaksensa: koska hän siis makasi veljensä emännän kanssa, antoi hän sen pudota maahan, ja turmeli sen, ettei hän olisi antanut veljellensä siementä."],[38,10,"Ja se paha, kuin hän teki, ei kelvannut Herralle, joka kuoletti myös hänen.","Ja se paha, kuin hän teki, ei kelvannut Herralle, joka kuoletti myös hänen."],[38,11,"Niin sanoi Juuda miniällensä Tamarille: ole leskenä isäs huoneessa siihenasti kuin minun poikani Sela kasvaa. Sillä hän ajatteli: tohtii tapahtua, että hän myös kuolee, niinkuin hänen veljensäkin. Niin Tamar meni pois, ja oli isänsä huoneessa.","Niin sanoi Juuda miniällensä Tamarille: ole leskenä isäs huoneessa siihenasti kuin minun poikani Sela kasvaa. Sillä hän ajatteli: tohtii tapahtua, että hän myös kuolee, niinkuin hänen veljensäkin. Niin Tamar meni pois, ja oli isänsä huoneessa."],[38,12,"Koska monta päivää oli kulunut, kuoli Suan tytär, Juudan emäntä. Ja kuin Juuda oli itsensä lohduttanut, meni hän Timnatiin, lammastensa keritsiäin tykö ystävänsä Hiran kanssa Odollamista.","Koska monta päivää oli kulunut, kuoli Suan tytär, Juudan emäntä. Ja kuin Juuda oli itsensä lohduttanut, meni hän Timnatiin, lammastensa keritsiäin tykö ystävänsä Hiran kanssa Odollamista."],[38,13,"Niin ilmoitettiin Tamarille, sanoen: katso, appes menee ylös Timnatiin keritsemään lampaitansa.","Niin ilmoitettiin Tamarille, sanoen: katso, appes menee ylös Timnatiin keritsemään lampaitansa."],[38,14,"Niin riisui hän yltänsä leskivaatteensa, ja verhoitti itsensä liinalla ja peitti itsensä, ja istui kahden lähteen veräjälle, joka on tiellä Timnatiin; sillä hän näki, että Sela oli kasvanut, ja ei häntä annettu sille emännäksi.","Niin riisui hän yltänsä leskivaatteensa, ja verhoitti itsensä liinalla ja peitti itsensä, ja istui kahden lähteen veräjälle, joka on tiellä Timnatiin; sillä hän näki, että Sela oli kasvanut, ja ei häntä annettu sille emännäksi."],[38,15,"Koska Juuda näki hänen, luuli hän sen portoksi; sillä hän oli peittänyt kasvonsa.","Koska Juuda näki hänen, luuli hän sen portoksi; sillä hän oli peittänyt kasvonsa."],[38,16,"Ja hän poikkesi tien oheen hänen tykönsä, ja sanoi: annas minun maata kanssas; sillä ei hän tietänyt sitä miniäksensä. Hän vastasi: mitäs minun annat, jos sinä makaisit minun kanssani?","Ja hän poikkesi tien oheen hänen tykönsä, ja sanoi: annas minun maata kanssas; sillä ei hän tietänyt sitä miniäksensä. Hän vastasi: mitäs minun annat, jos sinä makaisit minun kanssani?"],[38,17,"Hän sanoi: minä lähetän kauriin laumastani. Hän vastasi: anna siis minulle pantti niin kauvaksi kuin sinä sen lähetät.","Hän sanoi: minä lähetän kauriin laumastani. Hän vastasi: anna siis minulle pantti niin kauvaksi kuin sinä sen lähetät."],[38,18,"Hän sanoi: mitästä minä sinulle pantiksi annan? Hän vastasi: sinettis, sitees, ja sauvas, joka kädessäs on. Niin hän antoi ne hänelle, ja makasi hänen kanssansa, ja hän tuli raskaaksi hänestä.","Hän sanoi: mitästä minä sinulle pantiksi annan? Hän vastasi: sinettis, sitees, ja sauvas, joka kädessäs on. Niin hän antoi ne hänelle, ja makasi hänen kanssansa, ja hän tuli raskaaksi hänestä."],[38,19,"Ja hän nousi ja meni, ja pani pois peitteen, ja puki jälleen leskivaatteet yllensä.","Ja hän nousi ja meni, ja pani pois peitteen, ja puki jälleen leskivaatteet yllensä."],[38,20,"Mutta Juuda lähetti kauriin ystävänsä kanssa Odollamista, että hän vaimolta ottais pantin jälleen: ja ei hän löytänyt häntä.","Mutta Juuda lähetti kauriin ystävänsä kanssa Odollamista, että hän vaimolta ottais pantin jälleen: ja ei hän löytänyt häntä."],[38,21,"Niin hän kyseli sen paikan miehiltä, sanoen: kussa on se portto, kuin istui näillä kahdella lähteellä tien ohessa? He vastasivat: ei yksikään portto ole tässä ollut.","Niin hän kyseli sen paikan miehiltä, sanoen: kussa on se portto, kuin istui näillä kahdella lähteellä tien ohessa? He vastasivat: ei yksikään portto ole tässä ollut."],[38,22,"Mutta hän palasi Juudan tykö, ja sanoi: en minä löytänyt häntä; sanoivat myös sen paikan miehet, ettei tässä ole yhtäkään porttoa ollut.","Mutta hän palasi Juudan tykö, ja sanoi: en minä löytänyt häntä; sanoivat myös sen paikan miehet, ettei tässä ole yhtäkään porttoa ollut."],[38,23,"Juuda sanoi: pitäkään ne, ettemme mitämaks häpiään tulisi; katso, minä lähetin kauriin, ja et sinä löytänyt häntä.","Juuda sanoi: pitäkään ne, ettemme mitämaks häpiään tulisi; katso, minä lähetin kauriin, ja et sinä löytänyt häntä."],[38,24,"Liki kolmen kuukauden jälkeen ilmoitettiin Juudalle: sinun miniäs Tamar on salavuoteessa ollut, ja katso, salavuoteesta on hän myös raskaaksi tullut. Juuda sanoi: viekäät häntä poltettaa.","Liki kolmen kuukauden jälkeen ilmoitettiin Juudalle: sinun miniäs Tamar on salavuoteessa ollut, ja katso, salavuoteesta on hän myös raskaaksi tullut. Juuda sanoi: viekäät häntä poltettaa."],[38,25,"Mutta koska hän tuotiin edes, lähetti hän appensa tykö, sanoen: siitä miehestä, jonka nämät ovat, olen minä raskas. Ja sanoi: tunnetkos, kenenkä on tämä sinetti, side ja sauva.","Mutta koska hän tuotiin edes, lähetti hän appensa tykö, sanoen: siitä miehestä, jonka nämät ovat, olen minä raskas. Ja sanoi: tunnetkos, kenenkä on tämä sinetti, side ja sauva."],[38,26,"Ja Juuda tunsi ne, ja sanoi: hän on minua hurskaampi: etten minä hänelle poikaani Selaa antanut. Kuitenkin ei hän enempää maannut häntä.","Ja Juuda tunsi ne, ja sanoi: hän on minua hurskaampi: etten minä hänelle poikaani Selaa antanut. Kuitenkin ei hän enempää maannut häntä."],[38,27,"Ja tapahtui hänen synnyttämisensä ajalla, ja katso, kaksoiset olivat hänen kohdussansa.","Ja tapahtui hänen synnyttämisensä ajalla, ja katso, kaksoiset olivat hänen kohdussansa."],[38,28,"Ja tapahtui hänen synnyttäissänsä, pisti toinen ulos kätensä, johonka lastenämmä tarttui, ja sitoi siihen punaisen langan, sanoen: tämä tulee ensisti ulos.","Ja tapahtui hänen synnyttäissänsä, pisti toinen ulos kätensä, johonka lastenämmä tarttui, ja sitoi siihen punaisen langan, sanoen: tämä tulee ensisti ulos."],[38,29,"Mutta koska hän kätensä takaperin veti, tuli ulos hänen veljensä, ja hän sanoi: miksis olet reväissyt? Tämä rikkirepäisemys on sinun tähtes: ja hänen nimensä kutsuttiin Perets.","Mutta koska hän kätensä takaperin veti, tuli ulos hänen veljensä, ja hän sanoi: miksis olet reväissyt? Tämä rikkirepäisemys on sinun tähtes: ja hänen nimensä kutsuttiin Perets."],[38,30,"Sitte tuli ulos hänen veljensä, jonka kädessä oli se punainen lanka; ja hänen nimensä kutsuttiin Sera.","Sitte tuli ulos hänen veljensä, jonka kädessä oli se punainen lanka; ja hänen nimensä kutsuttiin Sera."],[39,1,"Ja Josef vietiin alas Egyptiin: ja Potiphar Egyptiläinen Pharaon kamaripalvelia ja huovinhaltia osti hänen Ismaelilaisilta, jotka hänen sinne alas vieneet olivat.","Ja Josef vietiin alas Egyptiin: ja Potiphar Egyptiläinen Pharaon kamaripalvelia ja huovinhaltia osti hänen Ismaelilaisilta, jotka hänen sinne alas vieneet olivat."],[39,2,"Ja Herra oli Josephin kanssa, ja hän oli onnellinen mies, ja oli isäntänsä Egyptiläisen huoneessa.","Ja Herra oli Josephin kanssa, ja hän oli onnellinen mies, ja oli isäntänsä Egyptiläisen huoneessa."],[39,3,"Ja hänen isäntänsä näki, että Herra oli hänen kanssansa; sillä kaikki, mitä hän teki, antoi Herra menestyä hänen kädessänsä.","Ja hänen isäntänsä näki, että Herra oli hänen kanssansa; sillä kaikki, mitä hän teki, antoi Herra menestyä hänen kädessänsä."],[39,4,"Niin että hän löysi armon hänen edessänsä, ja tuli hänen palveliaksensa: ja hän asetti hänen huoneensa ylitse, ja kaikki mitä hänellä oli, antoi hän hänen käteensä.","Niin että hän löysi armon hänen edessänsä, ja tuli hänen palveliaksensa: ja hän asetti hänen huoneensa ylitse, ja kaikki mitä hänellä oli, antoi hän hänen käteensä."],[39,5,"Ja siitä ajasta kuin hän oli hänen pannut huoneensa ja kaiken tavaransa päälle, siunasi Herra sen Egyptiläisen huoneen Josephin tähden, ja Herran siunaus oli kaikissa niissä, jotka hänellä kotona ja kedolla olivat.","Ja siitä ajasta kuin hän oli hänen pannut huoneensa ja kaiken tavaransa päälle, siunasi Herra sen Egyptiläisen huoneen Josephin tähden, ja Herran siunaus oli kaikissa niissä, jotka hänellä kotona ja kedolla olivat."],[39,6,"Sentähden antoi hän kaikki Josephin haltuun, mitä hänellä oli, ja ei tiedustellut mitään häneltä, paitsi sitä ruokaa, jonka hän söi. Ja Joseph oli kauniin luontoinen, ja ihana kasvoilta.","Sentähden antoi hän kaikki Josephin haltuun, mitä hänellä oli, ja ei tiedustellut mitään häneltä, paitsi sitä ruokaa, jonka hän söi. Ja Joseph oli kauniin luontoinen, ja ihana kasvoilta."],[39,7,"Ja tapahtui tämän jälkeen, että hänen isäntänsä emännän silmät paloivat Josephin päälle, ja sanoi: makaa minun kanssani.","Ja tapahtui tämän jälkeen, että hänen isäntänsä emännän silmät paloivat Josephin päälle, ja sanoi: makaa minun kanssani."],[39,8,"Mutta hän kielsi, ja sanoi isäntänsä emännälle: katso, minun isäntäni ei tiedusta minulta, mitä huoneessa on, ja kaikki mitä hänellä on, antoi hän minun käteeni.","Mutta hän kielsi, ja sanoi isäntänsä emännälle: katso, minun isäntäni ei tiedusta minulta, mitä huoneessa on, ja kaikki mitä hänellä on, antoi hän minun käteeni."],[39,9,"Ei pidä hän itseänsä tässä huoneessa suurempana minua, ei myös ole hän kieltänyt minulta mitään, paitsi sinun, siinä kuin sinä olet hänen emäntänsä: kuinka siis minä niin paljon pahaa tekisin ja rikkoisin Jumalaa vastaan?","Ei pidä hän itseänsä tässä huoneessa suurempana minua, ei myös ole hän kieltänyt minulta mitään, paitsi sinun, siinä kuin sinä olet hänen emäntänsä: kuinka siis minä niin paljon pahaa tekisin ja rikkoisin Jumalaa vastaan?"],[39,10,"Mutta hän piti jokapäivä senkaltaiset puheet Josephin kanssa; mutta ei hän totellut maata hänen kanssansa, eli olla hänen kanssansa.","Mutta hän piti jokapäivä senkaltaiset puheet Josephin kanssa; mutta ei hän totellut maata hänen kanssansa, eli olla hänen kanssansa."],[39,11,"Ja tapahtui yhtenä päivänä, että Joseph meni huoneesen askaroitsemaan; ja ei ollut yksikään perheestä läsnä.","Ja tapahtui yhtenä päivänä, että Joseph meni huoneesen askaroitsemaan; ja ei ollut yksikään perheestä läsnä."],[39,12,"Ja hän tarttui hänen hameesensa, sanoen: makaa minun kanssani. Mutta hän jätti hameensa hänen käteensä, ja pakeni, ja meni ulos.","Ja hän tarttui hänen hameesensa, sanoen: makaa minun kanssani. Mutta hän jätti hameensa hänen käteensä, ja pakeni, ja meni ulos."],[39,13,"Koska hän näki, että hän jätti hameensa hänen käteensä, ja pakeni ulos:","Koska hän näki, että hän jätti hameensa hänen käteensä, ja pakeni ulos:"],[39,14,"Huusi hän perhettänsä, ja sanoi heille: katsokaat, hän on tuonut meille yhden Hebrealaisen miehen, saattamaan meitä häpiään: hän tuli minun tyköni makaamaan minun kanssani; mutta minä huusin korkialla äänellä.","Huusi hän perhettänsä, ja sanoi heille: katsokaat, hän on tuonut meille yhden Hebrealaisen miehen, saattamaan meitä häpiään: hän tuli minun tyköni makaamaan minun kanssani; mutta minä huusin korkialla äänellä."],[39,15,"Ja koska hän kuuli, että minä riahdin ja huusin, jätti hän minulle hameensa, pakeni ja meni ulos.","Ja koska hän kuuli, että minä riahdin ja huusin, jätti hän minulle hameensa, pakeni ja meni ulos."],[39,16,"Niin hän piti hänen hameensa tykönänsä, siihenasti kuin hänen isäntänsä kotia tuli,","Niin hän piti hänen hameensa tykönänsä, siihenasti kuin hänen isäntänsä kotia tuli,"],[39,17,"Ja puhui hänelle ne sanat, sanoen: Hebrealainen palvelia, jonkas olet meille tuonut, tuli minun tyköni, saattamaan minua häpiään.","Ja puhui hänelle ne sanat, sanoen: Hebrealainen palvelia, jonkas olet meille tuonut, tuli minun tyköni, saattamaan minua häpiään."],[39,18,"Mutta koska minä riahdin ja huusin, jätti hän minulle hameensa ja pakeni ulos.","Mutta koska minä riahdin ja huusin, jätti hän minulle hameensa ja pakeni ulos."],[39,19,"Koska hänen isäntänsä kuuli emäntänsä sanat, kuin hän puhui hänelle, sanoen: niin on sinun palvelias tehnyt minulle, vihastui hän sangen kovin.","Koska hänen isäntänsä kuuli emäntänsä sanat, kuin hän puhui hänelle, sanoen: niin on sinun palvelias tehnyt minulle, vihastui hän sangen kovin."],[39,20,"Ja hänen isäntänsä otti Josephin, ja pani vankihuoneesen, jossa kuninkaan vangit olivat: ja niin hän oli siellä vankihuoneessa.","Ja hänen isäntänsä otti Josephin, ja pani vankihuoneesen, jossa kuninkaan vangit olivat: ja niin hän oli siellä vankihuoneessa."],[39,21,"Mutta Herra oli Josephin kanssa, ja käänsi laupiutensa hänen tykönsä; ja antoi hänen löytää armon vankihuoneen haltian edessä.","Mutta Herra oli Josephin kanssa, ja käänsi laupiutensa hänen tykönsä; ja antoi hänen löytää armon vankihuoneen haltian edessä."],[39,22,"Niin että hän antoi kaikki vangit vankihuoneessa Josephin käden alle, että kaikki mitä siellä tehtiin, se tehtiin hänen kauttansa.","Niin että hän antoi kaikki vangit vankihuoneessa Josephin käden alle, että kaikki mitä siellä tehtiin, se tehtiin hänen kauttansa."],[39,23,"Ja vankihuoneen haltia ei pitänyt mistään murhetta niistä, jotka hänen kädessänsä olivat; sillä Herra oli Josephin kanssa, ja mitä hän teki, antoi Herra menestyä.","Ja vankihuoneen haltia ei pitänyt mistään murhetta niistä, jotka hänen kädessänsä olivat; sillä Herra oli Josephin kanssa, ja mitä hän teki, antoi Herra menestyä."],[40,1,"Ja sitte tapahtui, että Egyptin kuninkaan ylimmäinen juomanlaskia ja leipoja rikkoivat herraansa Egyptin kuningasta vastaan:","Ja sitte tapahtui, että Egyptin kuninkaan ylimmäinen juomanlaskia ja leipoja rikkoivat herraansa Egyptin kuningasta vastaan:"],[40,2,"Niin Pharao vihastui molempain palveliainsa, ylimmäisen juomanlaskian ja ylimmäisen leipojan päälle.","Niin Pharao vihastui molempain palveliainsa, ylimmäisen juomanlaskian ja ylimmäisen leipojan päälle."],[40,3,"Ja heitti heidät vankiuteen huovinhaltian huoneesen, vankihuoneesen siihen paikkaan, jossa Joseph oli vankina.","Ja heitti heidät vankiuteen huovinhaltian huoneesen, vankihuoneesen siihen paikkaan, jossa Joseph oli vankina."],[40,4,"Ja huovinhaltia pani Josephin heidän kanssansa palvelemaan heitä. Ja he olivat vankiudessa kappaleen aikaa.","Ja huovinhaltia pani Josephin heidän kanssansa palvelemaan heitä. Ja he olivat vankiudessa kappaleen aikaa."],[40,5,"Ja molemmat näkivät unta, kumpikin unensa yhtenä yönä, kukin unensa selityksen jälkeen, Egyptin kuninkaan juomanlaskia ja leipoja, jotka olivat sidottuna vankihuoneessa.","Ja molemmat näkivät unta, kumpikin unensa yhtenä yönä, kukin unensa selityksen jälkeen, Egyptin kuninkaan juomanlaskia ja leipoja, jotka olivat sidottuna vankihuoneessa."],[40,6,"Koska Joseph tuli aamulla heidän tykönsä, ja näki heidän murheelliseksi.","Koska Joseph tuli aamulla heidän tykönsä, ja näki heidän murheelliseksi."],[40,7,"Kysyi hän niiltä Pharaon palvelioilta, jotka hänen kanssansa herransa vankihuoneessa olivat, ja sanoi: miksi te olette tänäpänä surulliset?","Kysyi hän niiltä Pharaon palvelioilta, jotka hänen kanssansa herransa vankihuoneessa olivat, ja sanoi: miksi te olette tänäpänä surulliset?"],[40,8,"He vastasivat häntä: me olemme nähneet unta, ja ei ole, joka sen selittää. Niin sanoi Joseph heille: Jumalan on selitys, kuitenkin jutelkaat se minulle.","He vastasivat häntä: me olemme nähneet unta, ja ei ole, joka sen selittää. Niin sanoi Joseph heille: Jumalan on selitys, kuitenkin jutelkaat se minulle."],[40,9,"Niin ylimmäinen juomanlaskia jutteli unensa Josephille, ja sanoi hänelle: minä näin unta ja katso, viinapuu oli minun edessäni.","Niin ylimmäinen juomanlaskia jutteli unensa Josephille, ja sanoi hänelle: minä näin unta ja katso, viinapuu oli minun edessäni."],[40,10,"Ja sillä viinapuulla oli kolme haaraa ja se oli niinkuin viheriöitsemällänsä, sen kukoistus kävi ylös, ja sen rypäleet tuleentuivat viinamarjoiksi.","Ja sillä viinapuulla oli kolme haaraa ja se oli niinkuin viheriöitsemällänsä, sen kukoistus kävi ylös, ja sen rypäleet tuleentuivat viinamarjoiksi."],[40,11,"Ja Pharaon juoma-astia oli minun kädessäni: niin minä otin viinamarjat, ja pusersin ne Pharaon juomaastiaan, ja annoin sen juoma-astian Pharaon käteen.","Ja Pharaon juoma-astia oli minun kädessäni: niin minä otin viinamarjat, ja pusersin ne Pharaon juomaastiaan, ja annoin sen juoma-astian Pharaon käteen."],[40,12,"Ja Joseph sanoi hänelle: tämä on sen selitys: Kolme haaraa ovat kolme päivää.","Ja Joseph sanoi hänelle: tämä on sen selitys: Kolme haaraa ovat kolme päivää."],[40,13,"Kolmen päivän sisällä korottaa Pharao sinun pääs, ja asettaa sinun jällensä entiseen virkaas: ja sinä annat Pharaon käteen juoma-astian niinkuin ennenkin, koska olit hänen juomansa laskia.","Kolmen päivän sisällä korottaa Pharao sinun pääs, ja asettaa sinun jällensä entiseen virkaas: ja sinä annat Pharaon käteen juoma-astian niinkuin ennenkin, koska olit hänen juomansa laskia."],[40,14,"Mutta muista minua tykönäs, koska sinun hyvin käy, ja tee sitte laupius minun kanssani, ettäs ilmoittaisit minun Pharaolle, ja antaisit minun ottaa täältä ulos.","Mutta muista minua tykönäs, koska sinun hyvin käy, ja tee sitte laupius minun kanssani, ettäs ilmoittaisit minun Pharaolle, ja antaisit minun ottaa täältä ulos."],[40,15,"Sillä minä olen salaisesti varastettu Hebrealaisten maalta; enkä ole tässä mitään tehnyt, että he minun tähän vankiuteen panivat.","Sillä minä olen salaisesti varastettu Hebrealaisten maalta; enkä ole tässä mitään tehnyt, että he minun tähän vankiuteen panivat."],[40,16,"Koska ylimmäinen leipoja näki, että selitys oli hyvä; sanoi hän Josephille: minä myös uneksuin, ja katso, kolme palmikoittua koria oli minun pääni päällä.","Koska ylimmäinen leipoja näki, että selitys oli hyvä; sanoi hän Josephille: minä myös uneksuin, ja katso, kolme palmikoittua koria oli minun pääni päällä."],[40,17,"Ja ylimmäisessä korissa oli kaikkinaisia leivotuita ruokia Pharaon tarpeeksi: ja linnut söivät niitä korista minun pääni päältä.","Ja ylimmäisessä korissa oli kaikkinaisia leivotuita ruokia Pharaon tarpeeksi: ja linnut söivät niitä korista minun pääni päältä."],[40,18,"Joseph vastasi, ja sanoi: tämä on sen selitys: kolme koria ovat kolme päivää.","Joseph vastasi, ja sanoi: tämä on sen selitys: kolme koria ovat kolme päivää."],[40,19,"Ja kolmen päivän sisällä ylentää Pharao sinun pääs, ja ripustaa sinun hirsipuuhun: ja linnut syövät sinun lihas sinun päältäs.","Ja kolmen päivän sisällä ylentää Pharao sinun pääs, ja ripustaa sinun hirsipuuhun: ja linnut syövät sinun lihas sinun päältäs."],[40,20,"Ja tapahtui kolmantena päivänä, koska Pharao piti syntymäpäiväänsä, teki hän pidon kaikille palvelioillensa, ja ylensi ylimmäisen juomanlaskian pään, ja ylimmäisen leipojan pään palvelioittensa seassa.","Ja tapahtui kolmantena päivänä, koska Pharao piti syntymäpäiväänsä, teki hän pidon kaikille palvelioillensa, ja ylensi ylimmäisen juomanlaskian pään, ja ylimmäisen leipojan pään palvelioittensa seassa."],[40,21,"Ja asetti ylimmäisen juomanlaskian jälleen (entiseen) virkaansa, antamaan Pharaon käteen juomaastian.","Ja asetti ylimmäisen juomanlaskian jälleen (entiseen) virkaansa, antamaan Pharaon käteen juomaastian."],[40,22,"Mutta ylimmäisen leipojan antoi hän hirttää; niinkuin Joseph oli heille selittänyt.","Mutta ylimmäisen leipojan antoi hän hirttää; niinkuin Joseph oli heille selittänyt."],[40,23,"Mutta ylimmäinen juomanlaskia ei muistanut Josephia, vaan unhotti hänen.","Mutta ylimmäinen juomanlaskia ei muistanut Josephia, vaan unhotti hänen."],[41,1,"Ja tapahtui kahden ajastajan perästä, että Pharao näki unen, niinkuin hän olis seisonut virran tykönä.","Ja tapahtui kahden ajastajan perästä, että Pharao näki unen, niinkuin hän olis seisonut virran tykönä."],[41,2,"Ja katso, virrasta astui ylös seitsemän kaunista ja lihavaa lehmää, jotka kävivät laitumella ruohostossa.","Ja katso, virrasta astui ylös seitsemän kaunista ja lihavaa lehmää, jotka kävivät laitumella ruohostossa."],[41,3,"Sitte näki hän toiset seitsemän lehmää tulevan virrasta ylös, rumaa ja laihaa; ja seisoivat niiden (toisten) lehmäin tykönä virran reunalla.","Sitte näki hän toiset seitsemän lehmää tulevan virrasta ylös, rumaa ja laihaa; ja seisoivat niiden (toisten) lehmäin tykönä virran reunalla."],[41,4,"Ja ne rumat ja laihat lehmät söivät ne seitsemän lihavaa ja kaunista lehmää. Niin Pharao heräsi.","Ja ne rumat ja laihat lehmät söivät ne seitsemän lihavaa ja kaunista lehmää. Niin Pharao heräsi."],[41,5,"Ja hän nukkui jällensä, ja näki toisen kerran unta: ja katso, seitsemän täysinäistä ja paksua tähkäpäätä kasvoivat yhdessä oljessa.","Ja hän nukkui jällensä, ja näki toisen kerran unta: ja katso, seitsemän täysinäistä ja paksua tähkäpäätä kasvoivat yhdessä oljessa."],[41,6,"Ja katso, seitsemän pientä ja itätuulelta surkastunutta tähkäpäätä kasvoivat niiden jälkeen.","Ja katso, seitsemän pientä ja itätuulelta surkastunutta tähkäpäätä kasvoivat niiden jälkeen."],[41,7,"Ja ne seitsemän laihaa tähkää nielivät ne seitsemän paksua ja täysinäistä tähkäpäätä. Niin Pharao heräsi ja näki, että se oli uni.","Ja ne seitsemän laihaa tähkää nielivät ne seitsemän paksua ja täysinäistä tähkäpäätä. Niin Pharao heräsi ja näki, että se oli uni."],[41,8,"Ja aamulla oli hänen henkensä murheellinen, lähetti ja antoi kutsua kokoon kaikki Egyptin noidat ja tietäjät, ja Pharao jutteli heille unensa. Mutta ei ollut, joka sen taisi selittää Pharaon edessä.","Ja aamulla oli hänen henkensä murheellinen, lähetti ja antoi kutsua kokoon kaikki Egyptin noidat ja tietäjät, ja Pharao jutteli heille unensa. Mutta ei ollut, joka sen taisi selittää Pharaon edessä."],[41,9,"Niin puhui ylimmäinen juomanlaskia Pharaolle, sanoen: minä muistan tänäpänä minun rikokseni.","Niin puhui ylimmäinen juomanlaskia Pharaolle, sanoen: minä muistan tänäpänä minun rikokseni."],[41,10,"Koska Pharao vihastui palveliainsa päälle, ja pani minun ja ylimmäisen leipojan vankiuteen, huovinhaltian huoneesen;","Koska Pharao vihastui palveliainsa päälle, ja pani minun ja ylimmäisen leipojan vankiuteen, huovinhaltian huoneesen;"],[41,11,"Niin me molemmat näimme yhtenä yönä unta, kumpikin unensa selityksen jälkeen me uneksuimme.","Niin me molemmat näimme yhtenä yönä unta, kumpikin unensa selityksen jälkeen me uneksuimme."],[41,12,"Ja siellä oli meidän kanssamme Hebrealainen nuorukainen, huovinhaltian palvelia, ja me juttelimme hänelle, ja hän selitti meille meidän unemme: kummallekin unensa jälkeen selitti hän sen.","Ja siellä oli meidän kanssamme Hebrealainen nuorukainen, huovinhaltian palvelia, ja me juttelimme hänelle, ja hän selitti meille meidän unemme: kummallekin unensa jälkeen selitti hän sen."],[41,13,"Ja niinkuin hän meille selitti, niin se tapahtui: sillä minä asetettiin minun virkaani ja hän hirtettiin.","Ja niinkuin hän meille selitti, niin se tapahtui: sillä minä asetettiin minun virkaani ja hän hirtettiin."],[41,14,"Niin lähetti Pharao, ja antoi kutsua Josephin, ja he hopusti ottivat hänen vankiudesta ulos. Ja hän antoi itsensä keritä, ja muutti vaattensa ja tuli Pharaon tykö.","Niin lähetti Pharao, ja antoi kutsua Josephin, ja he hopusti ottivat hänen vankiudesta ulos. Ja hän antoi itsensä keritä, ja muutti vaattensa ja tuli Pharaon tykö."],[41,15,"Niin sanoi Pharao Josephille: minä olen unta nähnyt, ja ei ole sen selittäjää; mutta minä olen kuullut sinusta sanottavan: koskas unen kuulet, niin sinä taidat sen selittää.","Niin sanoi Pharao Josephille: minä olen unta nähnyt, ja ei ole sen selittäjää; mutta minä olen kuullut sinusta sanottavan: koskas unen kuulet, niin sinä taidat sen selittää."],[41,16,"Joseph vastasi Pharaota, sanoen: ei se ole minulla; mutta Jumala aavistaa kuitenkin Pharaolle hyvää.","Joseph vastasi Pharaota, sanoen: ei se ole minulla; mutta Jumala aavistaa kuitenkin Pharaolle hyvää."],[41,17,"Niin puhui Pharao Josephille: unessa olin minä seisovana virran reunalla.","Niin puhui Pharao Josephille: unessa olin minä seisovana virran reunalla."],[41,18,"Ja katso, virrasta tuli ylös seitsemän lihavaa ja kaunista lehmää, jotka kävivät laitumella ruohostossa.","Ja katso, virrasta tuli ylös seitsemän lihavaa ja kaunista lehmää, jotka kävivät laitumella ruohostossa."],[41,19,"Ja katso, heidän jälkeensä tulivat ylös toiset seitsemän pientä ja juuri rumaa ja laihaa lehmää: en ole minä koko Egyptin maalla nähnyt niin rumia.","Ja katso, heidän jälkeensä tulivat ylös toiset seitsemän pientä ja juuri rumaa ja laihaa lehmää: en ole minä koko Egyptin maalla nähnyt niin rumia."],[41,20,"Ja ne laihat ja rumat lehmät söivät ne ensimäiset seitsemän lihavaa lehmää.","Ja ne laihat ja rumat lehmät söivät ne ensimäiset seitsemän lihavaa lehmää."],[41,21,"Ja koska he olivat syöneet, ei heidän päällänsä mitään tuntunut, että he olivat syöneet; vaan olivat niin rumat nähdä kuin ennenkin. Niin minä heräsin.","Ja koska he olivat syöneet, ei heidän päällänsä mitään tuntunut, että he olivat syöneet; vaan olivat niin rumat nähdä kuin ennenkin. Niin minä heräsin."],[41,22,"Ja taas näin minä unessani seitsemän tähkäpäätä kasvaneen yhdessä oljessa, täysinäistä ja kaunista.","Ja taas näin minä unessani seitsemän tähkäpäätä kasvaneen yhdessä oljessa, täysinäistä ja kaunista."],[41,23,"Sitte kävi ylös seitsemän kuivaa, pientä ja itätuulelta surkastunutta tähkäpäätä.","Sitte kävi ylös seitsemän kuivaa, pientä ja itätuulelta surkastunutta tähkäpäätä."],[41,24,"Ja ne pienet tähkäpäät nielivät ne seitsemän kaunista tähkäpäätä. Ja minä olen sen sanonut tietäjille, mutta ei ole joka sen minulle ilmoittais.","Ja ne pienet tähkäpäät nielivät ne seitsemän kaunista tähkäpäätä. Ja minä olen sen sanonut tietäjille, mutta ei ole joka sen minulle ilmoittais."],[41,25,"Joseph sanoi Pharaolle: Pharaon uni on yhtäläinen: Jumala ilmoittaa Pharaolle, mitä hän tekevä on.","Joseph sanoi Pharaolle: Pharaon uni on yhtäläinen: Jumala ilmoittaa Pharaolle, mitä hän tekevä on."],[41,26,"Ne seitsemän kaunista lehmää ovat seitsemän vuotta, ja ne seitsemän täysinäistä tähkäpäätä ovat myös seitsemän vuotta: se on yhtäläinen uni.","Ne seitsemän kaunista lehmää ovat seitsemän vuotta, ja ne seitsemän täysinäistä tähkäpäätä ovat myös seitsemän vuotta: se on yhtäläinen uni."],[41,27,"Mutta ne seitsemän laihaa ja rumaa lehmää, jotka astuivat ylös heidän jälkeensä, ovat seitsemän vuotta, ja ne seitsemän laihaa ja itätuulelta surkastunutta tähkäpäätä ovat seitsemän nälkävuotta.","Mutta ne seitsemän laihaa ja rumaa lehmää, jotka astuivat ylös heidän jälkeensä, ovat seitsemän vuotta, ja ne seitsemän laihaa ja itätuulelta surkastunutta tähkäpäätä ovat seitsemän nälkävuotta."],[41,28,"Se on nyt se, kuin minä Pharaolle sanonut olen: että Jumala ilmoitti Pharaolle, mitä hän tekevä on.","Se on nyt se, kuin minä Pharaolle sanonut olen: että Jumala ilmoitti Pharaolle, mitä hän tekevä on."],[41,29,"Katso, seitsemän viljaista vuotta tulevat koko Egyptin maalle.","Katso, seitsemän viljaista vuotta tulevat koko Egyptin maalle."],[41,30,"Ja niiden jälkeen tulevat seitsemän nälkävuotta, niin että kaikki senkaltainen viljan kyllyys unhotetaan Egyptin maalla, ja se kallis aika hävittää maakunnan.","Ja niiden jälkeen tulevat seitsemän nälkävuotta, niin että kaikki senkaltainen viljan kyllyys unhotetaan Egyptin maalla, ja se kallis aika hävittää maakunnan."],[41,31,"Ja ei enämpi tiedetä siitä viljan kyllyydestä maakunnassa, sen kalliin ajan tähden, joka tulee; sillä se tulee sangen raskaaksi.","Ja ei enämpi tiedetä siitä viljan kyllyydestä maakunnassa, sen kalliin ajan tähden, joka tulee; sillä se tulee sangen raskaaksi."],[41,32,"Mutta että uni on kerrottu Pharaolle, se (aavistaa) että asia on Jumalalta päätetty, ja Jumala on pian sen tekevä.","Mutta että uni on kerrottu Pharaolle, se (aavistaa) että asia on Jumalalta päätetty, ja Jumala on pian sen tekevä."],[41,33,"Nyt siis Pharao etsikään toimellista ja taitavaa miestä, asettaaksensa Egyptin maan päälle.","Nyt siis Pharao etsikään toimellista ja taitavaa miestä, asettaaksensa Egyptin maan päälle."],[41,34,"Toimittakaan Pharao ja asettakaan ottomiehiä maakuntaan, ja ottakaan viidennen osan Egyptin maalta niinä seitsemänä viljavuonna.","Toimittakaan Pharao ja asettakaan ottomiehiä maakuntaan, ja ottakaan viidennen osan Egyptin maalta niinä seitsemänä viljavuonna."],[41,35,"Ja he kootkaan kaikkinaista ravintoa niinä hyvinä vuosina, jotka tulevat, ja antakaan tulla jyviä Pharaon haltuun, varaksi kaupungeissa, ja tallella pitäkään.","Ja he kootkaan kaikkinaista ravintoa niinä hyvinä vuosina, jotka tulevat, ja antakaan tulla jyviä Pharaon haltuun, varaksi kaupungeissa, ja tallella pitäkään."],[41,36,"Että ruokaa olis tähteelle pantu maakunnalle, niinä seitsemänä nälkävuonna, jotka tulevat Egyptin maalle, ettei maa hävitettäisi näljän tähden.","Että ruokaa olis tähteelle pantu maakunnalle, niinä seitsemänä nälkävuonna, jotka tulevat Egyptin maalle, ettei maa hävitettäisi näljän tähden."],[41,37,"Ja se puhe kelpasi Pharaolle, ja kaikille hänen palvelioillensa.","Ja se puhe kelpasi Pharaolle, ja kaikille hänen palvelioillensa."],[41,38,"Ja Pharao sanoi palvelioillensa: taidammeko me löytää tainkaltaisen miehen, jossa Jumalan henki on?","Ja Pharao sanoi palvelioillensa: taidammeko me löytää tainkaltaisen miehen, jossa Jumalan henki on?"],[41,39,"Ja Pharao sanoi Josephille: että Jumala on tämän kaiken sinulle ilmoittanut, niin ei ole yhtään niin taitavaa ja ymmärtäväistä kuin sinä olet.","Ja Pharao sanoi Josephille: että Jumala on tämän kaiken sinulle ilmoittanut, niin ei ole yhtään niin taitavaa ja ymmärtäväistä kuin sinä olet."],[41,40,"Ole sinä minun huoneeni päällä, ja sinun sanalles pitää kaiken minun kansani kuuliaisen oleman; ainoastansa kuninkaallisessa istuimessa tahdon minä olla korkiampi sinua.","Ole sinä minun huoneeni päällä, ja sinun sanalles pitää kaiken minun kansani kuuliaisen oleman; ainoastansa kuninkaallisessa istuimessa tahdon minä olla korkiampi sinua."],[41,41,"Ja Pharao sanoi Josephille: katso, minä olen asettanut sinun koko Egyptin päälle.","Ja Pharao sanoi Josephille: katso, minä olen asettanut sinun koko Egyptin päälle."],[41,42,"Ja Pharao otti sormuksen kädestänsä, ja pani sen Josephin käteen: ja puetti hänen kalleisiin liinavaatteisiin, ja ripusti kultakäädyt hänen kaulaansa.","Ja Pharao otti sormuksen kädestänsä, ja pani sen Josephin käteen: ja puetti hänen kalleisiin liinavaatteisiin, ja ripusti kultakäädyt hänen kaulaansa."],[41,43,"Ja antoi hänen ajaa toisessa vaunussansa, ja antoi huutaa hänen edellänsä: Abrek: ja asetti hänen koko Egyptin maan päälle.","Ja antoi hänen ajaa toisessa vaunussansa, ja antoi huutaa hänen edellänsä: Abrek: ja asetti hänen koko Egyptin maan päälle."],[41,44,"Ja Pharao sanoi Josephille: minä olen Pharao; ja ilman sinun tahdotas ei pidä yhdenkään ylentämän kättänsä taikka jalkaansa koko Egyptin maalla.","Ja Pharao sanoi Josephille: minä olen Pharao; ja ilman sinun tahdotas ei pidä yhdenkään ylentämän kättänsä taikka jalkaansa koko Egyptin maalla."],[41,45,"Ja Pharao kutsui Josephin nimen Salaisuutten selittäjäksi: ja antoi hänelle Asnatin, Potipheran Onin papin tyttären, emännäksi. Niin Joseph meni ympärinsä Egyptin maan.","Ja Pharao kutsui Josephin nimen Salaisuutten selittäjäksi: ja antoi hänelle Asnatin, Potipheran Onin papin tyttären, emännäksi. Niin Joseph meni ympärinsä Egyptin maan."],[41,46,"Ja Joseph oli kolmenkymmenen ajastaikainen, koska hän seisoi Pharaon, Egyptin kuninkaan edessä. Ja Joseph läksi Pharaon tyköä, ja vaelsi ympärinsä kaiken Egyptin maan.","Ja Joseph oli kolmenkymmenen ajastaikainen, koska hän seisoi Pharaon, Egyptin kuninkaan edessä. Ja Joseph läksi Pharaon tyköä, ja vaelsi ympärinsä kaiken Egyptin maan."],[41,47,"Ja maa kasvoi pivottaisin niinä seitsemänä viljavuosina.","Ja maa kasvoi pivottaisin niinä seitsemänä viljavuosina."],[41,48,"Ja hän kokosi niinä seitsemänä vuonna kaikkinaisen elatuksen, joka oli Egyptin maalla, ja pani sen tähteelle kaupunkeihin: mitä elatusta maa kasvoi ympärinsä kunkin kaupungin, sen hän siihen tähteelle pani.","Ja hän kokosi niinä seitsemänä vuonna kaikkinaisen elatuksen, joka oli Egyptin maalla, ja pani sen tähteelle kaupunkeihin: mitä elatusta maa kasvoi ympärinsä kunkin kaupungin, sen hän siihen tähteelle pani."],[41,49,"Ja Joseph kokosi sangen paljon jyviä, niinkuin santaa meressä, siihenasti että hän lakkasi lukemasta, sillä ne olivat epälukuiset.","Ja Joseph kokosi sangen paljon jyviä, niinkuin santaa meressä, siihenasti että hän lakkasi lukemasta, sillä ne olivat epälukuiset."],[41,50,"Ja Josephille syntyi kaksi poikaa, ennenkuin kallis aika tuli, jotka hänelle synnytti Asnat, Potipheran Onin papin tytär.","Ja Josephille syntyi kaksi poikaa, ennenkuin kallis aika tuli, jotka hänelle synnytti Asnat, Potipheran Onin papin tytär."],[41,51,"Ja kutsui esikoisensa nimen Manasse; sillä (sanoi hän) Jumala on antanut minun unhottaa kaiken minun vaivani, ja kaiken minun isäni huoneen.","Ja kutsui esikoisensa nimen Manasse; sillä (sanoi hän) Jumala on antanut minun unhottaa kaiken minun vaivani, ja kaiken minun isäni huoneen."],[41,52,"Mutta toisen nimen hän kutsui Ephraim; sillä (sanoi hän) Jumala on tehnyt minun hedelmälliseksi minun raadollisuuteni maassa.","Mutta toisen nimen hän kutsui Ephraim; sillä (sanoi hän) Jumala on tehnyt minun hedelmälliseksi minun raadollisuuteni maassa."],[41,53,"Koska ne seitsemän viljavuotta olivat kuluneet Egyptin maalla,","Koska ne seitsemän viljavuotta olivat kuluneet Egyptin maalla,"],[41,54,"Rupesivat ne seitsemän nälkävuotta tulemaan, niinkuin Joseph oli (edellä) sanonut: ja nälkä tuli kaikkiin maakuntiin; mutta koko Egyptin maalla oli leipää.","Rupesivat ne seitsemän nälkävuotta tulemaan, niinkuin Joseph oli (edellä) sanonut: ja nälkä tuli kaikkiin maakuntiin; mutta koko Egyptin maalla oli leipää."],[41,55,"Kuin Egyptin maa myös kärsi nälkää, huusi kansa Pharaon tykö leivän tähden. Mutta Pharao sanoi kaikille Egyptiläisille: menkäät Josephin tykö; mitä hän sanoo teille, se tehkäät.","Kuin Egyptin maa myös kärsi nälkää, huusi kansa Pharaon tykö leivän tähden. Mutta Pharao sanoi kaikille Egyptiläisille: menkäät Josephin tykö; mitä hän sanoo teille, se tehkäät."],[41,56,"Koska nälkä tuli koko maakuntaan, avasi Joseph kaikki jyväaitat jokapaikassa, ja myi Egyptiläisille; sillä nälkä tuli aina raskaammaksi Egyptin maalla.","Koska nälkä tuli koko maakuntaan, avasi Joseph kaikki jyväaitat jokapaikassa, ja myi Egyptiläisille; sillä nälkä tuli aina raskaammaksi Egyptin maalla."],[41,57,"Ja kaikki maakunnat tulivat Egyptiin ostamaan Josephilta; sillä suuri nälkä oli kaikissa maakunnissa.","Ja kaikki maakunnat tulivat Egyptiin ostamaan Josephilta; sillä suuri nälkä oli kaikissa maakunnissa."],[42,1,"Mutta koska Jakob näki olevan jyviä myydä Egyptissä, sanoi hän pojillensa: mitä te katselette toinen toisenne päälle?","Mutta koska Jakob näki olevan jyviä myydä Egyptissä, sanoi hän pojillensa: mitä te katselette toinen toisenne päälle?"],[42,2,"Ja sanoi: katso, minä kuulen Egyptissä olevan jyviä; menkäät alas sinne, ja ostakaat meille sieltä, että me eläisimme, ja emme kuolisi.","Ja sanoi: katso, minä kuulen Egyptissä olevan jyviä; menkäät alas sinne, ja ostakaat meille sieltä, että me eläisimme, ja emme kuolisi."],[42,3,"Niin menivät kymmenen Josephin veljeä alas, ostamaan jyviä Egyptistä.","Niin menivät kymmenen Josephin veljeä alas, ostamaan jyviä Egyptistä."],[42,4,"Mutta BenJaminia, Josephin veljeä, ei lähettänyt Jakob veljiensä kanssa; sillä hän sanoi: ettei hänelle vahinkoa tapahtuisi.","Mutta BenJaminia, Josephin veljeä, ei lähettänyt Jakob veljiensä kanssa; sillä hän sanoi: ettei hänelle vahinkoa tapahtuisi."],[42,5,"Niin läksivät Israelin lapset matkaan (jyviä) ostamaan muiden seurassa; sillä nälkä oli Kanaanin maalla.","Niin läksivät Israelin lapset matkaan (jyviä) ostamaan muiden seurassa; sillä nälkä oli Kanaanin maalla."],[42,6,"Mutta Joseph oli hallitsia maakunnassa, hän antoi myydä jyviä kaikelle maan kansalle. Niin tulivat Josephin veljet, ja kumarsivat maahan kasvoillensa hänen eteensä.","Mutta Joseph oli hallitsia maakunnassa, hän antoi myydä jyviä kaikelle maan kansalle. Niin tulivat Josephin veljet, ja kumarsivat maahan kasvoillensa hänen eteensä."],[42,7,"Ja Joseph näki veljensä, ja tunsi heidät, ja teeskeli hänensä oudoksi heitä vastaan, ja puhui kovasti heidän kanssansa, ja sanoi heille: kusta te tulette? He vastasivat: Kanaanin maalta, ostamaan syötävää.","Ja Joseph näki veljensä, ja tunsi heidät, ja teeskeli hänensä oudoksi heitä vastaan, ja puhui kovasti heidän kanssansa, ja sanoi heille: kusta te tulette? He vastasivat: Kanaanin maalta, ostamaan syötävää."],[42,8,"Ja Joseph tunsi veljensä, vaan ei he häntä tunteneet.","Ja Joseph tunsi veljensä, vaan ei he häntä tunteneet."],[42,9,"Niin Joseph muisti unensa, jotka hän oli nähnyt heistä; ja sanoi heille: te olette vakojat, ja olette tulleet katsomaan, kusta maa avojoin olis.","Niin Joseph muisti unensa, jotka hän oli nähnyt heistä; ja sanoi heille: te olette vakojat, ja olette tulleet katsomaan, kusta maa avojoin olis."],[42,10,"He vastasivat häntä: ei minun herrani: mutta sinun palvelias ovat tulleet ostamaan jyviä.","He vastasivat häntä: ei minun herrani: mutta sinun palvelias ovat tulleet ostamaan jyviä."],[42,11,"Me olemme kaikki yhden miehen pojat: me olemme vaat, eikä sinun palvelias ole ikänänsä olleet vakojat.","Me olemme kaikki yhden miehen pojat: me olemme vaat, eikä sinun palvelias ole ikänänsä olleet vakojat."],[42,12,"Hän sanoi heille: ei suinkaan, mutta te olette tulleet katsomaan, kusta maa avojoin olis.","Hän sanoi heille: ei suinkaan, mutta te olette tulleet katsomaan, kusta maa avojoin olis."],[42,13,"He sanoivat: me sinun palvelias olimme kaksitoistakymmentä veljestä, yhden miehen pojat Kanaanin maalla; ja katso, nuorin on nyt meidän isämme tykönä, mutta yksi ei ole sillen eleillä.","He sanoivat: me sinun palvelias olimme kaksitoistakymmentä veljestä, yhden miehen pojat Kanaanin maalla; ja katso, nuorin on nyt meidän isämme tykönä, mutta yksi ei ole sillen eleillä."],[42,14,"Joseph sanoi heille: sepä se on, kuin minä olen teille puhunut, sanoen: vakojat te olette.","Joseph sanoi heille: sepä se on, kuin minä olen teille puhunut, sanoen: vakojat te olette."],[42,15,"Siinä teitä pitää koeteltaman. Niin totta kuin Pharao elää, ei teidän pidä täältä pääsemän, jollei teidän nuorin veljenne tule tänne.","Siinä teitä pitää koeteltaman. Niin totta kuin Pharao elää, ei teidän pidä täältä pääsemän, jollei teidän nuorin veljenne tule tänne."],[42,16,"Lähettäkäät yksi teistänne, joka tuo teidän veljenne tänne: mutta teidän pitää vankina oleman, niin teidän puheenne koetellaan, jos teissä totuus on; mutta jollei, niin totta kuin Pharao elää, te olette vakojat.","Lähettäkäät yksi teistänne, joka tuo teidän veljenne tänne: mutta teidän pitää vankina oleman, niin teidän puheenne koetellaan, jos teissä totuus on; mutta jollei, niin totta kuin Pharao elää, te olette vakojat."],[42,17,"Niin hän pani heidät kiinni kolmeksi päiväksi.","Niin hän pani heidät kiinni kolmeksi päiväksi."],[42,18,"Ja kolmantena päivänä sanoi Joseph heille: jos te tahdotte elää, niin tehkäät näin; sillä minä pelkään Jumalaa.","Ja kolmantena päivänä sanoi Joseph heille: jos te tahdotte elää, niin tehkäät näin; sillä minä pelkään Jumalaa."],[42,19,"Jos te olette vaat, niin antakaat yksi teidän veljistänne olla sidottuna teidän vankihuoneessanne; mutta menkäät te ja viekäät kotia, mitä te ostaneet olette nälkää vastaan kotonanne.","Jos te olette vaat, niin antakaat yksi teidän veljistänne olla sidottuna teidän vankihuoneessanne; mutta menkäät te ja viekäät kotia, mitä te ostaneet olette nälkää vastaan kotonanne."],[42,20,"Ja tuokaat teidän nuorin veljenne minun tyköni, että teidän sananne todeksi löyttäisiin, ettette kuolisi; ja he tekivät niin.","Ja tuokaat teidän nuorin veljenne minun tyköni, että teidän sananne todeksi löyttäisiin, ettette kuolisi; ja he tekivät niin."],[42,21,"Mutta he sanoivat toinen toisellensa: me olemme totisesti vianalaiset meidän veljemme tähden; sillä me näimme hänen sielunsa ahdistuksen, koska hän meiltä armoa rukoili, ja emme kuulleet häntä; sentähden on tämä ahdistus meidän päällemme tullut.","Mutta he sanoivat toinen toisellensa: me olemme totisesti vianalaiset meidän veljemme tähden; sillä me näimme hänen sielunsa ahdistuksen, koska hän meiltä armoa rukoili, ja emme kuulleet häntä; sentähden on tämä ahdistus meidän päällemme tullut."],[42,22,"Ruben vastasi heitä, sanoen: enkö minä puhunut teille, sanoen: älkäät tehkö vääryyttä nuorukaiselle, ja ette tahtoneet kuulla? Ja nyt hänen verensä meiltä vaaditaan.","Ruben vastasi heitä, sanoen: enkö minä puhunut teille, sanoen: älkäät tehkö vääryyttä nuorukaiselle, ja ette tahtoneet kuulla? Ja nyt hänen verensä meiltä vaaditaan."],[42,23,"Vaan ei he tietäneet Josephin sitä ymmärtävän; sillä hän puhui heille tulkin kautta.","Vaan ei he tietäneet Josephin sitä ymmärtävän; sillä hän puhui heille tulkin kautta."],[42,24,"Ja hän käänsi itsensä heistä, ja itki. Koska hän jällensä käänsi heidän puoleensa ja puhutteli heitä, otti hän Simeonin heiltä, ja sitoi hänen heidän nähtensä.","Ja hän käänsi itsensä heistä, ja itki. Koska hän jällensä käänsi heidän puoleensa ja puhutteli heitä, otti hän Simeonin heiltä, ja sitoi hänen heidän nähtensä."],[42,25,"Ja Joseph käski heidän säkkinsä täytettää jyvillä, ja annettaa heidän rahansa jälleen itsekunkin omaan säkkiinsä, ja annettaa heille evästä matkalle; ja heille tehtiin niin.","Ja Joseph käski heidän säkkinsä täytettää jyvillä, ja annettaa heidän rahansa jälleen itsekunkin omaan säkkiinsä, ja annettaa heille evästä matkalle; ja heille tehtiin niin."],[42,26,"Ja he panivat kalunsa aaseinsa päälle, ja läksivät sieltä.","Ja he panivat kalunsa aaseinsa päälle, ja läksivät sieltä."],[42,27,"Koska yksi heistä avasi säkkinsä, antaaksensa ruokaa aasillensa, ja äkkäsi rahansa säkkinsä suussa,","Koska yksi heistä avasi säkkinsä, antaaksensa ruokaa aasillensa, ja äkkäsi rahansa säkkinsä suussa,"],[42,28,"Ja sanoi veljillensä: minulle on annettu minun rahani jällensä, katso, se on minun säkissäni. Niin heidän sydämensä vavahtui, ja hämmästyivät keskenänsä, sanoen: miksi on Jumala meille näin tehnyt?","Ja sanoi veljillensä: minulle on annettu minun rahani jällensä, katso, se on minun säkissäni. Niin heidän sydämensä vavahtui, ja hämmästyivät keskenänsä, sanoen: miksi on Jumala meille näin tehnyt?"],[42,29,"Koska he tulivat isänsä Jakobin tykö Kanaanin maalle, ilmoittivat he hänelle kaikki, mitä heille tapahtunut oli, sanoen:","Koska he tulivat isänsä Jakobin tykö Kanaanin maalle, ilmoittivat he hänelle kaikki, mitä heille tapahtunut oli, sanoen:"],[42,30,"Se mies, sen maan herra, puhui kovasti meille, ja piti meitä maan vakojina.","Se mies, sen maan herra, puhui kovasti meille, ja piti meitä maan vakojina."],[42,31,"Ja me vastasimme häntä: me olemme vaat, emme ole ikänänsä oleet vakoojat.","Ja me vastasimme häntä: me olemme vaat, emme ole ikänänsä oleet vakoojat."],[42,32,"Me olimme kaksitoistakymmentä veljestä meidän isämme poikaa: yksi ei ole silleen eleissä, ja nuorin on nyt isämme tykönä Kanaanin maalla.","Me olimme kaksitoistakymmentä veljestä meidän isämme poikaa: yksi ei ole silleen eleissä, ja nuorin on nyt isämme tykönä Kanaanin maalla."],[42,33,"Sanoi se mies, sen maan herra meille: siitä minä tunnen, jos te olette vaat: yksi teidän veljistänne jättäkäät minun tyköni, ja ottakaat teidän taloinne tarve, ja menkäät pois.","Sanoi se mies, sen maan herra meille: siitä minä tunnen, jos te olette vaat: yksi teidän veljistänne jättäkäät minun tyköni, ja ottakaat teidän taloinne tarve, ja menkäät pois."],[42,34,"Ja tuokaat teidän nuorin veljenne minun tyköni, niin minä ymmärrän, ett'ette ole vakojat, vaan vaat; niin annan minä myös teidän veljenne jälleen, ja saatte tehdä kauppaa tässä maakunnassa.","Ja tuokaat teidän nuorin veljenne minun tyköni, niin minä ymmärrän, ett'ette ole vakojat, vaan vaat; niin annan minä myös teidän veljenne jälleen, ja saatte tehdä kauppaa tässä maakunnassa."],[42,35,"Ja tapahtui, koska he tyhjensivät säkkejänsä, katso, oli itsekunkin rahakäärö hänen säkissänsä: ja kuin he näkivät rahakäärönsä, hämmästyivät he isänsä kanssa.","Ja tapahtui, koska he tyhjensivät säkkejänsä, katso, oli itsekunkin rahakäärö hänen säkissänsä: ja kuin he näkivät rahakäärönsä, hämmästyivät he isänsä kanssa."],[42,36,"Niin sanoi Jakob heidän isänsä heille: te olette saattaneet minun lapsettomaksi: Joseph ei ole elävissä, eikä Simeon, Ja Benjaminin tahdotte te vielä viedä pois; minun kohtaani nämät kaikki tapahtuvat.","Niin sanoi Jakob heidän isänsä heille: te olette saattaneet minun lapsettomaksi: Joseph ei ole elävissä, eikä Simeon, Ja Benjaminin tahdotte te vielä viedä pois; minun kohtaani nämät kaikki tapahtuvat."],[42,37,"Ruben vastasi isällensä, sanoen: tapa molemmat minun poikani, jollen minä häntä jälleen sinulle (kotia) tuo, ainoastansa anna häntä minun haltuuni, minä hänen sinulle jälleen (kotia) tuon.","Ruben vastasi isällensä, sanoen: tapa molemmat minun poikani, jollen minä häntä jälleen sinulle (kotia) tuo, ainoastansa anna häntä minun haltuuni, minä hänen sinulle jälleen (kotia) tuon."],[42,38,"Hän sanoi: ei minun poikani pidä menemän alas teidän kanssanne: sillä hänen veljensä on kuollut, ja hän on jäänyt yksin, ja jos hänelle tapahtuis jotakin pahaa tiellä, jota te vaellatte, niin te saatatte minun harmaat karvani murheella hautaan.","Hän sanoi: ei minun poikani pidä menemän alas teidän kanssanne: sillä hänen veljensä on kuollut, ja hän on jäänyt yksin, ja jos hänelle tapahtuis jotakin pahaa tiellä, jota te vaellatte, niin te saatatte minun harmaat karvani murheella hautaan."],[43,1,"Mutta kallis aika ahdisti maata.","Mutta kallis aika ahdisti maata."],[43,2,"Ja koska he loppuivat syödä ne jyvät kuin he Egyptistä tuoneet olivat, sanoi heidän isänsä heille: menkäät jällensä sinne, ja ostakaat meille jotakin elatusta.","Ja koska he loppuivat syödä ne jyvät kuin he Egyptistä tuoneet olivat, sanoi heidän isänsä heille: menkäät jällensä sinne, ja ostakaat meille jotakin elatusta."],[43,3,"Niin vastasi häntä Juuda, sanoen: se mies haastoi meitä sangen kovin, ja sanoi: ei pidä teidän näkemän minun kasvojani, jollei teidän veljenne ole teidän kanssanne.","Niin vastasi häntä Juuda, sanoen: se mies haastoi meitä sangen kovin, ja sanoi: ei pidä teidän näkemän minun kasvojani, jollei teidän veljenne ole teidän kanssanne."],[43,4,"Jos siis sinä nyt lähetät meidän veljemme meidän kanssamme, niin me menemme alas ja ostamme sinulle elatusta.","Jos siis sinä nyt lähetät meidän veljemme meidän kanssamme, niin me menemme alas ja ostamme sinulle elatusta."],[43,5,"Vaan jolles häntä lähetä, niin emme mekään mene; sillä se mies sanoi meille: ei teidän pidä näkemän minun kasvojani, jollei teidän veljenne ole teidän kanssanne.","Vaan jolles häntä lähetä, niin emme mekään mene; sillä se mies sanoi meille: ei teidän pidä näkemän minun kasvojani, jollei teidän veljenne ole teidän kanssanne."],[43,6,"Israel sanoi: miksi te teitte minua vastaan niin pahoin, että te sanoitte sille miehelle teillänne vielä olevan veljen.","Israel sanoi: miksi te teitte minua vastaan niin pahoin, että te sanoitte sille miehelle teillänne vielä olevan veljen."],[43,7,"He vastasivat: se mies kysyi meistä niin visusti, ja meidän suvustamme, sanoen: vieläkö teidän isänne elää? Onko teillä vielä veljeä? Niin me vastasimme häntä kuin hän kysyi. Taitaisimmeko me ratki tietää hänen sanovan: tuokaat veljenne tänne.","He vastasivat: se mies kysyi meistä niin visusti, ja meidän suvustamme, sanoen: vieläkö teidän isänne elää? Onko teillä vielä veljeä? Niin me vastasimme häntä kuin hän kysyi. Taitaisimmeko me ratki tietää hänen sanovan: tuokaat veljenne tänne."],[43,8,"Niin sanoi Juuda isällensä Israelille: lähetä nuorukainen minun kanssani, niin me valmistamme ja lähdemme matkaan: että me eläisimme ja emme kuolisi, sekä me että sinä ja meidän lapsemme.","Niin sanoi Juuda isällensä Israelille: lähetä nuorukainen minun kanssani, niin me valmistamme ja lähdemme matkaan: että me eläisimme ja emme kuolisi, sekä me että sinä ja meidän lapsemme."],[43,9,"Minä takaan hänen edestänsä, kaipaa häntä minun käsistäni; jollen minä tuo häntä jälleen sinun tykös, ja pane häntä sinun etees, niin minä olen vikapää sinun edessäs kaikkena minun elinaikanani.","Minä takaan hänen edestänsä, kaipaa häntä minun käsistäni; jollen minä tuo häntä jälleen sinun tykös, ja pane häntä sinun etees, niin minä olen vikapää sinun edessäs kaikkena minun elinaikanani."],[43,10,"Sillä jollei meillä olisi ollut viivytystä, totisesti me olisimme jo toisen kerran tulleet jällensä.","Sillä jollei meillä olisi ollut viivytystä, totisesti me olisimme jo toisen kerran tulleet jällensä."],[43,11,"Niin sanoi Israel heidän isänsä heille: jos nyt kumminkin niin pitää oleman, tehkäät siis näin: ottakaat maan parhaista hedelmistä teidän astioihinne, ja viekäät sille miehelle lahjoja: jotakin mastiksia ja hunajaa, ja styraksia, ja ladanumia, ja dadelia ja mandelia.","Niin sanoi Israel heidän isänsä heille: jos nyt kumminkin niin pitää oleman, tehkäät siis näin: ottakaat maan parhaista hedelmistä teidän astioihinne, ja viekäät sille miehelle lahjoja: jotakin mastiksia ja hunajaa, ja styraksia, ja ladanumia, ja dadelia ja mandelia."],[43,12,"Ottakaat myös toinen raha teidän myötänne, ja se raha, jonka te toitte jällensä säkkein suussa, viekäät myötänne; taitaa olla, että se on epähuomiosta tapahtunut.","Ottakaat myös toinen raha teidän myötänne, ja se raha, jonka te toitte jällensä säkkein suussa, viekäät myötänne; taitaa olla, että se on epähuomiosta tapahtunut."],[43,13,"Ottakaat myös teidän veljenne; ja valmistakaat, ja menkäät jälleen sen miehen tykö.","Ottakaat myös teidän veljenne; ja valmistakaat, ja menkäät jälleen sen miehen tykö."],[43,14,"Jumala kaikkivaltias antakoon teidän löytää laupiuden sen miehen edessä, että hän päästäis jälleen teille toisen teidän veljenne, ja (tämän) BenJaminin. Mutta minä, niinkuin minä olen lapsettomaksi joutunut, olen lapsetonna.","Jumala kaikkivaltias antakoon teidän löytää laupiuden sen miehen edessä, että hän päästäis jälleen teille toisen teidän veljenne, ja (tämän) BenJaminin. Mutta minä, niinkuin minä olen lapsettomaksi joutunut, olen lapsetonna."],[43,15,"Niin ottivat miehet nämät lahjat, ja ottivat kaksi sen vertaa rahaa myötänsä, ja BenJaminin: valmistivat itsensä ja menivät Egyptiin, ja seisoivat Josephin edessä.","Niin ottivat miehet nämät lahjat, ja ottivat kaksi sen vertaa rahaa myötänsä, ja BenJaminin: valmistivat itsensä ja menivät Egyptiin, ja seisoivat Josephin edessä."],[43,16,"Ja kun Joseph näki BenJaminin heidän kanssansa, sanoi hän huoneensa haltialle: vie nämät miehet huoneesen, ja tee ja teurasta ja valmista; sillä heidän pitää minun kanssani päivällistä syömän.","Ja kun Joseph näki BenJaminin heidän kanssansa, sanoi hän huoneensa haltialle: vie nämät miehet huoneesen, ja tee ja teurasta ja valmista; sillä heidän pitää minun kanssani päivällistä syömän."],[43,17,"Ja se mies teki niinkuin Joseph oli hänelle käskenyt, ja vei miehet Josephin huoneesen.","Ja se mies teki niinkuin Joseph oli hänelle käskenyt, ja vei miehet Josephin huoneesen."],[43,18,"Ja he pelkäsivät, että he vietiin Josephin huoneesen, ja sanoivat: me viedään tänne sen rahan tähden jonka me tätä ennen löysimme meidän säkeistämme: että hän soimais meitä, ja saattais meitä oikeuden alle, ja ottais meitä orjiksensa, ja meidän aasimme.","Ja he pelkäsivät, että he vietiin Josephin huoneesen, ja sanoivat: me viedään tänne sen rahan tähden jonka me tätä ennen löysimme meidän säkeistämme: että hän soimais meitä, ja saattais meitä oikeuden alle, ja ottais meitä orjiksensa, ja meidän aasimme."],[43,19,"Sentähden he menivät Josephin huoneenhaltian tykö, ja puhuttelivat häntä huoneen oven edessä,","Sentähden he menivät Josephin huoneenhaltian tykö, ja puhuttelivat häntä huoneen oven edessä,"],[43,20,"Ja sanoivat: ah, minun herrani, me olimme ennen tänne tulleet ostamaan jyviä.","Ja sanoivat: ah, minun herrani, me olimme ennen tänne tulleet ostamaan jyviä."],[43,21,"Ja koska me tulimme yösialle, ja avasimme meidän säkkimme, katso, niin oli itsekunkin raha säkkinsä suussa täydellä painolla: sentähden olemme me ne jällensä myötämme tuoneet.","Ja koska me tulimme yösialle, ja avasimme meidän säkkimme, katso, niin oli itsekunkin raha säkkinsä suussa täydellä painolla: sentähden olemme me ne jällensä myötämme tuoneet."],[43,22,"Olemme myös toisen rahan myötämme tuoneet ostaaksemme jyviä; emme sitä tiedä, kuka on pannut jällensä meidän rahamme meidän säkkiimme.","Olemme myös toisen rahan myötämme tuoneet ostaaksemme jyviä; emme sitä tiedä, kuka on pannut jällensä meidän rahamme meidän säkkiimme."],[43,23,"Mutta hän sanoi: olkaat hyvässä turvassa, älkäät peljätkö: teidän Jumalanne ja teidän isänne Jumala on teille tavaran antanut teidän säkkiinne: teidän rahanne olen minä saanut. Ja hän toi Simeonin heidän tykönsä.","Mutta hän sanoi: olkaat hyvässä turvassa, älkäät peljätkö: teidän Jumalanne ja teidän isänne Jumala on teille tavaran antanut teidän säkkiinne: teidän rahanne olen minä saanut. Ja hän toi Simeonin heidän tykönsä."],[43,24,"Ja se mies vei heidät Josephin huoneesen, antoi heille vettä pestä heidän jalkojansa, ja antoi ruokaa heidän aaseillensa.","Ja se mies vei heidät Josephin huoneesen, antoi heille vettä pestä heidän jalkojansa, ja antoi ruokaa heidän aaseillensa."],[43,25,"Mutta he valmistivat lahjojansa, siihen asti kuin Joseph tuli päivälliselle; sillä he olivat kuulleet, että heidän piti siellä syömän.","Mutta he valmistivat lahjojansa, siihen asti kuin Joseph tuli päivälliselle; sillä he olivat kuulleet, että heidän piti siellä syömän."],[43,26,"Koska Joseph tuli huoneesen, kantoivat he lahjoja huoneesen hänelle käsissänsä, ja kumarsivat maahan hänen eteensä.","Koska Joseph tuli huoneesen, kantoivat he lahjoja huoneesen hänelle käsissänsä, ja kumarsivat maahan hänen eteensä."],[43,27,"Ja hän tervehti heitä rakkaasti, ja sanoi: onko teidän vanha isänne rauhassa, josta te minulle sanoitte? Vieläkö hän elää?","Ja hän tervehti heitä rakkaasti, ja sanoi: onko teidän vanha isänne rauhassa, josta te minulle sanoitte? Vieläkö hän elää?"],[43,28,"He vastasivat: sinun palvelias meidän isämme on rauhassa, ja elää vielä; ja he kumarsivat ja maahan lankesivat hänen edessänsä.","He vastasivat: sinun palvelias meidän isämme on rauhassa, ja elää vielä; ja he kumarsivat ja maahan lankesivat hänen edessänsä."],[43,29,"Niin hän nosti silmänsä ja näki veljensä BenJaminin, äitinsä pojan, ja sanoi: onko tämä teidän nuorin veljenne, josta te sanoitte minulle? Ja sanoi vielä: Jumala olkoon sinulle armollinen, minun poikani.","Niin hän nosti silmänsä ja näki veljensä BenJaminin, äitinsä pojan, ja sanoi: onko tämä teidän nuorin veljenne, josta te sanoitte minulle? Ja sanoi vielä: Jumala olkoon sinulle armollinen, minun poikani."],[43,30,"Ja Joseph kiiruhti itsensä; sillä hänen sydämensä paloi veljeänsä kohtaan, ja etsi siaa itkeäksensä; ja meni kamariinsa, ja itki siellä.","Ja Joseph kiiruhti itsensä; sillä hänen sydämensä paloi veljeänsä kohtaan, ja etsi siaa itkeäksensä; ja meni kamariinsa, ja itki siellä."],[43,31,"Ja kuin hän oli pessyt kasvona, tuli hän ulos; ja pidätti itsensä, ja sanoi: tuokaat leipää.","Ja kuin hän oli pessyt kasvona, tuli hän ulos; ja pidätti itsensä, ja sanoi: tuokaat leipää."],[43,32,"Ja pantiin erinänsä hänelle ja erinänsä heille, niin myös Egyptiläisille, jotka hänen kanssansa atrioitsivat, erinänsä; sillä Egyptiläiset ei saa syödä Hebrealaisten kanssa, sillä se on Egyptiläisille kauhistus.","Ja pantiin erinänsä hänelle ja erinänsä heille, niin myös Egyptiläisille, jotka hänen kanssansa atrioitsivat, erinänsä; sillä Egyptiläiset ei saa syödä Hebrealaisten kanssa, sillä se on Egyptiläisille kauhistus."],[43,33,"Ja he istutettiin hänen kohdallensa, esikoinen esikoisuutensa jälkeen, ja nuorin nuoruutensa jälkeen: sitä miehet ihmettelivät keskenänsä.","Ja he istutettiin hänen kohdallensa, esikoinen esikoisuutensa jälkeen, ja nuorin nuoruutensa jälkeen: sitä miehet ihmettelivät keskenänsä."],[43,34,"Ja heille kannettiin ruokaa hänen pöydältänsä, mutta BenJaminille viisi kertaa enemmän kuin muille. Ja he joivat ja juopuivat hänen kanssansa.","Ja heille kannettiin ruokaa hänen pöydältänsä, mutta BenJaminille viisi kertaa enemmän kuin muille. Ja he joivat ja juopuivat hänen kanssansa."],[44,1,"Ja Joseph käski huoneensa haltiaa, sanoen: täytä miesten säkit jyvillä, niin paljo kuin he voivat kannattaa, ja pane itsekunkin raha säkkinsä suuhun.","Ja Joseph käski huoneensa haltiaa, sanoen: täytä miesten säkit jyvillä, niin paljo kuin he voivat kannattaa, ja pane itsekunkin raha säkkinsä suuhun."],[44,2,"Ja minun maljani, se hopiamalja pane nuorimman säkin suuhun, ynnä jyväinsä hinnan kanssa. Ja hän teki niinkuin Joseph hänelle käski.","Ja minun maljani, se hopiamalja pane nuorimman säkin suuhun, ynnä jyväinsä hinnan kanssa. Ja hän teki niinkuin Joseph hänelle käski."],[44,3,"Mutta aamulla päivän valjetessa, päästettiin miehet menemään aaseinensa.","Mutta aamulla päivän valjetessa, päästettiin miehet menemään aaseinensa."],[44,4,"Ja koska he olivat lähteneet kaupungista, eikä vielä kauvas joutuneet, sanoi Joseph huoneensa haltialle: nouse ja aja takaa miehiä, ja koska heidän saat takaa, niin sano heille: miksi te olette hyvän pahalla maksaneet?","Ja koska he olivat lähteneet kaupungista, eikä vielä kauvas joutuneet, sanoi Joseph huoneensa haltialle: nouse ja aja takaa miehiä, ja koska heidän saat takaa, niin sano heille: miksi te olette hyvän pahalla maksaneet?"],[44,5,"Eikö se ole, josta minun herrani juo? Ja josta hän kyllä hyvin taitaa arvata teistä? Te olette pahoin tehneet.","Eikö se ole, josta minun herrani juo? Ja josta hän kyllä hyvin taitaa arvata teistä? Te olette pahoin tehneet."],[44,6,"Ja kuin hän käsitti heidät, puhui hän nämät sanat heille.","Ja kuin hän käsitti heidät, puhui hän nämät sanat heille."],[44,7,"He vastasivat häntä: miksi minun herrani senkaltaista puhuu? Pois se, että sinun palvelias niin tekisivät.","He vastasivat häntä: miksi minun herrani senkaltaista puhuu? Pois se, että sinun palvelias niin tekisivät."],[44,8,"Katso, rahan, jonka me löysimme säkkeimme suusta, olemme me jälleen sinulle tuoneet Kanaanin maalta: kuinkasta siis me varastimme hopiaa eli kultaa sinun herras huoneesta?","Katso, rahan, jonka me löysimme säkkeimme suusta, olemme me jälleen sinulle tuoneet Kanaanin maalta: kuinkasta siis me varastimme hopiaa eli kultaa sinun herras huoneesta?"],[44,9,"Jonka tyköä sinun palvelioiltas se löydetään, hän kuolkaan: niin tahdomme me myös olla orjat minun herralleni.","Jonka tyköä sinun palvelioiltas se löydetään, hän kuolkaan: niin tahdomme me myös olla orjat minun herralleni."],[44,10,"Hän sanoi: olkaan nyt teidän sananne jälkeen: jonka tyköä se löydetään, hän olkaan minun orjani; mutta te olette vapaat.","Hän sanoi: olkaan nyt teidän sananne jälkeen: jonka tyköä se löydetään, hän olkaan minun orjani; mutta te olette vapaat."],[44,11,"Ja he laskivat kiiruusti itsekukin säkkinsä maahan, ja jokainen avasi säkkinsä.","Ja he laskivat kiiruusti itsekukin säkkinsä maahan, ja jokainen avasi säkkinsä."],[44,12,"Ja hän etsei, ruveten vanhimmasta niin nuorimpaan asti; ja hopiamalja löydettiin BenJaminin säkistä.","Ja hän etsei, ruveten vanhimmasta niin nuorimpaan asti; ja hopiamalja löydettiin BenJaminin säkistä."],[44,13,"Niin repäisivät vaatteensa, ja itsekukin pani kuormansa aasin päälle, ja palasivat kaupunkiin.","Niin repäisivät vaatteensa, ja itsekukin pani kuormansa aasin päälle, ja palasivat kaupunkiin."],[44,14,"Ja Juuda meni veljinensä Josephin huoneesen (sillä hän oli vielä silloin siellä); ja he lankesivat maahan hänen eteensä.","Ja Juuda meni veljinensä Josephin huoneesen (sillä hän oli vielä silloin siellä); ja he lankesivat maahan hänen eteensä."],[44,15,"Joseph sanoi heille: mikä työ se on, kuin te tehneet olette? Ettekö te tietäneet, että senkaltainen mies kuin minä olen taitaa kyllä hyvin arvata.","Joseph sanoi heille: mikä työ se on, kuin te tehneet olette? Ettekö te tietäneet, että senkaltainen mies kuin minä olen taitaa kyllä hyvin arvata."],[44,16,"Ja Juuda sanoi: mitä me vastaamme minun herralleni? Taikka mitä me puhumme? Taikka millä me taidamme itsemme puhdistaa? Jumala on löytänyt sinun palveliais vääryyden: katso, me olemme meidän herramme orjat, sekä me, että se, jolta malja löydettiin.","Ja Juuda sanoi: mitä me vastaamme minun herralleni? Taikka mitä me puhumme? Taikka millä me taidamme itsemme puhdistaa? Jumala on löytänyt sinun palveliais vääryyden: katso, me olemme meidän herramme orjat, sekä me, että se, jolta malja löydettiin."],[44,17,"Mutta hän sanoi: pois se, että minä niin tekisin; sen miehen, jolta malja on löydetty, pitää oleman minun orjani; mutta menkäät te rauhassa isänne tykö.","Mutta hän sanoi: pois se, että minä niin tekisin; sen miehen, jolta malja on löydetty, pitää oleman minun orjani; mutta menkäät te rauhassa isänne tykö."],[44,18,"Niin Juuda astui hänen tykönsä, ja sanoi: ah minun herrani, suo nyt palvelias puhua yksi sana minun herrani korvissa, ja älkään julmistuko sinun vihas sinun palvelias päälle, sillä sinä olet niinkuin Pharao.","Niin Juuda astui hänen tykönsä, ja sanoi: ah minun herrani, suo nyt palvelias puhua yksi sana minun herrani korvissa, ja älkään julmistuko sinun vihas sinun palvelias päälle, sillä sinä olet niinkuin Pharao."],[44,19,"Minun herrani kysyi hänen palvelioiltansa, sanoen: onko teillä isää taikka veljeä?","Minun herrani kysyi hänen palvelioiltansa, sanoen: onko teillä isää taikka veljeä?"],[44,20,"Niin me vastasimme meidän herraamme: meillä on vanha isä, ja nuorukainen syntynyt hänen vanhalla ijällänsä, jonka veli on kuollut, ja hän on yksinänsä jäänyt äidistänsä, ja hänen isänsä pitää hänen rakkaana.","Niin me vastasimme meidän herraamme: meillä on vanha isä, ja nuorukainen syntynyt hänen vanhalla ijällänsä, jonka veli on kuollut, ja hän on yksinänsä jäänyt äidistänsä, ja hänen isänsä pitää hänen rakkaana."],[44,21,"Niin sinä sanoit palvelioilles: tuokaat häntä tänne minun tyköni, että minä saan nähdä hänen.","Niin sinä sanoit palvelioilles: tuokaat häntä tänne minun tyköni, että minä saan nähdä hänen."],[44,22,"Mutta me vastasimme minun herralleni: ei taida nuorukainen jättää isäänsä; sillä jos hän jättäis isänsä, niin hän kuolis.","Mutta me vastasimme minun herralleni: ei taida nuorukainen jättää isäänsä; sillä jos hän jättäis isänsä, niin hän kuolis."],[44,23,"Niin sinä sanoit palvelioilles. jollei teidän nuorin veljenne tule teidän kanssanne, niin ei teidän pidä enää minun kasvojani näkemän.","Niin sinä sanoit palvelioilles. jollei teidän nuorin veljenne tule teidän kanssanne, niin ei teidän pidä enää minun kasvojani näkemän."],[44,24,"Ja koska me menimme sinun palvelias minun isäni tykö, ja ilmoitimme hänelle minun herrani sanat,","Ja koska me menimme sinun palvelias minun isäni tykö, ja ilmoitimme hänelle minun herrani sanat,"],[44,25,"Niin sanoi meidän isämme: menkäät jälleen pois, ja ostakaat meille jotakin elatusta.","Niin sanoi meidän isämme: menkäät jälleen pois, ja ostakaat meille jotakin elatusta."],[44,26,"Mutta me sanoimme: emme tohdi sinne mennä; vaan jos meidän nuorin veljemme on meidän kanssamme, niin me menemme; sillä emme saa nähdä sen miehen kasvoja, jollei meidän nuorin veljemme ole meidän kanssamme.","Mutta me sanoimme: emme tohdi sinne mennä; vaan jos meidän nuorin veljemme on meidän kanssamme, niin me menemme; sillä emme saa nähdä sen miehen kasvoja, jollei meidän nuorin veljemme ole meidän kanssamme."],[44,27,"Niin sinun palvelias minun isäni sanoi meille: te tiedätte, että minun emäntäni synnytti minulle kaksi,","Niin sinun palvelias minun isäni sanoi meille: te tiedätte, että minun emäntäni synnytti minulle kaksi,"],[44,28,"Ja toinen läksi minun tyköäni, josta sanottiin, että hän on kuoliaaksi revelty, ja en ole minä häntä vielä sitte nähnyt.","Ja toinen läksi minun tyköäni, josta sanottiin, että hän on kuoliaaksi revelty, ja en ole minä häntä vielä sitte nähnyt."],[44,29,"Jos te tämän myös minulta viette pois, ja hänelle tapahtuis jotakin pahaa, niin te saattaisitte minun harmaat karvani murheella hautaan.","Jos te tämän myös minulta viette pois, ja hänelle tapahtuis jotakin pahaa, niin te saattaisitte minun harmaat karvani murheella hautaan."],[44,30,"Jos minä nyt tulisin sinun palvelias minun isäni tykö, ja ei olisi nuorukainen meidän kanssamme: sillä hänen henkensä riippuu tämän hengestä.","Jos minä nyt tulisin sinun palvelias minun isäni tykö, ja ei olisi nuorukainen meidän kanssamme: sillä hänen henkensä riippuu tämän hengestä."],[44,31,"Niin tapahtuis, koska hän näkis, ettei nuorukainen kanssa olisi, että hän kuolis; niin me sinun palvelias saattaisimme sinun palvelias meidän isämme harmaat karvat murheella hautaan.","Niin tapahtuis, koska hän näkis, ettei nuorukainen kanssa olisi, että hän kuolis; niin me sinun palvelias saattaisimme sinun palvelias meidän isämme harmaat karvat murheella hautaan."],[44,32,"Sillä sinun palvelias on taannut nuorukaisen minun isäni edessä, sanoen: jollen minä häntä tuo jällensä sinun tykös, niin minä sen edestä kaiken minun elinaikani olen vikapää kärsimään.","Sillä sinun palvelias on taannut nuorukaisen minun isäni edessä, sanoen: jollen minä häntä tuo jällensä sinun tykös, niin minä sen edestä kaiken minun elinaikani olen vikapää kärsimään."],[44,33,"Ja nyt siis jääkään sinun palvelias nuorukaisen edestä minun herralleni orjaksi: vaan nuorukainen menkään veljeinsä kanssa.","Ja nyt siis jääkään sinun palvelias nuorukaisen edestä minun herralleni orjaksi: vaan nuorukainen menkään veljeinsä kanssa."],[44,34,"Sillä kuinka minä taidan mennä minun isäni tykö, jollei nuorukainen olisi minun kanssani? Etten minä näkisi sitä surkeutta, johon minun isäni joutuu.","Sillä kuinka minä taidan mennä minun isäni tykö, jollei nuorukainen olisi minun kanssani? Etten minä näkisi sitä surkeutta, johon minun isäni joutuu."],[45,1,"Niin ei Joseph voinut itseänsä silleen pidättää kaikkein niiden edessä, jotka hänen tykönänsä seisoivat, ja hän huusi: menkäät ulos kaikki minun tyköäni; ja ei yksikään seisonut hänen tykönänsä, koska Joseph itsensä ilmoitti veljillensä.","Niin ei Joseph voinut itseänsä silleen pidättää kaikkein niiden edessä, jotka hänen tykönänsä seisoivat, ja hän huusi: menkäät ulos kaikki minun tyköäni; ja ei yksikään seisonut hänen tykönänsä, koska Joseph itsensä ilmoitti veljillensä."],[45,2,"Ja itki korkealla äänellä, niin että Egyptiläiset ja Pharaon perhe sen kuulivat.","Ja itki korkealla äänellä, niin että Egyptiläiset ja Pharaon perhe sen kuulivat."],[45,3,"Ja Joseph sanoi veljillensä: minä olen Joseph. Vieläkö minun isäni elää? Mutta ei hänen veljensä taitaneet häntä vastata; sillä he olivat niin hämmästyneet hänen kasvoinsa edessä.","Ja Joseph sanoi veljillensä: minä olen Joseph. Vieläkö minun isäni elää? Mutta ei hänen veljensä taitaneet häntä vastata; sillä he olivat niin hämmästyneet hänen kasvoinsa edessä."],[45,4,"Niin sanoi Joseph veljillensä: tulkaat siis minun tyköni. Ja he tulivat. Ja hän sanoi: minä olen Joseph teidän veljenne, jonka te myitte Egyptiin.","Niin sanoi Joseph veljillensä: tulkaat siis minun tyköni. Ja he tulivat. Ja hän sanoi: minä olen Joseph teidän veljenne, jonka te myitte Egyptiin."],[45,5,"Ja nyt, älkäät surulliset olko, ja älkäät niin kovin hämmästykö, että te olette minua tänne myyneet; sillä teidän henkenne elatuksen tähden on Jumala minun teidän edellänne tänne lähettänyt.","Ja nyt, älkäät surulliset olko, ja älkäät niin kovin hämmästykö, että te olette minua tänne myyneet; sillä teidän henkenne elatuksen tähden on Jumala minun teidän edellänne tänne lähettänyt."],[45,6,"Kaksi nälkävuotta on jo ollut maassa, ja vielä nyt on viisi vuotta, niin ettei kynnetä eikä niitetä.","Kaksi nälkävuotta on jo ollut maassa, ja vielä nyt on viisi vuotta, niin ettei kynnetä eikä niitetä."],[45,7,"Mutta Jumala on minun lähettänyt teidän edellänne, tallella pitämään teitä maan päällä, ja elättämään teitä suuren pelastuksen kautta.","Mutta Jumala on minun lähettänyt teidän edellänne, tallella pitämään teitä maan päällä, ja elättämään teitä suuren pelastuksen kautta."],[45,8,"Ja nyt ette ole minua tänne lähettäneet, vaan Jumala, joka myös minun asetti isäksi Pharaolle, ja herraksi kaiken hänen huoneensa päälle, ja koko Egyptin maan esimieheksi.","Ja nyt ette ole minua tänne lähettäneet, vaan Jumala, joka myös minun asetti isäksi Pharaolle, ja herraksi kaiken hänen huoneensa päälle, ja koko Egyptin maan esimieheksi."],[45,9,"Rientäkäät ja menkäät minun isäni tykö, ja sanokaat hänelle: näin sanoo sinun poikas Joseph: Jumala on minun asettanut koko Egyptin maan herraksi, tule alas minun tyköni, ja älä viivyttele.","Rientäkäät ja menkäät minun isäni tykö, ja sanokaat hänelle: näin sanoo sinun poikas Joseph: Jumala on minun asettanut koko Egyptin maan herraksi, tule alas minun tyköni, ja älä viivyttele."],[45,10,"Ja sinä olet asuva Gosenin maassa, ja olet oleva juuri läsnä minua, sinä ja sinun lapses ja sinun lastes lapset, sinun karjas, pienet ja suuret, ja kaikki mitä sinulla on.","Ja sinä olet asuva Gosenin maassa, ja olet oleva juuri läsnä minua, sinä ja sinun lapses ja sinun lastes lapset, sinun karjas, pienet ja suuret, ja kaikki mitä sinulla on."],[45,11,"Siellä minä elätän sinua, vielä on viisi nälkävuotta, ettet sinä ja sinun huonees, ja kaikki kuin sinulla on, hukkuisi.","Siellä minä elätän sinua, vielä on viisi nälkävuotta, ettet sinä ja sinun huonees, ja kaikki kuin sinulla on, hukkuisi."],[45,12,"Ja katso, teidän silmänne näkevät, ja minun veljeni BenJaminin silmät, että minä puhun teidän kanssanne suusta suuhun.","Ja katso, teidän silmänne näkevät, ja minun veljeni BenJaminin silmät, että minä puhun teidän kanssanne suusta suuhun."],[45,13,"Ja ilmoittakaat minun isälleni kaikki minun kunniani Egyptissä, ja kaikki mitä te nähneet olette. Rientäkäät siis ja tuokaat minun isäni tänne.","Ja ilmoittakaat minun isälleni kaikki minun kunniani Egyptissä, ja kaikki mitä te nähneet olette. Rientäkäät siis ja tuokaat minun isäni tänne."],[45,14,"Ja hän halasi veljeänsä BenJaminia kaulasta ja itki, ja BenJamin myös itki hänen kaulassansa.","Ja hän halasi veljeänsä BenJaminia kaulasta ja itki, ja BenJamin myös itki hänen kaulassansa."],[45,15,"Ja hän antoi suuta kaikille veljillensä, ja itki heidän ylitsensä; ja sitte puhuivat hänen veljensä hänen kanssansa.","Ja hän antoi suuta kaikille veljillensä, ja itki heidän ylitsensä; ja sitte puhuivat hänen veljensä hänen kanssansa."],[45,16,"Koska se sanoma kuului Pharaon huoneesen, nimittäin, että Josephin veljet tulleet olivat, oli se hyvä Pharaon mielestä, ja kaikkein hänen palveliainsa.","Koska se sanoma kuului Pharaon huoneesen, nimittäin, että Josephin veljet tulleet olivat, oli se hyvä Pharaon mielestä, ja kaikkein hänen palveliainsa."],[45,17,"Ja Pharao sanoi Josephille: sano veljilles, tehkäät näin: sälyttäkäät teidän juhtainne päälle, ja menkäät matkaanne; ja kuin te tulette Kanaanin maalle,","Ja Pharao sanoi Josephille: sano veljilles, tehkäät näin: sälyttäkäät teidän juhtainne päälle, ja menkäät matkaanne; ja kuin te tulette Kanaanin maalle,"],[45,18,"Niin ottakaat teidän isänne, ja teidän perheenne ja tulkaat minun tyköni: minä annan teille Egyptin maan hyvyyden, ja te syötte maan ytimen.","Niin ottakaat teidän isänne, ja teidän perheenne ja tulkaat minun tyköni: minä annan teille Egyptin maan hyvyyden, ja te syötte maan ytimen."],[45,19,"Ja käske heitä: tehkäät niin, ottakaat teillenne vaunut Egyptin maalta teidän lapsillenne, ja emännillenne, ja tuokaat teidän isänne ja tulkaat.","Ja käske heitä: tehkäät niin, ottakaat teillenne vaunut Egyptin maalta teidän lapsillenne, ja emännillenne, ja tuokaat teidän isänne ja tulkaat."],[45,20,"Älkäät myös totelko teidän talonne kappaleita: sillä kaikki Egyptin maan hyvyys pitää teidän oleman.","Älkäät myös totelko teidän talonne kappaleita: sillä kaikki Egyptin maan hyvyys pitää teidän oleman."],[45,21,"Ja Israelin lapset tekivät niin, ja Joseph antoi heille vaunut Pharaon käskyn jälkeen, ja antoi myös heille evään matkalle.","Ja Israelin lapset tekivät niin, ja Joseph antoi heille vaunut Pharaon käskyn jälkeen, ja antoi myös heille evään matkalle."],[45,22,"Ja antoi heille kaikille itsekullekin muutinvaatteet, mutta BenJaminille antoi hän kolmesataa hopiapenninkiä, ja viidet muutinvaatteet.","Ja antoi heille kaikille itsekullekin muutinvaatteet, mutta BenJaminille antoi hän kolmesataa hopiapenninkiä, ja viidet muutinvaatteet."],[45,23,"Mutta isällensä lähetti hän kymmenen aasia sälytettyä Egyptin hyvyydellä, ja kymmenen aasintammaa, kannattaen jyviä ja leipää ja evästä isällensä matkalle.","Mutta isällensä lähetti hän kymmenen aasia sälytettyä Egyptin hyvyydellä, ja kymmenen aasintammaa, kannattaen jyviä ja leipää ja evästä isällensä matkalle."],[45,24,"Niin hän lähetti veljensä matkaan, ja sanoi heille: älkäät riidelkö tiellä.","Niin hän lähetti veljensä matkaan, ja sanoi heille: älkäät riidelkö tiellä."],[45,25,"Niin he läksivät Egyptistä, ja tulivat Kanaanin maalle isänsä Jakobin tykö.","Niin he läksivät Egyptistä, ja tulivat Kanaanin maalle isänsä Jakobin tykö."],[45,26,"Ja ilmoittivat hänelle, sanoen: vielä Joseph elää, ja on koko Egyptin maan herra; ja hänen sydämensä hämmästyi, sillä ei hän uskonut heitä.","Ja ilmoittivat hänelle, sanoen: vielä Joseph elää, ja on koko Egyptin maan herra; ja hänen sydämensä hämmästyi, sillä ei hän uskonut heitä."],[45,27,"Niin he sanoivat hänelle kaikki Josephin sanat, kuin hän heille puhunut oli. Ja kuin hän näki vaunut, jotka Joseph oli lähettänyt häntä tuomaan, niin Jakobin, heidän isänsä henki virkosi.","Niin he sanoivat hänelle kaikki Josephin sanat, kuin hän heille puhunut oli. Ja kuin hän näki vaunut, jotka Joseph oli lähettänyt häntä tuomaan, niin Jakobin, heidän isänsä henki virkosi."],[45,28,"Ja Israel sanoi: nyt minulla kyllä on, että minun poikani Joseph vielä elää: minä menen häntä katsomaan ennekuin minä kuolen.","Ja Israel sanoi: nyt minulla kyllä on, että minun poikani Joseph vielä elää: minä menen häntä katsomaan ennekuin minä kuolen."],[46,1,"Niin läksi Israel kaiken sen kanssa kuin hänellä oli, ja koska hän tuli BerSabaan, uhrasi hän uhria isänsä Isaakin Jumalalle.","Niin läksi Israel kaiken sen kanssa kuin hänellä oli, ja koska hän tuli BerSabaan, uhrasi hän uhria isänsä Isaakin Jumalalle."],[46,2,"Ja Jumala puhui yöllä näyssä Israelille, sanoen: Jakob, Jakob. Hän vastasi: tässä minä olen.","Ja Jumala puhui yöllä näyssä Israelille, sanoen: Jakob, Jakob. Hän vastasi: tässä minä olen."],[46,3,"Ja hän sanoi: Minä olen Jumala, sinun isäs Jumala: älä pelkää mennä Egyptiin: sillä minä teen sinun siellä suureksi kansaksi.","Ja hän sanoi: Minä olen Jumala, sinun isäs Jumala: älä pelkää mennä Egyptiin: sillä minä teen sinun siellä suureksi kansaksi."],[46,4,"Minä menen Egyptiin sinun kanssas, ja minä jällensä sinun sieltä johdatan. Ja Joseph laskee kätensä sinun silmäis päälle.","Minä menen Egyptiin sinun kanssas, ja minä jällensä sinun sieltä johdatan. Ja Joseph laskee kätensä sinun silmäis päälle."],[46,5,"Ja Jakob läksi BerSabasta: ja Israelin lapset veivät isänsä Jakobin ynnä lastensa ja emäntäinsä kanssa, vaunuissa, jotka Pharao oli häntä tuomaan lähettänyt.","Ja Jakob läksi BerSabasta: ja Israelin lapset veivät isänsä Jakobin ynnä lastensa ja emäntäinsä kanssa, vaunuissa, jotka Pharao oli häntä tuomaan lähettänyt."],[46,6,"Ja he ottivat karjansa ja tavaransa, jotka he olivat koonneet Kanaanin maalla, ja tulivat Egyptiin, Jakob ja kaikki hänen siemenensä hänen kanssansa.","Ja he ottivat karjansa ja tavaransa, jotka he olivat koonneet Kanaanin maalla, ja tulivat Egyptiin, Jakob ja kaikki hänen siemenensä hänen kanssansa."],[46,7,"Hänen poikansa ja hänen poikainsa pojat hänen kanssansa, hänen tyttärensä ja hänen lastensa tyttäret, ja kaikki hänen siemenensä, vei hän kanssansa Egyptiin.","Hänen poikansa ja hänen poikainsa pojat hänen kanssansa, hänen tyttärensä ja hänen lastensa tyttäret, ja kaikki hänen siemenensä, vei hän kanssansa Egyptiin."],[46,8,"Ja nämät ovat Israelin lasten nimet, jotka tulivat Egyptiin: Jakob ja hänen poikansa. Jakobin esikoinen Ruben.","Ja nämät ovat Israelin lasten nimet, jotka tulivat Egyptiin: Jakob ja hänen poikansa. Jakobin esikoinen Ruben."],[46,9,"Ja Rubenin lapset: Hanok, Pallu, Hetsron ja Karmi.","Ja Rubenin lapset: Hanok, Pallu, Hetsron ja Karmi."],[46,10,"Simeonin lapset: Jemuel, Jamin, Ohad, Jakin, Zohar: niin myös Saul, Kananean vaimon poika.","Simeonin lapset: Jemuel, Jamin, Ohad, Jakin, Zohar: niin myös Saul, Kananean vaimon poika."],[46,11,"Levin lapset: Gerson, Kahat ja Merari.","Levin lapset: Gerson, Kahat ja Merari."],[46,12,"Juudan lapset: Ger, Onan, Sela, Perets ja Sera. Mutta Ger ja Onan kuolivat Kanaanin maalla. Ja Peretsin pojat olivat: Hetsron ja Hamul.","Juudan lapset: Ger, Onan, Sela, Perets ja Sera. Mutta Ger ja Onan kuolivat Kanaanin maalla. Ja Peretsin pojat olivat: Hetsron ja Hamul."],[46,13,"Ja Isaskarin lapset: Tola, Phua, Job ja Simron.","Ja Isaskarin lapset: Tola, Phua, Job ja Simron."],[46,14,"Ja Sebulonin lapset: Sered, Elon ja Jahleel.","Ja Sebulonin lapset: Sered, Elon ja Jahleel."],[46,15,"Nämät ovat Lean lapset, jotka hän synnytti Jakobille Mesopotamiassa, ja Dinan hänen tyttärensä. Kaikki hänen poikansa ja tyttärensä olivat kolmeneljättäkymmentä henkeä.","Nämät ovat Lean lapset, jotka hän synnytti Jakobille Mesopotamiassa, ja Dinan hänen tyttärensä. Kaikki hänen poikansa ja tyttärensä olivat kolmeneljättäkymmentä henkeä."],[46,16,"Gadin lapset: Ziphion, Haggi, Suni, Etsbon, Eri, Arodi ja Areli.","Gadin lapset: Ziphion, Haggi, Suni, Etsbon, Eri, Arodi ja Areli."],[46,17,"Asserin lapset: Jemna, Jesua, Jesui, Bria ja Sera heidän sisarensa. Mutta Brian lapset: Heber ja Malkiel.","Asserin lapset: Jemna, Jesua, Jesui, Bria ja Sera heidän sisarensa. Mutta Brian lapset: Heber ja Malkiel."],[46,18,"Nämät ovat Silpan lapset, jonka Laban antoi tyttärellensä Lealle, ja hän synnytti Jakobille nämät kuusitoistakymmentä henkeä.","Nämät ovat Silpan lapset, jonka Laban antoi tyttärellensä Lealle, ja hän synnytti Jakobille nämät kuusitoistakymmentä henkeä."],[46,19,"Rakelin Jakobin emännän lapset: Joseph ja BenJamin.","Rakelin Jakobin emännän lapset: Joseph ja BenJamin."],[46,20,"Ja Josephille olivat syntyneet Egyptin maalla, jotka hänelle synnytti Asnat, Potipheran Onin papin tytär: nimittäin Manasse ja Ephraim.","Ja Josephille olivat syntyneet Egyptin maalla, jotka hänelle synnytti Asnat, Potipheran Onin papin tytär: nimittäin Manasse ja Ephraim."],[46,21,"BenJaminin lapset: Bela, Beker, Asbel, Gera, Naaman, Ehi ja Ros; Mupim, Hupim, ja Ard.","BenJaminin lapset: Bela, Beker, Asbel, Gera, Naaman, Ehi ja Ros; Mupim, Hupim, ja Ard."],[46,22,"Nämät ovat Rakelin lapset, jotka ovat Jakobille syntyneet, kaikki yhteen, neljätoistakymmentä henkeä.","Nämät ovat Rakelin lapset, jotka ovat Jakobille syntyneet, kaikki yhteen, neljätoistakymmentä henkeä."],[46,23,"Danin lapset: Husim.","Danin lapset: Husim."],[46,24,"Naphtalin lapset: Jahseel, Guni, Jetser ja Sillem.","Naphtalin lapset: Jahseel, Guni, Jetser ja Sillem."],[46,25,"Nämät ovat Bilhan lapset, jonka Laban antoi tyttärellensä Rakelille, ja hän synnytti nämät Jakobille, kaikki yhteen, seitsemän henkeä.","Nämät ovat Bilhan lapset, jonka Laban antoi tyttärellensä Rakelille, ja hän synnytti nämät Jakobille, kaikki yhteen, seitsemän henkeä."],[46,26,"Kaikki henget, kuin tulivat Jakobin kanssa Egyptiin, jotka olivat tulleet hänen kupeistansa, paitsi Jakobin poikain emäntiä, ovat kaikki yhteen, kuusiseitsemättäkymmentä henkeä.","Kaikki henget, kuin tulivat Jakobin kanssa Egyptiin, jotka olivat tulleet hänen kupeistansa, paitsi Jakobin poikain emäntiä, ovat kaikki yhteen, kuusiseitsemättäkymmentä henkeä."],[46,27,"Ja Josephin pojat, jotka hänelle olivat syntyneet Egyptissä, olivat kaksi henkeä. Niin että kaikki henget Jakobin huoneesta, jotka tulivat Egyptiin olivat seitsemänkymmentä.","Ja Josephin pojat, jotka hänelle olivat syntyneet Egyptissä, olivat kaksi henkeä. Niin että kaikki henget Jakobin huoneesta, jotka tulivat Egyptiin olivat seitsemänkymmentä."],[46,28,"Ja hän lähetti edellänsä Juudan Josephin tykö, osoittamaan hänelle tietä Goseniin, ja he tulivat Gosenin maalle.","Ja hän lähetti edellänsä Juudan Josephin tykö, osoittamaan hänelle tietä Goseniin, ja he tulivat Gosenin maalle."],[46,29,"Niin valmisti Joseph vaununsa ja meni isäänsä Israelia vastaan Goseniin. Ja koska hän sai nähdä hänen, halasi hän häntä kaulasta ja itki hetken aikaa hänen kaulassansa.","Niin valmisti Joseph vaununsa ja meni isäänsä Israelia vastaan Goseniin. Ja koska hän sai nähdä hänen, halasi hän häntä kaulasta ja itki hetken aikaa hänen kaulassansa."],[46,30,"Niin sanoi Israel Josephille: nyt minä mielelläni kuolen, että minä näin sinun kasvos, ja ettäs vielä elät.","Niin sanoi Israel Josephille: nyt minä mielelläni kuolen, että minä näin sinun kasvos, ja ettäs vielä elät."],[46,31,"Ja Joseph sanoi veljillensä, ja isänsä huoneelle: minä menen ja ilmoitan Pharaolle, ja sanon hänelle: minun veljeni ja isäni huone, jotka olivat Kanaanin maalla, ovat tulleet minun tyköni.","Ja Joseph sanoi veljillensä, ja isänsä huoneelle: minä menen ja ilmoitan Pharaolle, ja sanon hänelle: minun veljeni ja isäni huone, jotka olivat Kanaanin maalla, ovat tulleet minun tyköni."],[46,32,"Ja he ovat paimenet, sillä he ovat tottuneet karjaa kaitsemaan: niin myös suuret ja pienet karjansa, ja kaikki, mitä heillä oli, ovat tuoneet myötänsä.","Ja he ovat paimenet, sillä he ovat tottuneet karjaa kaitsemaan: niin myös suuret ja pienet karjansa, ja kaikki, mitä heillä oli, ovat tuoneet myötänsä."],[46,33,"Koska siis Pharao kutsuu teitä ja sanoo: mikä teidän virkanne on?","Koska siis Pharao kutsuu teitä ja sanoo: mikä teidän virkanne on?"],[46,34,"Niin sanokaat: sinun palvelias ovat tottuneet karjaa kaitsemaan, hamasta meidän nuoruudestamme niin tähänasti, sekä me että meidän isämme: että te saisitte asua Gosenin maalla, sillä kaikki paimenet ovat kauhistus Egyptiläisille.","Niin sanokaat: sinun palvelias ovat tottuneet karjaa kaitsemaan, hamasta meidän nuoruudestamme niin tähänasti, sekä me että meidän isämme: että te saisitte asua Gosenin maalla, sillä kaikki paimenet ovat kauhistus Egyptiläisille."],[47,1,"Niin Joseph tuli ja ilmoitti Pharaolle, ja sanoi: minun isäni ja minun veljeni, heidän karjansa, pienet ja suuret, ja kaikki, mitä heillä on, ovat tulleet Kanaanin maalta; ja katso, he ovat Gosenin maalla.","Niin Joseph tuli ja ilmoitti Pharaolle, ja sanoi: minun isäni ja minun veljeni, heidän karjansa, pienet ja suuret, ja kaikki, mitä heillä on, ovat tulleet Kanaanin maalta; ja katso, he ovat Gosenin maalla."],[47,2,"Ja hän otti viisi nuorimmista veljistänsä, ja asetti Pharaon eteen.","Ja hän otti viisi nuorimmista veljistänsä, ja asetti Pharaon eteen."],[47,3,"Niin Pharao sanoi hänen veljillensä: mikä teidän virkanne on? He vastasivat: sinun palvelias ovat paimenet, sekä me että meidän isämme.","Niin Pharao sanoi hänen veljillensä: mikä teidän virkanne on? He vastasivat: sinun palvelias ovat paimenet, sekä me että meidän isämme."],[47,4,"Ja sanoivat vielä Pharaolle: me olemme tulleet asumaan teidän kanssanne tälle maalle; sillä sinun palvelioillas ei ole laidunta karjallensa, niin kova nälkä on Kanaanin maalla. Niin suo sinun palvelias asua Gosenin maalla.","Ja sanoivat vielä Pharaolle: me olemme tulleet asumaan teidän kanssanne tälle maalle; sillä sinun palvelioillas ei ole laidunta karjallensa, niin kova nälkä on Kanaanin maalla. Niin suo sinun palvelias asua Gosenin maalla."],[47,5,"Niin Pharao puhui Josephille, sanoen: sinun isäs ja veljes ovat tulleet sinun tykös.","Niin Pharao puhui Josephille, sanoen: sinun isäs ja veljes ovat tulleet sinun tykös."],[47,6,"Egyptin maa on altis sinun edessäs; aseta isäs asumaan ja veljes kaikkein parhaasen paikkaan tässä maassa: asukaan Gosenin maalla. Ja jos sinä ymmärrät, että heidän seassansa on kelvollisia miehiä, niin aseta heitä minun karjani päälle.","Egyptin maa on altis sinun edessäs; aseta isäs asumaan ja veljes kaikkein parhaasen paikkaan tässä maassa: asukaan Gosenin maalla. Ja jos sinä ymmärrät, että heidän seassansa on kelvollisia miehiä, niin aseta heitä minun karjani päälle."],[47,7,"Ja Joseph toi isänsä, Jakobin, sisälle, ja asetti hänen Pharaon eteen. Ja Jakob siunasi Pharaota.","Ja Joseph toi isänsä, Jakobin, sisälle, ja asetti hänen Pharaon eteen. Ja Jakob siunasi Pharaota."],[47,8,"Niin Pharao sanoi Jakobille: kuinka vanha sinä olet?","Niin Pharao sanoi Jakobille: kuinka vanha sinä olet?"],[47,9,"Jakob sanoi Pharaolle: minun kulkemiseni aika on sata ja kolmekymmentä ajastaikaa: vähä ja paha on minun elämäni aika ja ei ulotu minun isäini kulkemisen aikaan.","Jakob sanoi Pharaolle: minun kulkemiseni aika on sata ja kolmekymmentä ajastaikaa: vähä ja paha on minun elämäni aika ja ei ulotu minun isäini kulkemisen aikaan."],[47,10,"Ja Jakob siunasi Pharaota, ja läksi hänen tyköänsä.","Ja Jakob siunasi Pharaota, ja läksi hänen tyköänsä."],[47,11,"Niin Joseph toimitti isänsä ja veljensä asumaan, ja antoi heille omaisuuden Egyptin maalla, parhaassa maan paikassa; nimittäin Rameseksen maalla, niinkuin Pharao oli käskenyt.","Niin Joseph toimitti isänsä ja veljensä asumaan, ja antoi heille omaisuuden Egyptin maalla, parhaassa maan paikassa; nimittäin Rameseksen maalla, niinkuin Pharao oli käskenyt."],[47,12,"Ja Joseph elätti isänsä, veljensä ja koko isänsä huoneen, sen jälkeen kuin heillä lapsia oli.","Ja Joseph elätti isänsä, veljensä ja koko isänsä huoneen, sen jälkeen kuin heillä lapsia oli."],[47,13,"Ja ei ollut leipää kaikessa maassa; sillä sangen raskas nälkä oli, niin että Egyptin ja Kanaanin maa nääntyi näljän tähden.","Ja ei ollut leipää kaikessa maassa; sillä sangen raskas nälkä oli, niin että Egyptin ja Kanaanin maa nääntyi näljän tähden."],[47,14,"Ja Joseph kokosi kaiken rahan kuin löyttiin Egyptin ja Kanaanin maalla, jyväin edestä kuin he ostivat. Ja Joseph vei rahan Pharaon huoneesen.","Ja Joseph kokosi kaiken rahan kuin löyttiin Egyptin ja Kanaanin maalla, jyväin edestä kuin he ostivat. Ja Joseph vei rahan Pharaon huoneesen."],[47,15,"Koska raha oli kulunut Egyptin ja Kanaanin maalta, niin tulivat kaikki Egyptiläiset Josephin tykö, sanoen: anna meille leipää, miksi meidän pitää kuoleman edessäs, että raha on puuttunut?","Koska raha oli kulunut Egyptin ja Kanaanin maalta, niin tulivat kaikki Egyptiläiset Josephin tykö, sanoen: anna meille leipää, miksi meidän pitää kuoleman edessäs, että raha on puuttunut?"],[47,16,"Joseph sanoi: tuokaat teidän karjanne, ja minä annan teille karjanne edestä, jos raha on puuttunut?","Joseph sanoi: tuokaat teidän karjanne, ja minä annan teille karjanne edestä, jos raha on puuttunut?"],[47,17,"Ja he toivat karjansa Josephille, ja Joseph antoi heille leipää hevosten, ja lammasten, ja karjan ja aasein edestä. Niin hän ruokki heitä leivällä sen vuoden, kaiken heidän karjansa edestä.","Ja he toivat karjansa Josephille, ja Joseph antoi heille leipää hevosten, ja lammasten, ja karjan ja aasein edestä. Niin hän ruokki heitä leivällä sen vuoden, kaiken heidän karjansa edestä."],[47,18,"Koska se vuosi oli kulunut, tulivat he hänen tykönsä toisna vuonna, ja sanoivat hänelle: emme taida salata meidän herraltamme, ettei ainoastansa raha ole kulunut, mutta myös kaikki karja on meidän herrallamme, ja ei ole mitään jäänyt meidän herramme edessä, paitsi meidän ruumistamme ja meidän peltoamme.","Koska se vuosi oli kulunut, tulivat he hänen tykönsä toisna vuonna, ja sanoivat hänelle: emme taida salata meidän herraltamme, ettei ainoastansa raha ole kulunut, mutta myös kaikki karja on meidän herrallamme, ja ei ole mitään jäänyt meidän herramme edessä, paitsi meidän ruumistamme ja meidän peltoamme."],[47,19,"Miksi meidän pitää kuoleman edessäs ja meidän peltomme tulee kylmille? Osta meitä ja meidän maamme leivän edestä, niin me ja meidän maamme tulemme Pharaon omaksi. Anna siemeniä, että me eläisimme ja emme kuolisi, ja ei maa tulisi kylmille.","Miksi meidän pitää kuoleman edessäs ja meidän peltomme tulee kylmille? Osta meitä ja meidän maamme leivän edestä, niin me ja meidän maamme tulemme Pharaon omaksi. Anna siemeniä, että me eläisimme ja emme kuolisi, ja ei maa tulisi kylmille."],[47,20,"Niin Joseph osti koko Egyptin maan Pharaolle; sillä Egyptiläiset myivät itsekukin peltonsa, että nälkä heitä niin kovin ahdisti: ja maa tuli Pharaon omaksi.","Niin Joseph osti koko Egyptin maan Pharaolle; sillä Egyptiläiset myivät itsekukin peltonsa, että nälkä heitä niin kovin ahdisti: ja maa tuli Pharaon omaksi."],[47,21,"Ja hän siirsi kansan kaupunkeihin yhdestä Egyptin äärestä niin toiseen.","Ja hän siirsi kansan kaupunkeihin yhdestä Egyptin äärestä niin toiseen."],[47,22,"Paitsi pappein peltoa, jota ei hän ostanut: sillä se oli säätty Pharaolta, että papit söisivät sen nimitetyn osan, kuin Pharao heille antoi: sentähden ei he myyneet maatansa.","Paitsi pappein peltoa, jota ei hän ostanut: sillä se oli säätty Pharaolta, että papit söisivät sen nimitetyn osan, kuin Pharao heille antoi: sentähden ei he myyneet maatansa."],[47,23,"Niin Joseph sanoi kansalle: katso, minä olen ostanut tänäpänä teidän ja teidän maanne Pharaolle: katso, tässä on teille siemenet, kylväkäät teidän maanne.","Niin Joseph sanoi kansalle: katso, minä olen ostanut tänäpänä teidän ja teidän maanne Pharaolle: katso, tässä on teille siemenet, kylväkäät teidän maanne."],[47,24,"Ja teidän pitää antaman tulosta viidennen osan Pharaolle; mutta neljä osaa pitää oleman teille pellon siemeneksi, ja teille ravinnoksi, ja niille, jotka ovat teidän huoneessanne, ja ruaksi teidän lapsillenne.","Ja teidän pitää antaman tulosta viidennen osan Pharaolle; mutta neljä osaa pitää oleman teille pellon siemeneksi, ja teille ravinnoksi, ja niille, jotka ovat teidän huoneessanne, ja ruaksi teidän lapsillenne."],[47,25,"Niin he sanoivat: sinä olet meitä elämässä pitänyt: anna ainoastansa meidän löytää armo sinun meidän herramme edessä, ja me tahdomme olla Pharaon orjat.","Niin he sanoivat: sinä olet meitä elämässä pitänyt: anna ainoastansa meidän löytää armo sinun meidän herramme edessä, ja me tahdomme olla Pharaon orjat."],[47,26,"Ja Joseph teki sen määrän koko Egyptin maalle, hamaan tähän päivään asti, että Pharaolle piti annettaman viides osa; paitsi pappein maata, se ei tullut Pharaon omaksi.","Ja Joseph teki sen määrän koko Egyptin maalle, hamaan tähän päivään asti, että Pharaolle piti annettaman viides osa; paitsi pappein maata, se ei tullut Pharaon omaksi."],[47,27,"Niin Israel asui Egyptissä Gosenin maalla; ja he omistivat sen, ja kasvoivat ja suuresti lisääntyivät.","Niin Israel asui Egyptissä Gosenin maalla; ja he omistivat sen, ja kasvoivat ja suuresti lisääntyivät."],[47,28,"Ja Jakob eli Egyptin maalla, seitsemäntoistakymmentä ajastaikaa, ja koko hänen ikänsä oli sata ja seitsemänviidettäkymmentä ajastaikaa.","Ja Jakob eli Egyptin maalla, seitsemäntoistakymmentä ajastaikaa, ja koko hänen ikänsä oli sata ja seitsemänviidettäkymmentä ajastaikaa."],[47,29,"Ja koska Israelin päivät joutuivat kuolla, kutsui hän poikansa Josephin, ja sanoi hänelle: jos minä olen löytänyt armon sinun edessäs, niin laske nyt kätes minun kupeeni alle, ettäs tekisit laupiuden ja totuuden minun kanssani, ettes hautaisi minua Egyptiin.","Ja koska Israelin päivät joutuivat kuolla, kutsui hän poikansa Josephin, ja sanoi hänelle: jos minä olen löytänyt armon sinun edessäs, niin laske nyt kätes minun kupeeni alle, ettäs tekisit laupiuden ja totuuden minun kanssani, ettes hautaisi minua Egyptiin."],[47,30,"Mutta minä tahdon maata minun isäini tykönä, ja sinun pitää viemän minua Egyptistä, ja hautaaman minua heidän hautaansa. Ja hän sanoi: minä teen sinun sanas jälkeen.","Mutta minä tahdon maata minun isäini tykönä, ja sinun pitää viemän minua Egyptistä, ja hautaaman minua heidän hautaansa. Ja hän sanoi: minä teen sinun sanas jälkeen."],[47,31,"Hän sanoi: vanno minulle. Ja hän vannoi hänelle. Ja Israel kallisti itsensä päänalaiselle.","Hän sanoi: vanno minulle. Ja hän vannoi hänelle. Ja Israel kallisti itsensä päänalaiselle."],[48,1,"Sitte sanottiin Josephille: katso, sinun isäs sairastaa. Ja hän otti molemmat poikansa kanssansa, Manassen ja Ephraimin.","Sitte sanottiin Josephille: katso, sinun isäs sairastaa. Ja hän otti molemmat poikansa kanssansa, Manassen ja Ephraimin."],[48,2,"Niin Jakobille ilmoitettiin, sanoen: katso, sinun poikas Joseph tulee sinun tykös. Ja Israel vahvisti itsensä ja istui vuoteessa.","Niin Jakobille ilmoitettiin, sanoen: katso, sinun poikas Joseph tulee sinun tykös. Ja Israel vahvisti itsensä ja istui vuoteessa."],[48,3,"Ja Jakob sanoi Josephille: Jumala kaikkivaltias näkyi minulle Lutsissa Kanaanin maalla; ja siunasi minua.","Ja Jakob sanoi Josephille: Jumala kaikkivaltias näkyi minulle Lutsissa Kanaanin maalla; ja siunasi minua."],[48,4,"Ja sanoi minulle: katso, minä annan sinun olla hedelmällisen ja lisääntyä, ja teen sinun paljoksi kansaksi; ja annan myös tämän maan sinun siemenelles sinun jälkees, ijankaikkiseksi perimiseksi.","Ja sanoi minulle: katso, minä annan sinun olla hedelmällisen ja lisääntyä, ja teen sinun paljoksi kansaksi; ja annan myös tämän maan sinun siemenelles sinun jälkees, ijankaikkiseksi perimiseksi."],[48,5,"Nyt siis ne kaksi sinun poikaas, jotka sinulle ovat syntyneet Egyptissä, ennenkuin minä tulin tänne sinun tykös, pitää oleman minun; nimittäin Ephraim ja Manasse, niinkuin Ruben ja Simeon ovat minun.","Nyt siis ne kaksi sinun poikaas, jotka sinulle ovat syntyneet Egyptissä, ennenkuin minä tulin tänne sinun tykös, pitää oleman minun; nimittäin Ephraim ja Manasse, niinkuin Ruben ja Simeon ovat minun."],[48,6,"Mutta sinun lapses, jotkas siität niiden jälkeen, pitää oleman sinun, ja pitää nimitettämän veljeinsä nimellä, heidän perimisestänsä.","Mutta sinun lapses, jotkas siität niiden jälkeen, pitää oleman sinun, ja pitää nimitettämän veljeinsä nimellä, heidän perimisestänsä."],[48,7,"Ja koska minä tulin Mesopotamiasta, kuoli minulta Rakel Kanaanin maalla, tiellä, koska vielä kappale matkaa oli Ephrataan; ja minä hautasin hänen siellä Ephratan tiellä, se on Betlehem.","Ja koska minä tulin Mesopotamiasta, kuoli minulta Rakel Kanaanin maalla, tiellä, koska vielä kappale matkaa oli Ephrataan; ja minä hautasin hänen siellä Ephratan tiellä, se on Betlehem."],[48,8,"Ja Israel näki Josephin pojat, ja sanoi: kutka nämät ovat?","Ja Israel näki Josephin pojat, ja sanoi: kutka nämät ovat?"],[48,9,"Ja Joseph vastasi isäänsä: ne ovat minun poikani, jotka Jumala on minulle täällä antanut. Ja hän sanoi: tuos heitä minun tyköni siunatakseni heitä.","Ja Joseph vastasi isäänsä: ne ovat minun poikani, jotka Jumala on minulle täällä antanut. Ja hän sanoi: tuos heitä minun tyköni siunatakseni heitä."],[48,10,"Sillä Israelin silmät olivat pimiät vanhuudesta, eikä taitanut hyvin nähdä. Ja hän vei heidät hänen tykönsä. Ja hän antoi suuta heidän, ja otti heitä syliinsä.","Sillä Israelin silmät olivat pimiät vanhuudesta, eikä taitanut hyvin nähdä. Ja hän vei heidät hänen tykönsä. Ja hän antoi suuta heidän, ja otti heitä syliinsä."],[48,11,"Ja Israel sanoi Josephille: en minä ajatellut nähdä sinun kasvojas, ja katso, Jumala on antanut minun myös nähdä sinun siemenes.","Ja Israel sanoi Josephille: en minä ajatellut nähdä sinun kasvojas, ja katso, Jumala on antanut minun myös nähdä sinun siemenes."],[48,12,"Ja Joseph otti heidät pois hänen sylistänsä, ja kumarsi itsiänsä maahan hänen kasvoinsa eteen.","Ja Joseph otti heidät pois hänen sylistänsä, ja kumarsi itsiänsä maahan hänen kasvoinsa eteen."],[48,13,"Niin Joseph otti heidät molemmat, Ephraimin oikiaan käteensä, jonka hän asetti Israelin vasemmalle kädelle, ja Manassen vasempaan käteensä, Israelin oikialle kädelle, ja vei heidät hänen tykönsä.","Niin Joseph otti heidät molemmat, Ephraimin oikiaan käteensä, jonka hän asetti Israelin vasemmalle kädelle, ja Manassen vasempaan käteensä, Israelin oikialle kädelle, ja vei heidät hänen tykönsä."],[48,14,"Niin Israel ojensi oikian kätensä, ja laski Ephraimin pään päälle, joka oli nuorempi, mutta vasemman kätensä Manassen pään päälle, ja muutti tiettävästi kätensä; sillä Manasse oli esikoinen.","Niin Israel ojensi oikian kätensä, ja laski Ephraimin pään päälle, joka oli nuorempi, mutta vasemman kätensä Manassen pään päälle, ja muutti tiettävästi kätensä; sillä Manasse oli esikoinen."],[48,15,"Ja hän siunasi Josephia, ja sanoi: Jumala, jonka kasvoin edessä minun isäni Abraham ja Isaak vaeltaneet ovat, Jumala, joka minun kainnut on minun elinaikanani tähän päivään asti.","Ja hän siunasi Josephia, ja sanoi: Jumala, jonka kasvoin edessä minun isäni Abraham ja Isaak vaeltaneet ovat, Jumala, joka minun kainnut on minun elinaikanani tähän päivään asti."],[48,16,"Enkeli, joka minun pelastanut on kaikesta pahasta, siunatkoon näitä nuorukaisia, että he nimitettäisiin minun ja minun isäini, Abrahamin, ja Isaakin nimellä, ja kasvaisivat aivan paljoksi maan päällä.","Enkeli, joka minun pelastanut on kaikesta pahasta, siunatkoon näitä nuorukaisia, että he nimitettäisiin minun ja minun isäini, Abrahamin, ja Isaakin nimellä, ja kasvaisivat aivan paljoksi maan päällä."],[48,17,"Mutta koska Joseph näki isänsä laskevan oikian kätensä Ephraimin pään päälle, otti hän sen pahaksi, ja rupesi isänsä käteen, siirtääksensä Ephraimin pään päältä Manassen pään päälle.","Mutta koska Joseph näki isänsä laskevan oikian kätensä Ephraimin pään päälle, otti hän sen pahaksi, ja rupesi isänsä käteen, siirtääksensä Ephraimin pään päältä Manassen pään päälle."],[48,18,"Ja sanoi Joseph isällensä: ei niin minun isäni; tämä on esikoinen, laske oikia kätes hänen päänsä päälle.","Ja sanoi Joseph isällensä: ei niin minun isäni; tämä on esikoinen, laske oikia kätes hänen päänsä päälle."],[48,19,"Mutta hänen isänsä kielsi sen, ja sanoi: minä tiedän kyllä, minun poikani, minä tiedän: tämä myös tulee suureksi kansaksi; mutta kuitenkin hänen nuorempi veljensä tulee suuremmaksi kuin hän, ja hänen siemenensä tulee suureksi kansain paljoudeksi.","Mutta hänen isänsä kielsi sen, ja sanoi: minä tiedän kyllä, minun poikani, minä tiedän: tämä myös tulee suureksi kansaksi; mutta kuitenkin hänen nuorempi veljensä tulee suuremmaksi kuin hän, ja hänen siemenensä tulee suureksi kansain paljoudeksi."],[48,20,"Niin hän siunasi heitä sinä päivänä, sanoen: joka tahtoo jonkun siunata Israelissa, niin sanokaan näin: Jumala tehköön sinun niinkuin Ephraimin ja Manassen. Ja niin asetti hän Ephraimin Manassen edelle.","Niin hän siunasi heitä sinä päivänä, sanoen: joka tahtoo jonkun siunata Israelissa, niin sanokaan näin: Jumala tehköön sinun niinkuin Ephraimin ja Manassen. Ja niin asetti hän Ephraimin Manassen edelle."],[48,21,"Ja Israel sanoi Josephille: katso minä kuolen; ja Jumala on teidän kanssanne, ja vie teitä jällensä teidän isäinne maalle.","Ja Israel sanoi Josephille: katso minä kuolen; ja Jumala on teidän kanssanne, ja vie teitä jällensä teidän isäinne maalle."],[48,22,"Minä olen myös antanut sinulle osan maata, päälle sinun veljeis osan, jonka minä miekallani ja joutsellani Amorilaisten käsistä ottanut olen.","Minä olen myös antanut sinulle osan maata, päälle sinun veljeis osan, jonka minä miekallani ja joutsellani Amorilaisten käsistä ottanut olen."],[49,1,"Niin kutsui Jakob poikansa, ja sanoi: kootkaat teitänne, ja minä ilmoitan teille, mitä teille tapahtuu tulevaisilla ajoilla.","Niin kutsui Jakob poikansa, ja sanoi: kootkaat teitänne, ja minä ilmoitan teille, mitä teille tapahtuu tulevaisilla ajoilla."],[49,2,"Tulkaat kokoon ja kuulkaat, te Jakobin lapset, kuulkaat teidän isäänne Israelia.","Tulkaat kokoon ja kuulkaat, te Jakobin lapset, kuulkaat teidän isäänne Israelia."],[49,3,"Ruben, sinä olet minun esikoiseni, minun voimani, ja väkevyyteni alku, ylimmäinen kunniassa, ja ylimmäinen vallassa.","Ruben, sinä olet minun esikoiseni, minun voimani, ja väkevyyteni alku, ylimmäinen kunniassa, ja ylimmäinen vallassa."],[49,4,"Hempiä niinkuin vesi, ei sinun pidä ylimmäisen oleman; sillä sinä astuit isäs vuoteesen: silloin sinä saastutit sen. Hän nousi minun vuoteelleni.","Hempiä niinkuin vesi, ei sinun pidä ylimmäisen oleman; sillä sinä astuit isäs vuoteesen: silloin sinä saastutit sen. Hän nousi minun vuoteelleni."],[49,5,"Simeon ja Levi ovat veljekset, heidän miekkansa ovat murha-aseet.","Simeon ja Levi ovat veljekset, heidän miekkansa ovat murha-aseet."],[49,6,"Ei minun sieluni pidä tuleman heidän neuvoonsa, ja minun kunniani ei pidä yhdistymän heidän seurakuntansa kanssa; sillä kiukussansa ovat he miehen murhanneet, ja ylpeydessänsä turmelleet härjän.","Ei minun sieluni pidä tuleman heidän neuvoonsa, ja minun kunniani ei pidä yhdistymän heidän seurakuntansa kanssa; sillä kiukussansa ovat he miehen murhanneet, ja ylpeydessänsä turmelleet härjän."],[49,7,"Kirottu olkoon heidän kiukkunsa, että se niin tuima on, ja heidän julmuutensa, että se niin paatunut on. Minä eroitan heitä Jakobissa, ja hajotan heitä Israelissa.","Kirottu olkoon heidän kiukkunsa, että se niin tuima on, ja heidän julmuutensa, että se niin paatunut on. Minä eroitan heitä Jakobissa, ja hajotan heitä Israelissa."],[49,8,"Juuda, sinä olet; sinua pitää sinun veljes kiittämän, sinun kätes pitää oleman sinun vihollistes niskalle, sinun isäs lapset pitää sinua kumartaman.","Juuda, sinä olet; sinua pitää sinun veljes kiittämän, sinun kätes pitää oleman sinun vihollistes niskalle, sinun isäs lapset pitää sinua kumartaman."],[49,9,"Juuda on nuori jalopeura, saaliilta olet sinä astunut, minun poikani: hän on itsensä kumartanut maahan, ja levännyt niinkuin jalopeura, ja niinkuin suuri jalopeura; kuka tohtii hänen herättää?","Juuda on nuori jalopeura, saaliilta olet sinä astunut, minun poikani: hän on itsensä kumartanut maahan, ja levännyt niinkuin jalopeura, ja niinkuin suuri jalopeura; kuka tohtii hänen herättää?"],[49,10,"Ei valtikka oteta pois Juudalta, eikä Lain opettaja hänen jalvoistansa, siihenasti kuin Sankari tulee, ja hänessä kansat riippuvat kiinni.","Ei valtikka oteta pois Juudalta, eikä Lain opettaja hänen jalvoistansa, siihenasti kuin Sankari tulee, ja hänessä kansat riippuvat kiinni."],[49,11,"Hän sitoo varsansa viinapuuhun, ja aasintammansa varsan parhaasen viinapuuhun; Hän pesee vaatteensa viinassa, ja hameensa viinamarjan veressä.","Hän sitoo varsansa viinapuuhun, ja aasintammansa varsan parhaasen viinapuuhun; Hän pesee vaatteensa viinassa, ja hameensa viinamarjan veressä."],[49,12,"Hänen silmänsä ovat punaisemmat viinaa ja hampaansa valkeammat rieskaa.","Hänen silmänsä ovat punaisemmat viinaa ja hampaansa valkeammat rieskaa."],[49,13,"Zebulon on asuva meren sataman ja haahtein satamain vieressä, ja on ulottuva hamaan Sidoniin.","Zebulon on asuva meren sataman ja haahtein satamain vieressä, ja on ulottuva hamaan Sidoniin."],[49,14,"Isaskar on luja aasi, ja sioittaa itsensä rajain välille.","Isaskar on luja aasi, ja sioittaa itsensä rajain välille."],[49,15,"Hän näki levon hyväksi, ja maan ihanaksi; ja kumarsi hartiansa kantamaan, ja on veronalainen palvelia.","Hän näki levon hyväksi, ja maan ihanaksi; ja kumarsi hartiansa kantamaan, ja on veronalainen palvelia."],[49,16,"Dan on tuomitseva kansaansa, niinkuin joku Israelin sukukunnista.","Dan on tuomitseva kansaansa, niinkuin joku Israelin sukukunnista."],[49,17,"Dan on oleva kärmeenä tiellä, ja kyykärmeenä polulla; ja puree hevosta vuokoiseen, niin että sen ajaja seljällensä lankee.","Dan on oleva kärmeenä tiellä, ja kyykärmeenä polulla; ja puree hevosta vuokoiseen, niin että sen ajaja seljällensä lankee."],[49,18,"Herra, minä odotan sinun autuuttas.","Herra, minä odotan sinun autuuttas."],[49,19,"Gad hän on; hänelle tekee joukko väkirynnäkön; mutta hän itse on tekevä väkirynnäkön vihdoin heille.","Gad hän on; hänelle tekee joukko väkirynnäkön; mutta hän itse on tekevä väkirynnäkön vihdoin heille."],[49,20,"Asserista tulee hänen lihava leipänsä, ja hän antaa kuninkaalle herkut.","Asserista tulee hänen lihava leipänsä, ja hän antaa kuninkaalle herkut."],[49,21,"Naphtali on nopia peura, ja antaa suloiset puheet.","Naphtali on nopia peura, ja antaa suloiset puheet."],[49,22,"Joseph on hedelmällisen puun oksa, hedelmällisen puun oksa lähteen tykönä: tyttäret kävelivät muurin päällä.","Joseph on hedelmällisen puun oksa, hedelmällisen puun oksa lähteen tykönä: tyttäret kävelivät muurin päällä."],[49,23,"Ja vaikka ampujat saattivat hänen mielensä karvaaksi, riitelivät hänen kanssansa ja vihasivat häntä,","Ja vaikka ampujat saattivat hänen mielensä karvaaksi, riitelivät hänen kanssansa ja vihasivat häntä,"],[49,24,"On kuitenkin hänen joutsensa vahvana pysynyt, ja hänen käsivartensa miehustunut, sen väkevän kätten kautta Jakobissa; hänestä on paimen ja kivi Israelissa.","On kuitenkin hänen joutsensa vahvana pysynyt, ja hänen käsivartensa miehustunut, sen väkevän kätten kautta Jakobissa; hänestä on paimen ja kivi Israelissa."],[49,25,"Sinun isäs Jumalalta on hän sinulle avun tuottava, ja ynnä kaikkivaltiaan kanssa on hän sinua siunaava taivaan siunauksella ylhäältä, ja syvyyden siunauksella alhaalta, niin myös nisäin ja kohtuin siunauksella.","Sinun isäs Jumalalta on hän sinulle avun tuottava, ja ynnä kaikkivaltiaan kanssa on hän sinua siunaava taivaan siunauksella ylhäältä, ja syvyyden siunauksella alhaalta, niin myös nisäin ja kohtuin siunauksella."],[49,26,"Sinun isäs siunaukset minun isäini siunausten sivussa, ulottuvat voimallisesti niihin kalliimpihin asti maailman kukkuloilla; jotka tulevat Josephin pään päälle, ja Natsirein pään laelle, hänen veljeinsä keskellä.","Sinun isäs siunaukset minun isäini siunausten sivussa, ulottuvat voimallisesti niihin kalliimpihin asti maailman kukkuloilla; jotka tulevat Josephin pään päälle, ja Natsirein pään laelle, hänen veljeinsä keskellä."],[49,27,"BenJamin on raatelevainen susi, aamulla hän syö saaliin, ja ehtoona saaliin jakaa.","BenJamin on raatelevainen susi, aamulla hän syö saaliin, ja ehtoona saaliin jakaa."],[49,28,"Nämät kaikki ovat kaksitoistakymmentä Israelin sukukuntaa. Ja tämä on se kuin heidän isänsä heille puhui siunatessansa heitä: itsekutakin, niinkuin kunkin siunaus oli, siunasi hän heitä.","Nämät kaikki ovat kaksitoistakymmentä Israelin sukukuntaa. Ja tämä on se kuin heidän isänsä heille puhui siunatessansa heitä: itsekutakin, niinkuin kunkin siunaus oli, siunasi hän heitä."],[49,29,"Ja hän käski heitä, ja sanoi heille: minä kootaan minun kansani tykö: haudatkaat minua minun isäni tykö, siihen luolaan, joka on Hetiläisen Ephronin vainiossa.","Ja hän käski heitä, ja sanoi heille: minä kootaan minun kansani tykö: haudatkaat minua minun isäni tykö, siihen luolaan, joka on Hetiläisen Ephronin vainiossa."],[49,30,"Siihen luolaan Makpelan vainiossa, joka on Mamren kohdalla Kanaanin maalla, jonka Abraham osti hautaamisen perimiseksi vainion kanssa, siltä Hetiläiseltä Ephronilta.","Siihen luolaan Makpelan vainiossa, joka on Mamren kohdalla Kanaanin maalla, jonka Abraham osti hautaamisen perimiseksi vainion kanssa, siltä Hetiläiseltä Ephronilta."],[49,31,"Sinne ovat he haudanneet Abrahamin ja hänen emäntänsä Saaran, sinne ovat he myös haudanneet Isaakin ja Rebekan hänen emäntänsä. Sinne olen minä myös haudannut Lean.","Sinne ovat he haudanneet Abrahamin ja hänen emäntänsä Saaran, sinne ovat he myös haudanneet Isaakin ja Rebekan hänen emäntänsä. Sinne olen minä myös haudannut Lean."],[49,32,"Siihen vainioon ja siihen luolaan, kuin on ostettu Hetin lapsilta.","Siihen vainioon ja siihen luolaan, kuin on ostettu Hetin lapsilta."],[49,33,"Ja koska Jakob lopetti käskyn lastensa tykö, pani hän jalkansa kokoon vuoteessa; ja loppui, ja koottiin kansansa tykö.","Ja koska Jakob lopetti käskyn lastensa tykö, pani hän jalkansa kokoon vuoteessa; ja loppui, ja koottiin kansansa tykö."],[50,1,"Niin Joseph lankesi isänsä kasvoille, itki hänen ylitsensä, ja antoi suuta hänen.","Niin Joseph lankesi isänsä kasvoille, itki hänen ylitsensä, ja antoi suuta hänen."],[50,2,"Ja Joseph käski palvelioitansa lääkäreitä voidella isäänsä; ja lääkärit voitelivat Israelia.","Ja Joseph käski palvelioitansa lääkäreitä voidella isäänsä; ja lääkärit voitelivat Israelia."],[50,3,"Ja he täyttivät hänelle neljäkymmentä päivää; sillä niin monta oli voiteluspäivää. Ja Egyptiläiset itkivät häntä seitsemänkymmentä päivää.","Ja he täyttivät hänelle neljäkymmentä päivää; sillä niin monta oli voiteluspäivää. Ja Egyptiläiset itkivät häntä seitsemänkymmentä päivää."],[50,4,"Koska hänen murhepäivänsä olivat kuluneet, puhui Joseph Pharaon palvelioille, sanoen: jos minä olen armon löytänyt teidän edessänne, niin puhukaat Pharaolle, ja sanokaat:","Koska hänen murhepäivänsä olivat kuluneet, puhui Joseph Pharaon palvelioille, sanoen: jos minä olen armon löytänyt teidän edessänne, niin puhukaat Pharaolle, ja sanokaat:"],[50,5,"Minun isäni vannotti minua, sanoen: katso, minä kuolen, hautaa minua minun hautaani, jonka minä olen kaivanut minulle Kanaanin maalla: niin tahtoisin minä nyt siis mennä, ja haudata minun isäni, ja palata tänne jällensä.","Minun isäni vannotti minua, sanoen: katso, minä kuolen, hautaa minua minun hautaani, jonka minä olen kaivanut minulle Kanaanin maalla: niin tahtoisin minä nyt siis mennä, ja haudata minun isäni, ja palata tänne jällensä."],[50,6,"Pharao sanoi hänelle: mene ja hautaa sinun isäs, niinkuin hän sinua vannottanut on.","Pharao sanoi hänelle: mene ja hautaa sinun isäs, niinkuin hän sinua vannottanut on."],[50,7,"Niin Joseph meni hautaamaan isäänsä; ja hänen kanssansa menivät kaikki Pharaon palveliat, hänen huoneensa vanhimmat, ja kaikki Egyptin maan vanhimmat.","Niin Joseph meni hautaamaan isäänsä; ja hänen kanssansa menivät kaikki Pharaon palveliat, hänen huoneensa vanhimmat, ja kaikki Egyptin maan vanhimmat."],[50,8,"Kaikki myös Josephin väki, ja hänen veljensä, ja hänen isänsä väki. Ainoastaan lapsensa, ja lampaansa, ja karjansa jättivät he Gosenin maalle.","Kaikki myös Josephin väki, ja hänen veljensä, ja hänen isänsä väki. Ainoastaan lapsensa, ja lampaansa, ja karjansa jättivät he Gosenin maalle."],[50,9,"Menivät myös hänen kanssansa vaunut ja ratsasmiehet. Ja se oli sangen suuri joukko.","Menivät myös hänen kanssansa vaunut ja ratsasmiehet. Ja se oli sangen suuri joukko."],[50,10,"Ja koska he tulivat Atadin riihen tykö, joka on sillä puolen Jordania, niin he pitivät siinä suuren ja katkeran valituksen; ja hän murehti isäänsä seitsemän päivää.","Ja koska he tulivat Atadin riihen tykö, joka on sillä puolen Jordania, niin he pitivät siinä suuren ja katkeran valituksen; ja hän murehti isäänsä seitsemän päivää."],[50,11,"Ja koska Kanaanin maan asuvaiset näkivät heidän murheensa Atadin riihen tykönä, sanoivat he: Egyptiläiset murehtivat siellä sangen kovin. Siitä se paikka kutsutaan: Egyptiläisten valitus, joka on sillä puolella Jordania.","Ja koska Kanaanin maan asuvaiset näkivät heidän murheensa Atadin riihen tykönä, sanoivat he: Egyptiläiset murehtivat siellä sangen kovin. Siitä se paikka kutsutaan: Egyptiläisten valitus, joka on sillä puolella Jordania."],[50,12,"Niin hänen lapsensa tekivät hänelle niinkuin hän oli käskenyt.","Niin hänen lapsensa tekivät hänelle niinkuin hän oli käskenyt."],[50,13,"Ja veivät hänen Kanaanin maalle, ja hautasivat hänen Makpelan vainion luolaan, jonka Abraham vainion kanssa ostanut oli perintöhaudaksi, Ephronilta Hetiläiseltä, Mamren kohdalla.","Ja veivät hänen Kanaanin maalle, ja hautasivat hänen Makpelan vainion luolaan, jonka Abraham vainion kanssa ostanut oli perintöhaudaksi, Ephronilta Hetiläiseltä, Mamren kohdalla."],[50,14,"Niin palasi Joseph Egyptiin, hän ja hänen veljensä, ja kaikki jotka hänen kanssansa olivat menneet hautaamaan hänen isäänsä, sitte kuin hän isänsä haudannut oli.","Niin palasi Joseph Egyptiin, hän ja hänen veljensä, ja kaikki jotka hänen kanssansa olivat menneet hautaamaan hänen isäänsä, sitte kuin hän isänsä haudannut oli."],[50,15,"Mutta koska Josephin veljet näkivät isänsä kuolleeksi, sanoivat he: mitämaks, Joseph on vihaava meitä, ja kaiketi kostaa meille kaiken sen pahan, kuin me häntä vastaan tehneet olemme.","Mutta koska Josephin veljet näkivät isänsä kuolleeksi, sanoivat he: mitämaks, Joseph on vihaava meitä, ja kaiketi kostaa meille kaiken sen pahan, kuin me häntä vastaan tehneet olemme."],[50,16,"Sentähden käskivät he sanoa Josephille: sinun isäs käski ennenkuin hän kuoli, sanoen:","Sentähden käskivät he sanoa Josephille: sinun isäs käski ennenkuin hän kuoli, sanoen:"],[50,17,"Niin sanokaat Josephille: minä rukoilen, anna nyt veljilles anteeksi heidän rikoksensa ja pahatekonsa, että he niin pahoin ovat tehneet sinua vastaan. Anna nyt anteeksi, sinun isäs Jumalan palveliain pahateko. Mutta Joseph itki heidän näitä puhuissansa.","Niin sanokaat Josephille: minä rukoilen, anna nyt veljilles anteeksi heidän rikoksensa ja pahatekonsa, että he niin pahoin ovat tehneet sinua vastaan. Anna nyt anteeksi, sinun isäs Jumalan palveliain pahateko. Mutta Joseph itki heidän näitä puhuissansa."],[50,18,"Ja hänen veljensä myös tulivat ja lankesivat maahan hänen eteensä ja sanoivat: katso, me olemme sinun palvelias.","Ja hänen veljensä myös tulivat ja lankesivat maahan hänen eteensä ja sanoivat: katso, me olemme sinun palvelias."],[50,19,"Joseph sanoi heille: älkäät peljätkö; sillä minä olen Jumalan käden alla.","Joseph sanoi heille: älkäät peljätkö; sillä minä olen Jumalan käden alla."],[50,20,"Te ajattelitte minua vastaan pahaa; mutta Jumala on ajatellut sen hyväksi, että hän tekis, niinkuin nyt nähtävä on, pelastaaksensa paljo kansaa.","Te ajattelitte minua vastaan pahaa; mutta Jumala on ajatellut sen hyväksi, että hän tekis, niinkuin nyt nähtävä on, pelastaaksensa paljo kansaa."],[50,21,"Älkäät siis nyt peljätkö, minä ravitsen teitä ja teidän lapsianne; ja hän rohkaisi heitä ja puheli ystävällisesti heidän kanssansa.","Älkäät siis nyt peljätkö, minä ravitsen teitä ja teidän lapsianne; ja hän rohkaisi heitä ja puheli ystävällisesti heidän kanssansa."],[50,22,"Ja niin asui Joseph Egyptissä, hän ja hänen isänsä huone; ja Joseph eli sata ja kymmenen ajastaikaa,","Ja niin asui Joseph Egyptissä, hän ja hänen isänsä huone; ja Joseph eli sata ja kymmenen ajastaikaa,"],[50,23,"Ja näki Ephraimin lapset kolmanteen polveen, niin myös Makirin Manassen pojan lapset, kasvatetut Josephin polven juuressa.","Ja näki Ephraimin lapset kolmanteen polveen, niin myös Makirin Manassen pojan lapset, kasvatetut Josephin polven juuressa."],[50,24,"Joseph sanoi veljillensä: minä kuolen, ja Jumala on totisesti etsivä teitä, ja vie teidän tältä maalta siihen maahan, jonka hän on itse vannonut Abrahamille, Isaakille ja Jakobille.","Joseph sanoi veljillensä: minä kuolen, ja Jumala on totisesti etsivä teitä, ja vie teidän tältä maalta siihen maahan, jonka hän on itse vannonut Abrahamille, Isaakille ja Jakobille."],[50,25,"Niin vannotti Joseph Israelin lapsia, sanoen: Jumala on totisesti teitä etsivä, viekäät pois minun luuni täältä.","Niin vannotti Joseph Israelin lapsia, sanoen: Jumala on totisesti teitä etsivä, viekäät pois minun luuni täältä."],[50,26,"Ja niin Joseph kuoli sadan ja kymmenen ajastaikaisena, ja he voitelivat hänen, ja panivat arkkuun Egyptissä.","Ja niin Joseph kuoli sadan ja kymmenen ajastaikaisena, ja he voitelivat hänen, ja panivat arkkuun Egyptissä."]]}};